\title{Escape of mass of the Thue-Morse sequence}

\author{Erez Nesharim}
\email{nesharim@technion.ac.il}
\address{Department of Mathematics, Technion - Israel Institute of Technology, Haifa, Israel}

\author{Uri Shapira}
\email{ushapira@technion.ac.il}
\address{Department of Mathematics, Technion - Israel Institute of Technology, Haifa, Israel}

\author{Noy Soffer Aranov}
\email{noysofferaranov@math.utah.edu}
\address{Department of Mathematics, University of Utah, Salt Lake City, Utah, USA}

\maketitle
\begin{abstract}
	Every Laurent series in $\fqttt$ has a continued fraction expansion whose partial quotients are polynomials. De Mathan and Teuli\'e proved that the degrees of the partial quotients of the left-shifts of every quadratic Laurent series are unbounded. Shapira and Paulin and Kemarsky improved this by showing that certain sequences of probability measures on the space of lattices in the plane $\fqttt^2$ exhibit positive escape of mass and conjectured that this escape is full -- that is, that these probability measures converge to zero. We disprove this conjecture by analysing in detail the case of the Laurent series over $\ft$ whose sequence of coefficients is the Thue-Morse sequence. The proof relies on 
	%\ezerase{realising a twisted version of the number wall corresponding to the Thue-Morse sequence as a certain substitution tiling possessing finding many symmetries.}
	the discovery of explicit symmetries in its number wall.
\end{abstract}

\paragraph{}
\begin{center}
	\emph{Dedicated to Gozal Nesharim on his \nth{75} birthday}
\end{center}

%\eznote{Section 4 should be updated to fit the current more relaxed style of the other sections.}

%\eznote{The treatment of boundaries between the blocks in the proof of Theorem 1.3 should be made clearer.}

\section{Introduction}
In this paper we study in detail a certain tiling of $\bbn^2$ by $\bF_2$ that is obtained by simple geometric means from 
the \emph{number wall} of the Thue-Morse sequence and establish its automaticity in an explicit manner. 
This tiling is tightly related to questions in Diophantine approximation 
of quadratic Laurent series in the local field $\ftttt$ and to the properties of an orbit of the 
full diagonal group in $\PGL_2\left(\ftttt\times \bF_2((t))\right)$ acting on the homogeneous space 
\begin{equation}\label{eq:homogeneous}
	\PGL_2\left(\ftttt\times \bF_2((t))\right)/\PGL_2\left(\bF_2\br{t,t^{-1}}\right).
\end{equation}
Our analysis of the tiling allows us to disprove certain statements in the Diophantine side that were widely believed to hold and, in that respect, are surprising. Consequently, this paper may be of interest to three groups of mathematicians with different mathematical backgrounds: automatic tilings, Diophantine approximation, and homogeneous dynamics. 

We split the introduction into two parts. We begin by explaining briefly the implication of the analysis carried out to Diophantine approximation and homogeneous dynamics. We then move to defining the necessary terminology in the theory of tilings and stating our main result.

\subsection{Partial escape of mass}

Let $q$ be a prime power. Every Laurent series $\theta\in\fqttt$ has a unique continued fraction expansion 
$$
\theta=a_0+\cfrac{1}{a_1+\cfrac{1}{a_2+\cdots\vphantom{\cfrac{1}{1}}}}\eqdef[a_0;a_1,a_2,\dots]\,,
$$
where $a_k=a_k(\theta)\in\fqt$ are polynomials for every $k \geq 0$, and
\begin{equation}\label{eq:dk}
	d_k = d_k(\theta) \defeq \deg\left(a_k\right)
\end{equation} 
for every $k \geq 1$ satisfies $d_k \geq 1$. It also has a unique base-$t$ expansion
$$
\theta = \sum_{n=-\infty}^\infty b_n t^{-n}\,,
$$
where $b_n=b_n(\theta)\in\fq$ for every $n\in\bbz$, and only finitely many of the coefficients of positive powers of $t$ are nonzero. Multiplication by $t$ changes the base-$t$ expansion by a left-shift. Therefore, for every $j,n\in\bbz$ the base-$t$ expansion of $t^j\theta$ satisfies \begin{equation}\label{eq:base-t-expansion}
	b_n\left(t^j\theta\right) = b_{n+j}\left(\theta\right).
\end{equation} 
It is natural to ask how $a_k\left(t^j\theta\right)$ vary as $k,j\rightarrow \infty$.

A very well studied scenario is when $\theta$ is quadratic over $\fqtt$.
%It is well known that $\theta$ has a periodic continued fraction expansion and we can write
%\begin{equation}
%    \theta=[b_0(\theta);b_1(\theta),\dots,b_{m_{\theta}}(\theta),\overline{a_1(\theta),\dots ,a_{l_{\theta}}(\theta)}],
%\end{equation}
%where $(a_1(\theta),\dots ,a_{l_{\theta}}(\theta))$ denotes the periodic part of the continued fraction expansion of $\theta$. 
De Mathan and Teuli\'e proved \cite[Theorem 4.5]{dMT} that
\begin{equation*}
    \limsup_{k,j\rightarrow\infty}d_k\left(t^j\theta\right)=\infty\,.
\end{equation*}
Paulin and Shapira \cite{PS}, relying on an earlier work with Kemarsky \cite{KPS},
improved this result by showing that, on average, a positive proportion of the degrees are unbounded, in the following sense:


%$d>0$ and $m\geq1$, %denote 
%\begin{equation}\label{eq:escape}
%	\esc(\Theta;d,j,m) \defeq \frac{\sum_{k=1}^{m}\max\left\{d_k\left(\theta_j\right)-d,0\right\}}
%	{\sum_{k=1}^{m}d_k\left(\theta_j\right)}.
%\end{equation}
\begin{definition}\label{def:escape}
	For any $\theta\in\fqttt$, $d>0$ and $k\geq1$, the \emph{mass of $\theta$ which lies above $d$ up to the $k$\textsuperscript{th} partial quotient} is 
	\begin{equation}\label{eq:escape}
		\es_\theta(d,k) \defeq \frac{\sum_{k'=1}^{k}\max\left\{d_{k'}-d,0\right\}}
		{\sum_{k'=1}^{k}d_{k'}}\,.
	\end{equation}
%	\usnote{Erez, it was written here $\esc$ and I changed to $\es$}
%	For any sequence $\Theta = \left\{\theta_j\right\}_{j=1}^\infty\sub\fqttt$,
%	the \emph{uniform escape of mass of $\Theta$} is
%    \begin{equation}\label{eq:uniform_escape}
