\subsection{Tilings and diagonally-aligned number walls}
%\usnote{What do you think about this name?} 
We now introduce some terminology in order to state our main Theorem~\ref{thm:main2}, which 
implies Theorem~\ref{thm:main}. We refer the reader to \cite[Section 4]{ALN} for a more thorough exposition of this terminology. 

Let $\Sig$ be a finite set and refer to its elements as \emph{tiles}. A 
%(2-dimensional) 
tiling of a subset $S\sub \bZ^2$ by $\Sig$
is simply a map $T:S\to \Sig$. We think of the tiling as a planar array of tiles where the tile $T(m,n)$ is located at position $(m,n)$. Note that the way we arrange $\bZ^2$ in the plane is \textbf{not} the standard way but the one consistent with matrix notation. That is, as the row index $m$ increases the position advances \emph{downwards}, and as the column index $n$ grows the position advances \emph{rightwards}.

%\usnote{I hid a paragraph here}
\ignore{
The study of the Thue-Morse sequence has a long history. Thue \cite{Thue1912} showed that for every $j\geq0$, $l>0$ and $u\in\{0,1\}^l$ there exists $1\leq n\leq 2l+1$ such that $\tm_{j+n}\neq u_{n \mod l}$ (see \cite{Berstel} for an exposition of Thue's work). In other words, the sequence $\tm$ has the property that all its left-shifts are poorly approximable by periodic sequences. Hence, it is natural to study approximations of $\left\{t^j\tm\right\}_{j=0}^\infty$ by rational functions in $\fttt$.
}

Let  
\begin{equation}\label{eq:no-polynomial-part}
	\theta = \sum_{n=1}^\infty b_n t^{-n}\in \fqttt.
\end{equation} 
It is well known 
%(see~\cite{} for example) 
that many of the Diophantine properties of the Laurent series $\theta$ are encoded in the tiling
\begin{equation}\label{eq:tm_hankel_array}
	\frakh(\theta) \defeq\left\{\frakh_{m,n}(\theta)\right\}_{m=1,n=1}^\infty,
\end{equation}
where for any $m,n\geq1$,
\begin{equation}\label{eq:tm_hankel}
	\frakh_{m,n}(\theta) \defeq \det
	\begin{pmatrix}
		b_{n}&b_{n+1}&\cdots &b_{n+m-1}\\
		b_{n+1}&\iddots&\iddots&b_{n+m}\\
		\vdots&\iddots&\iddots&\vdots\\
		b_{n+m-1}&b_{n+m}&\cdots&b_{n+2m-2}
	\end{pmatrix}
\end{equation}
%\begin{equation}\label{eq:tm_hankel_array}
%	\frakh(\theta) \defeq\left\{\frakh_{i,j}(\theta)\right\}_{i=0,j=0}^\infty,
%\end{equation}
%where for any $i,j\geq0$
%\begin{equation}\label{eq:tm_hankel}
%	%\forall i,j\ge 0,\quad 
%	%\frakh_{i,j}=
%	\frakh_{i,j}(\theta) \defeq \det
%	\begin{pmatrix}
%		\theta_{j+1}&\theta_{j+2}&\cdots &\theta_{j+i+1}\\
%		\theta_{j+2}&\iddots&\iddots&\theta_{j+i+2}\\
%		\vdots&\iddots&\iddots&\vdots\\
%		\theta_{j+i+1}&\cdots&\cdots&\theta_{j+2i+1}
%	\end{pmatrix}
%\end{equation}
is a determinant of a Hankel matrix which corresponds to the sequence $\{b_n\}_{n=1}^\infty$, computed in $\bF_q$.
%\red{Isn't it more natural to define this array so that $\theta_j$ will appear at row 0 column $j$ and not $j-1$?}
More explicitly, for any $k\geq1$, denote 
\begin{equation}\label{eq:diophantine}
i_k=i_k(\theta)\defeq\sum_{k'=1}^kd_{k'}\,,
\end{equation}
where $\left\{d_k\right\}_{k=1}^\infty$ are the degrees of the partial quotients of $\theta$ defined in \eqref{eq:dk}.
%, and $d_0=d_0(\theta)\defeq0$. 
The integer $i_k$ is the degree of the denominator of the $k$\textsuperscript{th} convergent of $\theta$. A standard fact in the theory of Diophantine approximation over function fields \cite[Setion 9]{dT04} is that
\begin{equation}\label{eq:last}
	\begin{aligned}
		\frakh_{i,1}(\theta)\neq0\ 
		&\iff
		\min_{M,N\in\fqt,\;N\neq0,\;\deg N<i} | N\theta - M |=q^{-i}  \\
		&\iff
		i=i_k(\theta) \text{ for some }k\geq1\,,
	\end{aligned}
\end{equation}
where the first equivalence follows by rewriting $| N\theta - M |=q^{-i}$ as a system of linear equations. By \eqref{eq:base-t-expansion} and \eqref{eq:tm_hankel}, the same holds more generally for every $j\geq0$ with $\frakh_{i,j+1}(\theta)$ and $t^{j}\theta$ instead of $\frakh_{i,1}(\theta)$ and $\theta$. It is evident from this and from Definition~\ref{def:escape} that in order to understand the approximations of $\left\{t^j\theta\right\}_{j=0}^\infty$ by rational functions in $\bF_q(t)$ in general and questions about escape of mass in particular, one can study the patterns of zeros in $\frakh(\theta)$.%the tiling \eqref{eq:tm_hankel_array}.

