It should be clear that $\set{\sminus{i}:0\le i\le 3}$ is a $D$-orbit. In fact, for every $0\leq i \leq3$ we have $\sminus{i} = \rho^i\sminus{0}$, the tiles $\sminus{0}$ and $\sminus{2}$ are fixed points for $\eta$, while $\eta\sminus{1}=\sminus{3}$.

To summarise, we have defined the set of basic tiles 
$$\Sig = \set{\splus{i}, \sminus{i}, \tilec{i}:0\le i\le 3}\cup\set{\tiler{a},\tiler{b},\tilo}$$
which consists of $15$ tiles, on which the dihedral group $D$ acts and partition it into five orbits.


Next, we introduce an extra symmetry on $\Sig$ that flips between $\splus{i}$ and $\sminus{i}$ for every $0\leq i\leq3$ and also flips between $\tiler{a}$ and $\tiler{b}$. This extra symmetry is crucial for our analysis. 
Let $$\bbz/2\bbz=\idist{\iota | \iota^2}$$ be a group of order two. 
\begin{definition}\label{def: iota}
%\usnote{I want to replace the notation $\tiler{a}$ by $\mb{r}^\pm$ so that $\iota$ will flip $+$ and $-$.}
The action of $\bbz/2\bbz$ on $\Sigma$ is defined by the following involution: 
\begin{gather*}
	\iota\tilo =\tilo\,,\\
	\begin{align*}
		\iota\tilec{i}&=\tilec{i}\,, &\quad& \textrm{for all $0\le i\le 3$}\,,
	\end{align*}\\
	\begin{align*}
		\iota \tiler{a} &= \tiler{b}\,, &\textrm{ and }& &\iota\tiler{b}&=\tiler{a}\,,&\quad&\\
		\iota \splus{i} &= \sminus{i}\,, &\textrm{ and }& &\iota\sminus{i}&=\splus{i}\,, &\quad& \textrm{for all $0\le i\le 3$}\,.
	\end{align*}
\end{gather*}
\end{definition} 
%As $\iota$ is of order $2$ we refer to it as an involution sometimes. 
The action of $\bbz/2\bbz$ on $\Sig$ commutes with the action of $D$. Therefore, this gives an action of the group
$$G: = D\times\bbz/2\bbz$$
on $\Sig$, where $D$ and $\bbz/2\bbz$ are viewed as subgroups of $G$. The decomposition of $\Sig$ into $G$-orbits is almost identical to the decomposition into $D$-orbits, just that now, the two $D$-orbits $\set{\splus{i}}_{i=0}^3$ and  $\set{\sminus{i}}_{i=0}^3$ become one $G$-orbit of $8$ elements. We have
\begin{equation}\label{eq: Sigma splits to G-orbits}
\Sig = G\splus{0}\cup G\tilec{0}\cup G\tiler{a}\cup G\tilo\,.
\end{equation}


\subsubsection{Actions on matrices}
\newcommand{\tgeo}{T^{\on{geo}}}
%\newcommand{\tinn}{T^{\on{entrie}}}
\newcommand{\tinn}{T^{\on{ent}}}
When one looks at the tiling $\frakf(\tm)$ in different scales and stares at it enough, the graphic depictions of 
the tiles in $\Sig$ emerge (see Figure \ref{fig:thm_flat_large}). 

\begin{figure}[ht]
	\centering
	\includegraphics[width=1\linewidth]{thm_flat_2048.png}
	\caption{The (diagonally-aligned) number wall of the Thue-Morse sequence $\frakf_{m,n}(\tm)$ for $0\leq m\leq2049$ and $1\leq n\leq2050$, where the $0$'s are white and the $1$'s are black.}
	\label{fig:thm_flat_large}
\end{figure}

In order to be able to exploit the $G$-action on these tiles for our cause, it is necessary to generalise this action to an action of $G$ on
square matrices over $\Sig$. There are two natural actions:
\begin{itemize}
\item For $g\in G$ and a matrix $M\in \Mat_n(\Sig)$, let $\tinn_g M$ denote the matrix obtained from $M$ by acting on each of its entries by $g$. It is clear that this defines a $G$-action on $\Mat_n(\Sig)$ for any $n\ge 1$.
\item For $g\in G$ and a matrix $M\in \Mat_n(\Sig)$, let $\tgeo_g M$ denote the matrix obtained from $M$ by acting on it by the isometry of the square $\pi(g)$, where 
$$\pi:G\to D$$ 
is the natural projection. For example, $\tgeo_\iota$ acts trivially, $\tgeo_\rho M$ rotates $M$ by $90\degree$ clockwise and $\tgeo_\eta M$ reflects $M$ along
the anti-diagonal.
It should be clear that this defines an action of $G$ on $\Mat_n(\Sig)$ for any $n\ge 1$.
\end{itemize}
These two actions commute in the sense that for every $n\geq1$ and $M\in\Mat_n(\Sig)$, every $g,h\in G$ satisfy
\begin{equation}\label{eq: commutation of tgeo and tinn}
\tinn_g\tgeo_h M = \tgeo_h\tinn_g M\,.
\end{equation}
In reality we will use a \emph{twisted} combination of these two actions. 
The twist is obtained from an automorphism $\psi:G\to G$, which we now introduce.
\begin{definition}
The function $\psi:G\to G$ is the unique group automorphism which is defined on the generators of $G$ by
\begin{equation}\label{eq:above}
	\psi(\rho) = \iota\rho\,,\quad\psi(\eta) = \iota\eta\,,\quad\psi(\iota) =\iota\,.
\end{equation}
\end{definition}
The reader can verify that there exists a unique automorphism $\psi$ of $G$ that satisfies \eqref{eq:above}. Such a verification amounts to showing that the group generated by $\iota\rho$ and  $\iota\eta$ is isomorphic to $D$ and that it does not contain $\iota$. %\red{Check that you agree}

We now define for any $l\ge 0$ the \emph{twisted action} of $G$ on $\Mat_{2^l}(\Sig)$. This action will extend the $G$-action described above on $\Sig$ which corresponds to the case $l = 0$. 
%In order to be formal, we view such a matrix as a map $a:[1,2^l]^2\to \Sig$. We denote $\pi:G\to D$ the natural %projection and let $D$ act on the square $[1,2^l]^2$ naturally by isometries of the square.

\begin{definition}\label{def: action on matrices}
The action of $G$ on $\Mat_{2^l}(\Sig)$ is as follows: for every $g\in G$ and $M\in\Mat_{2^l}(\Sig)$, the action of $g$ on $M$ is
\begin{equation}\label{eq: action on matrices}
g M \defeq \tgeo_g\tinn_{\psi^l(g)} M\,.
\end{equation}
%$g\cdot a$ to be the matrix defined by 
%$$\forall k\in [1,2^l]^2,\quad (g\cdot a)(k):= \psi^l(g)(a(\pi(g)^{-1}(k))).$$
In words, the action of $g$ on a matrix is defined by the geometric action of $\pi(g)$ as an isometry on the matrix $M$ thought of as a square and the action of $\psi^l(g)$ on each of the entries of the matrix $M$. 
\end{definition}
Note that the commutation \eqref{eq: commutation of tgeo and tinn} implies that this is indeed an action of $G$ on
$\Mat_{2^l}(\Sig)$ for any $l\ge 0$. Also note, that for $l=0$ we recover the action of $G$ on $\Sig$. 
\begin{example}
It is instructive to work out explicitly what happens for $2\times 2$ matrices ($l = 1$):
\begin{align}
\nonumber 
\rho\mat{a&b\\c&d}& =\mat{\psi( \rho) c&\psi( \rho) a\\\psi( \rho)d&\psi( \rho) b}  
= \mat{\iota \rho c&\iota \rho a\\\iota \rho d&\iota \rho b}, \\
\label{eq: acting with eta on 2 matrix}
\eta\mat{a&b\\c&d} &=  \mat{\psi( \eta) d&\psi( \eta) b\\\psi(\eta)c&\psi(\eta) a}
= \mat{\iota\eta d &\iota\eta b\\ \iota\eta c&\iota\eta a},\\
\nonumber \iota \mat{a&b\\c&d} &= \mat{\psi( \iota) a&\psi(  \iota) b\\\psi( \iota)c&\psi( \iota) d}
= \mat{\iota a &\iota b\\ \iota c&\iota d}.
\end{align}
\end{example}

\subsubsection{The $2$-substitution} 
We use the $G$-action on $\Sig$ and on $\Mat_2(\Sig)$ in order to define a $2$-substitution $\sigma:\Sig\to\Mat_2(\Sig)$, while having in mind the equivariance relation $$\sig(gs) = g\sig(s)$$ which we would like to hold. 
Recall that $\Sig$ splits into $4$ orbits of $G$ as in~\eqref{eq: Sigma splits to G-orbits}. The first step is
to define $\sig$ on the set of representatives 
$$\Sig_0:= \set{\splus{0},\tilec{0},\tiler{a},\tilo}.$$
\begin{definition}\label{def: the substitution sigma part 1}
The substitution $\sig$ is defined on $\Sig_0$ as follows:
\begin{align*}
\sig(\splus{0})& = \mat{\splus{0}& \tilec{0}\\ \tiler{a}&\sminus{0}}, &\quad 
\sig(\tilec{0}) &=  \mat{\tilo&\tilo \\ \tilec{0}&\tilo},\\[2pt]
\sig\left(\tiler{a}\right)  &= \mat{\sminus{1}& \splus{2} \\ \splus{0}&\sminus{3}}, &\quad
\sig(\tilo)   &= \mat{\tilo&\tilo \\ \tilo&\tilo}.
\end{align*}
\end{definition}
It is useful to have in mind the graphic depiction of the substitution, which can be generated by putting the depictions of each of the tiles adjacent to each other. For example, the image of $\splus{0}$ and $\tiler{a}$ are
\begin{align*}
\sig(\splus{0}) &=
\scalebox{0.3}{
	\begin{tikzpicture}
		\path  (0,0) pic{tilera};
		\path  (4,0) pic{sminus};
		\path  (0,4) pic{splus};
		\path  (4,4) pic{tilec};
	\end{tikzpicture}
}\,,\quad
&\sig\left(\tiler{a}\right)& = 
	\scalebox{0.3}{
		\begin{tikzpicture}
			\path  (0,0) pic{splus};
			\path[rotate=90,transform shape]  (0,-8) pic{sminus};
			\path[rotate=180,transform shape]  (-8,-8) pic{splus};
			\path[rotate=270,transform shape]  (-8,0) pic{sminus};
		\end{tikzpicture}
	}\,.
\end{align*}

The following lemma is essential for the extension of the definition of $\sig$ from $\Sig_0$ to all of $\Sig$ equivariantly.
\begin{lemma}	
\label{lem: stabilizer}
Every $s\in \Sig_0 = \set{\splus{0},\tilec{0},\tiler{a},\tilo}$
satisfies
\begin{equation}\label{eq: inclusion of stabilizers}
\on{Stab}_G(s) \leq \on{Stab}_G(\sig(s))\,.
\end{equation}
\end{lemma}
\begin{proof}
The proof follows by checking \eqref{eq: inclusion of stabilizers} for every $s\in \Sig_0$. Start with $s = \splus{0}$. Since $\av{G}=16$ and $\av{G\splus{0}}=8$, 
the stabilizer group $\on{Stab}_G(\splus{0})$ has $2$ elements. Since it contains the involution $\eta$, it must be equal to $\idist{\eta}$. Acting with $\eta$ on $\sig(\splus{0})$ using the twisted $G$-action, equation \eqref{eq: acting with eta on 2 matrix} gives
$$\eta\sig(\splus{0}) = \eta\mat{\splus{0}& \tilec{0}\\ \tiler{a}&\sminus{0}}
=\mat{\iota\eta \sminus{0}&\iota\eta \tilec{0}\\\iota\eta \tiler{a}&\iota \eta \splus{0}}=
\mat{\splus{0}& \tilec{0}\\ \tiler{a}& \sminus{0}},$$
so $\eta\in\on{Stab}_G(\sig(\splus{0}))$.

Proceed with $s = \tiler{a}$. The orbit $G\tiler{a}$ has $2$ elements and hence its stabilizer group is of order $8$. It clearly contains $\rho$ and $\iota\eta$ (since both $\iota$ and $\eta$ switch between $\tiler{a}$ and $\tiler{b}$). Since the group $\idist{\rho,\iota\eta}$ has $8$ elements, it is $\on{Stab}_G\left(\tiler{a}\right)$. Thus, in order to verify \eqref{eq: inclusion of stabilizers} it is enough to show that $\rho$ and $\iota\eta$ stabilize $\sig\left(\tiler{a}\right)$. 
Working with the definition of the twisted action on matrices (see \eqref{eq: acting with eta on 2 matrix}) gives
\begin{align*}
\rho\sig\left(\tiler{a}\right) 
&= 
\rho\mat{\sminus{1}& \splus{2} \\ \splus{0}&\sminus{3}} 
= 
\mat{ \psi(\rho) \splus{0}&  \psi(\rho)\sminus{1} \\  \psi(\rho)\sminus{3} & \psi(\rho) \splus{2}}
\\[1.5pt]
&= 
\mat{ \iota\rho \splus{0}& \iota\rho\sminus{1} \\ \iota\rho\sminus{3} & \iota\rho\splus{2}}  
= 
\mat{\sminus{1}& \splus{2} \\ \splus{0}&\sminus{3}}.
\end{align*}
Similarly, 
\begin{align*}
\eta\iota\sig\left(\tiler{a}\right) 
&= 
\eta\iota\mat{\sminus{1}& \splus{2} \\ \splus{0}&\sminus{3}} 
= 
\mat{ \psi(\eta\iota) \sminus{3}&  \psi(\eta\iota) \splus{2}  \\  \psi(\eta\iota)\splus{0}& \psi(\eta\iota) \sminus{1}}
\\[1.5pt]
&=
\mat{\eta \sminus{3}& \eta  \splus{2}  \\  \eta \splus{0}&\eta  \sminus{1}} 
=
\mat{\sminus{1}& \splus{2} \\ \splus{0}&\sminus{3}}.
\end{align*}

Next, equation \eqref{eq: inclusion of stabilizers} is verified for $s=\tilec{0}$. As for the previous cases, it is easy to see that since the 
orbit has $4$ elements, the stabilizer is of order $4$, so it must be $\idist{\eta,\iota}$. Therefore, it is enough to check that $\iota,\eta\in \on{Stab}_G(\sig(\tilec{0}))$. Indeed,
$$\eta\sig(\tilec{0}) = \eta \mat{\tilo&\tilo \\ \tilec{0}&\tilo} = 
\mat{\psi(\eta)\tilo&\psi(\eta)\tilo \\ \psi(\eta)\tilec{0}&\psi(\eta)\tilo}=
\mat{\eta\iota\tilo&\eta\iota\tilo \\ \eta\iota\tilec{0}&\eta\iota\tilo} =
\mat{\tilo&\tilo \\ \tilec{0}&\tilo}. $$
Similarly,
$$\iota\sig(\tilec{0}) = \iota \mat{\tilo&\tilo \\ \tilec{0}&\tilo} = 
\mat{\psi(\iota)\tilo&\psi(\iota)\tilo \\ \psi(\iota)\tilec{0}&\psi(\iota)\tilo}=
\mat{\iota\tilo&\iota\tilo \\ \iota\tilec{0}&\iota\tilo} =
 \mat{\tilo&\tilo \\ \tilec{0}&\tilo}. $$
Finally, the verification of \eqref{eq: inclusion of stabilizers} for $s=\tilo$ is left to the reader.
\end{proof}
Given Lemma~\ref{lem: stabilizer}, we extend the definition of $\sig$ to all of $\Sig$ as follows:
\begin{definition}\label{def: the substitution  sigma part 2}
For any $s\in \Sig$, write $s = gs_0$ for some $s_0\in \Sig_0$ and $g\in G$. 
Then
$$\sig(s) = \sig(gs_0): = g\sig(s_0)\,,$$
where $\sig(s_0)$ is as in Definition~\ref{def: the substitution sigma part 1}.
\end{definition}

This is well defined. Indeed, 
if $s = g_1s_1=g_2s_2$ for some $s_1,s_2\in \Sig_0$, then by construction $s_1=s_2$ and $g_2^{-1}g_1\in \on{Stab}_G(s_1)$. So, by Lemma~\ref{lem: stabilizer} $g_2^{-1}g_1\in \on{Stab}_G(\sig(s_1))$, which implies that $g_1\sig(s_1)=g_2\sig(s_2)$, as needed.

As hinted above, the commutation relation $\sig(gs) = g\sig(s)$ for $s\in \Sig$ will be a key feature in our ability to analyse this substitution. It is the seed that propagates and governs the symmetries in $\sig^\infty(\splus{0})$.
\begin{proposition}\label{prop: equivariance}
The $G$-actions on $\Sigma$ and on $\Mat_2(\Sig)$ commute with $\sigma$. More explicitly, every $g\in G$ and $s\in \Sig$ satisfy
\begin{equation}\label{eq:equivariance}
	\sig(gs) = g\sig(s)\,.
\end{equation}
\end{proposition}  
\begin{proof}
By Definition~\ref{def: the substitution  sigma part 2} this is almost a tautology, but there is still something to check: given $g\in G$ and $s\in \Sig$, write $s=g_0s_0$ for some $g_0\in G$ and $s_0\in \Sig_0$. Definition~\ref{def: the substitution  sigma part 2} gives
$$\sig(gs) = \sig(gg_0s_0) = gg_0\sig(s_0)\,.$$
On the other hand, by the same definition,
$$g\sig(s) = g\sig(g_0s_0) = gg_0\sig(s_0)\,,$$
which finishes the proof. 
\end{proof}
The readers are encouraged to calculate $\sig^l(\splus{0})$ for small values of $l$ by themselves or to look ahead at Example~\ref{example: first iterations} and Figure~\ref{fig:thm_infls}.

