			AD=BC=0\,,\quad\textrm{ or }\quad A=B=C=D=1\,.
		\end{equation}
		\item The outer frame relation is
		\begin{equation}\label{eq:outer-frame-f2}
			E+F=G+H\,.
		\end{equation}
	\end{itemize}

\end{itemize}
