\section{The tiling and its structure}\label{sec:tiling}
In this section the tilings $\sigma^\infty(\splus{0})$ and $\kappa_1\left(\sigma^\infty(\splus{0})\right)$ are analysed. This analysis is based on the symmetries in the definition of $\sigma$ and $\kappa$ and the extension of the $G$-action to large square patterns over $\Sigma$. The outcome of the analysis is a proof of Theorem \ref{thm:main2}.
\subsection{The structure of $\sig^\infty(\splus{0})$}
The following lemma and corollary explore further the $G$-action on large patterns.
\begin{lemma}
Let $l\ge 1$ and let
$\smallmat{A&B\\C&D}\in \Mat_{2^{l+1}}(\Sig)$. Then,
\begin{align}
\label{eq: rho on blocks}
\rho \mat{A&B\\C&D}& = \mat{\iota \rho C&\iota \rho A\\ \iota \rho D&\iota \rho B},\\
%,\quad 
%\eta \mat{\eta D&\eta B\\ \eta C&\eta A}\\
%
\label{eq: eta on blocks}
\eta \mat{A&B\\C&D} &= \mat{\iota \eta D&\iota \eta B\\ \iota \eta C&\iota\eta A},\\
%,\quad 
%\eta \mat{\eta D&\eta B\\ \eta C&\eta A}\\
%
\label{eq: iota on blocks}
\iota \mat{A&B\\C&D}& = \mat{\iota A&\iota B\\ \iota C&\iota D}.
%\quad 
%\iota \mat{\iota D&\iota B\\ \iota C&\iota A}\\
\end{align}
\end{lemma}
\begin{proof}
Start with \eqref{eq: iota on blocks}. 
Recall Definition~\ref{def: action on matrices}, that $\tgeo_\iota$ acts trivially and that $\psi^k(\iota)=\iota$ for any $k\in\bbz$. Therefore,
\begin{align*}
\iota \mat{A&B\\C&D} &= \tinn_\iota  \mat{A&B\\ C&D} = 
\mat{\tinn_\iota A&\tinn_\iota B\\ \tinn_\iota C&\tinn_\iota D} 
=\mat{\iota A&\iota B\\ \iota C&\iota D} 
%\\
%&=  \smallmat{\sig(\iota A)&\sig(\iota B)\\ \sig(\iota C)&\sig(\iota D)} = \sig(\iota M).
\end{align*}
For \eqref{eq: rho on blocks}, note that on the geometric level
$$\tgeo_\rho\mat{A&B\\ C&D} = \mat{\tgeo_\rho C &\tgeo_\rho A \\ \tgeo_\rho D&\tgeo_\rho B}.$$
Also, since any $l\ge 1$ satisfies 
$$
\psi^{l+1}(\rho) = \iota\psi^l(\rho)\,,
$$
this implies that
\begin{align*}
\rho  \mat{A&B\\ C&D}
&= 
\tinn_{\psi^{l+1}(\rho)} \tgeo_\rho\mat{A& B\\ C&D} 
\\[1.5pt]
&=\tinn_\iota \tinn_{\psi^{l}(\rho)} \mat{\tgeo_\rho C & \tgeo_\rho A\\ \tgeo_\rho D&\tgeo_\rho B} 
\\[3pt]
&=\iota \mat{\tinn_{\psi^l(\rho)}\tgeo_\rho C &\tinn_{\psi^l(\rho)} \tgeo_\rho A\\ \tinn_{\psi^l(\rho)}\tgeo_\rho D&\tinn_{\psi^l(\rho)}\tgeo_\rho B}
\\[1.5pt] 
&=  \iota \mat{\rho C & \rho A 
\\ \rho D& \rho B}
%line break
\\
&=  \mat{\iota \rho C  &\iota\rho A\\ 
\iota\rho D&\iota\rho B}.
%= \sig \tinn_{\psi^{l+1}(\rho)}\tgeo_\rho \smallmat{A&B\\ C&D } = \sig(\rho M).
\end{align*}
A similar reasoning shows \eqref{eq: eta on blocks}.
\end{proof}
The following statement is the propagation of the equivariance in Proposition~\ref{prop: equivariance} from 
basic tiles to larger patterns:
\begin{corollary}\label{cor:key}
	For every $s\in\Sigma$, $g\in G$ and $l\geq0$, the $l$\textsuperscript{th} iteration of $\sig$ satisfies 
	\begin{equation*}%\label{eq:reminiscent}
		\sigma^l(g s) = g\sigma^l\left(s\right).
	\end{equation*}
\end{corollary}
\begin{proof}
By induction on $l$. The base of the induction is Proposition \ref{prop: equivariance}. In the inductive step it is assumed that for some $l\geq0$, every $g\in G$ and $M\in \Mat_{2^l}(\Sig)$ satisfy
\begin{equation}\label{eq: equivariance2}
\sig(g M) = g\sig(M)\,.
\end{equation}
Due to the axioms of a group action, in order to complete the inductive step it is enough to check \eqref{eq: equivariance2} for $g \in \{\iota, \rho, \eta\}$ and every $M\in \Mat_{2^{l+1}}(\Sig)$. This identity will then propagate to any $g\in G$. Fix
$M = \smallmat{A&B\\C&D}\in \Mat_{2^{l+1}}(\Sig)$, where $A,B,C,D\in \Mat_{2^l}(\Sig)$. 
For $g=\iota$, using \eqref{eq: iota on blocks} and the inductive hypothesis gives
$$\iota \sig\mat{A&B\\ C&D} 
= 
\mat{\iota \sig( A)&\iota \sig(B)\\ \iota \sig( C)&\iota\sig( D)} 
=
\mat{\sig(\iota A)&\sig(\iota B)\\ \sig(\iota C)&\sig(\iota D)}
=
\sig\iota\mat{A&B\\ C&D}.
$$ 
For $g=\rho$, using \eqref{eq: rho on blocks} and the inductive hypothesis gives
$$\rho \sig\mat{A&B\\ C&D} 
= 
\mat{\iota \rho \sig( C)&\iota\rho \sig(A)\\ \iota\rho \sig( D)&\iota \rho\sig( B)} 
=
\mat{\sig(\iota \rho C)&\sig(\iota \rho C)\\ \sig(\iota \rho D)&\sig(\iota\rho B)}
=
\sig\rho\mat{A&B\\ C&D}.$$
For $g=\eta$ one uses \eqref{eq: eta on blocks} and the inductive hypothesis in a similar fashion.
\end{proof}

\begin{remark}
Corollary \ref{cor:key} with $s=\splus{0}$ and $g=\iota$ is a two dimensional manifestation of a standard observation about the Thue-Morse sequence, which is that $\mu^l(\tileb)$ equals $\mu^l(\tilea)$ in reversed order whenever $l$ is odd, where $\mu$ is defined in \eqref{eq:tm-substitution}.
\end{remark}
