\begin{lemma}\label{lem:sigma0_diagonal}
For any $l\geq0$, the main diagonal of $\sigma^l(\splus{0})$ is the Thue-Morse sequence on the symbols
$\splus{0}$ and $\sminus{0}$ of length $2^l$. The diagonal which lies just above it is a sequence of $\tilec{0}$'s, and apart from that every entry above the main diagonal is $\tilo$. A similar statement
holds for $\sig^\infty(\splus{0})$. Analogous statements hold for $\sigma^l(\sminus{0})$ and $\sig^\infty(\sminus{0})$.
\end{lemma}
\begin{proof}
The claims about the main diagonals follow by inspecting the main diagonals of 
\begin{align*}
	\sigma(\splus{0}) &= \mat{\splus{0}& \tilec{0} \\ \tiler{a}&\sminus{0}}, &&\textrm{ and } &\sigma(\sminus{0}) &= \mat{\sminus{0} &\tilec{0} \\ \tiler{b} & \splus{0}}.
\end{align*} 
The claims about the diagonals above them follow by also inspecting 
\begin{align*}
	\sigma(\tilec{0}) &= \mat{\tilo &\tilo\\ \tilec{0} &\tilo}, &&\textrm{ and } &\sigma(\tilo) &= \mat{\tilo&\tilo\\ \tilo&\tilo}.
\end{align*}
The reader should consult Example~\ref{example: first iterations}.
\end{proof}
