We will use the following terminology: 

\begin{definition}
	Let $\wh{\Sig}$ is a finite set of tiles and $P:\{1,\ldots,m\}\to\wh{\Sig}$ be a finite sequence of tiles from $\wh{\Sig}$.
	\begin{enumerate}
		\item The sequence $P^k$ is the concatenation of $P$ with itself $k$ times, i.e., every $1\leq i \leq m$ and $0\leq k'<k$ satisfies
		$$
		P^k(i+k'm) = P(i)\,.
		$$ 
		\item A finite sequence $P'$ of tiles from $\wh{\Sig}$ is \emph{periodic with period $P$} if there exists $k\ge 1$ such that $P'$ starts with $P^k$ and $P^{k+1}$ starts with $P'$.
	\end{enumerate}
\end{definition}

The following lemma allows us to identify when a
$1$-dimensional substitution tiling is periodic with a given period. Its proof is left to the reader.

\begin{lemma}\label{lem: periodic}
Let $\wh{\Sig}$ be a finite set and $\wh{\sig}:\wh{\Sig}\to\wh{\Sig}^k$ be a $1$-dimensional $k$-substitution on $\wh{\Sig}$, where $k\ge2$.  
If $s\in \wh{\Sig}$ and $l_0\ge 0$ satisfy that 
%all sequences of length 2 that appear in $\wh{\sig}^{l_0+1}(s)$ appear already in 
%$\wh{\sig}^{l_0}(s)$ and if 
both $\wh{\sig}^{l_0}(s)$ and 
$\wh{\sig}^{l_0+1}(s)$ are periodic with period $P$, then 
$\wh{\sig}^l(s)$ is periodic with period $P$ for any $l\ge l_0$.
\end{lemma}

