\subsection{Applying the coding}\label{sec:applying-the-coding}

Prior to the consideration of $\kappa_1\left(\sigma^\infty(\splus{0})\right)$, the following observation is useful:

\begin{lemma}\label{lem:consistent}
	The coding $\kappa$ and the tiling $\sigma^\infty(\splus{0})$ are consistent with respect to an overlap of length $1$, in the sense of \cite[Definition 4.8]{ALN}.
\end{lemma}

\begin{proof}
	The claim means that every square pattern of size $2$	
	$$\begin{array}{cc}
		a & b \\
		c & d
	\end{array}$$
	which is contained in $\sigma^\infty(\splus{0})$, satisfies 
	\begin{equation}\label{eq:consistent1}
		\left.\kappa(a)\right|_{[1,5]\times\{5\}} = \left.\kappa(b)\right|_{[1,5]\times\{1\}}\quad \text{and} \quad 
		\left.\kappa(c)\right|_{[1,5]\times\{5\}} = \left.\kappa(d)\right|_{[1,5]\times\{1\}}\,,
	\end{equation}
	and
	\begin{equation}\label{eq:consistent2}
	\left.\kappa(a)\right|_{\{5\}\times[1,5]} = \left.\kappa(c)\right|_{\{1\}\times[1,5]}\quad\text{and}\quad
	\left.\kappa(b)\right|_{\{5\}\times[1,5]} = \left.\kappa(d)\right|_{\{1\}\times[1,5]}\,.
	\end{equation} 
	It is a finite check verified with a computer program that there are $64$ square patterns of size $2$ in both $\sigma^5(\splus{0})$ and $\sigma^6(\splus{0})$ (see Figure \ref{fig:thm_infls}). Therefore, these are precisely the square patterns of size $2$ in $\sigma^\infty(\splus{0})$ (cf. \cite[Lemma 4.14]{ALN}). Verifying \eqref{eq:consistent1} and \eqref{eq:consistent2} for them is a finite check which is done with a computer program.%Modulo the group generated by $\rho$, this number is reduced to $19$. 
\end{proof}

\begin{convention}\label{conv: overlap}
Due to Lemma \ref{lem:consistent}, and following \cite[Section 4.3]{ALN}, it makes sense to extend the definition of the image under $\kappa_1$ of any rectangular pattern $P$ in $\sigma^\infty(\splus{0})$ by one column and one row. This means that if $P$ is a rectangular pattern of height and width $m\times n$ of tiles in $\Sig$, then $\kappa_1(P)$ is a rectangular pattern of height and width $(4m+1)\times(4n+1)$ of tiles in $\ft$ which is composed out of the images under $\ka$ of the tiles in $P$ stacked together with an overlap of length $1$. 
\end{convention}
\begin{convention}\label{conv: overlap2}
	In order to handle overlaps as in Convention \ref{conv: overlap}, it is helpful to introduce the following notation: given $k,l,m,n\geq1$ and $mn$ matrices of height and width $k+1$ and $l+1$, such that
	\begin{align*}
		A_{i,j}(k,\cdot) &= A_{i+1,j}(1,\cdot)\,,
		&&\textrm{for every $1\leq i\leq m-1$ and $1\leq j\leq 	n\,,$} &&\textrm{and}\\
		A_{i,j}(\cdot,l) &= A_{i,j+1}(\cdot,1)\,,&&
		\textrm{for every $1\leq i\leq m$ and $1\leq j\leq n-1$}\,,&&
	\end{align*}
 	then the matrix with square brackets
	\begin{equation}\label{eq:convention}
	\br{\begin{array}{ccc}
			A_{1,1}&\cdots&A_{1,n}\\
			\vdots &\vdots & \vdots\\ 
			A_{m,1}&\cdots&A_{m,n}
		\end{array}
	}
	\end{equation}
	is a matrix of height $km+1$ and width $ln+1$ which is composed out of the matrices $A_{i,j}$ arranged as blocks in a combined matrix in a way so that any two adjacent matrices overlap in $1$ row or column according to their respective position. Formally, for every $1\leq i \leq km+1$ and $1\leq j \leq ln+1$, denote 
	\begin{align*}
		i'&= 	\min\left\{\left\lceil\frac{i}{k}\right\rceil,m\right\},&&\textrm{ and } &
		j'&=
		\min\left\{\left\lceil\frac{j}{l}\right\rceil,n\right\}.
	\end{align*}
	Then the $(i,j)$\textsuperscript{th} entry of the matrix in \eqref{eq:convention} is
	$$
	A_{i',j'}
	\left(
	i - k\left(i'-1\right),
	j - l\left(j'-1\right)
	\right).
	$$
\end{convention}

These two conventions are particularly useful for the statement and proof of the following lemma regarding the symmetries of $\kappa_1$ with respect to the action of $\rho$.

\begin{lemma}\label{lem: kappa equivariance}
For every $l\ge 0$ and $s\in \Sig$ the image of $\rho \sig^l(s)$ under $\kappa_1$ satisfies
\begin{equation}\label{eq: kappa equiv}
\ka_1\left(\rho \sig^l(s)\right) = \rho \ka_1\left(\sig^l\left(\iota^l s\right)\right)\,.
\end{equation}
\end{lemma}
\begin{proof}
The proof is by induction on $l$. For $l=0$, equation \eqref{eq: kappa equiv} reads as 
$\ka_1(\rho(s)) = \rho\ka_1(\rho s)$. This equality holds by the way $\ka_1$ was defined, which equals $\ka$ by Convention~\ref{conv: overlap} -- on representatives of $\rho$-orbits and extended by the action of $\rho$. 

Assuming that the equality \eqref{eq: kappa equiv}  holds for all $s\in \Sig$ for some $l\ge 0$, it will be proved that it holds for all $s\in \Sig$ for $l+1$. Given any tile $s\in \Sig$, there are tiles $s_1,s_2,s_3,s_4\in\Sig$ such that
$$
\sig(s) = \mat{s_1 &s_2\\ s_3&s_4}.
$$ 
Therefore,
$$\sig^{l+1}(s) = \mat{\sig^l(s_1) &\sig^l(s_2)\\ \sig^l(s_3)&\sig^l(s_4)}.$$
By \eqref{eq: rho on blocks} and Corollary~\ref{cor:key}, this gives that
$$\rho\sig^{l+1}(s) 
= 
\mat{
\rho\iota\sig^l(s_3) &\rho\iota \sig^l(s_1)\\ \rho\iota \sig^l(s_4)&\rho\iota\sig^l(s_2)
}
=
\mat{
\rho \sig^l(\iota s_3)&\rho \sig^l(\iota s_1)\\ \rho \sig^l(\iota s_4)&\rho\sig^l(\iota s_2)
}
.$$
Therefore,
\begin{equation}\label{eq: non-trivial}
\ka_1\left(\rho \sig^{l+1}(s)\right) =  \br{\begin{array}{cc}
\ka_1\left(\rho \sig^l(\iota s_3)\right)&\ka_1\left(\rho \sig^l(\iota s_1)\right)\\[2pt]
\ka_1\left(\rho \sig^l(\iota s_4)\right)&\ka_1\left(\rho \sig^l(\iota s_2)\right)
\end{array}
}.
\end{equation} 
The right hand side of \eqref{eq: non-trivial} needs to be interpreted correctly: 
each block $\ka_1\left(\rho\sig^l(\iota s_i)\right)$ is of size $2^{l+2}+1$ by convention, and they are arranged in the combined matrix such that any two adjacent matrices overlap in $1$ row or column according to their respective position in the block matrix. This way they make together a matrix of size $2^{l+3}+1$ as they should. 
%The square brackets are used in order to indicate that this convention is being used. 

The fact that the four blocks within these square brackets can be glued like that in a consistent way requires a justification. Indeed, Corollary~\ref{cor:key} implies that $\rho$ and $\sig^l$ commute. Therefore, each of the $4$ blocks of \eqref{eq: non-trivial} appear in $\sig^\infty(\splus{0})$, and thus this consistency property is satisfied by Lemma~\ref{lem:consistent}. 

The equality in \eqref{eq: non-trivial} is then immediate: the application of $\ka_1$ is by Convention~\ref{conv: overlap} obtained by applying $\ka$ to all the entries of a matrix and gluing the resulting $5\times 5$ matrices over $\bF_2$
with an overlap of length $1$. The right hand side of \eqref{eq: non-trivial} is the exact same procedure taking into account the square bracket notation in Convention~\ref{conv: overlap2}. 

To finish, the inductive hypothesis and Corollary~\ref{cor:key} are applied to \eqref{eq: non-trivial} in order to conclude that
\begin{align*}
\ka_1\left(\rho \sig^{l+1}(s)\right)& = 
  \br{
\begin{array}{cc}
\rho\ka_1\left(\sig^l\left(\iota^{l+1}s_3\right)\right)&\rho\ka_1\left(\sig^l\left(\iota^{l+1}s_1\right)\right)\\
\rho\ka_1\left( \sig^l\left(\iota^{l+1}s_4\right)\right)&\rho\ka_1\left(\sig^l\left(\iota^{l+1}s_2\right)\right)
\end{array}
}\\[3pt]
&=
\rho \br{
\begin{array}{cc}
\ka_1( \sig^l(\iota^{l+1}s_1))&\ka_1(( \sig^l(\iota^{l+1}s_2))\\
\ka_1( \sig^l((\iota^{l+1}s_3) )&\ka_1((\sig^l(\iota^{l+1}s_4))
\end{array}
}
\\[1.5pt]
&=
\rho \ka_1\left(\sig^{l+1}\left(\iota^{l+1}s\right)\right),
\end{align*}
where the last equality follows from \eqref{eq: iota on blocks}.

\end{proof}
