\section{Escape of mass of the Thue-Morse sequence}\label{sec:uniform-escape-of-mass}
In this section we compute the escape of mass of $t^j\tm$ where $\tm$ is the Thue-Morse sequence thought of as a series in $\ftttt$. Escape of mass is expressed in Definition~\ref{def:escape} in terms of degrees of partial quotients of Laurent series. As we explain shortly, these degrees are tightly related to the length of consecutive zeros in number walls. However, in order to use the self-similarity of the number wall $\frakf(\alpha)$, it is convenient to extend the definition of escape of mass to number walls in general.

\subsection{Motivational picture}
We start by explaining an intuitive picture that motivates our discussion and terminology. Imagine a space $X$ partitioned into a sequence of subsets $X = \bigsqcup_{i=0}^\infty X_i$. The function $\mb{h}:X\to\bZ_{\ge 0}$ defined by $\mb{h}(x) =i\iff x\in X_i$ will be thought of as a height function, and so we think of $X$ as a tower with $X_i$ being the $i$\textsuperscript{th} floor. Imagine that there is a map $T:X\to X$ having the following two properties:
\begin{enumerate}
\item For all $x\in X$, $\mb{h}(T(x))\in \set{\mb{h}(x)+1, \mb{h}(x)-1}\cap \bZ_{\ge 0}$. That is, the height must change under the action of $T$ and cannot change by more than one.
\item If $\mb{h}(x) = i>0$, and $\mb{h}(T(x))=i-1$, then for any $0\le j\le i$, $\mb{h}(T^j(x)) = i-j$. That is, once an orbit starts going down, it will go down until it reaches floor $0$.
\end{enumerate}
Fix $x\in X_0$ and suppose we are given a sequence $P=\set{P_i}_{i=1}^\infty\in \bF_q^\bN$ with the property that 
$P_i \ne 0\iff T^i(x)\in X_0$. Then, we can recover the height of $T^i(x)$ by studying the $0$'s in the sequence $P$: each time we see in the sequence $P$ a pattern of the form $P_l,0,\dots, 0,P_{l+r}$, with $P_l\cdot P_{l+r}\ne 0$, then it follows that $r$ is even and the height of $T^{l+i}(x)$  satisfies 
\begin{equation}\label{eq:motivational}
	\mb{h}\left(T^{l+i}(x)\right) = \begin{cases}
	i & \mbox{ for } 0\le i\le r/2\\
	r/2 - (i-r/2) &\mbox{ for } r/2+1\le i \le r.
	\end{cases}
\end{equation}
This is exactly what happens behind the scenes when one restricts attention to a sequence that appears as a column (or a row) of a diagonally-aligned number wall. 

\subsection{Escape of mass for sequences}
In this section we develop the terminology which is necessary for the consideration of escape of mass in the context of general sequences over a finite field.
\begin{definition}\label{def:escape-for-sequences}
	Let $P:[m_1,m_2]\to \fq$ be any sequence over $\fq$ which is not identically zero. The \emph{height of $P$} is a function $\height_P:[m_1,m_2]\to\bbn$ defined by
	$$
	\height_P(i) \defeq \min_{P(i')\neq0} |i'-i|\,.
	$$
	The \emph{escape of mass of $P$} is a function $\esc_{P}:\bbn\to\bbn$ defined by
	$$
	\esc_P(d) \defeq \frac{\#\left\{m_1\leq i<m_2 \sep \max\left\{\height_P(i),\height_P(i+1)\right\}>d\right\}}{m_2-m_1}\,.
	$$
We refer to $\esc_P(d)$ as \emph{the mass of $P$ that lies above height $d$}.
\end{definition}

A basic tool that will be used several times later in this section is the ability to compute the escape of mass of a finite sequence by considering a partition of it into subsequences. In the statement of the next lemma we will use the square bracket notation that was introduced in Convention~\ref{conv: overlap2}.

\begin{lemma}\label{lem:gluing}
	Let $P':[0,m']\to \fq$ and $P'':[0,m']\to \fq$ be sequences over $\fq$ such that $P'(m')=P''(0)$, and set 
	$$P=\br{\begin{array}{c} P'\\P'' \end{array}}.$$
	Assume that $P'$ ends with precisely $0\leq d'<m'$ consecutive $0$'s while $P''$ starts with precisely $0\leq d''<m''$ consecutive $0$'s.
	Then for every $d$ which satisfies
	\begin{equation}\label{eq:overlap}	
		\max\{d',d''\}\leq d\,,
	\end{equation}
	the mass of $P$ which lies above $d$ satisfies 
	$$
	\esc_P(d) = 	\frac{m'}{m'+m''}\esc_{P'}(d)+\frac{m''}{m'+m''}\esc_P(d)\,.
	$$
\end{lemma}
\begin{proof}
	For every $d$ as in \eqref{eq:overlap}, the height functions satisfy 
	\begin{equation}\label{eq:PP}
		\begin{aligned}
			\height_{P'}(i) &> d \; \textrm{if and only if} \;	\height_{P}(i) > d\,,\; \textrm{for every} \; 0\leq i<m'\,,\; \textrm{and}\\
			\height_{P''}(i) &> d \; \textrm{if and only if} \;	\height_{P}(m'+i) > d\,,\; \textrm{for every} \; 0\leq i<m''\,.
		\end{aligned}
	\end{equation}
	The first line in \eqref{eq:PP} will be proved and the second line follows by symmetry. Since $P'$ is a subsequence of $P$, it satisfies $\height_{P}(i) \leq \height_{P'}(i)$. Therefore, it is enough to show that if $\height_{P'}(i) > d$, then $\height_{P}(i) > d$. By assumption, $P(m'-d')\neq0$, so $\height_{P}(i)=\height_{P'}(i)$ for every $0\leq i\leq m'-d'$, and it is enough to consider $i>m'-d'$. Moreover, for any $m'-d' < i < m'$, the height function satisfies $$\height_{P'}(i) = i+1 - (m'-d')\leq d'\,.$$ 
	Since $d'\leq d$ by \eqref{eq:overlap}, this finishes the argument for \eqref{eq:PP}. Using \eqref{eq:PP} gives
	\ignore{\begin{align*}
		&\#\left\{0\leq i<m'+m'' \sep \max\left\{\height_P(i),\height_P(i+1)\right\}>d\right\}
		\\
		&=\#\left\{0\leq i<m' \sep \max\left\{\height_{P'}(i),\height_{P'}(i+1)\right\}>d\right\} + \#\left\{m'\leq i<m'' \sep \max\left\{\height_{P''}(i),\height_{P''}(i+1)\right\}>d\right\}
		\\
	\end{align*}}
	%Therefore,
	\begin{align*}
		\esc_P(d) &= \frac{\#\left\{0\leq i<m'+m'' \sep \max\left\{\height_P(i),\height_P(i+1)\right\}>d\right\}}{m'+m''}
		\\
		&=
		\frac{m'}{m'+m''}\frac{\#\left\{0\leq i<m' \sep \max\left\{\height_{P'}(i),\height_{P'}(i+1)\right\}>d\right\}}{m'} + 
		\\
		&\phantom{=} \frac{m''}{m'+m''}\frac{\#\left\{0\leq i<m'' \sep \max\left\{\height_{P''}(i),\height_{P''}(i+1)\right\}>d\right\}}{m''}
		\\
		&=
		\frac{m'}{m'+m''}\esc_{P'}(d) + \frac{m''}{m'+m''}\esc_{P''}(d)
		\,.
	\end{align*}
	\ignore{\item Since $|i'-i''|\leq m$,
		\begin{align*}
			\height_Q(i)&>d\,, &&\textrm{ if and only if } &\height_P(i)&>d\,, \textrm{ for every $0\leq i< m'$ and }\,,\\
			\height_Q(i+m+m')&>d\,, &&\textrm{ if and only if } &\height_{P'}(i)&>d\,, \textrm{ for every $0\leq i< m''$}\,.\\
		\end{align*}
		Therefore,
		\begin{align*}
			&\#\left\{0\leq i<m+m'+m'' \sep \max\left\{\height_Q(i),\height_Q(i+1)\right\}>d\right\}
			\\
			&=\#\left\{0\leq i<m' \sep \max\left\{\height_{P'}(i),\height_{P'}(i+1)\right\}>d\right\} + \#\left\{m'\leq i<m'' \sep \max\left\{\height_{P''}(i),\height_{P''}(i+1)\right\}>d\right\}
			\\
		\end{align*}}
\end{proof}

Finally, we will also need the computation of the escape of mass for a basic building block which is composed out of a stretch of $0$'s between nonzero elements. 
\begin{lemma}\label{lem:basic}
	For any $r>0$ let $P:[0,r]\to \fq$ be a sequence which satisfies $P(i) = 0$ if and only if $0<i<r$. 
	Then for every $d$, the escape of mass of $P$ satisfies
	\begin{equation}\label{eq:motivational-escape}
		\esc_{P}(d) = \frac{2\max\{r/2-d,0\}}{r}\,.  
	\end{equation}
\end{lemma}
\begin{proof}
	As in \eqref{eq:motivational}, the height function of $P_r$ satisfies 
	\begin{equation*}
		\height_{P}(i)= 
		\begin{cases}
			i & \mbox{ for } 0\le i\le r/2\\
			r - i &\mbox{ for } r/2 < i \le r.
		\end{cases}
	\end{equation*}
	Therefore, for every $d$,
	\begin{align*}
		\esc_{P}(d) &= \frac{\#\left\{0\leq i< r\sep \height_{P}(i)>d \right\}}{r} \\
		& = \frac{2\#\left\{0\leq i \leq r/2\sep \height_{P}(i)>d \right\}}{r} 
		\\
		&= \frac{2\max\{r/2-d,0\}}{r}\,.
	\end{align*}
	as claimed.
\end{proof}

\subsection{Partial escape of mass}

We will show now that for $\theta=\{b_n\}_{n=1}^\infty$ thought of also as the Laurent series $\theta=\sum_{n=1}^\infty b_nt^{-n}\in\fqttt$, Definition~\ref{def:escape-for-sequences} applied to the first column of $\frakf(\theta)$ agrees with Definition \ref{def:escape}. Recall that \eqref{eq:diophantine} defines the integers
\begin{equation*}%\label{eq:diophantine}
	i_{k} = \sum_{k'=0}^kd_{k'} 
\end{equation*}
for every $k\geq1$, and set $i_0=i_0(\theta)\defeq0$. For every $k\geq1$ and $d\geq0$, the mass of $\theta$ which lies above $d$ up to the $k$\textsuperscript{th} degree is defined in \eqref{eq:escape} as 
$$
\es_{\theta}(d,k) 
= 	\frac{\sum_{k'=1}^{k}\max\left\{d_{k'}-d,0\right\}}
{\sum_{k'=1}^{k}d_{k'}}\,.
$$

\begin{proposition}\label{prop:escape}
	For any $\theta=\{b_n\}_{n=1}^\infty$, 
	\begin{equation*}%\label{eq:escape2}
		\es_{\theta}(d,k) = \esc_{\left.\frakf(\theta)\right|_{\left[0,2i_k\right]\times\{1\}}}(d)\,.
	\end{equation*}
\end{proposition}
\begin{proof}
	The standard facts from Diophantine approximation of Laurent series quoted in \eqref{eq:last} and \eqref{eq: frakf tile} mean that
	\begin{equation}\label{eq:last1}
		\frakf_{2i,1}(\theta)\neq0 \quad\iff\quad i=i_k \text{ for some }k\geq0\,,
	\end{equation}
	where the case $k=0$ holds since $\frakf_{0,1}=1$ by definition. Fix any $k\geq1$, and consider the first column of the tiling $\frakf$ between row $0$ to row $2i_k$. For the purpose of the current proof it is convenient to use the shortened notation for the height function along this column:
	\[
	\height \defeq \height_{\left.\frakf(\theta)\right|_{\left[0,2i_k\right]\times\{1\}}}\,.
	\]
	Then \eqref{eq:last1} implies that for every $d\geq0$,
	\begin{equation}\label{eq:aligned}
		\begin{aligned}
			&\#\left\{0\leq i<2i_k \sep \max\left\{\height(i),\height(i+1)\right\}>d\right\}
			\\
			&=\sum_{k'=1}^k\#\left\{2i_{k'-1}\leq i<2i_{k'} \sep \max\left\{\height(i),\height(i+1)\right\}>d\right\}
			\\
			&=\sum_{k'=1}^k2\max\{d_{k'}-d,0\}\,.
		\end{aligned}
	\end{equation}
	%where .
	%On the other hand, Equation \eqref{eq:diophantine} also gives %\begin{equation}\label{eq:diophantine2}
	%	i_k(\theta) = \sum_{k'=1}^k d_{k'}(\theta)\,.
	%\end{equation}
	Therefore, the mass of $\theta$ which lies above $d$ up to the $k$\textsuperscript{th} degree as defined in \eqref{eq:escape} satisfies
	\begin{equation}
		\begin{aligned}
			\es_{\theta}(d,k) 
			&= 	\frac{\sum_{k'=1}^{k}\max\left\{d_{k'}\left(\theta\right)-d,0\right\}}
			{\sum_{k'=1}^{k}d_{k'}\left(\theta\right)}
			\\[2pt] 
			&= 
			\frac{2\sum_{k'=1}^{k}\max\left\{d_{k'}\left(\theta\right)-d,0\right\}}
			{2i_k}
			= \esc_{\left.\frakf(\theta)\right|_{\left[0,2i_k\right]\times\{1\}}}(d)\,.
		\end{aligned}
	\end{equation}
\end{proof}

Note that for every $j\geq0$, the number wall of $\theta=\{b_{n+j}\}_{n=1}^\infty$, which is the sequence $\theta$ shifted to the left $j$ times, is given by a shift of the indices of the number wall of $\theta$ by the vector $(j,j)$. Formally, every $m$ and $n$ satisfy
$$
\frakf_{m,n}\left(t^j\theta\right) = \frakf_{m+j,n+j}(\theta)\,.
$$
This follows from the definition of $\frakf$ in terms of Hankel or Toeplitz determinants. Therefore, Proposition~\ref{prop:escape} implies that for every $j\geq0$, the escape of mass of $t^j\theta$ satisfies 
\begin{equation}\label{eq:follows}
	\es_{t^j\theta}(d,k) = \esc_{\left.\frakf(\theta)\right|_{\left[j,2i_k(t^j\theta)+j\right]\times\{j+1\}}}(d)\,.
\end{equation}

The rest of this section deals with the number wall of the Thue-Morse sequence $\frakf=\frakf(\tm)$, which as we proved in Section~\ref{sec:structure} is (after ignoring its $0$\textsuperscript{th} row) equal to $\kappa_1\left(\sigma^\infty(\splus{0})\right)$. Our immediate goal is to use the structure we developed in that section in order to express the escape of mass along each of its columns in simple terms. In the following theorem we will show that these columns are periodic. Furtheremore, the period will be described explicitly and this will give a useful expression of the escape of mass in terms of the period. It is convenient to introduce the following shortened notation: for any $d,l\geq0$ and $0\leq j \leq 2^{l+2}$ denote
\[
\esc_{l,j}(d) \defeq \esc_{\left.\kappa_1\left(\sigma^l\left(\tiler{a}\right)\right)\right|_{\left[1,2^{l+2}\right]\times\{j+1\}}}(d)\,.
\]

\begin{theorem}\label{thm:escape}
	For every $d\geq5$, $l\geq0$ and $0 \leq j \leq 2^{l+2}$, the limit as $k$ goes to infinity of the mass of $t^j\theta$ that lies above $d$ up to the $k$\textsuperscript{th} degree exists, and satisfies
	\[
	\lim_{k\to\infty}\es_{t^j\tm}(d,k) = \frac{1}{3}\esc_{l,j}(d) + \frac{2}{3}\esc_{l+1,j}(d)\,.
	\]
\end{theorem}

\begin{proof}
	Fix $l\geq0$ and $0 \leq j \leq 2^{l+2}$. By Lemma \ref{lem:sigmal0}, the first column of $\sigma^{\infty}(\splus{0})$ is periodic with period
	\begin{align*}
		\begin{array}{c} \splus{0}\\ \tiler{a}\\ \sminus{1}\end{array}.
	\end{align*}
	Consequently, for 
	\[
	j'\defeq\min\left\{\left\lfloor\frac{j}{4}\right\rfloor,2^{l}-1\right\},
	\] 
	the $(j')$\textsuperscript{th} column of $\sigma^{\infty}(\splus{0})$ is periodic with period 
	\begin{align*}
		\begin{array}{c} \left.\sigma^l(\splus{0})\right|_
			{\left[1,2^{l}\right]\times\{j'+1\}}\\
		\left.\sigma^l\left(\tiler{a}\right)\right|_
		{\left[1,2^{l}\right]\times\{j'+1\}}\\
		\left.\sigma^l(\sminus{1})\right|_
		{\left[1,2^{l}\right]\times\{j'+1\}}\\
		\end{array},
	\end{align*}
	and the $j$\textsuperscript{th} column of $\frakf(\tm)$ is periodic with period (due to Lemma \ref{lem:consistent} this holds also for $j=2^{l+2}$)
	\begin{equation}\label{eq:jth-column}
		\begin{aligned}
		\begin{array}{c}
			\left.\kappa_1\left(\sigma^l(\splus{0})\right)\right|_
			{\left[1,2^{l+2}\right]\times\{j+1\}}\\
			\left.\kappa_1\left(\sigma^l\left(\tiler{a}\right)\right)\right|_
			{\left[1,2^{l+2}\right]\times\{j+1\}}\\
			\left.\kappa_1\left(\sigma^l(\sminus{1})\right)\right|_
			{\left[1,2^{l+2}\right]\times\{j+1\}}\\
		\end{array}.
		\end{aligned}
	\end{equation}
	Recall that by definition $\frakf_{j,j+1}=1$ for every $j\geq0$. Since the period in \eqref{eq:jth-column} is of length $3\cdot2^{l+2}$, this implies that $\frakf_{j+3\cdot2^{l+2}i,j+1}=1$ for every $i\geq0$.
	Therefore,
	\ignore{By Theorem \ref{thm:main2},
	\[
	\left\{\frakf_{i,j}(\tm)\right\}_{i=1,j=1}^\infty=\kappa_1\left(\sigma^\infty(\splus{0})\right).
	\]}
	it follows from \eqref{eq:follows} and Lemma~\ref{lem:gluing} with $d'=d''=0$, that for every $d\geq0$,
	\begin{align*}
		\lim_{k\to\infty}\esc_{t^j\tm}(d,k) &= 	\lim_{k\to\infty}\esc_{\left.\frakf(\tm)\right|_{\left[j,3\cdot2^{l+2}k+j\right]\times\{j+1\}}}(d) \\
		&=
		\esc_{\left.\frakf(\tm)\right|_{\left[j,3\cdot2^{l+2}+j\right]\times\{j+1\}}}(d)\,.
	\end{align*}
	The border rows between $\sigma^l(\splus{0})$ and $\sigma^l\left(\tiler{a}\right)$ were analysed in the proof of Theorem \ref{thm:main2} in Section \ref{sec:tiling}. It follows from the discussion there that every sequence of consecutive $0$'s of length strictly greater than $5$ in this column is contained either within
	$$
	\left.\kappa_1\left(\sigma^l\left(\tiler{a}\right)\right)\right|_{\left[1,2^{l+2}\right]\times\{j+1\}},\\
	$$
	or within
	\begin{equation*}
		\begin{aligned}
			\begin{array}{c}
				\left.\kappa_1\left(\sigma^l(\sminus{1})\right)\right|_{\left[1,2^{l+2}\right]\times\{j+1\}}\\
				\left.\kappa_1\left(\sigma^l(\splus{0})\right)\right|_{\left[1,2^{l+2}\right]\times\{j+1\}}
			\end{array}.
		\end{aligned}
	\end{equation*}
	Therefore, applying Lemma~\ref{lem:gluing} twice gives that
	\begin{equation*}
	\esc_{\left.\frakf(\tm)\right|_{\left[j,3\cdot2^{l+2}+j\right]\times\{j+1\}}}(d) = 
	\esc_{\left.\frakf(\tm)\right|_{\left[2^{l+2},4\cdot2^{l+2}\right]\times\{j+1\}}}(d) \\\,,
	\end{equation*}
	for every $d\geq5$. Finally, recalling \eqref{eq:sigmal8} and applying Lemma~\ref{lem:gluing} again proves that 
	$$
	\esc_{\left.\frakf(\tm)\right|_{\left[2^{l+2}+1,4\cdot2^{l+2}\right]\times\{j+1\}}}(d) = \frac{1}{3}\esc_{l,j}(d) + \frac{2}{3}\esc_{l+1,j}(d)\,.
	$$
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:main}]
	By Lemma~\ref{lem: kappa1 of r0} and Lemma~\ref{lem:basic}, every $d,l\geq0$ satisfy
	\[
	\esc_{l,2^{l+1}}(d) = \frac{2\max\left\{2^{l+1}-2-d,0\right\}}{2^{l+2}}\,,
	\]
	and if $d\geq2$ then 
	\[
	\esc_{l,2^{l+2}}(d) = 0\,.
	\]
	Therefore, applying Theorem~\ref{thm:escape} with $j=2^{l+2}$ and taking the limit $l\to\infty$ gives \eqref{eq:main}.
\end{proof}

