This enables a simple recursive formula for $\esc_{l+2,j}$ in terms of $\esc_{l+1,j}$ and $\esc_{l,j}$. But first, a lemma that relates between the escape of mass of $\sigma^{l}\left(\tiler{a}\right)$ and $\sigma^{l}\left(\tiler{b}\right)$ is required. Define 
\[
\overline{e}_{l,j}(d) \defeq \esc_{\left.\kappa_1\left(\sigma^l\left(\tiler{b}\right)\right)\right|_{\left[1,2^{l+2}\right]\times\{j+1\}}}(d)\,.
\]

\begin{lemma}
	For every $d\geq3$, $l\geq0$ and $0 \leq j \leq 2^{l+2}$,
	$$\overline{\esc}_{l,j}(d) = \esc_{l,j}(d)\,.$$
\end{lemma}

\begin{proof}
	The result follows from the fact that both $\kappa_1\left(\sigma^l\left(\tiler{a}\right)\right)$ and $\kappa_1\left(\sigma^l\left(\tiler{b}\right)\right)$ contain the same diagonally-aligned square patterns of $0$'s of side length $d$ for every $d\geq3$. %\usnote{Erez, I killed the use of the term windows and their size. Instead we use side length for a square or a rotated square. Can you change this accordingly, I dont want to insert a mistake}. 
	Recall Lemma~\ref{lem: kappa1 of r0} and note that it has an analogue with 
	$\tiler{b}$ replacing $\tiler{a}$.
	In fact, for every $2\leq l'\leq l$, every diagonally-aligned square of $0$'s of size $2^{l'}-2 < d \leq 2^{l'+1}-2$ which is contained in either $\kappa_1\left(\sigma^l\left(\tiler{a}\right)\right)$ or $\kappa_1\left(\sigma^l\left(\tiler{b}\right)\right)$ is contained in the $0$'s which lie in the centre of $\kappa_1\left(\sigma^{l'}\left(\tiler{a}\right)\right)$and $\kappa_1\left(\sigma^{l'}\left(\tiler{b}\right)\right)$, respectively, for some $\tiler{a}$ or $\tiler{b}$ contained in $\sigma^{l-l'}\left(\tiler{a}\right)$ and $\sigma^{l-l'}\left(\tiler{b}\right)$. This can be proved by induction. Since $\tiler{b}=\iota\tiler{a}$ and $$\sigma^{l-l'}\left(\tiler{b}\right)=\iota\sigma^{l-l'}\left(\tiler{a}\right) = \tinn_\iota\left(\sigma^{l-l'}\left(\tiler{a}\right)\right),$$ 
	it follows that $\sigma^{l-l'}\left(\tiler{a}\right)(m,n)\in\{\tiler{a},\tiler{b}\}$ if and only if $\sigma^{l-l'}\left(\tiler{b}\right)(m,n)\in\{\tiler{a},\tiler{b}\}$, which finishes the proof.
	%\red{Erez, can't this be stated in a nicer way using $\sig(\iota\cdot s) = \iota\sig(s)$?}
\end{proof}

\begin{theorem}\label{thm:mkj}
	For every $d\geq0$, $l\geq0$, and $0 \leq j \leq 2^{l+2}$,
	\begin{equation}\label{eqn:m_k,j2}
		\esc_{l,j}(d)= \esc_{l,2^{l+2} - j}(d)\,,
	\end{equation}
	and if $d\geq5$ and $l\geq2$, then
	\begin{equation}\label{eqn:m_k,j}
		\esc_{l,j}(d)=
		\begin{cases}
			\frac{1}{2}\esc_{l-1,j}(d)+\frac{1}{2}\esc_{l-2,j}(d)&0\leq j\leq 2^{l}
			\\[10pt]
			\frac{2^l-\max\{d+2-\left(j-2^{l}\right),0\}}{2^{l+1}}+\frac{1}{2}\esc_{l-1,j-2^{l}}(d)&2^{l}\leq j\leq 2^{l+1}
		\end{cases}.
	\end{equation}
\end{theorem}
\begin{proof}
	Equation \eqref{eqn:m_k,j2} follows immediately from the fact that $\rho^2\tiler{a}=\tiler{a}$ combined with 
	Lemma~\ref{lem: kappa equivariance}. Equation \eqref{eqn:m_k,j} follows by inspecting \eqref{eq:twice} and applying lemmas \ref{lem:gluing} and \ref{lem:basic}.
\end{proof}

