\begin{algorithm2e}
\caption{Codebook vector reconstruction procedure}
\label{alg:reconstruct}
\KwIn{codebook parameters $\theta = [\theta_0 \dots \theta_{K-1}]$, reconstruct index $i$}
$v\gets [1]$ \\
\For{$k \in \{0, ..., K-1\}$}{
  $b \gets (i >> k) \land 1$ \\
  \uIf{$b == 0$}{
        $v \gets [\cos(\theta_k) v,\,\phantom{-}\sin(\theta_k) v]$ \\
  }
  \Else{
        $v \gets [\sin(\theta_k) v,\, -\cos(\theta_k) v]$ \\
  }
}
\Return $v$
\end{algorithm2e}

