\subsection{\texttt{krop} Clean-up}
\label{sec:cleanup}

As per \equationref{eq:cleanup}, the goal of clean-up is to compute $\text{argmax}_i (Vu)_i$, where $u$ is a noisy vector that results from unbinding. % Given a noisy vector $u$ that results from unbinding, the goal of clean-up is to return the item vector $v^*$ with highest dot-product similarity to $u$, i.e.:
% \begin{align}
% v^* = \underset{v\in V}{\text{argmax}}\, v^\top u,
% \end{align}
% where $V$ is the set of all vectors in item memory.
We will use $\tilde{H}^{(K)}$ as the codebook $V$, and derive here an efficient algorithm to compute $\tilde{H}^{(K)}u$. This algorithm (Alg.\@ \ref{alg:cleanup} below) is similar to the fast Walsh-Hadamard transform, but modified to incorporate the sines and cosines in $\tilde{H}^{(K)}$.

The algorithm works as follows.  Note that here we reason about $\tilde{H}^{(K)}$ mathematically, but do not actually store it in computer memory. %We will write $x\in X$ to signify that $x$ is a column vector in a matrix $X$.
Based on \equationref{eq:kro}, we can write
\begin{align}
    \tilde{H}^{(K)}u = \left[\begin{array}{cr}
    \tilde{H}^{(K-1)}c_{K-1} & \tilde{H}^{(K-1)}s_{K-1} \\
    \tilde{H}^{(K-1)}s_{K-1} & -\tilde{H}^{(K-1)}c_{K-1}
    \end{array}\right] \left[\begin{array}{c} \hat{u} \\ \check{u}\end{array}\right] = 
    \left[\begin{array}{c}
    \tilde{H}^{(K-1)} (c_{K-1} \hat{u} +  s_{K-1} \check{u}) \\
    \tilde{H}^{(K-1)} (s_{K-1} \hat{u} -  c_{K-1} \check{u})
    \end{array}\right],\label{eq:top}
\end{align}
where $\hat{x}$ and $\check{x}$ denote the first and second halves of any vector $x$.  \equationref{eq:top} decomposes the original problem into two sub-problems where the vector dimensions have been halved.  To iterate this decomposition further, we recursively define
\begin{align}
    U^{(K)}_0 = u && \begin{array}{cc}
    U^{(k-1)}_{2i} &= c_{k-1}\hat{U}^{(k)}_i + s_{k-1}\check{U}^{(k)}_i \\
    U^{(k-1)}_{2i+1} &= s_{k-1}\hat{U}^{(k)}_i - c_{k-1}\check{U}^{(k)}_i
    \end{array}.\label{eq:recurse}
\end{align}
Each $U^{(k)}$ can be viewed as a list containing $N/2^k$ items, where the $i^{th}$ item $U^{(k)}_i$ is the $2^k$-dimensional vector associated with the $i^{th}$ sub-problem at step $k$.

Expanding the recursion down to $k=0$, we find
\begin{align}
    \tilde{H}^{(K)}u =
    \left[\begin{array}{c}
    \tilde{H}^{(K-1)} U^{(K-1)}_0 \\
    \tilde{H}^{(K-1)} U^{(K-1)}_1
    \end{array}\right]
    = ... =
    \left[\begin{array}{c}
    \tilde{H}^{(0)} U^{(0)}_0 \\
    \vdots \\
    \tilde{H}^{(0)} U^{(0)}_{N-1}
    \end{array}\right],\label{eq:base}
\end{align}
where each $U^{(0)}_i$ is a $1$-dimensional vector multiplied by the $1\times 1$ matrix $\tilde{H}^{(0)} = [1]$.  Reinterpreting $U^{(0)}_i$ as a scalar, this means that $(\tilde{H}^{(K)}u)_i = U^{(0)}_i$.  Therefore, we do not need to work explicitly with $\tilde{H}^{(K)}$ at all: Instead, we can construct $U^{(0)}$ according to \equationref{eq:recurse}, compute $i^* = \text{argmax}_i U^{(0)}_i$, and reconstruct the single row $\tilde{H}^{(K)}_{i^*}$ as per \sectionref{sec:reconstruct}.

\begin{algorithm2e}
\caption{\texttt{krop} clean-up procedure}
\label{alg:cleanup}
\KwIn{codebook parameters $\theta = [\theta_0 \dots \theta_{K-1}]$, vector $u$}
$U^{(K)}_0 \gets u$ \\
\For{$k \in \{K, \dots, 1\}$}{
    \For{$i \in \{0, \dots, N/2^{k} -1$\}}{
        $U^{(k-1)}_{2i} \gets c_{k-1}\hat{U}^{(k)}_i + s_{k-1}\check{U}^{(k)}_i$ \\
        $U^{(k-1)}_{2i+1} \gets s_{k-1}\hat{U}^{(k)}_i - c_{k-1}\check{U}^{(k)}_i$ \\
    }
}
\Return $\underset{i}{\text{argmax}}\, U^{(0)}_i$
