  \caption{The overall sampling process of ICDM. $\mathbf{x}_t$ and $\mathbf{z}_t$ are invisible signals and we decode them into images here for illustration.}
  \label{p-ConJPC}
  \end{figure*}
  \begin{figure}[t]
    \centering
    \includegraphics[width=0.95\linewidth]{figures/gradient.pdf}
    \caption{The illustration of the JCG module.}
    \label{JCG}
  \end{figure}
Additionally, the related constants are ignored. We obtain the gradients and rewrite them in terms of $\mathbf{x}$ and $\mathbf{z}$ as
\begin{align}\label{Ours}
    &\nabla_{\mathbf{x}_t}\log p_{\mathbf{y}|\mathbf{x}_t,\mathbf{z}_t,\mathbf{h_x}}(\mathbf{y}|\mathbf{x}_t,\mathbf{z}_t,\mathbf{h_x})\approx \mathbf{\bar{r}}_x(\mathbf{x}_t,\mathbf{z}_t,\mathbf{y},\mathbf{h_x})\nonumber\\
    &=\sqrt{P_x}\zeta_t^2\mathbf{W}_\mathbf{x}^T(\mathbf{W}_{\mathbf{n}}^2)^{-1}(\frac{\mathbf{y}}{\zeta_t}-\sqrt{P_x}\mathbf{W_x}\mathbf{x}_t-\sqrt{P_z}\mathbf{W_z}\mathbf{z}_t),\nonumber\\
    &\nabla_{\mathbf{z}_t}\log p_{\mathbf{y}|\mathbf{x}_t,\mathbf{z}_t,\mathbf{h_x}}(\mathbf{y}|\mathbf{x}_t,\mathbf{z}_t,\mathbf{h_x})\approx \mathbf{\bar{r}}_z(\mathbf{x}_t,\mathbf{z}_t,\mathbf{y},\mathbf{h_x})\nonumber\\
    &=\sqrt{P_z}\zeta_t^2\mathbf{W}_\mathbf{z}^T(\mathbf{W}_{\mathbf{n}}^2)^{-1}(\frac{\mathbf{y}}{\zeta_t}-\sqrt{P_x}\mathbf{W_x}\mathbf{x}_t-\sqrt{P_z}\mathbf{W_z}\mathbf{z}_t).
\end{align}

These precisely estimated gradients not only improve the accuracy of interference cancellation but also enable the proposed ICDM to adaptively adjust the sampling process based on different channel gains, noise schedules, and the sample steps, thereby enhancing its adaptability to various scenarios.
\subsection{Interference Cancellation Algorithm of ICDM}


  % \begin{figure}[t]
  %   \centering
  %   \includegraphics[width=0.95\linewidth]{figures/signal-sampling.pdf}
  %   \caption{The }
  %   \label{SS}
  % \end{figure}
With these estimated gradients, we develop the ICDM interference cancellation algorithm by solving the ODE in (\ref{target_ODE}) with the proposed \textit{$p$-order joint conditional predict-correct ($p$-ConJPC) sampler} as shown in Fig. \ref{p-ConJPC}. The $p$-ConJPC is a specially designed iteration method that quickly and accurately estimates the clean signal $\mathbf{\hat{x}}$ and interference $\mathbf{\hat{z}}$ from the initial samples $\mathbf{x}_0$ and $\mathbf{z}_0$ drawn from $\mathcal{N}(0,\mathbf{I})$. It does so by combining the new gradients with the advanced UniPC method \cite{unipc}, which achieves $(p+1)$-th order of accuracy.

Using the definition in (\ref{diff_process}), the ODE in (\ref{target_ODE}) is specifically decomposed into two related ODEs for $\mathbf{x}_t$ and $\mathbf{z}_t$, namely
\begin{align}\label{target_ODE2}
  \frac{d\mathbf{x}_t}{dt}=f(t)\mathbf{x}_t-\frac{1}{2}g^2(t)\nabla _{\mathbf{x}_t}\log p(\mathbf{x}_t,\mathbf{z}_t|\mathbf{y},\mathbf{h_x}),\\
  \frac{d\mathbf{z}_t}{dt}=f(t)\mathbf{z}_t-\frac{1}{2}g^2(t)\nabla _{\mathbf{z}_t}\log p(\mathbf{x}_t,\mathbf{z}_t|\mathbf{y},\mathbf{h_x}),\nonumber
\end{align}
where $f(t)=\frac{d \log \sqrt{\alpha_t}}{dt}$, $g^2(t)=\frac{d(1-\alpha_t)}{dt}-2(1-\alpha_t)\frac{d\log \sqrt{\alpha_t}}{dt}$. 

The proposed $p$-order ConJPC sampler consists of three components: $1)$ a joint conditional gradient (JCG) module as illustrated in Fig. \ref{JCG}; $2)$ a $p$-order signal predict-correct (PC) sampling module, as described in Algorithm. \ref{alg:signal-sampling}; $3)$ a $p$-order interference PC sampling module. Given the previous $p$ samples $\{\mathbf{x}_{t-m}\}^p_{m=1}$ and $\{\mathbf{z}_{t-m}\}^p_{m=1}$, the $p$ JCG modules compute $2p$ joint conditional gradients $\{\mathbf{r}_\theta(\mathbf{x}_{t-m},\mathbf{z}_{t-m},\mathbf{y},\mathbf{h_x},t-m)\}^p_{m=1}$ and $\{\mathbf{r}_\phi(\mathbf{x}_{t-m},\mathbf{z}_{t-m},\mathbf{y},\mathbf{h_x},t-m)\}^p_{m=1}$, which are then fed, respectively, into the $p$-order signal PC sampling module and the $p$-order interference PC sampling module. Here, we have
\begin{align}
  \mathbf{r}_\theta(\mathbf{x}_{t},\mathbf{z}_{t},\mathbf{y},\mathbf{h_x},t)&=\mathbf{s}_\mathbf{\theta}(\mathbf{x}_{t},t)-\beta \mathbf{\bar{r}}_x(\mathbf{x}_t,\mathbf{z}_t,\mathbf{y},\mathbf{h_x})\nonumber\\
  &\approx \nabla _{\mathbf{x}_t}\log p(\mathbf{x}_t,\mathbf{z}_t|\mathbf{y},\mathbf{h_x}),\nonumber\\
   \mathbf{r}_\phi(\mathbf{x}_{t},\mathbf{z}_{t},\mathbf{y},\mathbf{h_x},t)&=\mathbf{s}_\mathbf{\phi}(\mathbf{z}_{t},t)-\gamma \mathbf{\bar{r}}_z(\mathbf{x}_t,\mathbf{z}_t,\mathbf{y},\mathbf{h_x})\nonumber\\
  &\approx \nabla _{\mathbf{z}_t}\log p(\mathbf{x}_t,\mathbf{z}_t|\mathbf{y},\mathbf{h_x}).
\end{align}

\begin{remark}\label{hy-par}
 The parameters $\beta$ and $\gamma$ combine all the constants in the estimated gradients and serve as guiding intensities, as introduced in diffusion models with classifier guidance \cite{diffbeatgan}. Here, a large value means the reconstructed signal is closer to the received signal, while a small value means the reconstructed signal is more likely to be generated. Therefore, these parameters balance consistency with the received signal and overall realism in interference cancellation.
\end{remark}


The two sampling modules combine the gradients from the $p$ JCG modules and use a predicter to generate the samples
\begin{align}\label{sampler1}
    &\mathbf{\bar{x}}_{t}=-\sqrt{1-\alpha_t}(e^{\eta _t}-1)\mathbf{r}_\mathbf{\theta}(\mathbf{x}_{t-1},\mathbf{z}_{t-1},\mathbf{y},\mathbf{h_x},t-1)\nonumber\\
    &+\sqrt{\frac{\alpha_t}{\alpha_{t-1}}}\mathbf{x}_{t-1}-\sqrt{1-\alpha_t}\eta _t \sum_{m=1}^{p-1}\frac{o^{p-1}_{m,t}}{w_{m,t}}\mathbf{D}^x_{m,t},\\
    &\mathbf{\bar{z}}_{t}=-\sqrt{1-\alpha_t}(e^{\eta _t}-1)\mathbf{r}_\mathbf{\theta}(\mathbf{z}_{t-1},\mathbf{z}_{t-1},\mathbf{y},\mathbf{h_x},t-1)\nonumber\\
    &+\sqrt{\frac{\alpha_t}{\alpha_{t-1}}}\mathbf{z}_{t-1}-\sqrt{1-\alpha_t}\eta _t \sum_{m=1}^{p-1}\frac{o^{p-1}_{m,t}}{w_{m,t}}\mathbf{D}^z_{m,t},\nonumber\\
    %\mathbf{D}^x_{m,t}=\frac{1}{w_{m,t}}\left[\mathbf{r}_\theta(\mathbf{x}_{t-m-1},\mathbf{z}_{t-m-1},\mathbf{y},\mathbf{h_x},t-m-1)-\mathbf{r}_\theta(\mathbf{x}_{t-1},\mathbf{z}_{t-1},\mathbf{y},\mathbf{h_x},t-1)\right],\quad m=1,2,\cdots,p-1,\nonumber\\
    % \mathbf{D}^z_{m,t}=\frac{1}{w_{m,t}}\left[\mathbf{r}_\phi(\mathbf{x}_{t-m-1},\mathbf{z}_{t-m-1},\mathbf{y},\mathbf{h_x},t-m-1)-\mathbf{r}_\phi(\mathbf{x}_{t-1},\mathbf{z}_{t-1},\mathbf{y},\mathbf{h_x},t-1)\right], \quad m=1,2,\cdots,p-1 .\nonumber
  \end{align}
%The OED equation enables us to develop the unconditional UniPC with $(p+1)$-th order to our joint conditional sampling process of ICDM.
where $\rho_t=\frac{1}{2}\log \frac{\alpha_t}{1-\alpha_t}$, $\eta_t=\rho _t-\rho _{t-1}$, $w_{m,t}=\frac{\rho _{t-m-1}-\rho _{t-1}}{\eta_t}$, for $m=1,2,\cdots,p-1$ and $w_{p,t}=1$. Let $\mathbf{o}^p_t=[o^{p}_{1,t},o^{p}_{2,t},\cdot,\cdot,\cdot,o^{p}_{p,t}]$, which is now can be computed as \cite{unipc}
\begin{align}
  \mathbf{o}^{p}_t=\frac{1}{\eta_t}\mathbf{\Gamma }^{-1}_{p}(t)\mathbf{b}_p(t).
\end{align}
Here, we have
\begin{align}\label{PC-parameter}
  \mathbf{\Gamma }_{p}(t)=\begin{bmatrix}
    1 & 1 &\cdot \cdot \cdot &1\\
    w_{1,t} & w_{2,t}& \cdot \cdot \cdot &w_{p,t}\\
    \cdot \cdot \cdot & \cdot \cdot \cdot &\cdot \cdot \cdot &\cdot \cdot \cdot\\
    w^{p-1}_{1,t} & w^{p-1}_{2,t} &\cdot \cdot \cdot &w^{p-1}_{p,t}
    \end{bmatrix},
\end{align}
\begin{gather}
  \mathbf{b}_p(t)=[(\frac{\psi_1-\frac{1}{1!}}{\eta_t})\cdot 1!,(\frac{\psi_2 -\frac{1}{2!}}{\eta_t})\cdot 2!,\cdots,(\frac{\psi_p-\frac{1}{p!}}{\eta_t})\cdot p!]^T\nonumber\\
  \psi_1=\frac{e^{\eta_t}-1}{\eta_t},\quad \psi_2=\frac{e^{\psi_1}-1}{\eta_t},\cdots,\psi_p=\frac{e^{\psi_{p-1}}-1}{\eta_t}.\nonumber
\end{gather}
We obtain $o^{p-1}_{m,t}$ by converting the $p$-order equations to $(p-1)$-order. The matrices $\mathbf{D}^x_{m,t}$ and $\mathbf{D}^z_{m,t}$ for $m=1,2,\cdots,p-1$, are computed from the gradients as following
\begin{align}
  {w_{m,t}}\mathbf{D}^x_{m,t}&=\mathbf{r}_\theta(\mathbf{x}_{t-m-1},\mathbf{z}_{t-m-1},\mathbf{y},\mathbf{h_x},t-m-1)\nonumber\\
  &-\mathbf{r}_\theta(\mathbf{x}_{t-1},\mathbf{z}_{t-1},\mathbf{y},\mathbf{h_x},t-1),\\
  {w_{m,t}}\mathbf{D}^z_{m,t}&=\mathbf{r}_\phi(\mathbf{x}_{t-m-1},\mathbf{z}_{t-m-1},\mathbf{y},\mathbf{h_x},t-m-1)\nonumber\\
  &-\mathbf{r}_\phi(\mathbf{x}_{t-1},\mathbf{z}_{t-1},\mathbf{y},\mathbf{h_x},t-1).
\end{align}


The method employs generalized polynomial interpolation to determine the optimal coefficients for solving the ODE (\ref{target_ODE2}) with $p$-th order of accuracy.

After predicting the samples $\mathbf{\bar{x}}_{t}$ and $\mathbf{\bar{z}}_{t}$, the corrector further refines them to obtain more accurate samples at the current time step with $(p+1)$-th order accuracy. Specifically, the predicted samples are used to compute the gradients via $\mathbf{s}_\theta(\mathbf{\bar{x}}_t,t)$ and $\mathbf{z}_\theta(\mathbf{\bar{z}}_t,t)$, which are then utilized to calculate $\mathbf{D}^x_{p,t}$ and $\mathbf{D}^x_{p,t}$ as
\begin{align}
  \mathbf{D}^x_{p,t}=\frac{1}{w_{p,t}}\left[\mathbf{s}_\theta(\mathbf{\bar{x}}_{t},t)-\mathbf{r}_\theta(\mathbf{x}_{t-1},\mathbf{z}_{t-1},\mathbf{y},\mathbf{h_x},t-1)\right],\nonumber\\
  \mathbf{D}^z_{p,t}=\frac{1}{w_{p,t}}\left[\mathbf{s}_\phi(\mathbf{\bar{z}}_{t},t)-\mathbf{r}_\phi(\mathbf{x}_{t-1},\mathbf{z}_{t-1},\mathbf{y},\mathbf{h_x},t-1)\right].
\end{align}


\begin{algorithm}[t]
  \caption{$p$-order signal PC sampling algorithm}
  \label{alg:signal-sampling}
  {\bf {Input:}}
	\small{$\mathbf{x}_{t-1}$, $\{\mathbf{r}_\theta(\mathbf{x}_{t-m},\mathbf{z}_{t-m},\mathbf{y},\mathbf{h_x},t-m)\}^p_{m=1}$}, $t$, $\alpha_t$. \\
	{\bf {Output:}}
	\small{$\mathbf{x}_t$.}
  \begin{algorithmic}[1]
    \STATE  $\rho_t=\frac{1}{2}\log \frac{\alpha_t}{1-\alpha_t}$, $\eta_t=\rho _t-\rho _{t-1}$
    \STATE \textbf{Predicter}:
    \FOR {$m=1$ to $p-1$}
    \STATE $w_{m,t}=\frac{1}{\eta_t}(\rho _{t-m-1}-\rho _{t-1})$
    \STATE ${w_{m,t}}\mathbf{D}^x_{m,t}=\mathbf{r}_\theta(\mathbf{x}_{t-m-1},\mathbf{z}_{t-m-1},\mathbf{y},\mathbf{h_x},t-m-1)$\\
    $-\mathbf{r}_\theta(\mathbf{x}_{t-1},\mathbf{z}_{t-1},\mathbf{y},\mathbf{h_x},t-1)$
    \ENDFOR
    \STATE $\mathbf{o}^{p-1}_{t}=\frac{1}{\eta_t}\mathbf{\Gamma }^{-1}_{p-1}(t)\mathbf{b}_{p-1}(t)$ as defined in (\ref{PC-parameter})
    \STATE $\mathbf{\bar{x}}_{t}=-\sqrt{1-\alpha_t}(e^{\eta _t}-1)\mathbf{r}_\mathbf{\theta}(\mathbf{x}_{t-1},\mathbf{z}_{t-1},\mathbf{y},\mathbf{h_x},t-1)$\\
    $+\sqrt{\frac{\alpha_t}{\alpha_{t-1}}}\mathbf{x}_{t-1}-\sqrt{1-\alpha_t}\eta _t \sum_{m=1}^{p-1}\frac{o^{p-1}_{m,t}}{w_{m,t}}\mathbf{D}^x_{m,t}$
    \STATE \textbf{Corrector}:
    \STATE $w_{p,t}=1$, $\mathbf{o}^{p}_{t}=\frac{1}{\eta_t}\mathbf{\Gamma }^{-1}_{p}(t)\mathbf{b}_p(t)$ 
    \STATE ${w_{p,t}}\mathbf{D}^x_{p,t}=\mathbf{s}_\theta(\mathbf{\bar{x}}_{t},,t)-\mathbf{r}_\theta(\mathbf{x}_{t-1},\mathbf{z}_{t-1},\mathbf{y},\mathbf{h_x},t-1)$
    \STATE $\mathbf{{x}}_{t}=-\sqrt{1-\alpha_t}(e^{\eta _t}-1)\mathbf{r}_\mathbf{\theta}(\mathbf{x}_{t-1},\mathbf{z}_{t-1},\mathbf{y},\mathbf{h_x},t-1)$\\
    $+\sqrt{\frac{\alpha_t}{\alpha_{t-1}}}\mathbf{x}_{t-1}-\sqrt{1-\alpha_t}\eta _t \sum_{m=1}^{p}\frac{o^{p}_{m,t}}{w_{m,t}}\mathbf{D}^x_{m,t}$

  \end{algorithmic}
  \end{algorithm}

  \begin{algorithm}[t]
    \caption{Interference Cancellation Algorithm of ICDM}
    \label{alg:sampling}
    {\bf {Input:}}
    \small{$\mathbf{y}$, $\mathbf{h_x}$, SINR} \\
    {\bf {Output:}}
    \small{Estimated $\mathbf{\hat{x}}$, $\mathbf{\hat{z}}$}.
    \begin{algorithmic}[1]
      \STATE $\mathbf{x}_0\sim\mathcal{N}(0,\mathbf{I}_{2k})$, $\mathbf{z}_0\sim\mathcal{N}(0,\mathbf{I}_{2k})$
      \FOR {$t=1$ to $p$}
      \STATE $\{\mathbf{r}_\theta(\mathbf{x}_{t-m},\mathbf{z}_{t-m},\mathbf{y},\mathbf{h_x},t-m)\}^t_{m=1}$, \\
      $\{\mathbf{r}_\phi(\mathbf{x}_{t-m},\mathbf{z}_{t-m},\mathbf{y},\mathbf{h_x},t-m)\}^t_{m=1}$ from JCG module
      \STATE $\mathbf{x}_t$ from $t$-order signal PC sampling module
      \STATE $\mathbf{z}_t$ from $t$-order interference PC sampling module
      \ENDFOR
      \FOR {$t=p+1$ to $T$}
      \STATE $\{\mathbf{r}_\theta(\mathbf{x}_{t-m},\mathbf{z}_{t-m},\mathbf{y},\mathbf{h_x},t-m)\}^p_{m=1}$, \\
      $\{\mathbf{r}_\phi(\mathbf{x}_{t-m},\mathbf{z}_{t-m},\mathbf{y},\mathbf{h_x},t-m)\}^p_{m=1}$ from JCG module
      \STATE $\mathbf{x}_t$ from $p$-order signal PC sampling module
      \STATE $\mathbf{z}_t$ from $p$-order interference PC sampling module
      \ENDFOR
      \STATE $\mathbf{\hat{x}}=\mathbf{x}_T$, $\mathbf{\hat{z}}=\mathbf{z}_T$
    \end{algorithmic}
    \end{algorithm}


In addition, the coefficients $o^p_{m,t}$ for $m=1,2,\cdots,p$ need to be recomputed, as they differ from the elements in $\mathbf{o}^{p-1}_t$. Using these data, we can obtain more accurate estimates of $\mathbf{x}_t$ and $\mathbf{z}_t$ with $(p+1)$-th order accuracy as
\begin{align}\label{sampler-corrector}
  &\mathbf{x}_{t}=-\sqrt{1-\alpha_t}(e^{\eta _t}-1)\mathbf{r}_\mathbf{\theta}(\mathbf{x}_{t-1},\mathbf{z}_{t-1},\mathbf{y},\mathbf{h_x},t-1)\nonumber\\
  &+\sqrt{\frac{\alpha_t}{\alpha_{t-1}}}\mathbf{x}_{t-1}-\sqrt{1-\alpha_t}\eta _t \sum_{m=1}^{p}\frac{o^{p}_{m,t}}{w_{m,t}}\mathbf{D}^x_{m,t},\\
  &\mathbf{z}_{t}=-\sqrt{1-\alpha_t}(e^{\eta _t}-1)\mathbf{r}_\mathbf{\theta}(\mathbf{z}_{t-1},\mathbf{z}_{t-1},\mathbf{y},\mathbf{h_x},t-1)\nonumber\\
  &\sqrt{\frac{\alpha_t}{\alpha_{t-1}}}\mathbf{z}_{t-1}-\sqrt{1-\alpha_t}\eta _t \sum_{m=1}^{p}\frac{o^{p}_{m,t}}{w_{m,t}}\mathbf{D}^z_{m,t},
\end{align}
which are the final samples of the ODEs at this time. 

Notably, we use only unconditional gradients for $\mathbf{D}^x_{p,t}$ and $\mathbf{D}^z_{p,t}$ to correct the predicted error of the predicted samples, improving accuracy from $p$-th order to $(p+1)$-th order and thus yielding more realistic samples. As discussed in Remark \ref{hy-par}, a more realistic sample requires samller $\beta$ and $\gamma$. Therefore, we set both to zero, which leads directly to these unconditional gradients. In the initial steps ($t\in[1,p]$), where fewer than $p$ previous samples are available, we employ a $t$-order ConJPC sampler to acquire the current samples.

After the last step, we can obtain the final results $\mathbf{\hat{x}}$ for signal estimation and $\mathbf{\hat{z}}$ for interference estimation, which are also solutions to the MAP problem (\ref{MAP_prb}). The interference cancellation algorithm of ICDM is shown in Algorithm \ref{alg:sampling}. The algorithm is accurate as it jointly solves the ODEs with $(p+1)$-th order accuracy, leveraging precisely estimated gradients from separate training and derivation. It is also fast because the $(p+1)$-th order iteration method reduces the steps needed to acquire the final samples $\mathbf{\hat{x}}$ and $\mathbf{\hat{z}}$. Moreover, the unconditional gradients $\mathbf{D}^x_{p,t}$ and $\mathbf{D}^z_{p,t}$ in the sampling modules can be computed in parallel, further accelerating the algorithm. 

