\section{Algorithms of EVA-S3PC}
\label{APP: Algorithms In EVA-S3PC}
This section introduces the S2PM and S2PHM protocols in EVA-S3PC\cite{EVA-S3PC}.
\subsection{S2PM}
The problem definition of S2PM is as follows: 

\begin{problem}[Secure 2-Party Matrix Multiplication]\label{Problem-S2PM}
    Alice has an $n\times s$ matrix $A$ and Bob has an $s\times m$ matrix $B$. They want to conduct the multiplication, such that Alice gets $V_a$ and Bob gets $V_b$, where $V_a+V_b=A\times B$.
\end{problem}

\subsubsection{Description of S2PM}
The S2PM includes three stages: CS pre-processing stage  in Algorithm \ref{alg:S2PM-Preprocessing}, online computation stage in Algorithm \ref{alg:S2PM-Computing}, and result verification stage in Algorithm \ref{alg:S2PM-Verification}.\\

\textbf{Pre-processing Stage.}
In Algorithm \ref{alg:S2PM-Preprocessing}, CS generates random private matrices $R_a$ for Alice and $R_b$ for Bob, where $rank(R_a) < s$ and $rank(R_b) < s$. Subsequently, CS computes $S_t=R_a \cdot R_b$ and generates random matrices $r_a$ for Alice and $r_b$ for Bob, where $r_a + r_b = S_t$. Finally, CS sends a set of matrices $(R_a, r_a, S_t)$ to Alice and $(R_b, r_b, S_t)$ to Bob.

\begin{breakablealgorithm}
    \caption{S2PM CS Pre-processing Stage}
    \label{alg:S2PM-Preprocessing}
    \begin{algorithmic}[1] 
        \Require $n, s, m$
        \Ensure Alice $\Leftarrow$ $(R_a,r_a,S_t)$ and Bob $\Leftarrow$ $(R_b,r_b,S_t)$
        \State $R_a \gets$ generate a random matrix \Comment{$R_a \in \mathbb{R}^{n \times s}, rank(R_a)=min(n,s)-1$}
        \State $R_b \gets$ generate a random matrix \Comment{$R_b \in \mathbb{R}^{s \times m}, rank(R_b)=min(s,m)-1$}
        \State $S_t = R_a \times R_b$ \Comment{$S_t \in \mathbb{R}^{n \times m}$}
        \State $r_a,r_b \gets$ generate random matrices \Comment{$r_a,r_b \in \mathbb{R}^{n \times m}, r_a + r_b = S_t$}
        \State Alice $\Leftarrow(R_a, r_a, S_t)$
        \State Bob $\Leftarrow(R_b, r_b, S_t)$
        \State \Return $(R_a, r_a, S_t)$, $(R_b, r_b, S_t)$
    \end{algorithmic}
\end{breakablealgorithm}


\textbf{Online Stage.}
In Algorithm \ref{alg:S2PM-Computing}, Alice computes $\hat{A} = A + R_a$ and sends $\hat{A}$ to Bob while Bob computes $\hat{B} = B + R_b$ and sends $\hat{B}$ to Alice. Bob then generates a random matrix $V_b$, computes $VF_b=V_b-\hat{A}\times B$, $T = r_b - VF_b$, and then sends  $(VF_b,T)$ to Alice. Finally, Alice computes the matrix $V_a = T + r_a - (R_a \times \hat{B})$, $VF_a = V_a + R_a \times \hat{B}$, and sends $VF_a$ to Bob.

\begin{breakablealgorithm}
    \caption{S2PM Online Computing Stage}
    \label{alg:S2PM-Computing}
    \begin{algorithmic}[1] 
        \Require $A \in \mathbb{R}^ {n \times s}$ and $B \in \mathbb{R}^{s\times m}$
        \Ensure Alice $\Leftarrow(V_a,VF_a)$ and Bob $\Leftarrow(V_b,VF_b)$
        \State $\hat{A} = A + R_a$ and send $\hat{A} \Rightarrow$ Bob \Comment{$\hat{A}\in \mathbb{R}^ {n \times s}$}
        \State $\hat{B} = B + R_b$ and send $\hat{B} \Rightarrow$ Alice \Comment{$\hat{B}\in \mathbb{R}^ {s \times m}$}
        \State $V_b\gets$ generate a random matrix \Comment{$V_b\in \mathbb{R}^ {n \times m}$}
        \State $VF_b = V_b-\hat{A}\times B$ \Comment{$VF_b\in \mathbb{R}^ {n \times m}$}
        \State $T = r_b - VF_b$ \Comment{$T\in \mathbb{R}^ {n \times m}$}
        \State send $(VF_b,T)\Rightarrow$ Alice
        \State $V_a = T + r_a - (R_a \times \hat{B})$ \Comment{$V_a\in \mathbb{R}^ {n \times m}$}
        \State $VF_a=V_a+R_a\times \hat{B}$ and send $VF_a\Rightarrow$ Bob \Comment{$VF_a\in \mathbb{R}^ {n \times m}$}
        \State \Return $(V_a,VF_a)$, $(V_b,VF_b)$ 
    \end{algorithmic}
\end{breakablealgorithm}


\textbf{Verification Stage.}
In Algorithm \ref{alg:S2PM-Verification}, Alice and Bob perform the same steps for $l$ rounds of verification. In each round, a vector $\hat{\delta_a}$ whose elements are all randomly composed of 0 or 1 is generated for the computation of $E_r=(VF_a+VF_b-S_t)\times \hat{\delta_a}$. Accept if $E_r = (0,0,\cdots,0)^T$ holds for all $l$ rounds, reject otherwise.


\begin{breakablealgorithm}
    \caption{S2PM Result Verification Stage}%标题
    \label{alg:S2PM-Verification}
    \begin{algorithmic}[1]
        \Require $VF_a, VF_b, S_t \in \mathbb{R}^ {n \times m}$ and $l > 0$
        \Ensure Accept if verified, Reject otherwise
        \For{$i := 1$ to $l$}
            \State $\hat{\delta_a}\gets$ generate a vector randomly composed of 0 or 1 \Comment{$\hat{\delta_a} \in \mathbb{R}^{m\times 1}$} 
            \State  $E_r=(VF_a+VF_b-S_t)\times \hat{\delta_a}$ \Comment{$E_r \in \mathbb{R}^{n\times 1}$}
            \If{$E_r\neq (0,0,\cdots,0)^T$}
                \State \Return Rejected; 
            \EndIf
        \EndFor
        \State \Return Accepted
    \end{algorithmic}
\end{breakablealgorithm}

\subsection{S2PHM}\label{S2PHM}
The problem definition of S2PHM is as follows:
\begin{problem}[Secure 2-Party Matrix Hybrid Multiplication Problem]
    Alice has private matrices $(A_1,A_2)$ and Bob has private matrices $(B_1,B_2)$, where $(A_1,B_1) \in \mathbb{R}^{n\times s}$,$(A_2,B_2) \in \mathbb{R}^{s\times m}$. They want to conduct the hybrid multiplication $f[(A_1, A_2), (B_1, B_2)] = (A_1 + B_1) \cdot (A_2+B_2)$ in which Alice gets $V_a$ and Bob gets $V_b$ such that $V_a + V_b =  (A_1 + B_1) \cdot (A_2+B_2)$.
\end{problem}

\subsubsection{Description of S2PHM}
In S2PHM, Alice and Bob compute $V_{a0} = A_1 \times A_2, V_{b0} = B_1 \times B_2$ respectively, and then jointly compute $V_{a1} + V_{b1} = A_1 \times B_2$  and $V_{b2}$, $V_{a2} \in \mathbb{R}^{n \times m}$ with S2PM protocol. Finally, Alice sums $V_a = V_{a0} + V_{a1} + V_{a2}$ and Bob sums $V_b = V_{b0} + V_{b1} + V_{b2}$.

\begin{breakablealgorithm}
    \caption{S2PHM}%
    \label{alg:S2PHM}
    \begin{algorithmic}[1] 
        \Require $(A_1,B_1) \in \mathbb{R}^{n\times s}$, $(A_2,B_2) \in \mathbb{R}^{s\times m}$
        \Ensure $V_a, V_b \in\mathbb{R}^ {n \times m}$ 
        \State $V_{a0} = A_1 \times A_2$ \Comment{$V_{a0} \in \mathbb{R}^{n \times m}$}
        \State $V_{b0} = B_1 \times B_2$ \Comment{$V_{b0} \in \mathbb{R}^{n \times m}$}
        \State $V_{a1}, V_{b1}\gets$ S2PM$(A_1, B_2)$ \Comment{$V_{a1}, V_{b1} \in \mathbb{R}^{n \times m}$}
        \State $V_{b2}, V_{a2}\gets$ S2PM$(B_1, A_2)$ \Comment{$V_{a2}, V_{b2} \in \mathbb{R}^{n \times m}$}
        \State $V_a = V_{a0} + V_{a1} + V_{a2}$ \Comment{$V_a \in \mathbb{R}^{n \times m}$}
        \State $V_b = V_{b0} + V_{b1} + V_{b2}$ \Comment{$V_b \in \mathbb{R}^{n \times m}$}
        \State \Return $V_a,V_b$ 
    \end{algorithmic}
\end{breakablealgorithm}


