\subsection{Numerical experiment} \label{sec_mbs_experiment}
\subsubsection{Problem description}


\noindent The four-particle system depicted in \Cref{fig:4Psystem_sketch} has been adapted from the literature \cite{gonzalez_1999_mechanical,kinon_2023_structurepreserving} and extended to include dissipation. The configuration of the system is characterized by the coordinate vector $q=(q_1,q_2,q_3,q_4) \in \R^{12}$ comprising the Cartesian coordinates of four masses $m_i$, $i=1,...,4$ in three dimensions.
Two nonlinear springs give rise to the potential function
\begin{equation} \label{eq:potential-4mass-system}
	V(q) = \frac{1}{2} k_{13} \pset[\big]{ \norm{q_3 - q_1}^2 - 1 }^2
	+ \frac{1}{2} k_{24} \pset[\big]{ \norm{q_4 - q_2}^2 - 1 }^2 ,
\end{equation}
with the spring stiffness parameters $k_{13}$ and $k_{24}$.
The mass matrix is block diagonal, i.e. $M = \diag\{m_1 I, m_2 I, m_3 I, m_4 I\}$. Additionally, we consider configuration-dependent viscous dissipation in terms of the Rayleigh dissipation function
\begin{align}
	G(q,v) = \frac{1}{2} \eta(q) v_{\mathrm{rel}}^2, \qquad
	v_{\mathrm{rel}} = \norm{v_3 -v_2},
\end{align}
where $\eta(q) = \eta_0 (1 + \alpha q_{\mathrm{rel}}^2) \geq 0$ is the dynamic viscosity parameter and
$q_{\mathrm{rel}}=\norm{q_3-q_2}$.
We have also introduced $\eta_0 >0 $ and $\alpha >0$ as constant parameters.
This leads to the dissipation matrix
\begin{align}
	R_{\mathrm{R}}(q) & = \eta(q) \begin{bmatrix}
		                              0 & 0  & 0  & 0 \\
		                              0 & I  & -I & 0 \\
		                              0 & -I & I  & 0 \\
		                              0 & 0  & 0  & 0
	                              \end{bmatrix}.
\end{align}
There are two rigid bars  connecting two masses, respectively, leading to the constraints on position level given by %\newpart{$g_1(q)=0$ and $g_2(q)=0$, where}
\begin{equation} \label{ex_constraints}
	g_1(q) = \frac{1}{2}\pset[\big]{ \norm{q_2-q_1}^2 - 1 } =0, \qquad
	g_2(q) = \frac{1}{2}\pset[\big]{ \norm{q_4-q_3}^2 - 1 } =0.
\end{equation}
In the numerical simulations the initial conditions
\begin{equation}
	\begin{aligned}
		{q}_1^0 & = \begin{bmatrix} 0 , 0 , 0 \end{bmatrix}\transp  \ , \ {q}_2^0 = \begin{bmatrix} 1 , 0 , 0 \end{bmatrix}\transp  \ , \  {q}_3^0 = \begin{bmatrix} 0 , 1 , 0 \end{bmatrix}\transp  \  , \  {q}_4^0 = \begin{bmatrix} 1 , 1 , 0 \end{bmatrix}\transp  ,          \\
		{v}_1^0 & = \begin{bmatrix} 0 , 0 , 0 \end{bmatrix}\transp \ , \ {v}_2^0 = \begin{bmatrix} 0 , 0 , 0 \end{bmatrix}\transp  \ , \  {v}_3^0 = \begin{bmatrix} 0 , 0 , 0 \end{bmatrix}\transp  \ , \ {v}_4^0 = \begin{bmatrix} 0 , 0 , \frac{20}{17} \end{bmatrix}\transp  ,
	\end{aligned}
\end{equation}
have been chosen consistently with the constraints \eqref{ex_constraints} and their velocity level counterparts induced by \eqref{eq_vel_constraint}.

\subsubsection{Methods}

\noindent The simulations have been conducted using our discrete gradient scheme for semi-explicit systems \eqref{block_pHDAE_timestepping_2}, implemented as suggested in \eqref{MBS_integrator_DG}. Results obtained with this scheme are labeled ``DG'' . The equations have been solved in each time step using Newton's method with a tolerance of $\epsilon_{\mathrm{Newton}}$. For the discrete gradients and Jacobians, we use the Gonzalez discrete gradient \eqref{eq:DD-Gonzalez}.
Since the constraints \eqref{ex_constraints} are quadratic, the application of the Gonzales discrete Jacobian boils down to a midpoint evaluation. In this example we assume zero inputs.

The generated data along with the source code for the simulations are openly available for verification purposes in the repository \url{https://github.com/plkinon/phdae_discrete_gradients} and are archived at \cite{kinon_2025_15007242}.

