\section{Further details on the DDR-method with singular descriptor matrix}\label{appendix_counter_example}

\noindent Towards the end of \Cref{sec_version3} we discussed possible limitations of the DDR-approach, questioning whether one can always find a discrete gradient that ensures the solvability of the system equation \eqref{eqn_colsp}, even for a singular descriptor matrix $E$.
This of course also depends on the choice of $\discreteE$, but for simplicity one would hope that for some suitable choice of $\discreteE$, such as the midpoint approximation
\begin{equation}
	\label{eq:midpoint_E}
	\discreteE(x,x') \vcentcolon= E(\tfrac{x+x'}2),
\end{equation}
one can always construct a discrete gradient satisfying \eqref{eqn_colsp2} for all $x,x'\in\R^n$.
The following example demonstrates that this is not in general the case when considering a fixed consistent approximation for $E$, like the one in \eqref{eq:midpoint_E}.


\begin{myex}
	Consider a pHDAE with given
	\begin{align*}
		\hamiltonian(x) & = \exp(\tfrac12x_1^2)-1+\tfrac12x_2^2,\quad \gradient\hamiltonian(x) =
		\begin{bmatrix}
			x_1\exp(\tfrac12x_1^2) \\
			x_2
		\end{bmatrix}
		,                                                                                        \\
		E(x)            & =
		\begin{bmatrix}
			1 \\
			1
		\end{bmatrix}
		\gradient\hamiltonian(x)\transp =
		\begin{bmatrix}
			x_1\exp(\tfrac12x_1^2) & x_2 \\
			x_1\exp(\tfrac12x_1^2) & x_2
		\end{bmatrix}
		,\quad\costate(x) = \tfrac12
		\begin{bmatrix}
			1 \\
			1
		\end{bmatrix}
		.
	\end{align*}
	Here, $E$ and $\costate$ are constructed such that $E\transp\costate=\gradient\hamiltonian$ holds, while the choice of the coefficients $J,R,B$ is free and they can be set e.g.~to zero, since they do not explicitly influence \eqref{eqn_colsp}. Correspondingly, we know that $\mathrm{colsp}(E\transp) = \mathrm{span}(\gradient\hamiltonian)$ holds pointwise.
	For $E$ we consider the midpoint approximation $\discreteE$ as in \eqref{eq:midpoint_E}, which results in
	\begin{equation*}
		\mathrm{colsp}\pset[\big]{\discreteE(x,x')\transp}
		= \mathrm{colsp}\pset[\big]{E(\tfrac{\state+\state'}{2})\transp}
		= \mathrm{span}\pset[\big]{\gradient\hamiltonian(\tfrac{x+x'}2)} .
	\end{equation*}
	A priori, we want to allow the choice of an arbitrary discrete gradient $\DG\hamiltonian$ of $\hamiltonian$.
	By \cite[Proposition~3.2]{McLQR99}, $\DG\hamiltonian$ may be split up into orthogonal contributions as
	\begin{equation}
		\label{eq:discrete_gradient_general_expression}
		\DG\hamiltonian(x,x') = \frac{\hamiltonian(x')-\hamiltonian(x)}{\lVert x'-x\rVert^2}(x'-x)+w(x,x')
	\end{equation}
	for $x\ne x'$, where $w$ satisfies $w(x,x')\in\mathrm{span}(\state'-\state)^\perp$
	and
	\begin{equation*}
		\lim_{x'\to x} \pset[\big]{ w(x,x')-\pi_{\mathrm{span}(x'-x)^\perp}\gradient\hamiltonian(x) } =0,
	\end{equation*}
	where
	\[
		\pi_{\mathrm{span}(x'-x)^\perp} = \frac{I-(x'-x)(x'-x)\transp}{\norm{x'-x}^2}
	\]
	denotes the orthogonal projection onto $\mathrm{span}(x'-x)^\perp$.
	Straightforward calculations yield that for the special choice
	\begin{equation*}
		x =
		\begin{bmatrix}
			a \\
			0
		\end{bmatrix}
		,\quad x' =
		\begin{bmatrix}
			0 \\
			b
		\end{bmatrix} , \quad  a,b \in \R \setminus \{0\},
	\end{equation*}
	where $b:= \pm a \sqrt{\exp(\frac{1}{2}(a/2)^2)}$,
	we have $\hamiltonian(x')\ne\hamiltonian(x)$ and $\gradient\hamiltonian(\tfrac{x+x'}2) \transp (x'-x) = 0$, and therefore
	\begin{equation*}
		x'-x\in \mathrm{span}\pset[\big]{\gradient\hamiltonian(\tfrac{x+x'}2)}^\perp = \mathrm{colsp}(\discreteE(x,x')\transp)^\perp.
	\end{equation*}
	Due to relation \eqref{eq:discrete_gradient_general_expression}, this implies $\DG\hamiltonian(x,x')\notin\mathrm{colsp}(\discreteE(x,x')\transp)$, i.e., there exists no vector $f$ satisfying $\discreteE(x,x')\transp f = \DG\hamiltonian(x,x')$ for this choice of $x,x'$.
	The discrete equation \eqref{eqn_colsp} is therefore unsolvable.
\end{myex}

