\subsection{Exponential Product Formulas}
A key result of semigroup theory includes \cite{nagel2}, \cite{pazy}, \cite{gold}, \cite{JD46}, and most importantly for our purposes the work of Franziska K\"uhnemund \cite{JD3} in which she extends the result to the bi-continuous case.

For Chernoff's product formula to hold in a Banach space X, let $$V(\cdot): [0,\infty)\rightarrow \mathcal{L}(X)$$ satisfy $V(0)=I$, $\Vert V(t)^{m}\Vert \leq M$ for all $t  \geq 0$, $m \in \mathbb{N}$, and some $M\geq 1$ and assume that  
\begin{equation*}
   \mathcal{K}x:= \lim_{h\to 0^{+}}\frac{V(h)x-x}{h}
\end{equation*}
exists for all $x \in D \subset X$, where $D$ and $(\lambda_{0}-\mathcal{K})D$ are dense subspaces in $X$ for some $\lambda_{0} >0$. Then the closure $\bar{\mathcal{K}}$ of $\mathcal{K}$ generates a strongly continuous semigroup $(T(t))_{t\geq 0}$ with $\Vert T(t)\Vert \leq M$($t\geq0$) which is given by 
 \begin{equation}\label{chernoff}
   T(t)x= \lim_{n\to \infty } V(\frac{t}{n})^{n}x .
\end{equation}
\noindent for all $x \in X$ and where the limit exists uniformly for $t$ in compact intervals.

In order to estimate the speed of convergence, one can employ the non-commutative binomial theorem as follows. Let $h=\frac{t}{n}.$ Then

\begin{equation*}\label{estimate}
\begin{split}
\Vert  V(h)^{n}- T(t) \Vert&=\Vert  V(h)^{n}- T(h)^{n} \Vert \leq \Vert \sum_{k=0}^{n-1} V(h)^{n-1-k}\Bigg[V(h)-T(h)\Bigg]T(h)^{k} \Vert \\ 
     &\leq \sum_{k=0}^{n-1} \Vert  V(h)^{n-1-k} \Vert \Vert  \Bigg [V(h)- T(h)\Bigg] T(h)^{k} \Vert  \\
     &\leq M\sum_{k=0}^{n-1} \Vert  \Bigg [V(h)- T(h)\Bigg] T(kh) \Vert \leq  n M^{2}  \Vert  V(h)- T(h) \Vert .
\end{split}
\end{equation*}
The inequality above indicates that the error estimates for $\Vert  (V(h)^{n}x- T(t)x \Vert$ can be derived from an estimate of $\Vert  V(h)- T(h) \Vert$ for small values of $h$. To do so, one considers approximations $V(t)$ that are \textit{``of order $p$"}; that is  $V(t)$ for which, in the case of matrices, the first $p$ Taylor coefficients coincide with the first $p$ Taylor coefficients of $$T(t)x=e^{t\mathcal{K}}x=x+t\mathcal{K}x+\frac{t^{2}}{2!}\mathcal{K}^{2}x+\cdots+\frac{t^{p}}{p!}\mathcal{K}^{p}x +\cdots.$$
Then, formally, for small values of $h$, one would then expect to obtain an estimate like  
\begin{equation} \label{order p}
\begin{split}
   \Vert V(h)x & -T(h)x\Vert \\ & \le \Vert \frac{h^{p+1}}{(p+1)!}(V(0)^{p+1}x-\mathcal{K}^{p+1}x)+\frac{h^{p+2}}{(p+2)!}(V(0)^{p+2}x-\mathcal{K}^{p+2}x)+\cdots \Vert\\
    &\leq \frac{h^{p+1}}{(p+1)!}\tilde{M}_x
   \end{split}
   \end{equation}
for some $\Tilde{M}_x\geq 0$. Together with estimate (\ref{estimate}), and setting $h=\frac{t}{n}$, we would then have

\begin{equation}\label{order pp}
\begin{split}
    \Vert  (V(\frac{t}{n})^{n}x- T(t)x \Vert
    &\leq \frac{1}{n^{p}}\frac{t^{p+1}}{(p+1)!} M^{2}\tilde{M_x}.
    \end{split}
\end{equation}

In 2009, E. Hansen and A. Ostermann showed in \cite{JD5} and \cite{JD6} that the estimates (\ref{order p}) and (\ref{order pp}) hold for splitting methods of the form
\begin{equation}\label{HOa}
    V(t):=\prod _{j=1}^{s}e^{\alpha_{j,1}t\mathcal{K}_{1}}\cdots e^{\alpha_{j,N}t\mathcal{K}_{N}},
\end{equation}
where $T(t) = e^{t\mathcal{K}}$ and $\mathcal{K} = \mathcal{K}_1 + \dots \mathcal{K}_N$, and where the real or complex coefficients $\alpha_{j}$'s and $\beta_{j}$'s are chosen in such a way that the method $V(t)$ has algebraic order $p$. For more details, see Section 3.4. Many of the central results of the theory of strongly continuous semigroups, especially those based on Laplace transform methods, can be lifted to the bi-continuous case, \cite{JD3}. One of the significant results is that Chernoff's product formula extends to bi-continuous semigroups.

\begin{theorem}\label{CPFBi} {(Chernoff's Bi-Continuous Product Formula)} Let $(\K,D(\K))$ be a linear operator on a bi-admissible Banach space $(X,\|\cdot\|,\tau)$, where $D(\K)$ and $(\lambda_0 I - \K)D(\K)$ are bi-dense in $X$ for some $\lambda_0 > \omega\ge 0$. Moreover, let $V(t) \in \mathcal{L}(X)$ be such that $||V(t)^n||\leq Me^{\omega n t}$ for all $n\in \mathbb{N}_0$ and $t \in [0,\delta)$. If 
	 $$V'(0+)g = \|\cdot\| - \lim_{t\to 0^+}\frac{V(t)g-g}{t} = \K g$$ for all $g\in D(\K)$ and if $\{V(t)^m : t \ge 0\}$ is locally bi-equicontinuous uniformly for
 $m\in\mathbb{N}$,  then the bi-closure of $(\K,D(\K))$ generates a bi-continuous semigroup $T(t)$ and 
 \begin{equation}\label{CPF eq Bi}
 T(t)g= \tau - \lim_{n\to\infty} \left(V(\frac{t}{n})\right)^n g
 \end{equation}
 for all $g \in X$ and $t \geq 0$ uniformly in $t$ on compact intervals.
\end{theorem}

\begin{proof} See \cite{JD3}.
\end{proof}

If one applies (\ref{CPF eq Bi} to bi-continuous Koopman-Lie semigroups on $C_b(\Omega)$, then one obtains that 
\begin{equation}\label{Arun}
T(t)g(\cdot)= g(\sigma(t,\cdot)) = \tau-\lim_{n\to\infty}\left(V(\frac{t}{n})\right)^ng(\cdot)=\tau-\lim_{n\to\infty}g(\sigma_n(t,\cdot))
\end{equation}
uniformly in compact time intervals for all $g\in C_b(\Omega)$. The following proposition, due to Arun Banjara  \cite{AB}, shows that (\ref{Arun}) implies that, for all $x\in\Omega$,  
\begin{equation} \label{ArunII}
\sigma(t,x) = \lim_{n\to\infty} \sigma_n(t,x).
\end{equation}

\begin{definition}
    Let $\Omega$ be a metric space. Then, for $x_n,x\in\Omega$, we say that $x_n$ is weak-$C_b(\Omega)$ convergent to $x$ and write $x_n \xrightarrow[]{C_b(\Omega)} x$ if $g(x_n) \to g(x)$ for all $g\in C_b(\Omega)$. 
\end{definition}

\begin{proposition}\label{Frank} Let $\Omega \subset \mathbb{R}^N$. Then the following statements are equivalent. 
\begin{itemize}
    \item[a)] $x_n  \to x$ as $n \to \infty$,
    \item[b)] $g(x_n) \to g(x)$ as $n\to \infty$ for all $g \in C_b(\Omega,\mathbb{R})$.    
\end{itemize}
\end{proposition}

\begin{proof}
  See Appendix \ref{FrankPr}.
\end{proof}

\indent Many approximation formulas can be derived from Chernoff's Product Formula. For example, 
\begin{enumerate}\label{list} 
\item [(1)]$V(t):=e^{t\K_1}e^{t\K_2}$, 
where $e^{t\K_1}$ and $e^{t\K_2}$ are strongly continuous or bi-continuous contraction semigroups on a Banach space $X$ with generators $(\mathcal{K}_{1}, D(\mathcal{K}_{1}))$ and $(\mathcal{K}_{2}, D(\mathcal{K}_{2}))$, respectively. Then $V(0)=I$ and $\Vert V(t)^{m} \Vert \leq 1$
%\Bigg(T_{1}(\frac{t}{n})T_{2}(\frac{t}{n})\Bigg)^{n}\leq M
%\end{equation}
for all $t\geq 0$, $m\in \mathbb{N}$ and 
\begin{equation}
\begin{split}
\mathcal{K}x&=\lim_{h \to 0^{+}}\frac{V(h)x-x}{h}=\lim_{h\to 0^{+}}\frac{T_{1}(h)T_{2}(h)x-x}{h}\\
&=\lim_{h\to 0^{+}}T_{1}(h)\frac{T_{2}(h)x-x}{h}+\lim_{h\to 0^{+}}\frac{T_{1}(h)x-x}{h}\\
&=\mathcal{K}_{2}x+\mathcal{K}_{1}x.
\end{split}
\end{equation}
So, consider $\mathcal{K}=\mathcal{K}_{1}+\mathcal{K}_{2}$ on $D:= D(\mathcal{K}_{1})\cap D(\mathcal{K}_{2})$ and assume that $D$ and $(\lambda_{0}-\mathcal{K}_{1}-\mathcal{K}_{2})D$ are dense in $X$. Then, by Chernoff's theorem, $$\mathcal{K}:=\overline{\mathcal{K}_{1}+\mathcal{K}_{2}}$$
generates a strongly continuous semigroup $(T(t))_{(t\geq 0)}$ given by the \textit{Lie-Trotter product formula }
\begin{equation}\label{LT}
    T(t)x=\lim_{n \to \infty}\Bigg(e^{\frac{t}{n}\K_1}e^{\frac{t}{n}\K_2}\Bigg)^{n}x
\end{equation}
for all $x\in X$ and the limit is uniform for $t$ in compact intervals. The Lie-Trotter product formula has approximation order 1; that is, in general there exists a constant $M_{g,t}$ such that
     $$\|T(t)x - \left(V(\frac{t}{n})\right)^n x \| \le \frac{M_{x,t}}{n}.$$ 
\item [(2)] If $V(t):=e^{\frac{t}{2}\K_2}e^{t\K_1}e^{\frac{t}{2}\K_2}$. Then, by Chernoff's theorem, $$\mathcal{K}:=\overline{\mathcal{K}_{1}+\mathcal{K}_{2}}$$
generates a strongly continuous semigroup $(T(t))_{(t\geq 0)}$ given by the \textit{Strang product formula }
\begin{equation}\label{SP}
    T(t)x=\lim_{n \to \infty}\Bigg(e^{\frac{t}{2n}\K_2}e^{\frac{t}{n}\K_1}e^{\frac{t}{2n}\K_2}\Bigg)^{n}x
\end{equation}
for all $x\in X$ and the limit is uniform for $t$ in compact intervals. In general, the Strang product formula has approximation order 2; that is, in general there exists a constant $M_{g,t}$ such that
     $$\|T(t)x - \left(V(\frac{t}{n})\right)^n x \| \le \frac{M_{x,t}}{n^2}.$$
     \begin{remark}
         The Lie-Trotter and Strang product formulas can also be employed in cases where the Koopman-Lie generator $\K$ can be split into $N$ simpler parts $\mathcal{K}=\K_1 +\cdots +\K_N$. Then we can rewrite the Lie-Trotter and Strang product formulas, as follows:
     \end{remark}
\item[(3)] If $V(t):=e^{t\K_1}e^{t\K_2}\cdots e^{t\K_N}$. Then, the higher dimensional Lie-Trotter product formula is given by
\begin{equation}\label{LTH}
    T(t)x=\lim_{n \to \infty}\Bigg(e^{\frac{t}{n}\K_1}e^{\frac{t}{n}\K_2}\cdots e^{\frac{t}{n}\K_N}\Bigg)^{n}x.
\end{equation}
\item[(4)] If $V(t):=e^{\frac{t}{2}\K_N}\cdots e^{t\K_1}\cdots e^{\frac{t}{2}\K_N}$. Then, the higher dimensional Strang product formula is given by 
\begin{equation}\label{SPH}
    T(t)x=\lim_{n \to \infty}\Bigg(e^{\frac{t}{2n}\K_N}\cdots e^{\frac{t}{2n}\K_2}e^{\frac{t}{n}\K_1}e^{\frac{t}{2n}\K_2}\cdots e^{\frac{t}{2n}\K_N}\Bigg)^{n}x.
\end{equation}

\end{enumerate}



\subsection{Higher-order Exponential Splitting Schemes}\label{sec:higher}
In \cite{JD5} and \cite{JD6}, E. Hansen and A. Ostermann consider exponential splitting schemes 
\begin{equation}\label{sec:HigherOrder}
    V_{p}(t):=\prod _{j=1}^{s}e^{\alpha_{j}t\mathcal{K}_{1}}e^{\beta_{j}t\mathcal{K}_{2}},
\end{equation}
where the real or complex coefficients $\alpha_{j}$'s and $\beta_{j}$'s are chosen in such a way that the method is algebraically of order $p$, meaning that whenever the operators $\mathcal{K},\mathcal{K}_{i}$ are replaced by finite matrices $\mathcal{M},\mathcal{M}_{i}$, we have
$$\|V(t)-e^{t\mathcal{M}}\| = O(t^{p+1}).$$
For example, to obtain a  $3$-stage splitting of the form (\ref{sec:HigherOrder}), consider 
 $$\K = \alpha_1\K_1+\beta_1\K_2 + \alpha_2\K_1+\beta_2\K_2 + \alpha_3\K_1+\beta_3\K_2$$
 with $\alpha_1+\alpha_2+ \alpha_3 = 1$, $\beta_1+\beta_2 +\beta_3 = 1$ for which the associated product formula
$$V(t)= e^{\alpha_1 t \K_1} e^{\beta_1 t\K_2} e^{\alpha_2 t \K_1} e^{\beta_2 t\K_2} e^{\alpha_3 t\K_1}   e^{\beta_3 t\K_2}$$
is algebraically of order $p = 3$. 
For such s-stage schemes, they provide a general error-estimate framework for the approximations of solutions of linear problems of the form 
\begin{equation}
    {x'}(t)=\mathcal{K}x(t)=(\mathcal{K}_{1}+\mathcal{K}_{2})x(t), \:\; x(0)=x
\end{equation}
where $\mathcal{K}_{1}$, $\mathcal{K}_{1}$, and $\mathcal{K}=\mathcal{K}_{1}$+$\mathcal{K}_{2}$ are generators of strongly continuous contraction semigroups (or analytic contraction semigroups if the coefficients $\alpha_{j}$'s and $\beta_{j}$'s are complex). Their analysis is based on the consideration of the operators $E_{p+1}$ that can be obtained as the product of exactly $p+1$ factors chosen among $\mathcal{K}_{1}$ or $\mathcal{K}_{2}$. 

\begin{theorem}{\cite{JD5}, \cite{JD6}}.\label{ha}
Let $\mathcal{K}_{1}$, $\mathcal{K}_{2}$, and $\mathcal{K}=\mathcal{K}_{1}$+$\mathcal{K}_{2}$ be generators of strongly continuous contraction semigroups on a Banach space $X$ (or analytic contraction semigroups if the coefficients $\alpha_{j}$'s and $\beta_{j}$'s are complex). Assume that 
there exists a subspace $U\subset D(\mathcal{K}^{p+1})$ such that all ${E}_{p+1}e^{t\mathcal{K}} : U \to X$ are well defined and all $E_{p+1}e^{t\mathcal{K}}u$ are uniformly bounded in $t\in [0,T]$ for any $u\in U$. Then, for all $u\in U$ and $T>0$, there exists a constant $M_{u,T}$ such that
\begin{equation}
\Vert V_{p}(\frac{t}{n})^{n}u-e^{t\mathcal{K}}u \Vert \leq M_{u,T} \frac{t^{p+1}}{n^{p}(p+1)!},  \;\; 0\leq t \leq T.
\end{equation}
\end{theorem}

\noindent
\textbf{Outline of proof:}
The proof is based on estimate of the form (\ref{estimate}); i.e, 
\begin{equation}
 \begin{split}
 \Vert V_{p}(\frac{t}{n})^{n}x-(e^{\frac{t\mathcal{K}}{n}})^{n}x\Vert &=\Vert \sum_{j=0}^{n-1}V_{p}(\frac{t}{n})^{n-j-1}(V_{p}(\frac{t}{n})-e^{{\frac{t\mathcal{K}}{n}}})e^{j\frac{t\mathcal{K}}{n}}x \Vert\\
 &\leq \sum_{j=0}^{n-1}\Vert (V_{p}(\frac{t}{n})-e^{\frac{t\mathcal{K}}{n}})e^{j\frac{t\mathcal{K}}{n}}x\Vert
 \end{split}
  \end{equation}
  and a sophisticated and elaborate estimate of the term $\Vert (V_{p}(\frac{t}{n})-e^{\frac{t\mathcal{K}}{n}})e^{j\frac{t\mathcal{K}}{n}}x\Vert$. \qed
\begin{remark} Since the proof of Theorem \ref{ha} given  in \cite{JD5} is of an algebraic nature, it can be extended to bi-continuous contraction semigroups without changing any of arguments. 
  \end{remark}


