In addition, all the methods mentioned above for solving autonomous three-dimensional problems can be generalized into a straightforward method for solving systems of differential equations via separation of variables, as explained below.

\begin{remark}\label{rem324}
     Let $F = (F_1,F_2,F_3):\mathbb{R}^3\supset \Omega \to \mathbb{R}^3$, $\Omega$ closed. If
$u'(t) = F(u(t))$, $u(0) = x,$
has unique, global, jointly continuous  solutions $\sigma(t,x) \in \Omega$ for all, $x=(x_1,x_2,x_3)\in\Omega,$ then
$$
T(t)g(x):=g(\sigma(t,x)) = e^{t\K}g(x) = e^{t(\K_1 +\K_2+\K_3)}g(x)$$ is bi-continuous on $C_b(\Omega)$, where
 $\K_ig(x) : = F_i(x)g_{x_i}(x)$. Define \\
  $ e^{t\K_1}g(x)= g(  \sigma(t, x_1), x_2,x_3)$, $ e^{t\K_2}g(x)= g(x_1,  \gamma(t,x_2),x_3)$, and $ e^{t\K_3}g(x)= g(x_1, x_2,  \tau(t,x_3))$.
 Here,  $\sigma(t, x_1)$ solves the frozen  problem 
 $x'(t)=F_1(x(t),x_2,x_3), x(0)=x_1$,  $ \gamma(t, x_2)$ solves the frozen problem $x'(t)=F_2(x_1,x(t),x_3), x(0)=x_2$, and  $ \tau(t, x_3)$ solves the frozen problem $x'(t)=F_3(x_1,x_2, x(t)), x(0)=x_3$. Thus, applying  contractions $V_{1}(t)=e^{t\K_3}e^{t\K_2}e^{t\K_1}$ such that 
\begin{equation*}
 g(\sigma(t,x)) = T(t)g(x) = \lim_{n\to\infty} \left(V(\frac{t}{n})\right)^n g(x) =  \lim_{n\to\infty} g(x_n(t,x)),
 \end{equation*}
where by Proposition \ref{Frank}, $\sigma(t,x)=\lim_{n\to \infty}x_n(t,x)$. This is equivalent to solving 
\begin{equation*}
     (x'(t),y'(t),z'(t))=(F_1(x(t),y(t),z(t)), F_2(x(t),y(t),z(t)),F_3(x(t),y(t),z(t))), 
\end{equation*}
given $(x(0), y(0), z(0)) = (x, y, z)$, via separation of variables after splitting into the following first-order sub-problems. We first freeze the variables $y$ and $z$ and solve the first-order problem 
$$x'(t) = F_1(x(t), y, z), \, x(0)=x_0 = x$$
with solution $x(t) = \sigma_{y,z}(t, x)$, then  freeze $x$ and $z$ to solve
$$y'(t) = F_2(x, y(t), z), \, y(0)=y_0 = y$$ with solution $y(t) = \gamma_{x,z}(t, y)$, and then freeze $x$ and $y$ to solve 
$$z'(t) = F_3(x, y, z(t)), \, z(0)=z_0 = z$$ with solution $z(t) = \tau_{x,y}(t, z)$. Finally, we combine the solutions of the sub-problems with a product formula like Lie-Trotter $V_{1}(t)$ or $V{S}(t)$, where 
$$e^{t\K_1}g(x,y,x) = g(\sigma_{y,z}(t, x),y,z), \hspace{1em} e^{t\K_2}g(x,y,z) = g(x,  \gamma_{x,z}(t, y),z), \hbox{ and } $$ $$e^{t\K_3}g(x,y,z) = g(x, y,  \tau_{x,y}(t, z)).$$
\noindent To apply Lie-Trotter $V_{1}(t)$ ,we use the following simple algorithm with starting values $x_0:=x$, $y_0:=y$, $z_0:=z$. Then, for $0\leq k \leq n-1$, we use the iterative process \\ \vspace{2em}
\begin{minipage}{0.36\textwidth}
\begin{align*}
        { {\color{red}(1)}} \quad & z_{k+1}&=\hbox{} &\tau_{x_{k},y_{k}}(\frac{t}{n},z_k),\\
 { {\color{blue}(2)}}  \quad & y_{k+1} &=\hbox{} &\gamma_{x_{k},z_{k+1}}(\frac{t}{n},y_k),\\
   { {\color{Green}(3)}}  \quad & x_{k+1}&=\hbox{} &\sigma_{y_{k+1},z_{k+1}}(\frac{t}{n},x_k).
       \end{align*}   
\end{minipage} %\hspace{em}
\begin{minipage}{0.62\textwidth}
    \begin{center}
    \includegraphics[keepaspectratio, scale=1.8]{pic/unit42.pdf}

     \end{center}
\end{minipage}
Then, $x_n=x_n(t)\approx x(t)$ , $y_n=y_n(t)\approx y(t)$,
$z_n=z_n(t)\approx z(t)$ with approximation order $C\frac{t^2}{n}$.

In Appendices \ref{app32} and \ref{app33}, we provide additional algorithms illustrating how the Strang splitting and third-order approximations can be applied to three-dimensional problems. Throughout this work, we employ all of the algorithms discussed to numerically approximate solutions to various systems. Moreover, even algorithms that are not explicitly presented here can be systematically constructed following similar procedures, highlighting the flexibility and generality of our approach.

\end{remark}

\section{Numerical Experiments}\label{sec:experiments}

\begin{example}[Lotka-Volterra]

The Lotka–Volterra model describes the interaction between predator and prey populations over time. It captures how prey grow in the absence of predators, while predators depend on prey for survival. This interaction leads to cyclical population dynamics governed by a nonlinear system of differential equations:
\begin{align*}
x'(t)&=\alpha x(t)-\beta x(t)y(t), \quad x(0)=x_0=x\\
y'(t)&=\delta x(t)y(t)-\tau y(t), \quad y(0)=y_0=y
\end{align*}
\textbf{Step 1:} Solve the first-order system via separation of variables.
 \begin{itemize}
   \item[a)] Freeze $y$: \hspace{1.8em}  $x'(t)= x(t)( \alpha -\beta y )$
   $$ \Rightarrow x(t) = \sigma_y(t,x)= x e^{t(\alpha - \beta y)}$$

   \item[b)] Freeze $x$: \hspace{1.8em}  $ y'(t) = y(t)( \delta x -\tau ) $
   $$ \Rightarrow y(t) = \gamma_x(t,y) = y e^{t(\delta x- \tau)}$$
   \end{itemize}
\textbf{Step 2:} Finally, to approximate the solutions, we can apply the Lie-Trotter $V_1(t)$ method (see part (a), Remark \ref{remApp}).



