sort Colour = struct red | green;
act red_button, green_button, set_red, set_green;
proc P(col: Colour) = 
         red_button.(col==green)->set_red.P(red) 
                                <> P(col)
       + green_button.(col==red)->set_green.P(green) 
                                <> P(col);
init P(red);
    \end{lstlisting}
  \end{minipage}
