\section{The DP-MAC With SE-R and Feedback}\label{sec-3}

\subsection{Model Formulation}
The DP-MAC with SE-R and feedback is depicted in Fig. \ref{figmod-2}, and  the channel output at time instant $t$ is given by
\begin{equation}
	Y_t=X_{1,t}+X_{2,t}+S_t+\eta_t,  \, t=1,2,\ldots,n,
\end{equation}
where $X_{i,t}$ ($i \in \{1,2\}$) is the output signal of Encoder $i$, $\eta_t \sim \mathcal{N}(0,\sigma^2)$ is an i.i.d. channel noise, and $S_t \sim \mathcal{N}(0,Q)$ is an i.i.d. state interference. Both transmitters know the  state sequence $S^n=(S_1,S_2,\ldots,S_n)$ in a non-causal manner.
In addition, we assume that $\eta_t$, $S_t$ and the messages $W_1,W_2$  are independent of each other.

An $(n,R_1,R_2,P_1,P_2)$-code for the model of Fig. \ref{figmod-2} consists of:
\begin{enumerate}[1)]
	\item two messages $W_1$ and $W_2$, where $W_i$
	is uniformly distributed over the set $\mathcal{W}_i=\{1,2,\ldots,2^{nR_i}\}$ for $i \in \{1,2\}$;
	\item two encoders (Encoder $1$ and Encoder $2$), where Encoder $i$ ($i \in \{1,2\}$) with output $X_{i,t}=\varphi_{i,t}(W_i,S^n,Y^{t-1})$ satisfying the average power constraint $
	\frac{1}{n}\sum_{t=1}^{n}{\rm E}[X_{i,t}^2] \le P_i$;
	\item a decoder with outputs $(\hat{W}_1,\hat{W}_2)=\psi(Y^n)$ and $\hat{S}^n=\phi(Y^n)$, where $\psi$ and $\phi$ are the decoding and estimation functions, respectively.

\end{enumerate}
The average decoding error probability is defined as
\begin{equation}\label{pe-def2}
\begin{aligned}
	P_{e}^{(n)}=\frac{1}{2^{n(R_1+R_2)}}\sum_{w_1=1}^{2^{nR_1}}\sum_{w_2=1}^{2^{nR_2}}\Pr\{&\psi(Y^n)\neq (w_1,w_2)\\
	&|(w_1,w_2)\;\mbox{was sent}\},
\end{aligned}
\end{equation}
and the mean-squared state estimation error ${\rm E}d(S^n,\hat{S}^n)$ satisfies (\ref{ee-def}).

An R-D tuple $(R_1, R_2, D)$ is achievable if for any $\epsilon>0$,
there exists the above $(n,R_1,R_2,P_1,P_2)$-code such that  $\frac{1}{n}H(W_1) \ge R_1-\epsilon$, $\frac{1}{n}H(W_2)\ge R_2-\epsilon$, $P_e^{(n)}\le \epsilon$, and ${\rm E}d(S^n,\hat{S}^n)\le D+\epsilon$ as $n\to \infty$.
The optimal R-D trade-off region for the DP-MAC with  SE-R and feedback is the closure of the convex hull of all achievable $(R_1, R_2, D)$ tuples, denoted as $\mathscr{C}_{\rm dp,mac}^{\rm fb}$.

\subsection{Main Results}
The following Theorem $\ref{th01}$ provides a  complete characterization of $\mathscr{C}_{\rm dp,mac}^{\rm fb}$.

\begin{theorem}\label{th01}
$\mathscr{C}_{\rm dp,mac}^{\rm fb}=\bigcup_{0\le \rho \le 1}\mathcal{R}(\rho)$, and $\mathcal{R}(\rho)$ is given by
	\begin{equation}\label{c2}
		\begin{aligned}
		\mathcal{R}(\rho)&=\bigcup_{0\le \gamma \le 1}\bigcup_{0\le \beta \le 1}
		\Big
		\{(0\le R_1,0\le R_2,D):\\
		R_1 &\le \frac{1}{2}\log \Big(1+\frac{\gamma P_1(1-\rho^{2})}{\sigma^2}\Big),\\
		R_2 &\le \frac{1}{2}\log \Big(1+\frac{\beta P_2(1-\rho^{2})}{\sigma^2}\Big),\\
		R_1+R_2 &\le  \frac{1}{2}\log \Big(1+\frac{\gamma P_1+\beta P_2+2\sqrt{\gamma P_1 \beta P_2}\rho}{\sigma^2}\Big),\\
		D&\ge \frac{Q(\gamma P_1+ \beta P_2+\sigma^2+2\sqrt{\gamma P_1 \beta P_2}\rho)}{L(\gamma,\beta)+2\sqrt{\gamma P_1 \beta P_2}\rho}
		\Big\}.
		\end{aligned}
	\end{equation}
where
\begin{equation}\label{lde}
\begin{aligned}
	L(\gamma,\beta)&=P_1+P_2+Q+\sigma^2+2\sqrt{(1-\gamma)P_1Q}\\
	&+2\sqrt{(1-\beta)P_2Q}+2\sqrt{(1-\gamma)(1-\beta)P_1P_2}.
\end{aligned}
\end{equation}	
\end{theorem}
\begin{proof}
See the next subsection.
\end{proof}
\begin{remark}\label{rem1}
	For the  DP-MAC with SE-R and without feedback, the optimal R-D trade-off region was characterized in \cite{jsec-mac} and is given by
		\begin{equation}
		\begin{aligned}
			&\mathscr{C}_{\rm dp,mac}=\bigcup_{0\le \gamma \le 1}\bigcup_{0\le \beta \le 1}
			\Big
			\{(0\le R_1,0\le R_2,D):\\
			&R_1 \le \frac{1}{2}\log \Big(1+\frac{\gamma P_1}{\sigma^2}\Big),
			R_2 \le \frac{1}{2}\log \Big(1+\frac{\beta P_2}{\sigma^2}\Big),\\
			&R_1+R_2 \le  \frac{1}{2}\log \Big(1+\frac{\gamma P_1+\beta P_2}{\sigma^2}\Big),\\		
			&D\ge \frac{Q(\gamma P_1+ \beta P_2+\sigma^2)}{L(\gamma,\beta)}
			\Big\}.
		\end{aligned}
	\end{equation}
where  $L(\gamma,\beta)$ is given in (\ref{lde}).
Letting $\rho=0$ in (\ref{c2}), we conclude that $\mathscr{C}_{\rm dp,mac}=\mathcal{R}(0)$. Then by changing $0 \le  \rho \le 1$, $\mathscr{C}_{\rm dp,mac}^{\rm fb}=\bigcup_{0\le \rho \le 1}\mathcal{R}(\rho)$ achieves a larger region than $\mathscr{C}_{\rm dp,mac}$, which indicates that \textit{feedback enhances the  optimal R-D trade-off region of the  DP-MAC with SE-R and without feedback}.
\end{remark}

\subsection{Proof of Theorem \ref{th01}}\label{sec3-3}
\subsubsection{Proof of Achievability}
The main idea of the SK-type feedback scheme for the DP-MAC with SE-R is briefly illustrated below.
Encoder $1$ uses power $(1-\gamma)P_1$ ($0\le \gamma \le 1$) to encode $S^n$ as $V_1^n=\sqrt{\frac{(1-\gamma)P_1}{Q}}S^n$,  uses power $\gamma P_1$ to encode $W_1$ and the feedback $Y^{n-1}$ as $G_1^n$, and then sends $X_1^n=V_1^n+G_1^n$.
Encoder $2$ uses power $(1-\beta)P_2$ ($0\le \beta \le 1$) to encode $S^n$ as $V_2^n=\sqrt{\frac{(1-\beta)P_2}{Q}}S^n$,  uses power $\beta P_2$ to encode $W_2$ and the feedback $Y^{n-1}$ as $G_2^n$, and then sends $X_2^n=V_2^n+G_2^n$.
Define $\lambda=1 +\sqrt{\frac{(1-\gamma)P_1}{Q}}+\sqrt{\frac{(1-\beta)P_2}{Q}}$,
the received channel output  can be written as
\begin{equation}\label{outp2}
		Y^n=X_1^n+X_2^n+S^n+\eta^n
			=G_1^n+G_2^n+\lambda S^n +\eta^n.
\end{equation}
Then $G_1^n$ and $G_2^n$ are constructed by the SK-type feedback scheme \cite{dpmac-fed} for the DP-MAC with a new state $\lambda S^n$.
The codewords $G_1^n$ and $G_2^n$ are described below.

At time $1$, $G_{2,1}=0$ and
\begin{equation}
	G_{1,1}=\sqrt{12\gamma P_1}(\theta_1-O_1),
\end{equation}
where $\theta_1=-\frac{1}{2}+\frac{(2W_1-1)}{2\cdot2^{nR_1}}$ and $O_1=\frac{\lambda}{\sqrt{12\gamma P_1}}S_1-\lambda \sum_{i=3}^{n}\mu_{1,i}S_i$.
The receiver gets
$Y_1=\sqrt{12\gamma P_1}(\theta_1-O_1) + \lambda S_1 +\eta_1$,
and calculates
$\hat{\theta}_{1,1}=\frac{Y_1}{\sqrt{12\gamma P_1}}=\theta_1+\lambda \sum_{i=3}^{n}\mu_{1,i}S_i+\varepsilon_{1,1}$, where $\varepsilon_{1,1}=\frac{\eta_1}{\sqrt{12\gamma P_1}}$, and $\alpha_{1,1}=\frac{\sigma^2}{12\gamma P_1}$.

At time $2$, $G_{1,2}=0$ and
\begin{equation}
	G_{2,2}=\sqrt{12\beta P_2}(\theta_2-O_2),
\end{equation}
where $\theta_2=-\frac{1}{2}+\frac{(2W_2-1)}{2\cdot2^{nR_2}}$ and $O_2=\frac{\lambda}{\sqrt{12\beta P_2}}S_2-\lambda \sum_{i=3}^{n}\mu_{2,i}S_i$.
The receiver gets
$Y_2=\sqrt{12\beta P_2}(\theta_2-O_2)+ \lambda S_2 +\eta_2$,
and calculates
$\hat{\theta}_{2,2}=\frac{Y_2}{\sqrt{12\beta P_2}}=\theta_2+\lambda \sum_{i=3}^{n}\mu_{2,i}S_i+\varepsilon_{2,2}$, where $\varepsilon_{2,2}=\frac{\eta_2}{\sqrt{12\beta P_2}}$, and $\alpha_{2,2}=\frac{\sigma^2}{12\beta P_2}$.
Let $\varepsilon_{1,2}\triangleq\varepsilon_{1,1}$ and $\alpha_{1,2}\triangleq\alpha_{1,1}$.

At time $t$ ($t\in\{3,\ldots,n\}$),
\begin{equation}\label{g1g2}
G_{1,t}=\sqrt{\frac{\gamma P_1}{\alpha_{1,t-1}}}\varepsilon_{1,t-1}, G_{2,t}=\text{sgn}(\rho_{t-1})\sqrt{\frac{\beta P_2}{\alpha_{2,t-1}}}\varepsilon_{2,t-1},
\end{equation}
where  for $i\in\{1,2\}$, $\alpha_{i,t-1}\triangleq {\rm Var}[\varepsilon_{i,t-1}]$,
$\varepsilon_{i,t-1}=\varepsilon_{i,t-2}-\mu_{i,t-1}(Y_{t-1}-\lambda S_{t-1})$,
$\mu_{i,t-1}=\frac{{\rm E}[\varepsilon_{i,t-2}(Y_{t-1}-\lambda S_{t-1})]}
{{\rm E}[(Y_{t-1}-\lambda S_{t-1})^2]}$,
$\rho_{t-1}=\frac{{\rm E}[\varepsilon_{1,t-1}\varepsilon_{2,t-1}]}{\sqrt{\alpha_{1,t-1}\alpha_{2,t-1}}}$ is the correlation coefficient between $\varepsilon_{1,t-1}$ and $\varepsilon_{2,t-1}$, $\text{sgn}(\rho_{t-1})$ is equal to $1$ if $\rho_{t-1}\ge 0$ and $0$ otherwise.

The analysis of achievable rates is similar to the SK-type schemes \cite{dpmac-fed,sk-mac} for the multiple-access channels. Hence we omit some steps of the proof and conclude that the achievable rates of this scheme satisfy
\begin{equation}
\begin{aligned}
&R_1\le \frac{1}{2}\log \Big(1+\frac{\gamma P_1 (1-\rho^{*2})}{\sigma^2}\Big),\\
&R_2 \le \frac{1}{2}\log \Big(1+\frac{\beta P_2 (1-\rho^{*2})}{\sigma^2}\Big),\\
&R_1+R_2\le \frac{1}{2}\log \Big(1+\frac{\gamma P_1+ \beta P_2+2\sqrt{\gamma P_1 \beta P_2}\rho^*}{\sigma^2}\Big),
\end{aligned}
\end{equation}
where $\rho^*$ is the unique positive root in $(0,1)$ of
\begin{equation}
\begin{aligned}
&\sigma^2\left(\gamma P_1+ \beta P_2+2\sqrt{\gamma P_1 \beta P_2}\rho+\sigma^2\right)\\
