\section{The Converse Part of Theorem 1}\label{App1}
\setcounter{equation}{0}

First, rate $R_1$ is bounded by
\begin{equation}\label{R1-a}
	\begin{aligned}
		R_1=&\;\frac{1}{n}H(W_1)\stackrel{(a)}=\frac{1}{n}H(W_1|W_2)\\
		=&\;\frac{1}{n}\big[H(W_1|W_2)-H(W_1|Y^n,S^n,W_2)\\
		&\;\;\;\;\;\;+H(W_1|Y^n,S^n,W_2)\big]\\
		\stackrel{(b)}\le &\; \frac{1}{n}I(W_1;Y^n,S^n|W_2)+\epsilon_{n}\\
		=&\;\frac{1}{n}\big[I(W_1;Y^n|S^n,W_2)+I(W_1;S^n|W_2)\big]+\epsilon_{n}\\
		\stackrel{(c)}=&\;\frac{1}{n}\Bigg[\sum_{i=1}^{n}\big[h(Y_i|Y^{i-1},S^n,W_2)\\
		&\;\;\;\;\;\;-h(Y_i|Y^{i-1},S^n,W_2,W_1)\big]\Bigg]+\epsilon_{n}\\
		\stackrel{(d)}=&\;\frac{1}{n}\Bigg[\sum_{i=1}^{n}\big[h(Y_i|X_{2,i},Y^{i-1},S^n,W_2)\\
		&\;\;\;\;\;\;-h(Y_i|X_{1,i},X_{2,i},Y^{i-1},S^n,W_2,W_1)\big]\Bigg]+\epsilon_{n}\\
		\stackrel{(e)} \le &\; \frac{1}{n}\sum_{i=1}^{n} \big[h(Y_i|X_{2,i},S_i)-h(Y_i|X_{1,i},X_{2,i},S_i)\big]
		+\epsilon_{n},
	\end{aligned}	
\end{equation}
where
\begin{enumerate}[(a)]
	\item follows from the fact that $W_2$ is independent of $W_1$;
	\item follows from  conditioning reduces entropy and Fano's inequality, i.e.,
	\begin{equation}
		H(W_1|Y^n,S^n,W_2)\le H(W_1,W_2|Y^n,S^n) \le n\epsilon_{n}, \nonumber
	\end{equation}
	where $\epsilon_{n}\to 0$ as $n \to \infty$;
	\item follows from the fact that $W_1$, $S^n$ and $W_2$ are independent and chain rule;
	\item follows from the fact that $X_{1,i}=\varphi_{1,i}(W_1,Y^{i-1},S^{n})$ and $X_{2,i}=\varphi_{2,i}(W_2,Y^{i-1},S^{n})$;
	\item follows from conditioning reduces entropy and the fact that the channel output at time $i$	depends only on the state $S_i$ and the inputs $X_{1,i}$ and  $X_{2,i}$, i.e.,
\end{enumerate}
\begin{equation}
	\begin{aligned}
		H(Y_i|X_{2,i},Y^{i-1},S^n,W_2) &\le H(Y_i|X_{2,i},S_{i}),\nonumber\\	
		H(Y_i|X_{1,i},X_{2,i},Y^{i-1},S^n,W_2,W_1)&=H(Y_i|X_{1,i},X_{2,i},S_i).
	\end{aligned}
\end{equation}

Similarly,
\begin{equation}
	R_2\le \frac{1}{n}\sum_{i=1}^{n} \big[h(Y_i|X_{1,i},S_i)-h(Y_i|X_{1,i},X_{2,i},S_i)\big]
	+\epsilon_{n},
\end{equation}
and the sum rate $R_1+R_2$ is bounded by
\begin{equation}\label{RS-a}
	\begin{aligned}
		R_1+ R_2&=\frac{1}{n}H(W_1,W_2)
		\le \frac{1}{n}I(W_1,W_2;Y^n|S^n)+\epsilon_{n}\\
		&\le \frac{1}{n} \sum_{i=1}^{n}\big[h(Y_i|S_i)-h(Y_i|X_{1,i},X_{2,i},S_i)\big]+\epsilon_{n}.
	\end{aligned}
\end{equation}

According to Lemma 1 in \cite{jsec-mac},  any communication scheme achieving a
distortion $D_n=\frac{1}{n}\sum_{t=1}^{n}{\rm E}[(S_t-\hat{S}_t)^2]$ over block length $n$ will have
\begin{equation}
	\frac{1}{2}\log \frac{Q}{D_n} \le \frac{1}{n}I(S^n;Y^n).
\end{equation}
Next, the sum $R_1+R_2+\frac{1}{2}\log \frac{Q}{D_n}$ is bounded by
\begin{equation}\label{rs-d-a}
	\begin{aligned}
		R_1&+R_2+\frac{1}{2}\log \frac{Q}{D_n}\\
		&\le
		\frac{1}{n}I(W_1,W_2;Y^n|S^n)
		+\frac{1}{n}I(S^n;Y^n)+\epsilon_{n}\\
		&=\frac{1}{n}I(W_1,W_2,S^n;Y^n)+ \epsilon_{n}\\
		&\le \frac{1}{n}\sum_{i=1}^{n}\big[h(Y_i)-h(Y_i|X_{1,i},X_{2,i},S_i)\big] +\epsilon_{n}.
	\end{aligned}
\end{equation}

Assume that $X_{1,i}$, $X_{2,i}$ and $S_{i}$ have zero means, variances $P_1$, $P_2$ and $Q$. In addition, the covariance matrix of the vector $[X_{1,i},X_{2,i},S_i]^T$ is assumed to be
\begin{equation}\label{ks-a}
	K_{X_{1,i},X_{2,i},S_i}=
	\begin{bmatrix}
		P_1	& a_i\sqrt{P_1P_2} & b_i\sqrt{P_1Q} \\
		a_i\sqrt{P_1P_2}	& P_2 & c_i\sqrt{P_2Q} \\
		b_i\sqrt{P_1Q}	& c_i\sqrt{P_2Q} & Q
	\end{bmatrix},
\end{equation}
where $-1\le a_i \le 1$, $-1\le b_i \le 1$, and $-1\le c_i \le 1$.
From (\ref{ks-a}),   the covariance matrix of the error vector of
the MMSE estimate of ${\bf X}_i=[X_{1,i},X_{2,i}]^T$ given $S_i$ is
\begin{equation}\label{givs-k}
	\begin{aligned}
		K_{{\bf X}_i|S_i}&=K_{{\bf X}_i}-K_{{\bf X}_iS_i} K_{S_i}^{-1}K_{S_i{\bf X}_i}\\
		&=\begin{bmatrix}
			(1-b_i^2)P_1	& (a_i-b_ic_i)\sqrt{P_1P_2}  \\
			(a_i-b_ic_i)\sqrt{P_1P_2}	& (1-c_i^2)P_2 \\
		\end{bmatrix},
	\end{aligned}
\end{equation}
and the correlation coefficient between $X_{1,i}$ and $X_{2,i}$ given $S_i$ is denoted as
\begin{equation}\label{rhoi}
	\rho_i =\frac{a_i-b_ic_i}{\sqrt{1-b_i^2}\sqrt{1-c_i^2}}.
\end{equation}
Here note that $\rho_i=0$ in the converse proof of \cite{jsec-mac}.
Then we calculate the differential entropy in (\ref{R1-a})-(\ref{RS-a}) and (\ref{rs-d-a}).

According to $Y_i=X_{1,i}+X_{2,i}+S_i+\eta_i$, we have
\begin{equation}\label{wfs-1}
	h(Y_i|X_{1,i},X_{2,i},S_i)=h(\eta_i)\stackrel{(a)}=\frac{1}{2}\log (2 \pi e \sigma^2),
\end{equation}
where (a) follows from the fact that $\eta_i$ is the Gaussian noise with zero-mean and variance $\sigma^2$,
and
\begin{equation}
	\begin{aligned}
		h(Y_i)&=h(X_{1,i}+X_{2,i}+S_i+\eta_i)\\
		&\le \frac{1}{2}\log \big(2 \pi e \big(P_{1}+P_{2}+Q+2a_i\sqrt{P_{1}P_{2}}\\ &\;\;\;+2b_i\sqrt{P_{1}Q}+2c_i\sqrt{P_{2}Q}+\sigma^2\big)\big),
	\end{aligned}	
\end{equation}
where the last step follows from maximum differential entropy lemma.

From (\ref{givs-k}) and (\ref{rhoi}), the term $h(Y_i|S_i)$ can be  written as
\begin{equation}
	\begin{aligned}
		h&(Y_i|S_i)=h(X_{1,i}+X_{2,i}+\eta_i|S_i)\\
		&\le \frac{1}{2}\log \Big(2\pi e \Big((1-b_i^2)P_{1}+(1-c_i^2)P_{2}\\
		&\;\;\;\;+2(a_i-b_ic_i)\sqrt{P_1P_2}+\sigma^2\Big)	
		\Big)\\
		&= \frac{1}{2}\log \Big(2 \pi e \Big((1-b_i^2)P_{1}+(1-c_i^2)P_{2}\\
		&\;\;\;\;+2\sqrt{P_{1}P_{2}}\sqrt{1-b_i^2}\sqrt{1-c_i^2}\rho_i+\sigma^2\Big)\Big).
	\end{aligned}
\end{equation}

Analogously, we have
\begin{equation}
	\begin{aligned}
		h&(Y_i|X_{2,i},S_i)=h(X_{1,i}+\eta_i|X_{2,i},S_i)\\
		&\le \frac{1}{2}\log \left(2 \pi e \left({\rm E}[(X_{1,i}-\hat{X}_{1,i}(X_{2,i},S_i))^2]+\sigma^2\right)\right)\\
		&= \frac{1}{2}\log \left(2 \pi e \left((1-b_i^2)P_{1}(1-\rho_i^2)+\sigma^2\right)\right),
	\end{aligned}
\end{equation}
where $\hat{X}_{1,i}(X_{2,i},S_i)$ is the MMSE estimate of $X_{1,i}$ given ${\bf V}_i=[X_{2,i},S_i]^T$, and the corresponding  minimum mean squared error is
\begin{equation}
	\begin{aligned}
		&K_{X_{1,i}}-K_{X_i{\bf V}_i}K_{{\bf V}_i}^{-1}K_{{\bf V}_iX_{1,i}}\\
		&=P_{1}\left(1-\frac{a_i^2-2a_ib_ic_i+b_i^2}{1-c_i^2}\right)
		=(1-b_i^2)P_{1}(1-\rho_i^2).
	\end{aligned}
\end{equation}
Similarly,
\begin{equation}\label{wfs-5}
	h(Y_i|X_{1,i},S_i)\le \frac{1}{2}\log \left(2 \pi e \left((1-c_i^2)P_{2}(1-\rho_i^2)+\sigma^2\right)\right).
\end{equation}

Define \begin{equation}\label{def-p-a}
	\gamma \triangleq \frac{1}{n} \sum_{i=1}^{n} (1-b_i^2), \beta \triangleq \frac{1}{n} \sum_{i=1}^{n} (1-c_i^2), \rho \triangleq \frac{1}{n} \sum_{i=1}^{n} \rho_i.
\end{equation}
Since $-1\le a_i,b_i,c_i \le 1$, we conclude that $0\le \gamma \le 1$, $0\le \beta \le 1$ and $-1\le \rho \le 1$.

By substituting (\ref{wfs-1})-(\ref{wfs-5}) into  (\ref{R1-a})-(\ref{RS-a}), and applying Jensen's inequality together with (\ref{def-p-a}), we conclude that
\begin{equation}\label{r12-up}
	\begin{aligned}
		&R_1\le  \frac{1}{2}\log \left(1+\frac{\gamma P_1}{\sigma^2}(1-\rho^2)\right),\\
		&R_2\le  \frac{1}{2}\log \left(1+\frac{\beta P_2}{\sigma^2}(1-\rho^2)\right),\\
		&R_1+R_2 \le \frac{1}{2}\log \left(1+\frac{\gamma P_{1}+\beta P_{2}+2\sqrt{\gamma \beta P_{1}P_{2}}\rho}{\sigma^2}\right),
	\end{aligned}
\end{equation}
Analogously, from (\ref{rs-d-a}), we have
\begin{equation}\label{r1r2d}
	R_1+R_2 +\frac{1}{2}\log \frac{Q}{D_n}
	\le \frac{1}{2}\log \left(1+\frac{L(\gamma,\beta)+2\sqrt{\gamma P_1 \beta P_2}\rho}{\sigma^2}\right),
\end{equation}
where
\begin{equation}\label{lde-a}
	\begin{aligned}
		L(\gamma,\beta)&=P_1+P_2+Q+\sigma^2+2\sqrt{(1-\gamma)P_1Q}\\
		&+2\sqrt{(1-\beta)P_2Q}+2\sqrt{(1-\gamma)(1-\beta)P_1P_2}.
	\end{aligned}
\end{equation}	

Equation (\ref{r1r2d}) can be  written as
\begin{equation}\label{d-it-a}
	D_n \ge \frac{Q\sigma^2 \cdot 2^{2(R_1+R_2)}}{L(\gamma,\beta)+2\sqrt{\gamma P_1 \beta P_2}\rho}.
\end{equation}
Substituting a fixed $R_1+R_2=\frac{1}{2}\log \Big(1+\frac{\gamma P_1+\beta P_2+2\sqrt{\gamma P_1 \beta P_2}\rho}{\sigma^2}\Big)$ into (\ref{d-it-a}), the distortion is bounded by
\begin{equation}\label{dn-low}
	D_n \ge \frac{Q(\gamma P_1+ \beta P_2+\sigma^2+2\sqrt{\gamma P_1 \beta P_2}\rho)}{L(\gamma,\beta)+2\sqrt{\gamma P_1 \beta P_2}\rho}.
\end{equation}
Hence, for any $0\le \gamma \le 1$, $0\le \beta \le 1$ and $-1\le \rho \le 1$, the closure of the convex hull of all regions that satisfy (\ref{r12-up}) for rate and (\ref{dn-low}) for distortion is the outer bound of the optimal R-D trade-off region $\mathscr{C}_{\rm dp,mac}^{\rm fb}$ of the DP-MAC with  SE-R and feedback.
Finally, since the region that satisfies (\ref{r12-up}) and (\ref{dn-low}) for $-1\le \rho <0$ is contained in the region for $0\le \rho \le 1$, the converse proof is completed.

