\subsection{Chance Constraints for Stochastic DC-MDPs} %  \& Chance Constraints

% We now turn our attention to MDPs with stochastic transitions, which are considerably more difficult to handle since they cannot be reformulated directly in the form (\ref{eqn:bilevel}). 

% A number of approaches could be used to encode stochastic variables, including sample approximation (SAA) \citep{kleywegt2002} and hindsight encoding \citep{raghavan2017} on the inner constraints, which would typically lead to a blowup in the problem size. 
%\emph{Chance-constrained} approaches \citep{ono2015,farina2016,ariu2017} instead generate constraints that hold with high probability, which often alleviate the computational burden at the expense of introducing some degree of (controllable) bias. Motivated by the recent applications of chance-constraints in planning and control, we take the latter approach, which will lead to a particularly elegant bi-level reformulation of (\ref{eqn:bilevel2}) as we now see.  

\emph{Chance-constrained optimization} \citep{ariu2017,farina2016,ono2015} allows us to derive high probability intervals on stochastic MDP transitions and reduce our solution to a robust optimization problem with probabilistic performance guarantees.
To achieve this, we will require that the state transition function $P(\st{}, \at{}, \st{}')$ has a natural reparameterization as a deterministic function $g$ of $(\st{}$, $\at{})$ and some exogenous independent and identically distributed noise variable $\xi$ with density $q(\cdot)$ on support $\Xi$, e.g. $\st{}' = g(\st{}, \at{}, \xi)$ \citep{bueno2019,patton2022}. Given a threshold $p \in (0, 1)$ close to 1, we also assume the existence of a computable interval $\Xi_p = [\xi_l, \xi_u]$ such that $\prob{\xi_l \leq \xi \leq \xi_u} \geq p$.

Thus, we can repeat the derivation of (\ref{eqn:bilevel}) by considering the worst case not only over $\st{1}$, but also over possible noise variables $\xi_{1:T} = [\xi_1, \dots \xi_T] \in \Xi_p^T$. The final problem is:
\begin{equation}
\label{eqn:bilevel-cc}
\begin{aligned}
    \min_{\mathbf{w} \in \mathcal{W}, \, \varepsilon \in [0, \infty)} \quad & \varepsilon  \\
    \textrm{s.t.}\quad &\varepsilon \!\geq\! \max_{\st{1}\in\states_1} \max_{\xi_{1:T} \in \Xi_p^T} \max_{\alpha \in \actions^T} \left[ V(\alpha, \st{1}, \xi_{1:T})\!-\! V(\mathbf{w}, \st{1}, \xi_{1:T}) \right],
\end{aligned}  
\end{equation}
where $V(\cdot, \st{1}, \xi_{1:T})$ corresponds to the total reward of the policy or plan accumulated over trajectory $\xi_{1:T}$ starting in $\st{1}$. In the stochastic setting, %it is important to note that 
$\varepsilon$ only holds with probability $p^T$ for a horizon $T$ problem. Experimentally, we found that choosing $p$ such that $p^T = P$, where $P$ is a desired probability bound on the full planning trajectory, was sufficient\footnote{Hence, we arbitrarily chose $p = 0.995$ for our empirical evaluations.}.

Once again, (\ref{eqn:bilevel-cc}) can be reformulated as:
\begin{equation}
\label{eqn:bilevel2-cc}
    \begin{aligned}
    \min_{\mathbf{w} \in \mathcal{W}, \, \varepsilon \in [0, \infty)} \quad &\varepsilon \\
    \textrm{s.t.} \quad &\varepsilon \geq V(\alpha, \st{1}, \xi_{1:T})- V(\mathbf{w}, \st{1}, \xi_{1:T}), \quad \, \forall \alpha \in \actions^T, \, \st{1} \in \states_1, \, \xi_{1:T} \in \Xi_p^T.
    \end{aligned}
\end{equation}
Therefore, we can again apply constraint generation to solve this problem in two stages, in which the inner optimization produces not only a worst-case initial state and action sequence, but also the disturbances $\xi_{1:T}^*$ that reproduce {all} future worst-case state realizations $\st{2}, \dots \st{T}$. The overall workflow of the computations is summarized as Algorithm~\ref{alg:stochastic}.

\begin{algorithm}[!h]
    \caption{Constraint-Generation Policy Optimization (CGPO)}
    \label{alg:stochastic}
    \begin{algorithmic}
        \STATE Initialize $p \in (0, 1)$, $\Xi_p$, $\st{1} \in\mathcal{S}_1$, $\xi_{1:T} \in \Xi_p^T$, $\alpha \in \mathcal{A}^T$
        \STATE Set $t = 0$ and $\mathcal{C}_0 = \lbrace (\st{1}, \xi_{1:T}, \alpha) \rbrace$
                \STATE \textbf{Step 1:} Solve the \textbf{outer problem}:
                \begin{equation*}     
                \begin{aligned}
                    (\mathbf{w}_t^*, \varepsilon_t^*) \in \,{\arg\!\min}_{\mathbf{w}\in\mathcal{W},\,\varepsilon \in [0, \infty)} \, &\varepsilon \\
                    \mathrm{s.t.} \quad &\varepsilon \geq V(\alpha, \st{1}, \xi_{1:T}) - V(\mathbf{w}, \st{1}), \quad \, \forall  \,( \st{1}, \xi_{1:T}, \alpha) \in \mathcal{C}_t
                \end{aligned}
                \end{equation*}   

                \STATE \textbf{Step 2:} Solve the \textbf{inner problem}:
                \begin{equation*}
                    \begin{aligned}
                    &(\st{1}^*, \xi_{1:T}^*, \alpha^*) \in {\arg\!\max}_{\st{1} \in \states_1, \, \xi_{1:T} \in \Xi_p^T,\, \alpha \in \actions^T} \left[                    V(\alpha, \st{1}, \xi_{1:T})- V(\mathbf{w}_{t}^*, \st{1}, \xi_{1:T}) \right]
                    \end{aligned}    
                \end{equation*}                
                \textbf{Step 3:} Check convergence:
                \IF{$V(\mathbf{w}_{t}^*, \st{1}^*, \xi_{1:T}^*) \geq V(\alpha^*, \st{1}^*, \xi_{1:T}^*)$ (or $\|\mathbf{w}_t^* - \mathbf{w}_{t-1}^*\| < \delta$)}
                    \STATE Terminate with policy $\pi_{\mathbf{w}_{t}^*}$ and error $\varepsilon_t^*$ 
                \ELSE
                    \STATE Set $t = t + 1$, $\mathcal{C}_{t+1} = \mathcal{C}_{t} \cup \lbrace (\st{1}^*, \xi_{1:T}^*, \alpha^*) \rbrace$ and \textbf{go to} \textbf{Step 1}
                \ENDIF
    \end{algorithmic}
\end{algorithm}


\paragraph{Remark} Algorithm \ref{alg:stochastic} may not terminate in general, unless convexity assumptions are placed on $V(\alpha, \st{})$ or $V(\mathbf{w}, \st{})$. Thus, in typical applications, one would terminate when $\|\mathbf{w}_t^* - \mathbf{w}_{t-1}^*\| < \delta$ for chosen hyper-parameter $\delta$. However, our experiments have shown empirically that Algorithm \ref{alg:stochastic} terminates with an exact optimal solution for most policy classes considered, at which point both the return and error curves ``plateau'' (cf. Fig. \ref{fig:simulation}).
