\subsection{Convergence}

% Scott Note: we've already said this isn't guaranteed to terminate... once is enough, let's not remind the reader. ;)
%Finite-time termination of Algorithm \ref{alg:stochastic} is impossible to show without strong assumptions (i.e. convexity). However, we can still 
Under mild conditions, if CGPO terminates at some iteration $t$, then $\mathbf{w}_t^*$ is optimal in $\mathcal{W}$ (with probability at least $p^T$ in the stochastic case).

\begin{theorem}
\label{thm:main}
    If $\mathcal{S}_1$, $\mathcal{A}$, $\Xi_p$ and $\mathcal{W}$ are non-empty compact subsets of Euclidean space, $V(\alpha, \st{}, \xi_{1:T})$ and $V(\mathbf{w}, \st{}, \xi_{1:T})$ are continuous, and CGPO terminates at iteration $t$, then $\mathbf{w}_t^*$ is optimal for problem (\ref{eqn:bilevel2-cc}).
\end{theorem}

\begin{proof}
    In the notation of \citep{blankenship1976infinitely}, we define $X^0 = [0, 2 B T]$, $X = \mathcal{W}$, $Y = \mathcal{A}^T \times \mathcal{S}_1 \times \Xi_p^T$. Making the change of variable $\varepsilon = x_0 \in X^0$, $x = \mathbf{w}$, and $y = (\alpha, \st{1}, \xi_{1:T}) \in Y$, and defining the continuous function $f(x, y) = \varepsilon(\alpha, \st{1}, \xi_{1:T}) = V(\alpha, \st{1}, \xi_{1:T}) - V(\mathbf{w}, \st{1}, \xi_{1:T})$, the problem (\ref{eqn:bilevel2-cc}) is equivalent to the problem:
\begin{equation*}
\begin{aligned}
    \min_{(x_0, x) \in X^0 \times X} \, x_0 \qquad
    \mathrm{s.t.} \quad f(x, y) - x_0 \leq 0, \quad \forall y \in Y
\end{aligned}
\end{equation*}
as discussed on p. 262 of \citep{blankenship1976infinitely}. Similarly, Algorithm \ref{alg:stochastic} can be reparameterized as Algorithm 2.1 in the aforementioned paper, with $x_t = \mathbf{w}_t^*$. Thus, the assumption of Theorem 2.1 in \citep{blankenship1976infinitely} holds and $\mathbf{w}_t^*$ is a solution of (\ref{eqn:bilevel2-cc}) as claimed. 
\end{proof}

\paragraph{Remark} Termination of CGPO guarantees that $\mathbf{w}_t^*$ is optimal in $\tilde{\Pi}_\mathcal{W}$, and $\varepsilon_t^*$ is the corresponding optimality gap. Moreover, if $\varepsilon_t^* = 0$ and the MDP is deterministic, then $\pi_{\mathbf{w}_t^*}$ is the {optimal} policy in $\Pi$. This suggests the gap estimate can be used as a principled way to assess the suitability of different policy classes. 

