        $O\left(\frac{\delta n^2d^{\frac{3}{\log{\delta}}}\log{d}}{\log{\delta}}\binom{n^2+\delta}{\delta}\right)$ basic instructions,
        \item 
        $O(\frac{n^2 \log{d}}{\log{\delta}})$ registers over $\mathbb{F}_p$.
    \end{itemize}
    Replacing by $\epsilon=\frac{3}{\log{\delta}} $, yields a program with
    \begin{itemize}
        \item 
         $O(\epsilon d^{\epsilon}\log{d})$ recursive calls to $M$,
         \item 
        $O\left(\epsilon \frac{n^{2^{\frac{3}{\epsilon}+1}}}{2^{\frac{3}{\epsilon}-1}}d^{\epsilon}\log{d}\right)$ basic instructions,
        \item
          $O\left(\epsilon \frac{n^{2^{\frac{3}{\epsilon}+1}}}{2^{\frac{3}{\epsilon}-1}}\log{d}\right)$ registers over  $\mathbb{F}_q$ for $q = O\left(\left(np\right)^{2^{\frac{3}{\epsilon}}} \right)$, and
        \item 
        $O(\epsilon n^2\log{d})$ registers over $\mathbb{F}_p$.
    \end{itemize}
    which completes the proof.
\end{proof}
