\title{Diffusion of Responsibility in Collective Decision Making}

\author {
    % Authors
    Pavel Naumov,\textsuperscript{\rm 1}
    Jia Tao\textsuperscript{\rm 2}
}
\affiliations {
    % Affiliations
    \textsuperscript{\rm 1} University of Southampton, United Kingdom\\
