\subsection{Properties of a Bisimulation}

In this subsection, we assume a fixed pair of mechanisms $(Ag,Alt,T,act,\ell)$ and $(Ag,Alt,T',act',\ell')$ and a bisimulation $R$ of these mechanisms. The next key lemma establishes that bisimulation preserves the {\em strategic power} of each agent. Its proof is in the appendix. 

\begin{lemma}\label{win-win lemma}
$n\in win_a(S)$ iff $n'\in win_a(S)$ for 
any subset $S\subseteq Alt$ of alternatives and
any two nodes $n$ and $n'$ of trees $T$ and $T'$, respectively, such that $nRn'$. 
\end{lemma}


\begin{lemma}\label{dict iff dict}
If $nRn'$ and an agent $a$ is a dictator at node $n$, then  $a$ is a dictator at node $n'$.
\end{lemma}
\begin{proof}
Consider any alternative $Y\in Alt$. By Definition~\ref{dict at node}, it suffices to show that $n'\in win_a(\{Y\})$.

% Note that $\ell'(m')\in Alt$ and, by item~5 of Definition~\ref{game}, function $\ell$ is a surjection. Thus, there must exist a  leaf node $m$ of tree $T$ such that
% \begin{equation}\label{31-jul-b}
% \ell(m)=\ell'(m').    
% \end{equation}
Note that $n\in win_a(\{Y\})$ by Definition~\ref{dict at node} and the assumption of the lemma that agent $a$ is a dictator at node~$n$. 
Therefore,
$n'\in win_a(\{Y\})$
by the assumption $nRn'$ of the lemma and Lemma~\ref{win-win lemma}. 
\end{proof}



\begin{lemma}\label{31-jul-d}
If bisimulation $R$ is total and every node $n$ of tree $T$ has a dictator at an ancestor of $n$, then every node $n'$ of tree $T'$ has a dictator at an ancestor of $n'$.
\end{lemma}
\begin{proof}
Consider any node $n'$ of tree $T'$. By Definition~\ref{total}, there is a node $n$ of tree $T$ such that
\begin{equation}\label{31-jul-c}
nRn'.    
\end{equation}
By the assumption of the lemma, there is a dictator agent $a$ at an ancestor $m$ of node $n$. By item~4 of Definition~\ref{def:bisimulation} and statement~\eqref{31-jul-c}, there is an ancestor $m'$ of node $n'$ such that $mRm'$. Then, $a$ is a dictator at node $m'$ by Lemma~\ref{dict iff dict}.   
\end{proof}


\begin{lemma}\label{resp iff resp}
For any two leaf nodes $n$ and $n'$, if $nRn'$ and an agent $a$ is responsible at $n$, then  $a$ is responsible at $n'$.
\end{lemma}
\begin{proof}
By Definition~\ref{responsible}, the assumption that $a$ is responsible at node $n$ implies that $n$ has an ancestor $m$ such that 
\begin{equation}\label{31-jul-a}
m\in win_a(Alt\setminus \{\ell(n)\}).    
\end{equation}
Thus, by item~4 of Definition~\ref{def:bisimulation} and the assumption $nRn'$ of the lemma, there is an ancestor $m'$ of node $n'$ such that $mRm'$. Hence, 
$
m'\in win_a(Alt\setminus \{\ell(n)\})
$
by Lemma~\ref{win-win lemma} and statement~\eqref{31-jul-a}.
Note that $\ell(n)=\ell'(n')$ by item~1 of Definition~\ref{def:bisimulation}. Then, 
$
m'\in win_a(Alt\setminus \{\ell'(n')\})
$.
Therefore, agent $a$ is responsible at leaf $n'$ by Definition~\ref{responsible}.
\end{proof}


We conclude this section with two important observations about arbitrary totally bisimular mechanisms.


\begin{lemma}\label{diffusion bisimilar}
If one of two totally bisimular mechanisms allows diffusion of responsibility, then so does the other.
\end{lemma}
\begin{proof}
The statement of the lemma follows from Lemma~\ref{resp iff resp} and Definition~\ref{total}.    
\end{proof}




