Hence, nodes $n_1$ 
and $n_2$ have exactly the same number of children labeled with the same set of alternatives (one child per alternative).

Consider a new mechanism that ``combines'' nodes $n_1$ and $n_2$ as well as their identically labeled children.  Let $R$ be the total bisimulation of the original and the new mechanism as shown by the dashed line on the diagram below:
\begin{center}
\scalebox{0.5}{\includegraphics{Images/canonical-seven.pdf}}
\vspace{-2mm}
\end{center}
We assume that all nodes not shown in the original mechanism are connected by the dashed lines to their clones in the new mechanism. Note that the new mechanism has fewer nodes than the original mechanism. Thus, by Definition~\ref{canonical}, the original mechanism is not in canonical form.
\end{proof}

% \begin{lemma}\label{super lemma}
% If a diffusion-free mechanism is in the canonical form, $n_1$ and $n_2$ are children of a node, and at least one of $n_1$ and $n_2$ is not a leaf, then $TreeAlt(n_1)=TreeAlt(n_2)$.
% \end{lemma}


\begin{lemma}\label{Jia's lemma}
In a diffusion-free mechanism  in canonical
form,
if $n$ is a parent of a non-leaf node $n_1$, then the tree rooted at node $n_1$ contains a node $m$ such that $height(m)=1$ and $act(m)\neq act(n)$.
\end{lemma}
\begin{proof}
If $height(n_1)=1$, then let $m$ be the node $n_1$. Note that $act(m)=act(n_1)\neq act(n)$ by Lemma~\ref{parent-child lemma} and the assumption that the mechanism is in canonical form. In what follows, we assume that 
\begin{equation}\label{7-aug-e}
height(n_1)\ge 2.   
\end{equation}
Let $n_2$ be the deepest leaf node in the subtree rooted at node $n_1$ as shown below: 


\begin{center}
\vspace{-2mm}
\scalebox{0.5}{\includegraphics{Images/canonical-eight.pdf}}
\vspace{-2mm}
\end{center}
Let $n_3$ be the parent of leaf $n_2$ and $n_4$ be the parent of node $n_3$. Note that $height(n_4)=2$ because $n_2$ is the deepest leaf node. Also, observe that node $n_4$ belongs to the subtree of node $n_1$ by the inequality~\eqref{7-aug-e}. By Lemma~\ref{two non-leaf children lemma}, node $n_4$ must have a child node $m$ such that $act(m)\neq act(n)$.
\end{proof}

\begin{lemma}\label{leaf's parent height 1}
If a diffusion-free mechanism is in canonical form, then the parent of each leaf node has height 1.    
\end{lemma}
\begin{proof}
Consider parent $n$ of a leaf node $n_1$. Towards the contradiction, suppose that $height(n)>1$. Then, node $n$ must have a child non-leaf node $n_2$. By Lemma~\ref{Jia's lemma}, the tree rooted at node $n_2$ contains a node $n_3$ such that $height(n_3)=1$ and \begin{equation}\label{2-aug-a}
act(n_3)\neq act(n).    
\end{equation}
By Lemma~\ref{two children lemma}, node $n_3$ has two leaf children labeled with different alternatives. Let $n_4$ be one of these leaf children such that $\ell(n_1)\neq \ell(n_4)$ and let $n_5$ be the other leaf child such that $\ell(n_4)\neq \ell(n_5)$, as shown:

\begin{center}
\vspace{0mm}
\scalebox{0.5}{\includegraphics{Images/canonical-nine.pdf}}
\vspace{-2mm}
\end{center}

First, note that agent $act(n)$ is responsible at node $n_4$. Indeed, because $\ell(n_1)\neq \ell(n_4)$, the agent had a strategy to prevent alternative $\ell(n_4)$ by transitioning the decision-making process from node $n$ to $n_1$.

Second, agent $act(n_3)$ is also responsible at node $n_4$. Indeed, because $\ell(n_4)\neq \ell(n_5)$, the agent had a strategy to prevent alternative $\ell(n_4)$ by transitioning the decision-making process from node $n_3$ to $n_5$.

Thus, agents $act(n)$ and $act(n_3)$ are both responsible at node $n_4$. Hence, $act(n)=act(n_3)$ by the assumption of the lemma that the mechanism is diffusion-free and Definition~\ref{diffusion}, which contradicts inequality~\eqref{2-aug-a}.
\end{proof}

By $TreeAlt(n)$ we refer to the set of all alternatives used to label the leaf nodes in the subtree of the mechanism rooted at node $n$. For the mechanism depicted in Figure~\ref{constitution figure}, we have
$TreeAlt(n_2)=\{\text{Yes},\text{No}\}$ and
$ChildAlt(n_2)=\{\text{Yes}\}$.


\begin{lemma}\label{child=tree lemma}
$ChildAlt(m)=TreeAlt(n)$, for any node $n$ of a diffusion-free mechanism in canonical form and any node $m$ of height~1 in the subtree rooted at $n$.
\end{lemma}
\begin{proof}
We prove the lemma by induction on $height(n)$. 

In the base case, $height(n)=1$.  Hence, $ChildAlt(n)=TreeAlt(n)$. Also, $n=m$ by the assumption $height(m)=1$ of the lemma. Therefore, $ChildAlt(m)=TreeAlt(n)$.

For the induction step, suppose that $height(n)>1$. Let $n_1$ be the child of node $n$ such that the subtree rooted at node $n_1$ contains node $m$. 
Note that 
$height(n_1)<height(n)$ because $n_1$ is a child of node $n$. 
Then, $ChildAlt(m)=TreeAlt(n_1)$ by the induction hypothesis. Thus, it suffices to show that $TreeAlt(n_1) =TreeAlt(n)$.

Suppose the opposite. Consider any alternative
\begin{equation}\label{7-aug-b}
Y\in TreeAlt(n)\setminus TreeAlt(n_1).    
\end{equation}
Then, there must exist a child $n_2$ of node $n$ such that 
\begin{equation}\label{7-aug-a}
   Y\in TreeAlt(n_2). 
\end{equation}
Observe that node $n_2$ cannot be a leaf node by the assumption $height(n)>1$ of the induction case and Lemma~\ref{leaf's parent height 1}. Hence, by Lemma~\ref{Jia's lemma}, the subtree rooted at $n_2$ contains a node $n_3$ such that $height(n_3)=1$ and 
\begin{equation}\label{7-aug-c}
act(n_3)\neq act(n),    
\end{equation}
as shown below:

\begin{center}
%\vspace{-1mm}
\scalebox{0.5}{\includegraphics{Images/canonical-ten.pdf}}
\vspace{-1mm}
\end{center}

Note $height(n_2)<height(n)$ because node $n_2$ is a child of node $n$. Thus, $ChildAlt(n_3)=TreeAlt(n_2)$
by the induction hypothesis. Hence, $Y\in ChildAlt(n_3)$ by statement~\eqref{7-aug-a}. Thus, 
node $n_3$ must have a child leaf node $n_4$ such that $\ell(n_4)=Y$. By Lemma~\ref{two children lemma}, node $n_3$ must also have another child leaf $n_5$ such that $\ell(n_5)\neq Y$.

First, note that agent $act(n)$ is responsible at node $n_4$. Indeed, because $Y\notin TreeAlt(n_1)$ by statement~\eqref{7-aug-b}, the agent had a strategy to prevent alternative $Y$ by transitioning the decision-making process from node $n$ to $n_1$.

Second, agent $act(n_3)$ is also responsible at node $n_4$. Indeed, because $\ell(n_5)\neq Y$, the agent had a strategy to prevent alternative $Y$ by transitioning the decision-making process from node $n_3$ to $n_5$.

Thus, agents $act(n)$ and $act(n_3)$ are both responsible at node $n_4$. Thus, $act(n)=act(n_3)$ by the assumption of the lemma that the mechanism is diffusion-free and Definition~\ref{diffusion}, which contradicts inequality~\eqref{7-aug-c}.
\end{proof}

\begin{lemma}\label{child= all alt}
If a diffusion-free mechanism is in canonical form, then $ChildAlt(n)=Alt$ for each node $n$ of height~1.    
\end{lemma}
\begin{proof}
Let $r$ be the root node of the mechanism. Then,  $ChildAlt(n)=AltTree(r)$ by Lemma~\ref{child=tree lemma}. At the same time, $AltTree(r)=Alt$ because labeling function $\ell$ is a surjection by item~5 of Definition~\ref{game}.     
\end{proof}

\subsection{Technical results}

We are now ready to prove the main result of this work.
\begin{theorem}\label{first main result}
Any diffusion-free mechanism is an elected dictatorship.    
\end{theorem}
\begin{proof}
Consider any diffusion-free mechanism $M$. Let $M'$ be any smallest (in terms of the number of nodes) mechanism totally bisimular to mechanism $M$. By Lemma~\ref{diffusion bisimilar} and Lemma~\ref{elected bisimilar}, it suffices to prove the statement of the theorem for mechanism $M'$. 

Note that mechanism $M'$ is in canonical form by Definition~\ref{canonical}. Consider any leaf node $m$. Node $m$ is not a root node by Lemma~\ref{no singleton mechanisms}.
Let $n$ be the parent of node $m$. Note that $height(n)=1$ by Lemma~\ref{leaf's parent height 1}. Thus, $Child(n)=Alt$ by Lemma~\ref{child= all alt}. Thus, $win_{act(n)}(Y)$ for each $Y\in Alt$ by Definition~\ref{df:winning set}.
Therefore, $act(n)$ is a dictator at node $n$ by Definition~\ref{dict at node}. Therefore, mechanism $m'$ 
is an elected dictatorship by Definition~\ref{elected dictatorship}.  
\end{proof}

The next observation about the special case of two-agent mechanisms can be proven directly or, as we do, derived from Theorem~\ref{first main result}. 
\begin{theorem}\label{two players main theorem}
Any diffusion-free two-agent mechanism is a dictatorship.   
\end{theorem}
\begin{proof}
Consider any two-agent diffusion-free mechanism. By Theorem~\ref{first main result}, this mechanism is an elected dictatorship. Thus, by Definition~\ref{elected dictatorship}, along any decision path, there is a node at which one of the agents is a dictator. 
Then, the mechanism can be viewed as a win-lose extensive form game, where the objective is to be the {\em first} to become the dictator at a node. 
It is a well-known fact in game theory~\cite[Theorem 3.5.1, p.91]{b18} that one of the players in a two-player win-lose extensive form game has a winning strategy. In our case, this means that one of the two agents has a strategy, at the root node, to reach a node at which the agent is a dictator. Recall that at such a node, the agent has a strategy to guarantee any alternative. Hence, the agent has a strategy at a root node to guarantee any alternative. Therefore, this agent is a dictator by Definition~\ref{dictator}.    
\end{proof}

\section{Conclusion}

In this paper, we have shown that in a consecutive collective decision-making mechanism under which each party meaningfully contributes to the decision process, it is unavoidable that in some cases the responsibility will be diffused between more than one agent. The precise statement of this result, given in Theorem~\ref{first main result} and Theorem~\ref{two players main theorem}, depends on the number of agents involved in the decision-making process.

