%\begin{lemma}\label{win-win lemma}
\noindent{\bf Lemma~\ref{win-win lemma}.} {\em 
$n\in win_a(S)$ iff $n'\in win_a(S)$ for 
any subset $S\subseteq Alt$ of alternatives and
any two nodes $n$ and $n'$ of trees $T$ and $T'$, respectively, such that $nRn'$. 
}
%\end{lemma}
\begin{proof}
We prove the lemma by induction on $height(n)+height(n')$. In the base case, $height(n)=height(n')=0$. Thus, $n$ and $n'$ are the leaf nodes. Hence, $\ell(n)=\ell(n')$ by item~1 of Definition~\ref{def:bisimulation}. Then, $\ell(n)\in S$ iff $\ell'(n')\in S$. Therefore, $n\in win_a(S)$ iff $n'\in win_a(S)$ by Definition~\ref{df:winning set}.

Suppose that $height(n)+height(n')>0$. Without loss of generality, we can assume that 
\begin{equation}\label{26-jul-height>0}
height(n)>0.    
\end{equation}


\noindent
$(\Rightarrow):$ Assume that
\begin{equation}\label{26-jul-n-win}
n\in win_a(S)    
\end{equation}
and consider the following three cases separately:

\vspace{1mm}
\noindent{\em Case 1}: $act(n)=a$.
By Definition~\ref{df:winning set}, the assumptions
\eqref{26-jul-height>0} and \eqref{26-jul-n-win} imply that node $n$ has child $m$ such that 
\begin{equation}\label{26-jul-a}
m\in win_a(S).    
\end{equation}
Then, $n\stackrel{a}{\to}m$ by Definition~\ref{df:to} and the assumption $act(n)=a$ of the case.
Hence, by item~2 of Definition~\ref{def:bisimulation} and the assumption $nRn'$ of the lemma, there is a node $m'$ such that 
\begin{align}
&n'\stackrel{a}{\to}m',\label{26-jul-b}\\
&mRm'.\label{26-jul-c}
\end{align}
Note that $height(m)<height(n)$ because node $m$ is a child of node $n$. Also, $height(m')\le height(n')$ by Definition~\ref{df:to} and statement~\eqref{26-jul-b}.
Thus, $height(m)+height(m')<height(n)+height(n')$.
Hence, $m\in win_a(S)$ iff $m'\in win_a(S)$ by the induction hypothesis and statement~\eqref{26-jul-c}. Thus, $m'\in win_a(S)$ by statement~\eqref{26-jul-a}.
Therefore, $n'\in win_a(S)$ by item~\ref{up lemma} of Lemma~\ref{up down lemma}.

\vspace{1mm}
\noindent{\em Case 2}:
$act(n)=act(n')\neq a$. The assumption~\eqref{26-jul-height>0} implies that node $n$ is not a leaf. Thus, node $n'$ is also not a leaf by the assumption $act(n)=act(n')$ of the case and item~4 of Definition~\ref{game}. 

Then, to show that $n'\in win_a(S)$, consider any child $m'$ of node $n'$. By item~3 of Definition~\ref{df:winning set} and the assumption $act(n')\neq a$ of the case, it suffices to show that 
\begin{equation}
m'\in win_a(S).\label{26-jul-d}
\end{equation}
Note that, 
$n'\stackrel{act(n)}{\to} m'$
by the assumption $act(n)=act(n')$ of the case and Definition~\ref{df:to}. 
Hence, by item~3 of Definition~\ref{def:bisimulation} and the assumption $nRn'$ of the lemma, there is node $m$ such that 
\begin{align}
&n\stackrel{act(n)}{\to} m,\label{26-jul-e}\\
&mRm'.\label{26-jul-f}
\end{align}
Then, by item~\ref{down lemma} of Lemma~\ref{up down lemma},
\begin{equation}
m\in win_a(S).\label{26-jul-g}    
\end{equation}

Note that $height(m')<height(n')$ because node $m'$ is a child of node $n'$. Also, $height(m)\le height(n)$ by Definition~\ref{df:to} and statement~\eqref{26-jul-e}.
Thus, $height(m)+height(m')<height(n)+height(n')$.
Hence, by statement~\eqref{26-jul-f} and the induction hypothesis,
$m\in win_a(S)$ iff $m'\in win_a(S)$. Therefore, statement~\eqref{26-jul-g} implies statement~\eqref{26-jul-d}.

\vspace{1mm}
\noindent{\em Case 3}: $act(n)\neq a$ and $act(n)\neq act'(n')$. The last inequality includes the situation when $act'(n')$ is not defined because $n'$ is a leaf node.

The assumption~\eqref{26-jul-height>0} implies that node $n$ is not a leaf node. Consider any child $m$ of this node. Then, by Definition~\ref{df:to},
\begin{equation}\label{26-jul-k}
n\stackrel{act(n)}{\to} m    
\end{equation}
and, by item~3 of Definition~\ref{df:winning set}, the assumption~$act(n)\neq a$ of the case and statement~\eqref{26-jul-n-win},
\begin{equation}
m\in win_a(S).  \label{26-jul-l}  
\end{equation}

By item~2 of Definition~\ref{def:bisimulation}, statement~\eqref{26-jul-k} and the assumption $nRn'$ of the lemma, there is a node $m'$ such 
that 
\begin{align}
&n'\stackrel{act(n)}{\to} m',\label{26-jul-m}\\
&mRm'.\label{26-jul-n}
\end{align}
By Lemma~\ref{no go lemma} and the assumption $act(n)\neq act'(n')$ of the case, statement~\eqref{26-jul-m} implies $n'=m'$. Hence, by statement~\eqref{26-jul-n},
\begin{equation}\label{26-jul-o}
mRn'.    
\end{equation}
Note that $height(m)+height(m')<height(n)+height(n')$ because $m$ is a child of node $n$ and $m'=n'$.
Hence, 
$m\in win_a(S)$ iff $n'\in win_a(S)$,
by statement~\eqref{26-jul-o} and the induction hypothesis.
Therefore, $n'\in win_a(S)$ by statement~\eqref{26-jul-l}. 


\noindent
$(\Leftarrow)$ Assume that
\begin{equation}\label{29-jul-a-win}
n'\in win_a(S)    
\end{equation}
and consider the following three cases separately:

\vspace{1mm}
\noindent{\em Case 1:} $act(n)=a\neq act'(n')$. This case includes the situation when $n'$ is a leaf node and $act'(n')$ is not defined. Inequality~\eqref{26-jul-height>0} implies that node $n$ has at least one child $m$. Then, by the assumption $act(n)=a$ of the case,
\begin{equation}\label{29-jul-c}
  n\stackrel{a}{\to} m.  
\end{equation}
Hence, by the assumption $nRn'$ of the lemma and item~2 of Definition~\ref{def:bisimulation}, there is a node $m'$ such that $n'\stackrel{a}{\to} m'$ and $mRm'$. Then, $n'=m'$ by Lemma~\ref{no go lemma} and the assumption $a\neq act'(n')$ of the case. Thus, 
\begin{equation}\label{29-jul-b}
    mRn'.
\end{equation}
Note $height(m)+height(n')<height(n)+height(n')$ because $m$ is a child of node $n$.
Hence, 
$m\in win_a(S)$ iff $n'\in win_a(S)$,
by statement~\eqref{29-jul-b} and the induction hypothesis. Thus, $m\in win_a(S)$ by statement~\eqref{29-jul-a-win}. Therefore, $n\in win_a(S)$ by item~\ref{up lemma} of Lemma~\ref{up down lemma} and statement~\eqref{29-jul-c}.

\vspace{1mm}
\noindent{\em Case 2:} $act(n)=a= act'(n')$. Assumption $act'(n')=a$ implies that node $n'$ is not a leaf. Thus, by Definition~\ref{df:winning set} and the assumption $act'(n')=a$, node $n'$ must have at least one child $m'$ such that
\begin{equation}\label{29-jul-d}
   m'\in win_a(S). 
\end{equation}
Note that 
$n'\stackrel{a}{\to}m'$ by the assumption $act'(n')=a$. Hence, by the assumption $nRn'$ of the lemma and item~3 of Definition~\ref{def:bisimulation}, there must exist a node $m$ such that 
\begin{align}
&n\stackrel{a}{\to}m,\label{29-jul-e}\\
&mRm'.\label{29-jul-f}
\end{align}
Note that $height(m')<height(n')$ because node $m'$ is a child of node $n'$. Also, $height(m)\le height(n)$ by Definition~\ref{df:to} and statement~\eqref{29-jul-e}.
Thus, $height(m)+height(m')<height(n)+height(n')$.
Hence, by statement~\eqref{29-jul-f} and the induction hypothesis,
$m\in win_a(S)$ iff $m'\in win_a(S)$.
Then, $m\in win_a(S)$ by statement~\eqref{29-jul-d}.
Therefore,  item~\ref{up lemma} of Lemma~\ref{up down lemma} and statement~\eqref{29-jul-e} imply that $n\in win_a(S)$.


\vspace{1mm}
\noindent{\em Case 3:} $act(n)\neq a$. Note that $act(n)$ is defined because, by assumption~\eqref{26-jul-height>0}, node $n$ is not a leaf. 

Consider any child $m$ of node $n$ by Definition~\ref{df:winning set}, it suffices to show that $m\in win_a(S)$. Indeed, note that $n\stackrel{act(n)}{\to}m$ by Definition~\ref{df:to}. Hence, by item~2 of Definition~\ref{def:bisimulation} and assumption $nRn'$ of the lemma, there exists a node $m'$ such that 
\begin{align}
&n'\stackrel{act(n)}{\to}m',\label{29-jul-g}\\
&mRm'.\label{29-jul-h}    
\end{align}
Thus, statement~\eqref{29-jul-a-win} and the assumption $act(n)\neq a$ of the case, by item~\ref{down lemma} of Lemma~\ref{up down lemma}, imply
\begin{equation}\label{29-jul-i} 
m'\in win_a(S).    
\end{equation}

Note that $height(m)<height(n)$ because node $m$ is a child of node $n$. Also, $height(m')\le height(n')$ by Definition~\ref{df:to} and statement~\eqref{29-jul-g}.
Thus, $height(m)+height(m')<height(n)+height(n')$.
Hence, by statement~\eqref{29-jul-h} and the induction hypothesis,
$m\in win_a(S)$ iff $m'\in win_a(S)$.
Then, $m\in win_a(S)$ by statement~\eqref{29-jul-i}.
\end{proof}

