%\begin{lemma}\label{no leaf-uncles lemma}
\noindent{\bf Lemma~\ref{no leaf-uncles lemma}.} {\em 
If a diffusion-free mechanism is in canonical form, then any child of a node of height 2 must have height~1.  
}
%\end{lemma}

\begin{proof}
Consider any node $n$ of height 2 and any child $m$ of this node. Note that $height(m)\le height(n)-1=1$. Thus, it suffices to show that $m$ is not a leaf node. Suppose the opposite. 

Since $height(n)=2$, node $n$ must have at least one child $m_1$ of height 1. By Lemma~\ref{two children lemma}, node $m_1$ has at least two children labeled with different alternatives. Let $m_2$ be child of node $m_1$ such that $\ell(m)\neq \ell(m_2)$ and $m_3$ be another child of $m_1$ such $\ell(m_3)\neq \ell(m_2)$, as shown in the diagram below:
\begin{center}
\scalebox{0.5}{\includegraphics{Images/canonical-three.pdf}}
\vspace{-2mm}
\end{center} 

First, note that agent $act(n)$ is responsible at node $m_2$. Indeed, because $\ell(m)\neq \ell(m_2)$, the agent had a strategy to prevent alternative $\ell(m_2)$ by transitioning the decision-making process from node $n$ to $m$.

Second, agent $act(m_1)$ is also responsible at node $m_2$. Indeed, because $\ell(m_3)\neq \ell(m_2)$, the agent had a strategy to prevent alternative $\ell(m_2)$ by transitioning the decision-making process from node $m_1$ to $m_3$.

Thus, agents $act(n)$ and $act(m_1)$ are both responsible at node $m_2$. Thus, $act(n)=act(m_1)$ by the assumption of the lemma that the mechanism is diffusion-free and Definition~\ref{diffusion}. The last statement contradicts Lemma~\ref{parent-child lemma}.
\end{proof}

%\begin{lemma}\label{childAlt lemma}
\noindent{\bf Lemma~\ref{childAlt lemma}.} {\em
If a diffusion-free mechanism is in canonical form, and $n_1$ and $n_2$ are children of a node of height 2, then $ChildAlt(n_1)=ChildAlt(n_2)$.
}
%\end{lemma}
\begin{proof}
By Lemma~\ref{no leaf-uncles lemma}, the assumptions of the lemma imply $height(n_1)=height(n_2)=1$, see the diagram below.
\begin{center}
\scalebox{0.5}{\includegraphics{Images/canonical-four.pdf}}
\vspace{-1mm}
\end{center}

Suppose $ChildAlt(n_1)\neq ChildAlt(n_2)$. Without loss of generality, let $Y\in ChildAlt(n_1)\setminus ChildAlt(n_2)$ for some $Y\in Alt$. Thus, node $n_1$ has a leaf child $m_1$ labeled with the alternative $Y\notin ChildAlt(n_2)$. Then, agent $act(n)$ is responsible at leaf node $m_1$ because the agent had a strategy to prevent alternative $Y$ by transitioning the decision-making process from node $n$ to node $n_2$.


At the same time, the assumption of the lemma that the mechanism is in canonical form, by Lemma~\ref{two children lemma}, implies that node $n_1$ has another leaf child, $m_2$, such that $\ell(m_1)\neq \ell(m_2)$. Then, agent $act(n_1)$ is responsible at leaf node $m_1$ because the agent had a strategy to prevent alternative $Y$ by transitioning the decision-making process from node $n_1$ to leaf node $m_2$.

Hence, agents $act(n)$ and $act(n_1)$ are both responsible at leaf node $m_1$. Then, $act(n)=act(n_1)$ by the assumption of the lemma that the mechanism is diffusion-free and Definition~\ref{diffusion}. The last statement contracts Lemma~\ref{parent-child lemma} because the mechanism is in canonical form.
\end{proof}




