\title{Airspeed estimation for UAVs using only propeller feedback}
\author{Evangelos Ntouros\thanks{Correspondence: e.ntouros@tudelft.nl}\and
        Pavel Kelley\and
        Ewoud J. J. Smeur}

\addbibresource{references.bib}

