\title{Navigating the Rabbit Hole: Emergent Biases in LLM-Generated Attack Narratives Targeting Mental Health Groups}


\author{Rijul Magu$^{1}$, Arka Dutta$^{2}$, Sean Kim$^{1}$, 
Ashiqur R. KhudaBukhsh$^{2}$, \\
\textbf{Munmun De Choudhury}$^{1}$ \\
\textsuperscript{1}College of Computing, Georgia Institute of Technology, Georgia, USA; \\
\textsuperscript{2}Rochester Institute of Technology, Rochester, New York, USA. \\
  \texttt{\{rijul.magu, sean.kim ,munmund\}@gatech.edu},\\\,\texttt{\{ad2688, axkvse\}@rit.edu}}






