\begin{claim}\label{claim:I-nbor-McMu}
Every vertex of $I$ has a neighbour in $M_c \cup M_u$.
\end{claim}
\begin{proof}
Assume, for a contradiction, that the vertex $u \in I$ only has neighbours in $M_r$.
Since every vertex of $M_r$ has no neighbours in $K$ by Claim~\ref{claim:M-complete-Kci}~(i), a shortest $u$-$C$-path $Q$ in $G+F$ has length at least 3.
This implies that there is an induced $P_5$ in $G+F$ with vertices in $V(Q) \cup V(C)$, a contradiction; see Figure~\ref{fig:claims-M} left.
The claim follows.
\end{proof}

\begin{claim}\label{claim:same-nbors}
If $u \in M_r$, then every vertex of $N_G(u)$ has the same neighbours in $M_c \cup M_u$.
\end{claim}
\begin{proof}
Note that $N_G(u) \subseteq I$ by Claim~\ref{claim:M-complete-Kci}~(i) and since $M_r \subseteq N$ is independent.
Let $v, w \in N_G(u)$.
Assume, for a contradiction, that the vertex $x \in M_c \cup M_u$ is a neighbour of $v$, but not a neighbour of $w$.
The vertex $w$ has a neighbour $y \in M_c \cup M_u$ in $G$ by Claim~\ref{claim:I-nbor-McMu}.
By considering shortest $u$-$C$-paths in $G+F$ containing the vertices $v$ and $x$, and $w$ and $y$, respectively, we see that $ux, uy \in F$.
Let $z \in K_c$ be a vertex that is not adjacent to $x$ in $G$, which exists, 
or $G$ would not be $3$-colourable.
Therefore, $wux$ together with a shortest $x$-$z$-path with internal vertices in $K_c$ contains an induced $P_5$ in $G+F$, a contradiction; see Figure~\ref{fig:claims-M} right.
As $v,w \in N_G(u)$ were arbitrary, the proof is complete.
\end{proof}

Claim~\ref{claim:G-Mr} is an important consequence of Claims~\ref{claim:I-nbor-McMu} and~\ref{claim:same-nbors}.

\begin{claim}\label{claim:G-Mr}
If there is 3-colouring $\psi'$ of $G - M_r$ that is an extension of $\psi$, then there is a 3-colouring of $G$ that is an extension of $\psi'$.
\end{claim}
\begin{proof}
Assume, for a contradiction, that for a vertex $u \in M_r$, there exist vertices $v_i \in N_G(u)$ with $\psi'(v_i) = i$ for every $i \in [3]$.
Note that $v_1,v_2,v_3 \in I$ by Claim~\ref{claim:M-complete-Kci}~(i).
By Claim~\ref{claim:I-nbor-McMu} and Claim~\ref{claim:same-nbors}, there exists a vertex $w \in M_c \cup M_u$ that is adjacent to $v_1$, $v_2$, and $v_3$, a contradiction to the fact that $\psi'$ is a $3$-colouring of $G-M_r$.
Therefore, for every vertex $u \in M_r$, there is a colour $i \in [3]$ such that no neighbour of $u$ in $G$ has colour $i$ under $\psi'$.
At this point,  choosing any such colour for every vertex of $M_r$ gives a 3-colouring of $G$ that is an extension of $\psi'$.
\end{proof}
\noindent
Claim~\ref{claim:G-Mr} implies that it suffices to decide if there is a 3-colouring $G-M_r$ that is an extension of $\psi$.
Hence, from now on, assume that $M_r = \emptyset$.
Recall that $J$ is the set of vertices of $I$ with no neighbour in $M_c$.
Consequently, by Claim~\ref{claim:I-nbor-McMu}, every vertex of $J$ has a neighbour in $M_u$.
Claim~\ref{claim:anti-complete} implies that every vertex of $M_c \cup M_u$ is either complete or anticomplete to each component of $G[I]$.
It follows that, if $u \in J$, then $J$ contains all vertices of the component of $u$ in $G[I]$.
We prove one more claim about the structure of the edges between $M_u$ and $J$.

