\section{Preliminaries}
\label{sec:preliminaries}
% We survey relevant notions from first-order logic
% (\Cref{sec:FOL}) 
% and theory combination.
% (\Cref{sec:thcombSMT}).

We use $\mathbb{N}$ to denote the set of naturals including $0$, and $\No$ to denote  $\mathbb{N}\setminus\{0\}$.
If $X$ is a set, $|X|$ is its cardinality, and $|\mathbb{N}|=\aleph_{0}$.

\subsection{First-order logic}
\label{sec:FOL}
A {\em signature} is a pair $\Sigma=(\F_{\Sigma},\P_{\Sigma})$ where:
$\F_{\Sigma}$ is a set of function symbols, each with arity $n\in\mathbb{N}$;
and $\P_{\Sigma}$ is a set of predicate symbols, each with arity $m\in\mathbb{N}$, containing at least the equality $=$, of arity $2$.
$\Sigma$ is said to be {\em empty} if it has no function and predicate symbols other than $=$.
% We may drop the subscripts $\Sigma$ from $\F_{\Sigma}$ and $\P_{\Sigma}$.
Two signatures are said to be {\em disjoint} if the only symbol they share is $=$.
% Taking countably many variables, 
We define {\em terms}, {\em literals}, {\em clauses} (i.e., disjunctions of literals), {\em cubes} (i.e., conjunctions of literals), {\em formulas} and {\em sentences} 
% (formulas without free variables) 
in the usual way.
If $\ns$ is a unary function symbol and $x$ a variable, we define by induction the terms $\ns^{0}(x):=x$ and $\ns^{n+1}(x):=\ns(\ns^{n}(x))$.
The set of variables in a formula $\varphi$ is denoted by $\vars(\varphi)$.

{\em $\Sigma$-interpretations} $\A$ are defined as usual:
$\dom{\A}$ is the {\em domain} of $\A$;
for a function symbol $f$ of arity $n$, $f^{\A}:\dom{\A}^{n}\to\dom{\A}$; 
for a predicate symbol $P$ of arity $m$, $P^{\A}\subseteq\dom{\A}^{m}$;
for a variable $x$, $x^{\A}\in\dom{\A}$.
For a term $\alpha$, $\alpha^{\A}$ is its value in  $\A$, and for a set $\Gamma$  of terms, $\Gamma^{\A}=\{\alpha^{\A} : \alpha\in\Gamma\}$.
If $\A$ satisfies $\varphi$, we write $\A\vDash\varphi$.
%
% I don't think we use this notation anywhere.
%
Formulas from \Cref{card-formulas} are satisfied by $\A$ 
when
$|\dom{\A}|$ is: at least $n$ (for $\neq(x_{1},\ldots,x_{n})$ and $\psi_{\geq n}$);
at most $n$ (for $\psi_{\leq n}$);
exactly $n$ (for $\psi_{=n}$).


