\begin{equation*}
\begin{aligned}
    \neq(x_{1},\ldots,x_{n})=\bigwedge_{i=1}^{n-1}\bigwedge_{j=i+1}^{n}\neg(x_{i}=x_{j})\\
    \\\vspace{-4mm}
    \psi_{\geq n}=\Exists{{x_1\ldots x_n}}\NNEQ{x}
