\section{\tp{Proof of \Cref{lem:SFWandDECimpCMMF}}{Proof of Result \ref{lem:SFWandDECimpCMMF}}}
We actually prove this in the many-sorted setting,\footnote{See \cite{CADE} for the definitions of a many-sorted signature, and what an interpretation is in that case.}
and then \Cref{lem:SFWandDECimpCMMF} follows as a particular instance,
where the number of sorts is 1.
As mentioned, this was already proven in \cite{CasalRasga2} (also for the many-sorted case),
but not explicitly stated.
More precisely, there, they proved shininess from strong politeness, and so relied on smoothness.
However, a careful look at the proof reveals the fact that smoothness was not relied on in the specific part of the proof that showed the computability of the minimal model function.
To be safe, we provide a full proof here.


Let $\Sigma$ be a many-sorted, first-order signature, $S$ a finite set of its sorts, and $\vars_{\s}(\varphi)$ be the set of variables of sort $\s$ in $\varphi$.

\paragraph{Finite witnessability:}
A $\Sigma$-theory $\T$ is finitely witnessable \wrt $S$ if there exists a function $\wit$ (called a witness) from the quantifier-free formulas of $\Sigma$ into themselves such that, for every quantifier-free formula $\varphi$, one has that: 
$(I)$ $\varphi$ and $\Exists{\overarrow{x}}\wit(\varphi)$ are $\T$-equivalent, where $\overarrow{x}=\vars(\wit(\varphi))\setminus\vars(\varphi)$;
$(II)$ if $\wit(\varphi)$ is $\T$-satisfiable there exists a $\T$-interpretation $\A$ that satisfies $\wit(\varphi)$ with $\s^{\A}=\vars_{\s}(\wit(\varphi))^{\A}$.

\paragraph{Strong finite witnessability:}
A $\Sigma$-theory $\T$ is strongly finitely witnessable \wrt $S$ if it is finitely witnessable \wrt $S$, with witness $\wit$, which in addition satisfies:
$(II^{\prime})$ for every quantifier-free formula $\varphi$, finite set of variables $V$, and arrangement $\delta_{V}$ on $V$, if $\wit(\varphi)\wedge\delta_{V}$ is $\T$-satisfiable then there exists a $\T$-interpretation $\A$ that satisfies $\wit(\varphi)\wedge\delta_{V}$ with $\s^{\A}=\vars_{\s}(\wit(\varphi)\wedge\delta_{V})^{\A}$.
In that case $\wit$ is called a strong witness.

\paragraph{Minimal model function}
The minimal model function $\minmod$ \wrt $S$ of a $\Sigma$-theory $\T$ is a function from the quantifier-free formulas of $\Sigma$ to the power set of $\N^{S}$ (that is, the set of functions from $S$ to $\N$) such that:
$(I)$ if $\varphi$ is a quantifier-free $\T$-satisfiable formula and $\textbf{n}\in\minmod(\varphi)$, there exists a $\T$-interpretation $\A$ that satisfies $\varphi$ with $|\s^{\A}|=\textbf{n}(\s)$ for every $\s\in S$;
$(II)$ if $\varphi$ is a quantifier-free $\T$-satisfiable formula, $\textbf{n}\in\minmod(\varphi)$, and $\B$ is a $\T$-interpretation that satisfies $\varphi$ with $|\s^{\B}|\neq \textbf{n}(\s)$ for some $\s\in S$, there exists $\s_{*}\in S$ such that $\textbf{n}(\s_{*})<|\s_{*}^{\B}|$.

\begin{theorem}
    If $\T$ is decidable and strongly finitely witnessable with respect to a finite set of sorts $S$, then it has a computable minimal model function with respect to $S$.
\end{theorem}

\begin{proof}

    Assume, without loss of generality, that $S=\{\s_{1},\ldots,\s_{n}\}$ so that we may write an element of the minimal model function as $(n_{1},\ldots,n_{n})$.
    Let $\wit$ be the strong witness for $\T$, $V$ be the set of variables in $\wit(\varphi)$, $V_{i}$ the set of variables in $\wit(\varphi)$ of sort $\s_{i}$, $Eq_{i}(V)$ the set of equivalence relations on $V_{i}$ (finite and easily algorithmically found), and $\eq{V}$ the product of $Eq_{i}(V)$.
    We then define $\minmod(\varphi)$ as the set of minimal elements of the set
    \[T(\varphi)=\{(|V_{1}/E_{1}|,\ldots,|V_{n}/E_{n}|) : \text{$E\in\eq{V}$ and $\wit(\varphi)\wedge\delta_{V}^{E}$ is $\T$-satisfiable}\},\]
    under the order such that $(n_{1},\ldots,n_{n})\leq (m_{1},\ldots,m_{n})$ if and only if $n_{i}\leq m_{i}$ for each $1\leq i\leq n$, and where:
    $E=(E_{1},\ldots,E_{n})$, and $\delta_{V}^{E}$ is the arrangement on $V$ inducing the equivalence $E_{i}$ on each $V_{i}$.
    This is computable as $\wit$ is computable, $\T$ is decidable, and the set whose minimal elements we must find is finite.

    Take an element $(|V_{1}/E_{1}|,\ldots,|V_{n}/E_{n}|)$ of $\minmod(\varphi)$, meaning $\wit(\varphi)\wedge\delta_{V}^{E}$ is $\T$-satisfiable;
    as $\wit$ is a strong witness, there is a $\T$-interpretation $\A$ that satisfies $\wit(\varphi)\wedge\delta_{V}^{E}$ with $\s_{i}^{\A}=\vars_{\s_{i}}(\wit(\varphi)\wedge\delta_{V}^{E})^{\A}=V_{i}^{\A}$ for every $\s_{i}\in S$. 
    Since $\A$ satisfies $\delta_{V}^{E}$, $V_{i}^{\A}$ has as many elements as $V_{i}/E_{i}$, and so $(|\s_{1}^{\A}|,\ldots,|\s_{n}^{\A}|)=(|V_{1}/E_{1}|,\ldots,|V_{n}/E_{n}|)$, meaning the first property of a minimal model function is satisfied.

    Now, suppose for the sake of contradiction that there is a tuple $(|V_{1}/E_{1}|,\ldots,\break|V_{n}/E_{n}|)$ in $\minmod(\varphi)$ and a $\T$-interpretation $\A$ that satisfies $\varphi$ such that $|\s_{i}^{\A}|\leq |V_{i}/E_{i}|$, for all $\s_{i}\in S$, and for at least one of them $|\s_{i}^{\A}|<|V_{i}/E_{i}|$.
    As $\wit$ is a strong witness we have that $\A$ satisfies $\Exists{\overarrow{x}}\wit(\varphi)$, for $\overarrow{x}=\vars(\wit(\varphi))\setminus\vars(\varphi)$, and therefore there is a $\T$-interpretation $\B$, differing from $\A$ at most on the values assigned to $\overarrow{x}$, that satisfies $\wit(\varphi)$.
    Let $F_{i}$ be the equivalence relation induced by $\B$ over $V_{i}$, and $F=(F_{1},\ldots,F_{n})$, so that $\B$ satisfies $\wit(\varphi)\wedge\delta_{V}^{F}$.
    Again, by using the fact that $\wit$ is a strong witness there must exist a third $\T$-interpretation $\C$ that satisfies $\wit(\varphi)\wedge\delta_{V}^{F}$ with $\s_{i}^{\C}=\vars_{\s_{i}}(\wit(\varphi)\wedge\delta_{V}^{F})^{\C}=V_{i}^{\C}$ for each $1\leq i\leq n$.
    Using $\C$ satisfies $\delta_{V}^{F}$, $|\s_{i}^{\C}|=|V_{i}/F_{i}|$, and since $\B$ also satisfies $\delta_{V}^{F}$, $|V_{i}/F_{i}|\leq |\s_{i}^{\B}|=|\s_{i}^{\A}|$.
    This means that $(|\s_{1}^{\C}|,\ldots,|\s_{n}^{\C}|)$, although being in $T(\varphi)$, is strictly less than $(|V_{1}/E_{1}|,\ldots,|V_{n}/E_{n}|)$, a minimal element of $T(\varphi)$, leading to a contradiction and finishing the proof.
\end{proof}

\section{\tp{Proof of \Cref{theo:SHINYminusSF}}{Proof of Result \ref{theo:SHINYminusSF}}}

\begin{proposition} \label{Tgr-dec}
    The theory $\Tgr$ is decidable.
\end{proposition}
\begin{proof}
    It suffices to show that it is decidable whether a conjunction of literals is $\Tgr$-satisfiable, so let $\varphi$ be a conjunction of literals. Write $\varphi = \varphi_1 \land \varphi_2$, where $\varphi_1$ contains the equalities and disequalities in $\varphi$ and $\varphi_2$ contains the literals of the form $P_n$ and $\lnot P_n$ in $\varphi$.

    We describe our decision procedure as follows. If $\varphi_1$ is unsatisfiable in equational logic, then $\varphi$ is $\Tgr$-unsatisfiable. Otherwise, let $m$ be the size of the smallest interpretation that satisfies $\varphi_1$.

    We claim that, in this case, $\varphi$ is $\Tgr$-satisfiable if and only if for every $n$ such that the literal $P_n$ is in $\varphi_2$, we have $F(n) \ge m$. This is because if the latter condition holds, we can extend an interpretation that satisfies $\varphi_1$ to a $\Tgr$-interpretation $\A$ satisfying $\varphi$ by setting $P_n^\A$ to true for every $n$ such that the literal $P_n$ is in $\varphi_2$ and setting $P_n^\A$ to false otherwise. Otherwise, there is some $n$ such that the literal $P_n$ is in $\varphi_2$ and $F(n) < m$. In this case, there is no interpretation that satisfies $\varphi_1$ of size at most $F(n)$, so $\varphi$ is $\Tgr$-unsatisfiable (since $P_n \rightarrow \psi_{\leq F(n)}$ is an axiom of $\Tgr$).
\end{proof}

\begin{proposition}
        The theory $\Tinfty$ is decidable.
    \end{proposition}

    \begin{proof}
    We prove $\Tinfty$ and equational logic satisfy the same quantifier-free formulas, and since the latter is decidable so will be $\Tinfty$.
    Of course equational logic satisfies all quantifier-free formulas that $\Tinfty$ satisfies, given that it has more models than $\Tinfty$.
    Reciprocally, suppose the quantifier-free formula $\varphi$ is satisfied by equational logic, and let $\A$ be an interpretation that satisfies $\varphi$.
    We consider the interpretation $\B$ with $\dom{\B}=\dom{\A}\cup B$, for a set $B=\{b_{n}:n\in\mathbb{N}\}$ disjoint from $\dom{\A}$, and $x^{\B}=x^{\A}$ for all variables $x$.
    $\B$ is a $\Tinfty$-interpretation, of course, but it also satisfies $\varphi$, which can be proven by a simple induction on the subformulas of $\varphi$.
    \end{proof}

\begin{proposition}
    The theory $\Tinfty \oplus \Tgr$ is undecidable.
\end{proposition}
\begin{proof}
    It suffices to show that $P_n$ is $\Tinfty \oplus \Tgr$-satisfiable if and only if $F(n) = \Inf$. If $F(n) = \Inf$, then $P_n$ is satisfied by the $\Tinfty \oplus \Tgr$-interpretation $\A$ of size $\aleph_0$ where $P_n^\A$ is true and $P_{n'}^\A$ is false for all $n' \neq n$. If $F(n) < \Inf$, then any $\Tgr$-interpretation satisfying $P_n$ must be finite (since $\Tgr$ has the axiom $P_n \rightarrow \psi_{\leq F(n)}$). Hence, $P_n$ is $\Tinfty \oplus \Tgr$-unsatisfiable.
\end{proof}











\section{Proofs concerning $\Tot$}

\begin{proposition}\label{Tot is gentle}
    The theory $\Tot$ is gentle.
\end{proposition}

\begin{proof}
Let:
    $\vars(\varphi)$ equal $\{x_{1},\ldots,x_{n}\}$;
    $M_{i}$ be the maximum of $j$ such that $\ns^{j}(x_{i})$ shows up in $\varphi$;
    $M^{\prime}_{0}$ be the maximum of $j$ such that $\ns^{j}(a)$ appears in $\varphi$, and if it doesn't we set $M^{\prime}_{0}$ to $0$;
    $M_{0}=M^{\prime}_{0}+\sum_{i=1}^{n}(M_{i}+1)$;
    and take fresh variables $x_{i,j}$, for $0\leq i\leq n$ and $0\leq j\leq M_{i}$.
    We then flatten and Ackermannize $\varphi$, meaning:
    we replace any term $\ns^{j}(x_{i})$ by $x_{i,j}$, and any term $\ns^{j}(a)$ by $x_{0,j}$, in order to obtain the formula of equational logic $\varphi^{\prime}$;
    and define the formula $\varphi_{*}$ as $\varphi^{\prime}\wedge Fun(V)$, where $V=\{x_{i,j} : 0\leq i\leq n, 0\leq j\leq M_{i}\}$ and 
    \[Fun(V)=\bigwedge_{0\leq i,p\leq n}\bigwedge_{0\leq j< M_{i}}\bigwedge_{0\leq q<M_{p}}(x_{i,j}=x_{p,q})\rightarrow(x_{i,j+1}=x_{p,q+1}).\]
    Now, consider the set $\eq{V}$ of equivalence relations on $V$, which is easily computable; 
    $[x_{i,j}]_{E}$ shall denote in what follows the equivalence class under $E$ with representative $x_{i,j}$. 
    We define a subset $\eqp{V}$ of $\eq{V}$ such that $E$ is in $\eqp{V}$ if, and only if, when defining the interpretation of equational logic with domain $V/E$ and where $x_{i,j}$ is assigned the value $[x_{i,j}]_{E}$ (an interpretation we shall denote by $\int{V}{E}$), $\varphi_{*}$ is true in this interpretation (this can be decided algorithmically given the finiteness of $V/E$).

    For $E\in\eqp{V}$ we define a partial function $\ns_{E}$ on $V/E$ by making $\ns_{E}([x_{i,j}]_{E})=[x_{i,j+1}]_{E}$ for all $i\in\{0,\ldots,n\}$ and $j\in\{0,\ldots,M_{i}-1\}$ (notice that $\ns_{E}([x_{i,M_{i}}]_{E})$ may still be defined if $[x_{i,M_{i}}]_{E}=[x_{p,q}]_{E}$ for a $q\in\{0,\ldots,M_{p}-1\}$).
    This is well-defined: 
    if $[x_{i,j}]_{E}=[x_{p,q}]_{E}$ for $0\leq i,p\leq n$, $0\leq j<M_{i}$ and $0\leq q<M_{p}$, we have that $\int{V}{E}$ satisfies $x_{i,j}=x_{p,q}$;
    since it also satisfies $Fun(V)$, we have that it satisfies $x_{i,j+1}=x_{p,q+1}$, meaning that $\ns_{E}([x_{i,j}]_{E})=[x_{i,j+1}]_{E}=[x_{p,q+1}]_{E}=\ns_{E}([x_{p,q}]_{E})$.
    The partial function $\ns_{E}$ can be computed by an exhaustive search, as $V$, and thus $V/E$, is finite.

    We then let $B_{0}^{E}$ be the orbit of $[x_{0,0}]_{E}$ under $\ns_{E}$:
    for a partial function, this means either the list $\{\ns_{E}^{j}([x_{0,0}]_{E}) : j\in\mathbb{N}\}$ if $\ns_{E}$ is always defined on $\ns_{E}^{j}([x_{0,0}]_{E})$;
    or the list $\{\ns_{E}^{0}([x_{0,0}]_{E}), \ldots, \ns_{E}^{J}([x_{0,0}]_{E})\}$, if $\ns_{E}$ is defined on all $\ns_{E}^{j}([x_{0,0}]_{E})$ for $0\leq j\leq J-1$, but not on $\ns_{E}^{J}([x_{0,0}]_{E})$;
    this can be easily found algorithmically.\footnote{\label{footnote-in-proofs}The proof of \Cref{prop:tgpdec} continues from here.}
    Define $\eqpp{V}$ as the subset of $\eqp{V}$ where $2|B_{0}^{E}|\geq |V/E|$.
    For every $E\in\eqpp{V}$, define the interval $I(E)$ as
    \[I(E)=\begin{cases}
        [|V/E|,2|B_{0}^{E}|] & \text{if $\ns_{E}$ is defined for all of $B_{0}^{E}$,}\\
        \{n\in\No: n\geq|V/E|\}\cup\{\Inf\} & \text{otherwise,}
    \end{cases}\]
    and we state that 
    \[\spec(\varphi)=\bigcup_{E\in\eqpp{V}}I(E)\]
    if $\eqpp{V}$ is not empty, and $\spec(\varphi)=\emptyset$ otherwise.
    Given that the sets $I(E)$ are computable and either finite or cofinite, so is $\spec(\varphi)$ if the identity truly holds, meaning $\Tot$ is gentle.
    We prove the identity in three cases.
    \begin{enumerate}
    \item If $\eqpp{V}$ is not empty and $\ns_{E}$ is defined for all of $B_{0}^{E}$, for each $0\leq j\leq 2|B_{0}^{E}|-|V/E|$ take a set $B$ with cardinality $j$ disjoint from $V/E$, and we define a $\Tot$-interpretation $\A_{j}$ as follows.

    We make $\dom{\A_{j}}=(V/E)\cup B$, which then has $|V/E|+j\leq 2|B_{0}^{E}|$ elements.
    Of course $a^{\A_{j}}=[x_{0,0}]_{E}$.
    $\ns^{\A_{j}}(b)=\ns_{E}(b)$ for all $b$ where $\ns_{E}$ is defined, and $\ns^{\A_{j}}(b)=b$ otherwise:
    this way the orbit of $a^{\A_{j}}$ under $\ns^{\A}$ has $|B_{0}^{E}|$ elements, making $\A_{j}$ a $\Tot$-interpretation.
    And, finally, $x^{\A_{j}}=[x]_{E}$ for all variables $x\in V$, $x_{i}^{\A_{j}}=[x_{i,0}]_{E}$ for all variables $x_{i}$ in $\varphi$, and arbitrarily otherwise, so $\A_{j}$ satisfies $\varphi$ as $E\in\eqp{V}$.

    There cannot exist a $\Tot$-interpretation $\A$ that induces the equivalence $E$ on $V$ with fewer than $|V/E|$ elements, obviously.
    And there cannot exist a $\Tot$-interpretation $\A$ that induces the equivalence $E$ on $V$ with more than $2|B_{0}^{E}|$ elements as the orbit of $a^{\A}$ under $\ns^{\A}$ has necessarily $|B_{0}^{E}|$ elements.

    \item If $\eqpp{V}$ is not empty and $\ns_{E}$ is not defined over all of $B_{0}^{E}$, take any $j\in\mathbb{N}$ and a set $B=\{b_{1},\ldots,b_{j}\}$ with cardinality $j$ disjoint from $V/E$, and we define a $\Tot$-interpretation $\A_{j}$ as follows.

    First $\dom{\A_{j}}=(V/E)\cup B$, so $|\dom{\A_{j}}|=|V/E|+j$.
    Second, of course $a^{\A_{j}}=[x_{0,0}]_{E}$.
    Third:
    $\ns^{\A_{j}}(b)=\ns_{E}(b)$ for all $b$ where $\ns_{E}$ is defined;
    $\ns^{\A_{j}}(b)=b_{1}$ for the one element $b\in B_{0}^{E}$ where $\ns_{E}$ is not defined;
    $\ns^{\A_{j}}(b_{i})=b_{i+1}$ for $1\leq i\leq j-1$;
    and, for all elements $b$ where $\ns^{\A_{j}}$ hasn't been defined yet, including $b_{j}$, $\ns^{\A}(b)=b$.
    Notice that, this way, the orbit of $a^{\A_{j}}$ under $\ns^{\A_{j}}$ has size $|B_{0}^{E}|+j$, and since $2(|B_{0}^{E}|+j)\geq |V/E|+2j\geq |V/E|+j=|\dom{\A_{j}}|$ we get $\A_{j}$ is a $\Tot$-interpretation.
    And, finally, $x^{\A_{j}}=[x]_{E}$ for all variables $x\in V$, $x_{i}^{\A_{j}}=[x_{i,0}]_{E}$ for all variables $x_{i}$ in $\varphi$, and arbitrarily otherwise, so $\A_{j}$ satisfies $\varphi$ as $E\in\eqp{V}$.

    Of course an interpretation that satisfies $\varphi$ and induces the equivalence $E$ must have at least $|V/E|$ elements, so we are done.

    \item Suppose a $\Tot$-interpretation $\A$ satisfies $\varphi$: 
    we can change the values assigned to the variables $x_{i,j}$ while keeping $\varphi$ satisfied, as they are not in $\varphi$, so that $x_{i,j}^{\A}=(\ns^{\A})^{j}(x_{i}^{\A})$;
    take then the equivalence $E$ on $V$ such that $x_{i,j}Ex_{p,q}$ if $x_{i,j}^{\A}=x_{p,q}^{\A}$.
    Of course $\varphi_{*}$ is satisfied by $\int{V}{E}$, so $E\in\eqp{V}$.
    If $\ns_{E}$ is defined for all elements of the orbit of $[x_{0,0}]_{E}$ under $\ns_{E}$, we have that $|\dom{\A}|=2|B_{0}^{E}|$ and, since $|\dom{\A}|\geq |V/E|$, we get $2|B_{0}^{E}|\geq |V/E|$;
    if it is not, then it contains $M_{0}$ elements, and since $|V/E|\leq M_{0}$ we again get $2|B_{0}^{E}|\geq |V/E|$, proving that $\eqpp{V}$.
    Therefore, for $\varphi$ to be satisfiable we must have some $E\in\eqpp{V}$.

\end{enumerate}


\end{proof}

\begin{proposition}\label{prop:diffproof}
    The theory $\Tot$ is decidable.
\end{proposition}

\begin{proof}
    Follows from \Cref{Tot is gentle}: 
    a quantifier-free formula $\varphi$ is $\Tot$-satisfiable if and only if $\spec(\varphi)$ is not empty, something that is decidable.
\end{proof}



