\begin{proposition}\label{prop:totSFW}
    The theory $\Tot$ is strongly finitely witnessable.
\end{proposition}

\begin{proof}
Let  $x_{1}$ through $x_{n}$ be the variables in a quantifier-free formula $\varphi$, $M_{i}$ be the maximum of $j$ such that $\ns^{j}(x_{i})$ occurs in $\varphi$, $M^{\prime}_{0}$ be the maximum of $j$ such that $\ns^{j}(x_{0})$ occurs in $\varphi$, $M_{0}$ be $M^{\prime}_{0}+\sum_{i=1}^{n}(M_{i}+1)$, and take fresh variables $x_{i,j}$, for $0\leq i\leq n$ and $0\leq j\leq M_{i}$.
    We state 
    \[\wit(\varphi)=\varphi\wedge\bigwedge_{i=0}^{n}\bigwedge_{j=0}^{M_{i}}x_{i,j}=\ns^{j}(x_{i})\]
    is a strong witness for $\Tot$.
    Of course it maps quantifier-free formulas into other quantifier-free formulas, and is computable.
    Furthermore, for $\overarrow{x}=\vars(\wit(\varphi))\setminus\vars(\varphi)$, it is obvious that $\Exists{\overarrow{x}}\wit(\varphi)$ implies $\varphi$, since $\wit(\varphi)$ itself already implies $\varphi$.
    Reciprocally, if the $\Tot$-interpretation $\A$ satisfies $\varphi$, we produce a new $\Tot$-interpretation $\B$ by changing the values assigned by $\A$ to those variables in $\overarrow{x}$ so that $x_{i,j}^{\B}=(\ns^{\A})^{j}(x_{i}^{\A})$;
    this way $\B$ satisfies $\wit(\varphi)$, and therefore $\A$ satisfies $\Exists{\overarrow{x}}\wit(\varphi)$.

    Now, take a finite set of variables $V$ (not to be confused with the $V$ used in the proof above that $\Tot$ is decidable), an arrangement $\delta_{V}$ over $V$, and a $\Tot$-interpretation $\A$ that satisfies $\wit(\varphi)\wedge\delta_{V}$: 
    there are two cases we consider;
    for simplicity, let $U$ denote $\vars(\wit(\varphi))$.
    \begin{enumerate}
        \item Suppose that the orbit of $a^{\A}$ under $\ns^{\A}$ is a subset of $U^{\A}\cup V^{\A}$, and we then define an interpretation $\B$ by making:
        $\dom{\B}=U^{\A}\cup V^{\A}$;
        $a^{\B}=a^{\A}$;
        $\ns^{\B}(b)=\ns^{\A}(b)$ whenever the latter value is in $\dom{\B}$, and otherwise $\ns^{\B}(b)=b$ (this way, the orbit of $a^{\B}$ under $\ns^{\B}$ is the same as the orbit of $a^{\A}$ under $\ns^{\A}$, and since $|\dom{\B}|\leq |\dom{\A}|$ we get $\B$ is a $\Tot$-interpretation);
        and $x^{\B}=x^{\A}$ for every variable $x\in U\cup V$, and arbitrarily otherwise (so $\dom{\B}=\vars(\wit(\varphi)\wedge\delta_{V})^{\B})$).

        It is clear that $\B$ satisfies $\delta_{V}$, given the definition of how it assigns values to variables;
        since $x_{i,j}^{\B}=x_{i,j}^{\A}$ and $x_{i,j}^{\A}=(\ns^{\A})^{j}(x_{i}^{\A})$, and thus $(\ns^{\B})^{j}(x_{i}^{\B})=(\ns^{\A})^{j}(x_{i}^{\A})$ (for $0\leq j\leq M_{i}$), we get $\B$ satisfies $\bigwedge_{i=0}^{n}\bigwedge_{j=0}^{M_{i}}x_{i,j}=\ns^{j}(x_{i})$.

        Finally, for any atomic subformula of $\varphi$ of the form $\ns^{j}(x_{i})=\ns^{q}(x_{p})$ (the cases $\ns^{j}(x_{i})=\ns^{q}(a)$ and $\ns^{j}(a)=\ns^{q}(a)$ being analogous), since $(\ns^{\B})^{j}(x_{i}^{\B})=(\ns^{\A})^{j}(x_{i}^{\A})$ and $(\ns^{\B})^{q}(x_{p}^{\B})=(\ns^{\A})^{q}(x_{p}^{\A})$, we get that the subformula is true in $\B$ if and only if it is true in $\A$;
        since $\varphi$ is quantifier-free, $\B$ satisfies $\varphi$, and thus $\wit(\varphi)$, and we are done.

        \item Suppose then that the orbit of $a^{\A}$ under $\ns^{\A}$ is not entirely contained in $U^{\A}\cup V^{\A}$:
        there are, however, at least $M_{0}+1$ (distinct) elements of it in $U^{\A}\cup V^{\A}$.
        For simplicity, assume $\{b_{1},\ldots, b_{R}\}$ is an enumeration of $V^{\A}\setminus U^{\A}$.
        We then define an interpretation $\B$ as follows:
        $\dom{\B}=U^{\A}\cup V^{\A}$;
        $a^{\B}=a^{\A}$;
        $\ns^{\B}(c)=\ns^{\A}(c)$ whenever the latter is in $U^{\A}$, $(\ns^{\B})^{M_{0}+1}(a^{\B})=b_{1}$, $\ns^{\B}(b_{r})=b_{r+1}$ for $1\leq r<R$, and if $\ns^{\B}(c)$ hasn't been defined yet we make it equal to $c$ (the orbit of $a^{\B}$ under $\ns^{\B}$ has then $M_{0}+R+1$ elements, and since $|U^{\A}|\leq 2M_{0}+1$ and $|V^{\A}\setminus U^{\A}|=R$ we conclude $\B$ is a $\Tot$-interpretation);
        and $x^{\B}=x^{\A}$ for every variable $x\in U\cup V$, and arbitrarily otherwise (so $\dom{\B}=\vars(\wit(\varphi)\wedge\delta_{V})^{\B})$).

        We finally prove $\B$ satisfies $\wit(\varphi)\wedge\delta_{V}$ just as in the item above.
\end{enumerate}
\end{proof}

