\begin{proposition}
    The theory $\TMn\oplus\Tot$ is undecidable.
\end{proposition}

\begin{proof}
    Assume instead $\TMn\oplus\Tot$ is decidable, and let us define a function $\NFT:\No\rightarrow\{0,1\}$ and formulas $\varphi_{n}$ by making:
    $\NFT(1)=\NFT(3)=1$ and $\NFT(2)=\NFT(4)=0$;
    assuming $\NFT$ defined up to $2n$, $\varphi_{n}$ equal to $\orb{n+1}(a)\wedge\varphi_{\geq \NFT_{1}(2n)+2}^{\eqs}$ (where, as before, $\NFT_{1}(n)=|\{1\leq i\leq n : \NFT(i)=1\}|$), and
        \[\NFT(2n+1)=\NFT(2n+2)=\begin{cases}
        1 & \text{if $\varphi_{n}$ is $\TMn\oplus\Tot$-satisfiable},\\
        $0$ & \text{otherwise};\\
    \end{cases}\]
    Of course $\NFT$ is computable, but we shall show that $\NFT=\nft$ and reach a contradiction; 
    assume this is true for all values up to $2n$ for $n\geq 2$, meaning in particular that $\NFT_{1}(n)=\nft_{1}(n)$, and we shall show $\nft(2n+1)=\nft(2n+2)=1$ if and only if $\varphi_{n}$ is $\TMn\oplus\Tot$-satisfiable.

    If it is satisfiable, there is a $\TMn\oplus\Tot$-interpretation $\A$ that satisfies $\varphi_{n}$, and thus $\orb{n+1}(a)$ as well as $\varphi_{\geq\nft_{1}(2n)+2}^{\eqs}$;
    from the axiom $\orb{n+1}(a)\rightarrow\psi_{\leq 2n+2}$ of $\Tot$ we get $\A$ has at most $2n+2$ elements, and from the axiomatization of $\TMn$ we get that it has at most $\nft_{1}(2n+2)$ elements satisfying  $\os(x)=x$.
    The fact that $\A$ satisfies $\varphi_{\geq\nft_{1}(2n)+2}^{\eqs}$ implies it has at least $\nft_{1}(2n)+2$ elements satisfying  $\os(x)=x$, and these two last facts are only compatible if $\nft(2n+1)=\nft(2n+2)=1$.

    Reciprocally, suppose $\nft(2n+1)=\nft(2n+2)=1$, and so there exists a $\TMn$-interpretation $\A$ with exactly $\nft_{1}(2n+2)=\nft_{1}(2n)+2$ elements satisfying  $\os(x)=x$, and $\nft_{0}(2n+2)=\nft_{0}(2n)$ satisfying  $\os(x)\neq x$ (and thus $2n+2$ elements in total, which we name $a_{1}$ through $a_{2n+2}$).
    Extend $\A$ to a $\Sat\oplus\Ss$-interpretation $\B$ by making $a^{\B}=a_{1}$, $\ns^{\B}(a_{i})=a_{i+1}$ for $1\leq i\leq n$, $\ns^{\B}(a_{n+1})=a_{n+1}$, and $\ns^{\B}(a_{i})=a_{i}$ for $n+2\leq i\leq 2n+2$:
    $\orb{n+1}(a)$ is then true in $\B$, while all $\orb{m}(a)$, for $m\neq n+1$, are obviously false. 
    We prove that $\B$ is then a $\TMn\oplus\Tot$-interpretation that satisfies $\varphi_{n}$, which shall finish the proof.
    $\B$ is certainly a $\TMn$-interpretation, vacuously satisfies all axioms $\orb{m}(a)\rightarrow\psi_{\leq 2m}$ for $m\neq n+1$, and satisfies $\orb{n+1}(a)\rightarrow\psi_{\leq 2n+2}$ given that it satisfies $\orb{n+1}(a)$ and has $2n+2$ elements, making of it a $\TMn\oplus\Tot$-interpretation.
    Furthermore, as mentioned before it satisfies $\orb{n+1}(a)$, and satisfies $\varphi_{\geq\nft_{1}(2n)+2}^{\eqs}$ since it has $\nft_{1}(2n+2)=\nft_{1}(2n)+2$ elements that satisfy  $\os(x)=x$.
\end{proof}





\section{Proofs concerning $\Tgp$}

\begin{proposition}\label{prop:tgpdec}
    The theory $\Tgp$ is decidable.
\end{proposition}

\begin{proof} 
This is essentially the same as the proof of \Cref{prop:diffproof}, the proofs being exactly the same up to \Cref{footnote-in-proofs}.
        The difference is that $\varphi$ is $\Tgp$-satisfiable if and only if there is an $E\in\eqp{V}$ such that
        \[|B_{0}|+F(|B_{0}|)\geq |V/E|.\]
        Now, we may not be able to calculate $F(|B_{0}|)$, but we can equivalently write this condition as $F(|B_{0}|)\geq |V/E|-|B_{0}|$, and such tests being computable are a prerequisite for $F$.
        \end{proof}



        \begin{proposition} 
        The theory $\Tinfty\oplus\Tgp$ is undecidable. 
        \end{proposition}

        \begin{proof} 
        Consider the formulas $\orb{n}$:
        we state that they are $\Tinfty\oplus\Tgp$-satisfiable if and only if $F(n)=\Inf$, what we know cannot be tested algorithmically.

        Take first an $n$ such that $F(n)=\Inf$, and define an interpretation $\A$ as follows:
        $\dom{\A}=\mathbb{N}$ (so $\A$ is a $\Tinfty$-interpretation) and $a^{\A}=0$;
        $\ns^{\A}(i)=i+1$ for all $i\neq n-1$, and $\ns^{\A}(n-1)=0$, so the orbit of $0$ is $\{0,\ldots,n-1\}$, meaning $\A$ satisfies $\orb{n}$ and, since $F(n)=\Inf$ and $\A$ is infinite we have that it is a $\Tgp$-interpretation;
        and $x^{\A}$ can be defined arbitrarily for all variables $x$.
        This means $\A$ is a $\Tinfty\oplus\Tgp$-interpretation that satisfies $\varphi$.

        Reciprocally, suppose $\A$ is a $\Tinfty\oplus\Tgp$-interpretation that satisfies $\orb{n}$: 
        if $F(n)\in\No$ we have $|\dom{\A}|\leq F(n)+n$, which is finite and thus contradicts the fact that $\A$ is supposed to be a $\Tinfty$-interpretation. 
        Thus $F(n)=\Inf$.
        \end{proof}


\section{\tp{Proof of \Cref{gentle-recovery}}{Proof of Theorem~\ref{gentle-recovery}}}

The key to the proof is the following result due to Fontaine.

\begin{lemma}[{\cite[Corollary~1]{gentle}}] \label{fontaine-lemma}
    Let $\T_1$ and $\T_2$ be theories over disjoint signatures $\Sigma_1$ and $\Sigma_2$, respectively. Suppose that it is decidable whether $\spec(\T_1,\varphi_1) \cap \spec(\T_2,\varphi_2) = \emptyset$, where $\varphi_1$ and $\varphi_2$ are conjunctions of literals over the signatures $\Sigma_1$ and $\Sigma_2$, respectively. Then, $\T_1 \oplus \T_2$ is decidable.
\end{lemma}

In light of the lemma, the following implies \Cref{gentle-recovery}.

\begin{lemma}
    Let $\T_1$ and $\T_2$ be decidable theories over disjoint signatures $\Sigma_1$ and $\Sigma_2$ respectively. Suppose that $\T_1$ is gentle and $\T_2$ has computable finite spectra. Then, it is decidable whether $\spec(\T_1,\varphi_1) \cap \spec(\T_2,\varphi_2) = \emptyset$, where $\varphi_1$ and $\varphi_2$ are conjunctions of literals over the signatures $\Sigma_1$ and $\Sigma_2$ respectively.
\end{lemma}
\begin{proof}
    Let $\varphi_1$ and $\varphi_2$ be conjunctions of literals over the signatures $\Sigma_1$ and $\Sigma_2$ respectively. We describe our decision procedure as follows. Since $\T_1$ is gentle, $\spec(\T_1,\varphi_1)$ is either of the form $S$ or $S \cup \{n \in \N \mid n \ge k\}$ for some $k \in \No$, where $S \subset \No$ is a finite set. We have $S \cap \spec(\T_2,\varphi_2) = \emptyset$ if and only if $n \notin \spec(\T_2,\varphi_2)$ for each $n \in S$, which we can check algorithmically since $\T_2$ has computable finite spectra. We also have $\{n \in \N \mid n \ge k\} \cap \spec(\T_2,\varphi_2) = \emptyset$ if and only if $\varphi_2 \land \neq(x_{1},\ldots,x_{k})$ is $\T_2$-unsatisfiable (where the variables $x_i$ are fresh). These computations allow us to determine whether $\spec(\T_1,\varphi_1) \cap \spec(\T_2,\varphi_2) = \emptyset$.
\end{proof}

We also prove here that \Cref{gentle-recovery} is a strengthening of \Cref{gentle-recovery-fontaine}.

\begin{proposition}
    If a theory $\T$ is gentle, then $\T$ has computable finite spectra.
\end{proposition}
\begin{proof}
    Let $\varphi$ be a quantifier-free formula, and let $k \in \No$. If $\T$ is gentle, then we can compute an explicit representation of the set $\spec(\T,\varphi)$, from which we can decide whether $k \in \spec(\T,\varphi)$.
\end{proof}

\begin{proposition}
    If a theory $\T$ is finitely axiomatizable, then $\T$ has computable finite spectra.
\end{proposition}
\begin{proof}
    Let $\varphi$ be a quantifier-free formula, and let $k \in \No$. Let $\Sigma$ be the signature over which $\T$ is defined. We may assume that $\Sigma$ only contains the symbols appearing in $\ax(\T) \cup \{\varphi\}$ so that, in particular, $\Sigma$ is finite. We can enumerate the $\Sigma$-interpretations of size $k$, checking whether any of them satisfy all of the formulas in $\ax(\T) \cup \{\varphi\}$. If we find a $\T$-interpretation of size $k$ satisfying $\varphi$, then $k \in \spec(\T,\varphi)$; otherwise, $k \notin \spec(\T,\varphi)$.
\end{proof}

\begin{proposition}
    Suppose that for a theory $\T$, there is an algorithm that, given a conjunction $\varphi$ of literals, outputs a finite set $S \subset \N$ such that $\spec(\T,\varphi) = S$. Then, $\T$ has computable finite spectra.
\end{proposition}
\begin{proof}
    Let $\varphi$ be a quantifier-free formula, and let $k \in \No$. Without loss of generality, $\varphi$ is a conjunction of literals (the general case follows by putting $\varphi$ in disjunctive normal form). We can compute a finite set $S \subset \N$ such that $\spec(\T,\varphi) = S$, from which we can decide whether $k \in \spec(\T,\varphi)$.
\end{proof}

\section{\tp{Proofs concerning \Cref{gentle-recovery-ex}}{Proof of Result \ref{gentle-recovery-ex}}}

\begin{proposition}
    For any $n \in \No$, the theory $\T_{\leq n}$ is gentle (and therefore decidable).
\end{proposition}
\begin{proof}
    Let $\varphi$ be a conjunction of literals. If $\varphi$ is unsatisfiable in equational logic, then $\spec(\T_{\leq n},\varphi) = \emptyset$. Otherwise, let $m$ be the size of the size of the smallest interpretation that satisfies $\varphi$. Then, $\spec(\T_{\leq n},\varphi) = [m,n]$.
\end{proof}

That $\Tgr$ is decidable is proved in \Cref{Tgr-dec}.

\begin{proposition}
    The theory $\Tgr$ has computable finite spectra.
\end{proposition}
\begin{proof}
    Let $\varphi$ be a conjunction of literals, and let $k \in \No$. Write $\varphi = \varphi_1 \land \varphi_2$, where $\varphi_1$ contains the equalities and disequalities in $\varphi$ and $\varphi_2$ contains the literals of the form $P_n$ and $\lnot P_n$ in $\varphi$.

    We describe our decision procedure as follows. If $\varphi_1$ is unsatisfiable in equational logic, then $\varphi$ is $\Tgr$-unsatisfiable, so $k \notin \spec(\Tgr,\varphi)$. Otherwise, let $m$ be the size of the smallest interpretation that satisfies $\varphi_1$. If $k < m$, then $k \notin \spec(\Tgr,\varphi)$. So assume that $k \ge m$.

    We claim that, in this case, $k \in \spec(\Tgr,\varphi)$ if and only if for every $n$ such that the literal $P_n$ is in $\varphi_2$, we have $F(n) \ge k$. This is because if the latter condition holds, we can extend an interpretation of size $k$ that satisfies $\varphi_1$ to a $\Tgr$-interpretation $\A$ of size $k$ satisfying $\varphi$ by setting $P_n^\A$ to true for every $n$ such that the literal $P_n$ is in $\varphi_2$ and setting $P_n^\A$ to false otherwise. Otherwise, there is some $n$ such that the literal $P_n$ is in $\varphi_2$ and $F(n) < k$. Then, there is no interpretation of $\varphi_2$ of size $k$ (since $P_n \rightarrow \psi_{\leq F(n)}$ is an axiom of $\Tgr$), so $k \notin \spec(\Tgr,\varphi)$.
\end{proof}

\begin{proposition}
    The theory $\Tgr$ is not gentle.
\end{proposition}
\begin{proof}
    It suffices to show that it is undecidable whether $\spec(\Tgr,\varphi)$ is infinite. And indeed, $\spec(\Tgr,P_n)$ is infinite if and only if $F(n) = \aleph_0$, which is undecidable by our assumptions on $F$.
\end{proof}

\begin{proposition}
    The theory $\Tgr$ is not finitely axiomatizable.
\end{proposition}
\begin{proof}
    If $\T$ is a finitely axiomatizable $\Spn$-theory, then the predicate $P_n$ does not appear in the axiomatization of $\T$ for some $n$ such that $F(n) < \aleph_0$. Then, $P_n \rightarrow \psi_{\leq F(n)}$ is $\Tgr$-valid but not $\T$-valid.
\end{proof}

\begin{proposition}
    There is no algorithm that, given a conjunction of literals $\varphi$ in the language of $\Tgr$, outputs a finite set $S \subset \N$ such that $\spec(\Tgr,\varphi) = S$
\end{proposition}
\begin{proof}
    Indeed, $\spec(\Tgr,\top)$ is not even a finite set.
\end{proof}

\begin{proposition}
    For any $n \in \No$, the theory $\T_{\leq n}$ is not stably infinite (and therefore neither strongly polite nor shiny).
\end{proposition}
\begin{proof}
    The theory has no models of size greater than $n$ and hence no infinite models.
\end{proof}

\begin{proposition}
    The theory $\Tgr$ is not stably infinite (and therefore neither strongly polite nor shiny).
\end{proposition}
\begin{proof}
    Let $n \in \No$ be such that $F(n) < \aleph_0$. Then, $P_n$ has no infinite $\Tgr$-models, since $P_n \rightarrow \psi_{\leq F(n)}$ is an axiom of $\Tgr$.
\end{proof}

\section{\tp{Proof of \Cref{new-method}}{Proof of Result \ref{new-method}}}

In light of \Cref{fontaine-lemma}, the following implies \Cref{new-method}.

\begin{lemma}
    Let $\T_1$ and $\T_2$ be decidable theories over disjoint signatures $\Sigma_1$ and $\Sigma_2$ respectively. Suppose that $\T_1$ is smooth and has a computable minimal model function and that $\T_2$ is infinitely decidable. Then, it is decidable whether $\spec(\T_1,\varphi_1) \cap \spec(\T_2,\varphi_2) = \emptyset$, where $\varphi_1$ and $\varphi_2$ are conjunctions of literals over the signatures $\Sigma_1$ and $\Sigma_2$ respectively.
\end{lemma}
\begin{proof}
    Let $\varphi_1$ and $\varphi_2$ be conjunctions of literals over the signatures $\Sigma_1$ and $\Sigma_2$ respectively. We describe our decision procedure as follows. If $\varphi_1$ is $\T_1$-unsatisfiable, then $\spec(\T_1,\varphi_1) \cap \spec(\T_2,\varphi_2) = \emptyset$, so suppose $\varphi_1$ is $\T_1$-satisfiable.

    If $\minmod_{\T_1}(\varphi_1) = n$ for some $n \in \No$, then $\spec(\T_1,\varphi_1) = \{m \in \No \mid m \ge n\} \cup \{\aleph_0\}$, since $\T_1$ is smooth. In this case, we have $\spec(\T_1,\varphi_1) \cap \spec(\T_2,\varphi_2) = \emptyset$ if and only if $\varphi_2$ has no $\T_2$-interpretations of size at least $n$, which happens exactly when $\varphi_2 \land \neq(x_{1},\ldots,x_{n})$ is $\T_2$-unsatisfiable (where the variables $x_i$ are fresh).

    If $\minmod_{\T_1}(\varphi_1) = \aleph_0$, then $\spec(\T_1,\varphi_1) = \{\aleph_0\}$. In this case, we have $\spec(\T_1,\varphi_1) \cap \spec(\T_2,\varphi_2) = \emptyset$ if and only if $\varphi_2$ is not satisfied by any infinite $\T_2$-interpretation, which we can check since $\T_2$ is infinitely decidable.
\end{proof}

\section{\tp{Proofs concerning \Cref{theo:onlybencomb}}{Proof of Result \ref{theo:onlybencomb}}}

\begin{proposition}\label{prop:tbSI}
    The theory $\Tb$ is not stably-infinite.
\end{proposition}

\begin{proof}
    $P_{1}$ is only satisfied by a $\Tb$-interpretation with one element.
\end{proof}

\begin{proposition}
    The theory $\Tb$ is not strongly polite.
\end{proposition}

\begin{proof}
    Follows from \Cref{prop:tbSI}, which implies $\Tb$ is not smooth.
\end{proof}

\begin{proposition}
    The theory $\Tinfty$ is not strongly polite.
\end{proposition}

\begin{proof}
    $\Tinfty$ was proven in \cite{CADE} not to be strongly finitely witnessable, so the result follows.
\end{proof}

\begin{proposition}
    The theory $\Tb$ is not shiny.
\end{proposition}

\begin{proof}
    Follows from \Cref{prop:tbSI}, which implies $\Tb$ is not smooth.
\end{proof}

\begin{proposition}
    The theory $\Tinfty$ is not shiny.
\end{proposition}

\begin{proof}
    $\Tinfty$ does not have the finite model property, and therefore is not shiny, since it is not trivial but has no finite models.
\end{proof}

\begin{proposition}
    The theory $\Tb$ does not have computable finite spectra.
\end{proposition}
\begin{proof}
    For all $n \ge 2$, we have $1 \in \spec(\Tb,P_n)$ if and only if $h(n)=0$, which is undecidable by assumption.
\end{proof}

\begin{proposition}
    The theory $\Tinfty$ has a computable minimal model function.
\end{proposition}

\begin{proof}
    Proven in \cite{LPAR}.
\end{proof}

\begin{proposition}
    The theory $\Tinfty$ is smooth.
\end{proposition}

\begin{proof}
    Obvious, but proven in \cite{CADE}.
\end{proof}

\begin{proposition}\label{prop:Tbdec}
    The theory $\Tb$ is decidable.
\end{proposition}

\begin{proof}
    Given a quantifier-free formula $\varphi$, assume without loss of generality $\varphi$ is a cube and write $\varphi=\varphi_{1}\wedge\varphi_{2}$, where $\varphi_{1}$ contains only equalities and disequalities, and $\varphi_{2}$ contains only the predicates $P_{n}$ and their negations.
    We state $\varphi$ is $\Tb$-satisfiable if, and only if, $\varphi_{1}$ is satisfiable in equational logic, $\varphi_{2}$ does not contain a predicate and its negation, and if $\varphi_{2}$ contains the literal $P_{1}$, then $\varphi_{1}$ has a model in equational logic of size $1$ and $\varphi_{2}$ contains no other positive literals.

    If $\varphi$ is $\Tb$-satisfiable so is $\varphi_{1}$, and by forgetting the predicates on a $\Tb$-interpretation that satisfies $\varphi_{1}$ we get an interpretation in equational logic that satisfies that formula.
    Of course $\varphi_{2}$ is also satisfiable, and then we cannot have both $P_{n}$ and $\neg P_{n}$ in $\varphi_{2}$.
    Finally, if $\varphi_{2}$ contains the literal $P_{1}$, any $\Tb$-interpretation $\A$ that satisfies $\varphi$ must satisfy $P_{1}$ as well, and by the axiom $P_{1}\rightarrow\psi_{=1}$ of $\Tb$ we get $\A$ has only one element;
    by forgetting its predicates, we get an interpretation in equational logic that satisfies $\varphi_{1}$ and has only one element.
    Furthermore, by the axioms $P_{1}\rightarrow\neg P_{n}$ we get $\A$ satisfies $\neg P_{n}$ for $n\geq 2$, and thus $\varphi_{2}$ cannot contain the positive literals $P_{n}$.

    For the reciprocal, start by assuming $\varphi_{2}$ does not contain the literal $P_{1}$, and since $\varphi_{1}$ is satisfiable in equational logic it has an infinite model $\A$, as equational logic is stably-infinite;
    turn $\A$ into a $\Spn$-interpretation by setting $P_{n}^{\A}$ to true if the literal $P_{n}$ occurs in $\varphi_{2}$, and otherwise to false, meaning it satisfies $\varphi_{2}$ as well (this is possible because $\varphi_{2}$ cannot contain both a literal and its negation).
    $\A$ then satisfies the axioms $P_{1}\rightarrow\psi_{=1}$ and $P_{1}\rightarrow \neg P_{n}$ vacuously, as it does not satisfy $P_{1}$;
    and it satisfies the axioms $P_{n}\rightarrow\psi_{\geq m}$ for $\nf(n)=1$ since it is infinite and therefore satisfies all $\psi_{\geq m}$.
    If $\varphi_{2}$ contains $P_{1}$, we take an interpretation $\A$ in equational logic that satisfies $\varphi_{1}$ with only one element, and make it into a $\Spn$-interpretation by setting $P_{1}^{\A}$ to true, and all other $P_{n}^{\A}$ to false (so $\A$ satisfies $\varphi_{2}$ as well, since that formula cannot contain any positive literals other than $P_{1}$).
    It satisfies $P_{1}\rightarrow\psi_{=1}$ as it contains only one element, $P_{1}\rightarrow\neg P_{n}$ as all $P_{n}$ different from $P_{1}$ are false in $\A$, and $P_{n}\rightarrow\psi_{\geq m}$ (for $n\geq 2$ with $\nf(n)=1$) vacuously.
\end{proof}

\begin{proposition}
    The theory $\Tb$ is infinitely decidable.
\end{proposition}

\begin{proof}
    Given a quantifier-free formula $\varphi$, we assume, without loss of generality, that $\varphi$ is a cube;
    write then $\varphi=\varphi_{1}\wedge\varphi_{2}$, where $\varphi_{1}$ contains only equalities and disequalities, and $\varphi_{2}$ contains only the predicates $P_{n}$ and their negations.
    As proven in \Cref{prop:Tbdec}, $\Tb$ is decidable, so we only need to worry whether $\Tb$-satisfiable $\varphi$ are satisfied by an infinite $\Tb$-interpretation:
    we state that such $\varphi$ have infinite $\Tb$-models if and only if $P_{1}$ does not appear as a literal in $\varphi_{2}$.

    One direction is obvious:
    if $\varphi_{1}$ contains $P_{1}$ and the $\Tb$-interpretation $\A$ satisfies $\varphi$, by the axiom $P_{1}\rightarrow \psi_{=1}$ we get $\A$ can only have one element.
    If $P_{1}$ is not in $\varphi_{2}$ we proceed as in the proof of \Cref{prop:Tbdec}:
    as equational logic is stably-infinite, take an infinite interpretation $\A$ that satisfies $\varphi_{1}$;
    and set $P_{n}^{\A}$ to true if and only if the positive literal $P_{n}$ occurs in $\varphi_{2}$, so $\A$, as a $\Spn$-interpretation, satisfies $\varphi_{2}$ as well.
\end{proof}





