\end{lemma}

\begin{proof}
   By Lemma~\ref{lm:block}, $\sum_{j=1}^{\|\Gamma_\mathcal{C}\|-1} m\cdot E_{ \langle \mathcal{C},j \rangle} = m \cdot (E_\mathcal{C}- E_{\langle \mathcal{C}, \|\Gamma_\mathcal{C}\| \rangle})$.
