\begin{theorem}\label{tm:PWA_AD}
The response time of a chain $\Gamma_\mathcal{C} = \{\tau_{\langle \mathcal{C},1 \rangle}, \tau_{ \langle \mathcal{C},2 \rangle}, ..., \tau_{ \langle \mathcal{C}, \|\Gamma_\mathcal{C}\| \rangle}\}$ with an \textbf{arbitrary deadline} on a \textbf{standard} ROS 2 multi-threaded executor with $m$ threads is upper-bounded by $R_\mathcal{C}=\Delta + \overline{sbf}_k(E_{\langle \mathcal{C}, \|\Gamma_\mathcal{C}\| \rangle}-1)$, if $dbf(\Delta)<sbf_\Pi(\Delta)$ holds for the following $dbf(\Delta)$:

\begin{equation}\begin{split}\label{eq:PWA_AD}
dbf(\Delta) &= m \cdot (E_\mathcal{C}- E_{\langle \mathcal{C}, \|\Gamma_\mathcal{C}\| \rangle}) \\
&+ (\sum_{\forall \Gamma_x \in \Gamma} W^*_x(\Delta, D_x - E_x)) - E_\mathcal{C}
\end{split} 
\end{equation}
\end{theorem}

\begin{proof}
    The difference from Theorem~\ref{tm:PWA_CD} is the second and third terms, which capture the maximum workload from interfering chain instances.
