\section{Canonical Path Method}\label{append:canonical-path}
The key to demonstrating a rapid mixing of a Markov chain using the canonical path technique lies in setting up a suitable multicommodity flow. For a pair $I,F\in \Omega$, we can imagine that by using the transitions of the Markov chain, we hope to route $\pi(I)\times \pi(F)$ units of fluid from $I$ to $F$. Specifically, we can define a canonical path $\gamma_{IF}:= (M_0 = I,M_1,\dots, M_l = F)$ from $I$ to $F$ through pairs $(M_i,M_{i+1})$ of states adjacent in the Markov chain. Let
\begin{align*}
    \Gamma := \{\gamma_{IF}\mid I,F\in\Omega\}
\end{align*}
be the set of all canonical paths. Then we can define the congestion $\varrho = \varrho(\Gamma)$ of the chain:
\begin{align}\label{eq:congestion}
    \varrho(\Gamma) := \max_{t=(M,M')}\left\{\frac{1}{\pi(M)P(M,M')} \sum_{I,F:\gamma \text{ uses }t} \pi(I)\pi(F) |\gamma_{IF}|\right\}
\end{align}
where $t$ runs over all transitions, i.e., all pairs of adjacent state of the chain; and $|\gamma_{IF}|$ denotes the length $l$ of the path $\gamma_{IF}$. In the analysis in~\cite{jerrum2003counting}, Jerrum modified the chain by making it ``lazy'', i.e., with probability $1/2$ the chain stays in the same state, and otherwise makes the transition specified in the original chain. This laziness doubles the mixing time, but ensures that the eigenvalues of the transition matrix are all non-negative, which helps the analysis. The relation between the congestion and the mixing time of a lazy MC is formalized as follows:
\begin{theorem}[\cite{jerrum2003counting}]\label{thm:canonical-mixing}
    The mixing time of the lazy MC is bounded by
$\tau_{\mix}(\varepsilon) \leq 2 \varrho\left(2 \ln \varepsilon^{-1}+\ln \pi_{\min}^{-1}\right)$,
where  $\varrho=\varrho(\Gamma)$ is the congestion defined in \eq{congestion} with respect to any set of canonical paths $\Gamma$, and $\pi_{\min}=\min_{M\in\Omega}\pi(M)$ is the minimum value of the stationary distribution.
\end{theorem}

Here we present a strengthened version of the multiple canonical path framework~\cite{sinclair1992improved,guo2017random}, which allows for multiple distinct paths between each pair $(I, F)$. Each path is associated with a selection probability $p^{(i)}_{IF}$, forming a complete probability distribution over the path set from $I$ to $F$. Intuitively, this framework can be viewed as a generalization of the original canonical path method, where for each pair $(I,F)$ we consider selecting a path from a collection with specific probabilities instead of a single canonical path.

Formally, we can define this multiple canonical path framework as follows:
\begin{definition}[Multiple canonical path framework]
Consider a Markov chain with state space $\Omega$.
    For any pair of state $(I,F)\in \Omega\times \Omega$, let $\Gamma_{IF} := \{(\gamma_{IF}^{(i)}, p_{IF}^{(i)})\mid i=1,2,\dots, l(I,F)\}$ be a collection of paths from $I$ to $F$ with size $l(I,F)$, where $\gamma_{IF}^{(i)}$ is the $i$-th path and $p_{IF}^{(i)}$ is the selection probability of the $i$-th path, satisfying the following conditions:
    \begin{itemize}
        \item Each $\gamma_{IF}^{(i)}$ is a path from $I$ to $F$ in the Markov chain, i.e., there exists a sequence of states $M_0 = I, M_1, \ldots, M_l = F$ such that $(M_j, M_{j+1})$ is a transition in the Markov chain for all $j=0,\ldots,l-1$.
        \item The selection probabilities $p_{IF}^{(i)}$ are non-negative and sum to 1: $p_{IF}^{(i)} \geq 0$ for all $i=1,\ldots,l(I,F)$, and $\sum_{i=1}^{l(I,F)} p^{(i)}_{IF} = 1$.

    \end{itemize}
    The length of each path $\gamma_{IF}^{(i)}$ is denoted as $|\gamma_{IF}^{(i)}|$, and for convenience we define $|\gamma_{IF}| = \max_{i=1,\ldots,l(I,F)} |\gamma_{IF}^{(i)}|$.

    The multiple canonical path framework is denoted as $\Gamma = \{\Gamma_{IF}\mid I,F\in\Omega\}$, and the congestion $\varrho$ is defined as follows:
    \begin{align}
         \varrho(\Gamma) := &\max_{t=(M,M')}\bigg\{\frac{1}{\pi(M)P(M,M')} \cdot 
        \sum_{I,F\in \Omega} \sum_{i=1}^{l(I,F)} \textbf{1}_{\{\gamma_{IF}^{(i)}\text{ uses }t\}} \cdot\pi(I)\pi(F) |\gamma_{IF}|\cdot p^{(i)}_{IF}\bigg\}.
    \end{align} 
\end{definition}



Similarly, \thm{canonical-mixing} remains valid for the enhanced multiple canonical path framework. In subsequent proofs in \append{dense-graph-proof}, we will employ this enhanced canonical path framework, as its multiple-path construction enables more effective utilization of symmetries between different transitions, thereby providing greater flexibility in establishing conductance bounds and mixing time estimates.

The key step in the proof in \thm{canonical-mixing} is constructing the relations between the congestion $\varrho$ as well as local and global variations:
\begin{lemma}\label{lem:canonical-mixing-variation}
    Let $\pi$ be the stationary distribution of a Markov chain with state space $\Omega$ and transition matrix $P$.
    For any function $f: \Omega\to\R$, define the variance of $f$ with respect to $\pi$ as
    \begin{align*}
        \Var_\pi(f) := \sum_{M\in\Omega} \pi(M)\left(f(M) - E_\pi f\right)^2 = \frac{1}{2} \sum_{I,F\in \Omega} \pi(I)\pi(F) \left(f(I) - f(F)\right)^2
    \end{align*}
    and the ``global variation'' of function $f$ with respect to the transition as
    \begin{align*}
        \mathcal{E}_\pi(f,f) := \frac{1}{2} \sum_{M,M'\in \Omega} \pi(M)P(M,M')\left(f(M) - f(M')\right)^2.
    \end{align*}
    Then for any canonical path framework $\Gamma$ of the MC, we have

    \begin{align}\label{eq:eq3}
        \mathcal{E}_\pi(f,f) \geq \frac{1}{\varrho(\Gamma)} \Var_\pi f.
    \end{align}
\end{lemma}


    To extend \thm{canonical-mixing} to the multiple canonical path scenario, it suffices to prove that \lem{canonical-mixing-variation} remains valid under the generalized framework: 
    \begin{proof}[Proof of \lem{canonical-mixing-variation} for multiple canonical path framework]
        \begin{align*}
            2\operatorname{Var}_{\pi}f & =\sum_{I,F\in\Omega}\pi(I)\pi(F)\left(f(I)-f(F)\right)^{2} \\ &=\sum_{I,F\in\Omega}\pi(I)\pi(F)\sum_{i=1}^{l(I,F)}p^{(i)}_{IF}\cdot\left(\sum_{(M,M')\in\gamma^{(i)}_{IF}}1\cdot\left(f(M)-f(M')\right)\right)^2 \\
        &\leq\sum_{I,F\in\Omega}\pi(I)\pi(F)\sum_{i=1}^{l(I,F)}p^{(i)}_{IF}\cdot\left|\gamma^{(i)}_{IF}\right|\sum_{(M,M')\in\gamma^{(i)}_{IF}}\left(f(M)-f(M')\right)^{2} \\
         & =\sum_{M,M'\in\Omega}\sum_{I,F\in\Omega}\pi(I)\pi(F)\cdot \sum_{i=1}^{l(I,F)}\textbf{1}_{\{\gamma_{IF}^{(i)}\text{ uses }(M,M')\}}p^{(i)}_{IF}\left|\gamma^{(i)}_{IF}\right|\left(f(M)-f(M')\right)^2 \\
         & =\sum_{M,M'\in\Omega}\left(f(M)-f(M')\right)^{2}\cdot  \sum_{I,F\in\Omega}\pi(I)\pi(F) \sum_{i=1}^{l(I,F)}\textbf{1}_{\{\gamma_{IF}^{(i)}\text{ uses }(M,M')\}}p^{(i)}_{IF}\left|\gamma^{(i)}_{IF}\right| \\
         & \leq\sum_{M,M'\in\Omega}\left(f(M)-f(M')\right)^{2}\pi(M)P(M,M')\varrho \\
         & =2\varrho\mathcal{E}_{\pi}(f,f).
        \end{align*}
    \end{proof}


Building upon the analytical framework in~\cite{jerrum2003counting}, we have extended \thm{canonical-mixing} to accommodate multiple canonical paths, achieving a stronger result:
\begin{theorem}\label{thm:canonical-mixing-multiple}
    For any Markov chain, the mixing time of its lazy MC is bounded by
$\tau_{\mix}(\varepsilon) \leq 2 \varrho\left(2 \ln \varepsilon^{-1}+\ln \pi_{\min}^{-1}\right)$,
where  $\varrho=\varrho(\Gamma)$ is the congestion defined in \eq{congestion} with respect to any \textbf{multiple canonical path framework} $\Gamma$, and $\pi_{\min}=\min_{M\in\Omega}\pi(M)$ is the minimum value of the stationary distribution.
\end{theorem}


