\subsection{Dense Bipartite Graphs}
\label{append:dense-bipartite}
In this section, we extend the results from \append{complete-bipartite} to non-complete bipartite graphs, providing proofs of \thm{bipartite-graph} and \thm{main-results-bigraph}. A natural approach is to leverage the aforementioned congestion calculations.
We discuss dense bipartite graphs $G$: there exists a constant $\xi$, such that each vertex is non-adjacent to at most $\xi$ vertices in the opposite partition.

For any transition $t=(M,M')$, let $\tilde{M}$ denote the matching of smaller size in $\{M,M'\}$. Since we have
\begin{align*}
    \pi(M)P(M,M') = \frac{1}{|E|}\cdot\frac{\lambda^2}{1+\lambda^2}\cdot \lambda^{2|\tilde{M}|} \Haf(\tilde{M}),
\end{align*}
we can rewrite \eq{congestion-matching} as follows:
\begin{align}
    \varrho := & \max_{t=(M,M')}\bigg\{\frac{1}{\pi(M)P(M,M')} \sum_{(I,F,i)\in cp(t)} p^{(i)}(I,F)\cdot \pi(I)\pi(F) |\gamma_{IF}|\bigg\}\notag \\
     =& \max_{t=(M,M')}\bigg\{ |E|\frac{1+\lambda^2}{{\lambda}^2}\cdot\frac{\sum_{(I,F,i)\in cp(t)} p^{(i)}(I,F)\cdot \lambda^{2|I|}\Haf(I)\lambda^{2|F|}\Haf(F) |\gamma_{IF}|}{\lambda^{2|\tilde{M}|}\Haf(\tilde{M})\cdot \sum_{X\text{ is a matching}} \lambda^{2|X|}\Haf(X)} \bigg\}.
\end{align}
For any bipartite graph $G$, let $G'$ be the corresponding complete bipartite graph with the same vertex set as $G$.
Let $\varrho_t'$ denote the congestion of transition $t=(M,M')$ in $G'$, $E'$ denote the edge set of $G'$, $P'(M,M')$ denote the corresponding transition probability of double-loop Glauber for $G'$, and $\Haf'(M)$ denote the corresponding hafnain of the subgraph induced by matching $M$ in $G'$, which is equal to $|M|!$.
We have already established an estimate for $\varrho_t'$ in \append{complete-bipartite}, and now we can use this estimate to bound $\varrho_t$ in $G$ by estimate $\Haf(M)$ via $\Haf'(M)$ for any matching $M$.

Note that for any two matchings $I$ and $F$, the canonical path from $I$ to $F$ remains identical in both $G$ and $G'$. Furthermore, for any matching $M$ of size $n'\geq \xi$, let $V'$ denote the vertex set of $M$. It is straightforward that the minimum degree $d'$ of the subgraph induced by $V'$ satisfies $d'\geq n' - \xi$. As a result, by~\cite{hall1948distinct} we can bound the number of perfect matching in this subgraph:

\begin{lemma}[\cite{hall1948distinct}]
    \label{lem:hall}
    For any balanced bipartite graph $G=(V_1,V_2,E)$ with $|V_1| = |V_2| = n$, if the minimum degree of $G$ is at least $d$, and there exists a perfect matching, then the number of perfect matchings in $G$ is at least $d!$.
\end{lemma}
Thus the number of perfect matching in this subgraph is not less than $(n'-\xi)!$, which means
\begin{align*}
    1\geq \frac{\Haf(M)}{\Haf'(M)}\geq \frac{(n'-\xi)!}{n'!}\geq \frac{1}{n'^\xi}\geq \frac{1}{n^\xi}.
\end{align*}

Therefore, we have
\begin{align*}
    \varrho  =& \max_{t=(M,M')}\bigg\{\frac{\sum_{(I,F,i)\in cp(t)} p^{(i)}(I,F)\cdot \lambda^{2|I|}\Haf(I)\lambda^{2|F|}\Haf(F) |\gamma_{IF}|}{\lambda^{2|\tilde{M}|}\Haf(\tilde{M})\cdot \sum_{X\text{ is a matching}}\lambda^{2|X|} \Haf(X)} \cdot |E|\frac{1+\lambda^2}{{\lambda}^2}\bigg\}\\
    \leq &\max_{t=(M,M')}\bigg\{\frac{ \sum_{(I,F,i)\in cp(t)} p^{(i)}(I,F)\cdot \lambda^{2|I|}\Haf'(I)\lambda^{2|F|}\Haf'(F) |\gamma_{IF}|}{\lambda^{2|\tilde{M}|}\Haf'(\tilde{M})n^{-\xi}\cdot \sum_{X\text{ is a matching}} \lambda^{2|X|}\Haf'(X)n^{-\xi}}\cdot |E'|\frac{1+\lambda^2}{{\lambda}^2}\bigg\}\\
    \leq & n^{2\xi} \varrho'.
\end{align*}

\begin{proof}[Proof of \thm{bipartite-graph}]
    By the analysis of \lem{poly-mix}, we have the congestion $\varrho'$ of double-loop Glauber on complete bipartite graph $G_{m,n}$ is bounded by $\varrho' = 8 mn^4\cdot \frac{(\lambda^2+1)(8\lambda^2-1)}{4\lambda^2 - 1}$. 
    Then we have the congestion $\varrho$ of double-loop Glauber on bipartite graph $G$ is bounded by $\varrho \leq n^{2\xi} \cdot \varrho' = 8 mn^{4+2\xi}\cdot \frac{(\lambda^2+1)(8\lambda^2-1)}{4\lambda^2 - 1}$.
    Thus again by \thm{canonical-mixing-multiple}, the mixing time of double-loop Glauber on complete bipartite graph $G_{m,n}$ is less than $ 16 mn^{4+2\xi}\cdot \frac{(\lambda^2+1)(8\lambda^2-1)}{4\lambda^2 - 1}\cdot \left(\ln{\epsilon^{-1}}+ 2n \ln |{\lambda}| + 2m\ln{m}\right)$.
\end{proof}

Furthermore, we complete the proof of \thm{main-results-bigraph} by extending the analysis of \thm{poly-mix} to the case of dense bipartite graphs.
\begin{proof}[Proof of \thm{main-results-bigraph}]
Take 
$$\eta_{\frac{\eps}{2}} =\frac{\epsilon}{2}\left(16 mn^{4+2\xi}\frac{(\lambda^2+1)(8\lambda^2-1)}{4\lambda^2 - 1}\left(\ln{{\epsilon}^{-1}}+ 2 n \ln |{\lambda}| + 2m\ln{m}\right)\right)^{-1}$$ 
in \lem{bigraph-uniform}. Then the failure probability of each inner layer sampling step can be bounded within $\eta_{\frac{\eps}{2}}$.
Again by \lem{poly-mix}, after $$16 mn^{4+2\xi}\frac{(\lambda^2+1)(8\lambda^2-1)}{4\lambda^2 - 1}\left(\ln{{\epsilon}^{-1}}+ 2 n \ln |{\lambda}| + 2m\ln{m}\right)$$ iterations, the total variance can be bounded by $\epsilon$. Therefore, we give a polynomial-time upper bound $\tilde{O}{(m^2n^{(15+2\xi)}(\log\eps^{-1})^2)}$ for the mixing time of double-loop Glauber on the given dense bipartite graph.
\end{proof}



