\subsection{Complete Graph $G_{2n}$}
\label{append:complete-non-bipartite}
In this section we turn our analysis to complete graph with $2n$ vertices, where the fundamental approach remains consistent with our complete bipartite graph methodology. 

We can again employ the same multiple canonical path scheme used for complete bipartite graphs. This approach still retains two key properties for complete graph:
\begin{itemize}
    \item All paths from $I$ to $F$ in this scheme only traverse matchings whose sizes lie within $\min\{|I|,|F|\} -1,\leq \max\{|I|,|F|\} + 1$ exactly as in the complete bipartite case; and the length of each path is bounded by $2n$.
    \item For complete graph $G_{2n}$, symmetry condition stated in \prop{congestion-symmetry-bipartite} still holds. We restate it here for clarity:
\end{itemize}
\begin{proposition}\label{prop:congestion-symmetry-non-bipartite}
    For complete graphs, under the aforementioned multiple canonical paths construction in \append{complete-bipartite}, the congestion of each transition in $T^+(k)$ (or $T^-(k)$) is identical.
\end{proposition}

Now we estimate the congestion of one transition $t$ in complete graph $G_{2n}$. First, we calculate $\pi(M)$ for each matching. Since any matching $M$ expands a complete subgraph of size $2|M|$, we have $\Haf(M) = (2|M|-1)!!$, and thus $\pi(M)\propto \lambda^{2|M|} (2|M|-1)!!$.
Then for edge sets of any two matchings $M$ and $M \cup\{e\}$, we have
\begin{align*}
    \Pr[M\to M\cup \{e\}] &=  \frac{1}{n(2n-1)}\cdot \frac{\lambda^2}{1+\lambda^2},\\
    \Pr[M \cup \{e\}\to M] &= \frac{1}{n(2n-1)}\cdot \frac{\Haf(G_M)}{\Haf(G_{M\cup\{e\}})}\cdot \frac{1}{1+\lambda^2} \geq \frac{1}{n(2n-1)}\cdot \frac{1}{2|M|+1}\cdot \frac{1}{1+\lambda^2}.
\end{align*}

Then we recalculate parameter $N_p$ and $N_{p,q}$ of complete graph $G_{2n}$:
\begin{align*}
    N_p =& \binom{2n}{2p}\cdot (2p-1)!! =\binom{2n}{2p} \cdot \frac{(2p)!}{2^p p!}=\frac{(2n)!}{p!(2n-2p)!\cdot2^p}
    \\ N_{p,q} =& \begin{cases}
    N_p\cdot \binom{2n-2p}{2} &\text{ if } q = p + 1;\\
    N_p\cdot p &\text{ if } q = p - 1.
\end{cases}
\end{align*}
Now consider $t\in T^+(k)$. Suppose $t=(M,M')$ with $|M| = k$ and $|M'|=k+1$, we have 
\begin{align*}
    \quad N_{k,k+1}\cdot \varrho_t 
   \leq& 2\cdot  \frac{1}{\pi(M)P(M,M')} \sum_{I:|I|\leq k+1} \sum_{F:|F|\geq k-1}\pi(I)\pi(F) |\gamma_{IF}|^2 \\
    \leq& 2\cdot \frac{n(2n-1)(1+\lambda^2)}{\lambda^2} \cdot (2n)^2\cdot N_{k,k+1} \cdot \frac{1}{N_{k,k+1}} \cdot \frac{\sum_{l=1}^{k+1} N_l\cdot \lambda^{2l} l! \cdot \sum_{l=k-1}^n N_l\cdot \lambda^{2l} l!}{\lambda^{2k}k!\cdot \sum_{l=1}^n N_l\cdot \lambda^{2l} l!}.
\end{align*}
Similarly,
notice that $\frac{N_{l+1}\cdot \lambda^{2(l+1)}(l+1)!}{N_l\cdot \lambda^{2l}l!} = \frac{(2n-2l)(2n-2l-1)}{2(l+1)}\cdot \lambda^2\cdot (l+1)\geq 6\lambda^2$ for $l<n-1$, when $\lambda^2>\frac{1}{6}$, we have
\begin{align*}
    \frac{\sum_{l=1}^{k+1} N_l\cdot \lambda^{2l}l!}{N_{k,k+1} \lambda^{2k}k!} 
    =&\frac{2}{(2n-2k)(2n-2k-1)} \cdot \frac{\sum_{l=1}^{k+1} N_l \lambda^{2l}l!}{N_{k+1}\cdot \lambda^{2(k+1)}(k+1)!}\cdot \frac{N_{k+1}\lambda^2(k+1)}{N_k}\\
    \leq& \frac{2}{(2n-2k)(2n-2k-1)} \cdot \left(\frac{6\lambda^2}{6\lambda^2-1}+1\right)\cdot 
    \frac{1}{2}\lambda^2 (2n-2k)(2n-2k-1) \\=&\lambda^2\left(\frac{6\lambda^2}{6\lambda^2-1}+1\right).
\end{align*}
Then consider $t\in T^-(k)$. Suppose $t=(M,M')$ with $|M| = k$ and $|M'|=k-1$, through similar analysis we have
\begin{align*}
 N_{k,k-1}\cdot \varrho_t 
 \leq &2\cdot  \frac{1}{\pi(M)P(M,M')} \sum_{I:|I|\leq k} \sum_{F:|F|\geq k-1}\pi(I)\pi(F) |\gamma_{IF}|^2 \\
    \leq &2\cdot n(2n-1)(2n+1)(1+\lambda^2) \cdot (2n)^2\cdot N_{k,k-1} \cdot \frac{1}{N_{k,k-1}} \cdot\frac{\sum_{l=1}^{k} N_l\cdot \lambda^{2l}l! \cdot \sum_{l=k-1}^n N_l\cdot \lambda^{2l}l!}{\lambda^{2k}k!\cdot \sum_{l=1}^n N_l\cdot \lambda^{2l}l!}.
\end{align*}
Similarly, when $\lambda^2>\frac{1}{6}$,
\begin{align*}
    \frac{\sum_{l=1}^{k} N_l\cdot \lambda^{2l}l!}{N_{k,k-1} \lambda^{2k}k!}
    =&\frac{1}{k} \cdot \frac{\sum_{l=1}^{k} N_l\cdot \lambda^{2l}l!}{N_{k}\cdot \lambda^{2k}k!}
    \leq \frac{1}{k}\cdot \left(\frac{6\lambda62}{6\lambda^2-1}+1\right)\leq \frac{6\lambda^2}{6\lambda^2-1}+1.
\end{align*}

Considering these two cases we have 
\begin{align*}
    \varrho_t&\leq \max\left\{2\cdot \frac{n(2n-1)(1+\lambda^2)}{\lambda^2} \cdot (2n)^2\cdot\lambda^2\left(\frac{6\lambda^2}{6\lambda^2-1}+1\right),2\cdot n(2n-1)(2n+1)(1+\lambda^2) \cdot (2n)^2\cdot\left(\frac{6\lambda^2}{6\lambda^2-1}+1\right)\right\}\\
    &\leq 32 n^5\cdot \frac{(\lambda^2+1)(12\lambda^2-1)}{6\lambda^2 - 1}.
\end{align*}

Let $\bar{\lambda}=\max\{1/\lambda,\lambda\}$, then we have the crude bound $\ln\pi(M)^{-1} \leq \ln{\left({\bar{\lambda}}^n\cdot (2n-1)!!\cdot(2n+1)^{2n} \right)}\leq n \ln |{\lambda}| + 3n\ln{(2n+1)}$, which holds uniformly over all matchings of $G$.

By \thm{canonical-mixing-multiple}, we establish a polynomial mixing time of double-loop Glauber on complete graphs:
\begin{lemma}\label{lem:poly-mix-non-bipartite}
     The mixing time of double-loop Glauber on complete graph $G_{2n}$ is less than $r_\epsilon = 64 n^5\cdot \frac{(\lambda^2+1)(12\lambda^2-1)}{6\lambda^2 - 1}\cdot \left(\ln{\epsilon^{-1}}+ n \ln |{\lambda}| + 3n\ln{(2n+1)}\right)$.
\end{lemma}


Finally, we incorporate the error terms from the uniform sampling of all matchings guaranteed by \lem{non-bigraph-uniform} into our analysis. Since the maximum matching size in $G_{2n}$ is at most $n$, each inner layer sampling step is performed on a complete graph with at most $2n$ vertices.

Take 
$$\eta_{\frac{\eps}{2}} =\frac{\eps}{2}/r_{\frac{\eps}{2}} = \frac{\epsilon}{2}\left(64 n^5\cdot \frac{(\lambda^2+1)(12\lambda^2-1)}{6\lambda^2 - 1}\cdot \left(\ln{\epsilon^{-1}}+ n \ln |{\lambda}| + 3n\ln{(2n+1)}\right)\right)^{-1}$$ 
in \lem{non-bigraph-uniform}. Then the failure probability of the inner layer sampling in each iteration can be bounded within $\eta_{\frac{\eps}{2}}$.
Again by \lem{poly-mix-non-bipartite}, after $r_{\frac{\eps}{2}}$ iterations, the total variance can be bounded by $\frac{\epsilon}{2} + \eta_{\frac{\eps}{2}} \cdot r_{\frac{\eps}{2}}=\epsilon$. Therefore, we give a polynomial-time upper bound for the mixing time of the double-loop Glauber dynamics on the complete graph $G_{2n}$:

\begin{theorem}\label{thm:poly-mix-non-bipartite}
    Given a graph $G_{2n}$, then for $\lambda>\frac{1}{\sqrt{6}}$, given error $\eps$, we can achieve a sampling using double-loop Glauber in time $\tilde{O}( n^{20}(\log \epsilon^{-1})^3)$ such that the total variation distance between the sampling distribution and the ideal stationary distribution is at most $\epsilon$. The iterations of double-loop Glauber is $r_{\frac{\eps}{2}}= \tilde{O}(n^6 \log \eps^{-1})$, and each inner layer sampling procedure needs $\tilde{O}(n^{14}(\log{\eps^{-1}})^2)$ time.
\end{theorem}

\subsection{Dense Non-bipartite Graphs}
\label{append:dense-non-bipartite}
In this subsection, we explore extending the results from \append{complete-non-bipartite} to non-complete graphs, providing proofs of \thm{non-bipartite-graph} and \thm{main-results-non-bigraph}. 
Similar as \append{dense-bipartite}, we discuss some dense graphs $G$: there exists a constant $\xi$, such that each vertex is non-adjacent to at most $\xi$ vertices.

For any graph $G$, let $G'$ be the corresponding complete bipartite graph with the same vertex set as $G$.
Let $\varrho_t'$ denote the congestion of transition $t=(M,M')$ in $G'$, $P(M,M')$ denote the corresponding transition probability of double-loop Glauber for $G'$, and $\Haf'(M)$ denote the corresponding Hafnian of the subgraph induced by matching $M$ in $G'$, which is equal to $(2|M|-1)!!$.
Then we use the estimate of $\varrho_t'$ given in \append{complete-non-bipartite} to bound $\varrho_t$ in the original graph $G$.

Note that for any two matchings $I$ and $F$, the canonical path from $I$ to $F$ remains identical in both $G$ and $G'$. 

In what follows, we employ graph-theoretic techniques to bound the number of perfect matchings in subgraphs induced by matchings. 
\begin{proposition}
    Let $G_E$ denote the induced graph of a matching $M$ of size $n'\geq \xi$, then the number of perfect matchings of is at least 
    \begin{align*}
        \frac{(2n'-1-\xi)!!}{(\xi+1)!!}.
     \end{align*} 
\end{proposition}
\begin{proof}
    Our analysis relies primarily on the Ore's Theorem~\cite{ore1960note}: 
\begin{lemma}
    Let $G=(V,E)$ be a simple graph. If for every pair of distinct non-adjacent vertices $u$ and $v$, the sum of their degrees satisfies $\deg(u) + \deg(v) \geq |V|$, then $G$ contains a Hamilton cycle.
\end{lemma}
    Ore's theorem shows that if the minimum degree of a graph with even vertices is at least $|V|/2$, then the graph contains a Hamilton cycle, which is also a perfect matching.

    Note that the minimum degree $d'$ of the subgraph $G_E$ satisfies $d'\geq 2n' - 1 - \xi$. We start from a vertex $u_1$, which has $2n' - 1 - \xi$ possible pairing choices with other vertices. For the choice of pair $(u_1,v_1)$, we delete the edge $(u_1,v_1)$ and all edges incident to $u_1$ and $v_1$. The remaining graph has $2n' - 2 - \xi$ vertices, and the minimum degree of this graph is at least $2n' - 3 - \xi$. We can repeat this process and find another pair $(u_2,v_2)$, and delete the edge $(u_2,v_2)$ and all edges incident to $u_2$ and $v_2$. This procedure can be repeated until we find $n'-\xi - 1$ pairs of vertices, and then the remaining graph has $2\xi+1$ vertices, with the minimum degree of the current graph being at least $2n' - 1 - \xi - 2(n'-\xi - 1) = \xi + 1$. Thus again by Ore's theorem, the remaining graph contains a Hamilton cycle. Finally, we choose this Hamilton cycle and find a perfect matching of $G_E$. The number of choices is
    \begin{align*}
        (2n'-\xi-1)\cdot(2n'-\xi-3)\cdots (\xi+3) = \frac{(2n'-1-\xi)!!}{(\xi+1)!!}.
    \end{align*}
\end{proof}

Now, we can bound $\Haf(M)$ by $\Haf'(M)$ for any matching $M$:
$$1\geq \frac{\Haf(M)}{\Haf'(M)}\geq \frac{{(2n'-1-\xi)!!}/{(\xi+1)!!}}{(2n'-1)!!}\geq \left((2n')^{\frac{\xi+1}{2}}\cdot (\xi+1)!!\right)^{-1}
\geq \frac{1}{(2n)^\xi}.$$

Therefore, we have
\begin{align*}
    \varrho  =& \max_{t=(M,M')}\bigg\{\frac{\sum_{(I,F,i)\in cp(t)} p^{(i)}(I,F)\cdot \lambda^{2|I|}\Haf(I)\lambda^{2|F|}\Haf(F) |\gamma_{IF}|}{\lambda^{2|\tilde{M}|}\Haf(\tilde{M})\cdot \sum_{X\text{ is a matching}}\lambda^{2|X|} \Haf(X)} \cdot |E|\frac{1+\lambda^2}{{\lambda}^2}\bigg\}\\
    \leq &\max_{t=(M,M')}\bigg\{\frac{\sum_{(I,F,i)\in cp(t)} p^{(i)}(I,F)\cdot \lambda^{2|I|}\Haf'(I)\lambda^{2|F|}\Haf'(F) |\gamma_{IF}|}{\lambda^{2|\tilde{M}|}\Haf'(\tilde{M})(2n)^{-\xi}\cdot \sum_{X\text{ is a matching}}\lambda^{2|X|} \Haf'(X)(2n)^{-\xi}} \cdot |E'|\frac{1+\lambda^2}{{\lambda}^2}\bigg\}\\
    \leq & {(2n)}^{2\xi} \varrho'.
\end{align*}

\begin{proof}[Proof of \thm{non-bipartite-graph}]
    By the analysis of \lem{poly-mix-non-bipartite}, we have the congestion $\varrho'$ of double-loop Glauber on complete graph $G_{2n}$ is bounded by $\varrho' = 32 n^5\cdot \frac{(\lambda^2+1)(12\lambda^2-1)}{6\lambda^2 - 1}$. 
    Then we have the congestion $\varrho$ of double-loop Glauber on bipartite graph $G$ is bounded by $\varrho \leq {2n}^{2\xi} \cdot \varrho' = 32\cdot 2^\xi \cdot n^{5+2\xi}\cdot \frac{(\lambda^2+1)(12\lambda^2-1)}{6\lambda^2 - 1}$.
    Thus by \thm{canonical-mixing-multiple}, the mixing time of double-loop Glauber on complete graph $G_{2n}$ is less than $ 64 \cdot 2^\xi\cdot n^{5+2\xi}\cdot \frac{(\lambda^2+1)(12\lambda^2-1)}{6\lambda^2 - 1}\cdot \left(\ln{\epsilon^{-1}}+ n \ln |{\lambda}| + 3n\ln{(2n+1)}\right)$.
\end{proof}

Finally, we complete the proof of \thm{main-results-non-bigraph} by extending the analysis of \thm{poly-mix-non-bipartite} to the case of dense graphs.
\begin{proof}[Proof of \thm{main-results-non-bigraph}]
Take $$\eta_{\frac{\eps}{2}} = \frac{\epsilon}{2}\left(64 \cdot 2^\xi\cdot n^{5+2\xi}\cdot \frac{(\lambda^2+1)(12\lambda^2-1)}{6\lambda^2 - 1}\cdot \left(\ln{\epsilon^{-1}}+ n \ln |{\lambda}| + 3n\ln{(2n+1)}\right)\right)^{-1}$$ in \lem{bigraph-uniform}. Then the failure probability of each inner layer sampling step can be bounded within $\eta_{\frac{\eps}{2}}$, and need $\tilde{O}(n^{14}(\log{\eps^{-1}})^2)$ time.
Again by \lem{poly-mix-non-bipartite}, after $$ 64 \cdot 2^\xi\cdot n^{5+2\xi}\cdot \frac{(\lambda^2+1)(12\lambda^2-1)}{6\lambda^2 - 1}\cdot \left(\ln{\epsilon^{-1}}+ n \ln |{\lambda}| + 3n\ln{(2n+1)}\right)$$ iterations, the total variance can be bounded by $\epsilon$. Therefore, we give a polynomial-time upper bound $\tilde{O}{(n^{(20+2\xi)}(\log\eps^{-1})^3)}$ for the mixing time of the double-loop Glauber dynamics on the given dense graph.
\end{proof}


