\section{Double-loop Glauber Dynamics on Weighted Graphs}\label{append:double-loop-weighted}
The original double-loop Glauber dynamics is designed for unweighted graphs, and this section extends the double-loop Glauber dynamics to weighted graphs.

First, we provide the formal definition of Hafnian on weighted graphs. 
\begin{definition}
    For a graph $G=(V,E)$, with $V=\{u_1, u_2,\ldots, u_{2n}\}$ and a weight $w_e$ assigned to each edge $e$, let matrix $A$ denote the weighted adjacency matrix of $G$ with
\begin{align*}
    A_{i,j} = \begin{cases} 
    w_{(i,j)} & \text{ if } (u_i,u_j)\in E;\\
    0 & \text{ otherwise.}
    \end{cases}
\end{align*}
Then the Hafnian of $G$ is defined as the Hafnian of $A$, as shown in \eq{Haf}:
    \begin{align*}
    \Haf(G) :=\operatorname{Haf}(A)=\frac{1}{2^n n!} \sum_{\sigma \in \mathcal{S}_{2 n}} \prod_{i=1}^n A_{\sigma(2 i-1), \sigma(2 i)}.
    \end{align*}
The above definition of Hafnian on weighted graphs can be rewritten as
\begin{align}
    \Haf(G) = \sum_{M\text{ is a perfect matching of } G} \prod_{e\in M} w_e.
\end{align}
\end{definition}

For convenience, let $w(M) = \prod_{e\in M} w_e$ denote the weight of matching $M$.
Same as unweighted graphs, the Hafnian of a vertex set in $G$ is defined as the Hafnian of the subgraph induced by the vertex set. Our goal is to sample a vertex set $S$ from $G$ such that
\begin{align*}
    \Pr[S] \propto \lambda^{|S|}\Haf^2(S).
\end{align*}

Without loss of generality, we can assume that $w_e\geq 1$ for $\forall e \in E$. Otherwise, suppose $w_* = \min_e\{w_e\}\leq 1$, then we can define a new weight $w'_e = w_e/w_*$ for all edges $e\in E$, and then take $\lambda_*=\lambda\cdot{w_*}$. The Hafnian of a vertex set with new weights is $\Haf_*(S) = w_*^{-\frac{|S|}{2}} \cdot \Haf(G')$, which means $\lambda^{|S|}\Haf^2(S) = \lambda_*^{|S|}\Haf_*^2(S)$.

Our double-loop Glauber dynamics on weighted graphs is similar to the unweighted case, but with a few modifications. In particular, the weight of a matching is defined as the product of the weights of its edges, and the probability of sampling $M$ is proportional to the weight of $M$, denoted as $w(M)$. The algorithm is formally presented in \algo{double-loop-weighted}. 

\begin{algorithm}[h]
    \SetAlgoLined 
	\KwIn{A graph $G=(V,E)$, with a weight $w_e\geq 1$ assigned to each edge $e$.}
	\KwOut{A sample of vertex set $S$ of $G$ such that
        $\Pr[S] \propto \lambda^{|S|}\Haf^2(S)$. }

        \vspace{1em}
        Initialize $X_0$ as an arbitrary matching in $G$;\

        Initialize $t\leftarrow 0$, set the number of iterations $T$;\

	\lWhile{$t < T$}\
    {
        \Indp Choose a uniformly random edge $e$ from $E$;\

        \lIf{$e$ and $X_t$ form a new matching}\
        {\Indp Set $X_{t+1} = X_t\cup\{e\}$ with probability $\frac{\lambda^2}{1+\lambda^2}$ and otherwise set $X_{t+1} = X_t$;\;}

        \lElse 
        {\lIf{$e$ is in $X_t$}\
         {\Indp Sample a perfect matching $E_i$ in the subgraph induced by $X_t$ with probability $\Pr[E_i]\propto w(E_i)$. If $e\not\in E_i$, set $X_{t+1} = X_t$. If $e\in E_i$, set $X_{t+1} = X_t \backslash \{e\}$ with probability $\frac{1}{1+\lambda^2}\cdot \frac{1}{w_e^2}$ and otherwise set $X_{t+1} = X_t$;\;\label{lin:weighted-8}
         \Indm\lElse\
          {\quad \quad Set $X_{t+1} =X_t$;}}}
        $t \leftarrow t+1$;\;
        \caption{Double-loop Glauber Dynamics for Weighted Graphs}
    \label{algo:double-loop-weighted}
 }
 Output the vertex set in matching $X_T$;\;
\end{algorithm}

The main difference between \algo{double-loop-weighted} and \algo{double-loop} is that we need to sample a perfect matching in the subgraph induced by $X_t$ with probability $\Pr[E_i]\propto w(E_i)$, and the transition probability of sampling $X_{t+1}$ from $X_t$ is proportional to $\frac{1}{w_e^2}$. 

\begin{lemma}
    The stationary distribution of the double-loop Glauber dynamics on weighted graphs is given by
    \begin{align*}
        \Pr[S] \propto \lambda^{|S|}\Haf^2(S).
    \end{align*}
\end{lemma}
\begin{proof}
    For two matchings $X$ and $X\cup\{e\}$, we can calculate the transition probability as follows:
\begin{align*}
    \Pr[X\to X\cup\{e\}] = \frac{\lambda^2}{1+\lambda^2} \cdot \frac{1}{|E|}.
\end{align*}
If $X_t = X\cup\{e\}$, the probability $\Pr[e\in E_i]$ in \lin{weighted-8} in \algo{double-loop-weighted} can be rewritten as
\begin{align*}
    \Pr[e\in E_i] = \frac{\sum_{E'\text{ is a perfect matching of }G_{X} }w(E')\cdot w_e}{\sum_{E'\text{ is a perfect matching of }G_{X\cup\{e\}}} w(E')} = w_e\cdot \frac{\Haf(X)}{\Haf(X\cup\{e\})}.
\end{align*}
Thus we have
\begin{align}
    \Pr[X\cup\{e\} \to X] = \frac{1}{|E|} \cdot \frac{1}{w^2_e}\frac{1}{1+\lambda^2}\cdot w_e\frac{\Haf(X)}{\Haf(X\cup\{e\})} ,
\end{align}
where the third term comes from the probability of edge $e$ being in $E_i$. As a result, we can directly verify that the stationary distribution of matchings on weighted graphs is given by
\begin{align*}
    \pi(X)\propto \lambda^{2|E|}\cdot \Haf(G_X) \cdot w(X),
\end{align*}
and the distribution on vertex sets is 
\begin{align*}
    \pi(S)\propto \lambda^{|S|}\cdot \Haf(S)\cdot \sum_{\text{$X$ is a perfect matching of $G_S$}} w(X) = \lambda^{|S|}\cdot \Haf^2(S).
\end{align*}
\end{proof}

Finally, we give a Markov chain to satisfy the desired sampling of perfect matchings in \lin{weighted-8} in \algo{double-loop-weighted}. The method is based on the Markov chain for uniform sampling of perfect matchings by~\cite{jerrum1989approximating}, which is discussed in \append{uniform-sampling-pm}. The modified Markov chain is given as follows:

Let $\mathcal{N}$ denote the set of all perfect matchings and near-perfect matchings of $G$.
In any state $M\in\mathcal{N}$, choose an edge $e=(u,v)\in E$ uniformly at random and then
\begin{itemize}
    \item If $M\in M_n(G)$ and $e\in M$, then move to state $M' = M \backslash \{e\}$ with probability $\frac{1}{w_e}$;
    \item If $M\in M_{n-1}(G)$ and $u,v$ are unmatched in $M$, then move to state $M' = M\cup \{e\}$ with probability $1$;
    \item If $M\in M_{n-1}(G)$, $u$ is matched to $z$ in $M$ and $v$ is unmatched in $M$, then move to state $M' = M \cup \{e\} \backslash \{(z,u)\}$ with probability $\min\{1,\frac{w_e}{w_{(z,u)}}\}$; symmetrically, if $v$ is matched to $z$ and $u$ is unmatched, then move to state $M' = M \cup \{e\} \backslash \{(z,v)\}$ with probability $\min\{1,\frac{w_e}{w_{(z,v)}}\}$;
    \item In all other cases, do nothing.
\end{itemize}
\begin{lemma}
    The stationary distribution of the above Markov chain is given by
    \begin{align*}
        \Pr[M]\propto w(M).
    \end{align*}
\end{lemma}
\begin{proof}
    For two near-perfect matchings $M$ and $M'$ such that $M'= M\cup \{(u,v)\} \backslash \{(z,u)\}$, the transition probability is given by
\begin{align*}
    \Pr[M\to M'] = \frac{1}{|E|}\cdot \min\left\{1,\frac{w_{(u,v)}}{w_{(z,u)}}\right\};\quad \Pr[M'\to M] = \frac{1}{|E|} \cdot \min\left\{1,\frac{w_{(z,u)}}{w_{(u,v)}}\right\}.
\end{align*}
For a perfect matching $M$ and a near-perfect matching $M'$ such that $M'= M\backslash \{(u,v)\}$, the transition probability is given by
\begin{align*}
    \Pr[M\to M'] = \frac{1}{|E|};\quad \Pr[M'\to M] = \frac{1}{|E|}\cdot \frac{1}{w_{(u,v)}}.
\end{align*}
Therefore, the stationary distribution of the Markov chain is given by $\pi(M) \propto \prod_{e\in M}{w_e} = w(M).$
\end{proof}


