\section{Algorithms with Pseudocodes}\label{append:algorithm}
This section introduces the classical algorithms and their variants enhanced by Glauber dynamics we used for numerical experiments in \sec{experiments}. During the iterations of the Glauber dynamics, we create a list. As long as the size of current edge set equals $k/2$, we append the edge set to the list. Each time we generate a vertex set of size $k$ according to the Glauber dynamics, we choose the last element in the list as the selected matching. 

Similarly, each time we generate a vertex set of size $k$ according to the quantum inspired classical algorithm by~\citet{Oh_2024}, we sample $k/2$ columns of $V$ with replacement and repeat until the row indexes of the nonzero elements form a collision-free set of size $k$.

We first present the pseudocode for the original random search (RS) in \algo{random-search}. In each iteration, we randomly pick $k$ vertices from all $n$ vertices of the graph. If the objective function (Hafnian or density) corresponding to the subgraph is larger than the former recorded best value, we substitute the recorded best with the new submatrix.

\vspace{3mm}
\begin{algorithm}[H]
	\KwIn{

    $\boldsymbol{A}$ : Input matrix of dimension $n\times n$;

$k$ : Dimension of submatrix;

$f$ : Objective function;

$N:$ Number of iterations;}
	\KwOut{The submatrix $\boldsymbol{A}_B$ with the largest $f(\boldsymbol{A}_B)$; the function value $f(\boldsymbol{A}_B)$}
\vspace{1em}
        Initialize $i=0$, $Best=0$;

        Initialize $\boldsymbol{A}_B=None$;

	\lWhile{$i < N$}\
    {
        \Indp Choose $\boldsymbol{A}_i$, a $k$-dimensional submatrix of $\boldsymbol{A}$ uniformly at random; 

        Calculate $f(\boldsymbol{A}_i)$;

        \lIf{$f(\boldsymbol{A}_i)>Best$}\
        {\quad \quad $Best=f(\boldsymbol{A}_i)$;}

        {\Indm \quad \quad \quad ~$\boldsymbol{A}_B=\boldsymbol{A}_i$;}
 }

 Output $\boldsymbol{A}_B$ and $f(\boldsymbol{A}_B)$
\caption{Random Search}
 \label{algo:random-search}
\end{algorithm}

Next, we substitute the uniform random update in each iteration with \algo{glauber}, \algo{double-loop}, \algo{jerrum-glauber}, and the quantum-inspired classical algorithm by~\citet{Oh_2024} to enhance the above original random search. The pseudocode is presented in \algo{random-search-enhanced}. 

\begin{algorithm}[h]
	\KwIn{

    $\boldsymbol{A}$ : Input matrix of dimension $n\times n$;

$k$ : Dimension of submatrix ;

$f$ : Objective function ;

$N:$ Number of iterations ;}
	\KwOut{The submatrix $\boldsymbol{A}_B$ with the largest $f(\boldsymbol{A}_B)$; the function value $f(\boldsymbol{A}_B)$}
\vspace{1em}
        Initialize $i=0$, $Best=0$;

        Initialize $\boldsymbol{A}_B=None$;

	\lWhile{$i < N$}\
    {
        \Indp Choose $\boldsymbol{A}_i$, a $k$-dimensional submatrix of $\boldsymbol{A}$ according to \algo{glauber} or \algo{double-loop} or \algo{jerrum-glauber}; 

        Calculate $f(\boldsymbol{A}_i)$;

        \lIf{$f(\boldsymbol{A}_i)>Best$}\
        {\quad \quad $Best=f(\boldsymbol{A}_i)$;}

        {\Indm \quad \quad \quad ~$\boldsymbol{A}_B=\boldsymbol{A}_i$;}
 }

 Output $\boldsymbol{A}_B$ and $f(\boldsymbol{A}_B)$
	\caption{Random Search Enhanced by Glauber Dynamics}
    \label{algo:random-search-enhanced}
\end{algorithm}

Instead of applying i.i.d.~samples in random search, we adopt a neighbor update strategy in simulated annealing (SA). In each iteration, we randomly generate an integer $m\in[0,k-1]$ and randomly choose $m$ of the former vertices to keep unchanged. Then we randomly sample $k-m$ vertices from the remaining $n-m$ vertices to form a new vertex set of size $k$, and update the set with probability assigned by a Metropolis filter. With the annealing parameter $0<\gamma<1$, the temperature approaches exponentially small as iteration increases and the update probability when $f(\boldsymbol{A}_R)<(\boldsymbol{A}_S)$ approaches $0$. For complex search space with large numbers of local optima metaheuristic SA is capable of approximating the global optimum, due to its probabilistic acceptance of worse solutions which enables exploration beyond local minima~\cite{doi:10.1126/science.220.4598.671}. The pseudocode is presented in \algo{simulated-annealing}.

\begin{algorithm}[h]

	\KwIn{

    $\boldsymbol{A}$ : Input matrix of dimension $n\times n$;

$k$ : Dimension of submatrix;

$f$ : Objective function;

$N:$ Number of iterations;

$t:$ Initial temperature;

$\gamma$: Annealing parameter;}
	\KwOut{The submatrix $\boldsymbol{A}_B$ with the largest $f(\boldsymbol{A}_B)$; the function value $f(\boldsymbol{A}_B)$}
\vspace{1em}
        Generate a uniformly random binary vector $S$ of length $n$ with $k$ entries being one;

        Get the $k$-dimensional submatrix $\boldsymbol{A}_S$ according to $S$;

        Initialize $\boldsymbol{A}_B=\boldsymbol{A}_S$ and $Best=f(\boldsymbol{A}_S)$;

        Initialize $i=0$;

	\lWhile{$i < N$}\
    {
        \Indp Randomly generate an integer $m \in[0, k-1]$;

        Randomly choose $m$ nonzero entries of $S$ and keep them unchanged, then resample $k-m$ nonzero entries from the remaining $n-m$ vertices to get $R$; 

        Get $\boldsymbol{A}_{R}$ according to $R$;

        Calculate $f(\boldsymbol{A}_R)$;

        \lIf {$f(\boldsymbol{A}_R)>Best$}\
        \Indp $Best=f(\boldsymbol{A}_R)$;

        $\boldsymbol{A}_B=\boldsymbol{A}_R$;

        \Indm Set $S=R$ with probability $\min\{1,\exp\left[\frac{f\left(\boldsymbol{A}_R\right)-f\left(\boldsymbol{A}_S\right)}{t}\right]\}$

        \Indm \quad ~ $t~*= \gamma$

	\caption{Simulated Annealing}
     \label{algo:simulated-annealing}
 }

 Output $\boldsymbol{A}_B$ and $f(\boldsymbol{A}_B)$
\end{algorithm}

Finally, we substitute the uniformly random update in each iteration with \algo{glauber}, \algo{double-loop}, \algo{jerrum-glauber} and the quantum-inspired classical algorithm by~\citet{Oh_2024} again to enhance the above original simulated annealing. Specifically, we pick the initial $k$ vertices by Glauber dynamics, and in each iteration we remove the intersection of the Glauber dynamics outcomes with the $m$ unchanged vertices. Additionally, we remove a proper number of vertices randomly from the rest of the Glauber dynamics outcomes such that the number of the remaining vertices plus that of unchanged vertices equals $k$. The pseudocode is presented in \algo{simulated-annealing-enhanced}.

\begin{algorithm}[h]

	\KwIn{

    $\boldsymbol{A}$ : Input matrix of dimension $n\times n$;

$k$ : Dimension of submatrix;

$f$ : Objective function;

$N:$ Number of iterations;

$t:$ Initial temperature;

$\gamma:$ Annealing parameter;}
	\KwOut{The submatrix $\boldsymbol{A}_B$ with the largest $f(\boldsymbol{A}_B)$; the function value $f(\boldsymbol{A}_B)$}
\vspace{1em}
        Generate a binary vector $S$ of length $n$ with $k$ entries being one according to \algo{glauber} or \algo{double-loop} or \algo{jerrum-glauber};

        Get a $k$-dimensional submatrix $\boldsymbol{A}_S$ according to $S$;

        Initialize $\boldsymbol{A}_B=\boldsymbol{A}_S$ and $Best=f(\boldsymbol{A}_S)$;

        Initialize $i=0$;


	\lWhile{$i < N$}\
    {
        \Indp Randomly generate an integer $m \in[0, k-1]$;

        Generate $s$ by randomly choosing $m$ nonzero entries of $S$ and set the rest entries as zeroes;

        Get $\boldsymbol{A}_{{R}}$ according to $R$;

        Generate $r$ with $k$ entries are nonzero according to \algo{glauber} or \algo{double-loop} or \algo{jerrum-glauber} and set $m$ entries as zeroes randomly under the condition that there are no overlap between nonzero elements of $s$ and $r$;

        $R=s|r$;

        Calculate $f(\boldsymbol{A}_R)$;

        \lIf {$f(\boldsymbol{A}_R)>Best$}\
        \Indp $Best=f(\boldsymbol{A}_R)$;

        $\boldsymbol{A}_B=\boldsymbol{A}_R$;

        \Indm Set $S=R$ with probability $\min\{1,\exp\left[\frac{f\left(\boldsymbol{A}_R\right)-f\left(\boldsymbol{A}_S\right)}{t}\right]\}$

        \Indm \quad ~ $t~*= \gamma$

 }

 Output $\boldsymbol{A}_B$ and $f(\boldsymbol{A}_B)$

 \caption{Simulated Annealing Enhanced by Glauber Dynamics}
    \label{algo:simulated-annealing-enhanced}
\end{algorithm}
