    \centering
    \includegraphics[width=0.7\linewidth]{figs/app_B_flocking.pdf}
    \caption{\textbf{Flocking tasks illustration.} This figure depicts the Flocking task where agents aim to arrange themselves into a predefined target shape, here a hollow square. The panels show the progression from an initial agent configuration towards achieving the target. }
    \label{fig:app_B_flocking_cute}
