\section{Detailed Group Dynamics Metrics}
\label{app:group_dynamics_metrics}
To quantitatively analyze emergent collective behaviors, we compute metrics based on agent positions $\mathbf{x}_{i,t}$, their primary actions $A_{i,t}$, and messages $M_{i,t}$. These metrics are calculated per round and then typically averaged over the duration of a simulation run for correlation with the final score. The specific variable names used in our analysis scripts correspond to these conceptual definitions.

\paragraph{Communication-based Metrics}
\begin{itemize}
    \item \textbf{Proportion of Question Sentences:} The average per-round proportion of non-empty messages that contain a question mark (\texttt{`?'}).
    \item \textbf{Proportion of Digit Characters:} The average per-round proportion of all characters in non-empty messages that are digits. This may indicate sharing of numerical data like coordinates.
    \item \textbf{Mean Message Length:} The average per-round mean character length of non-empty messages.
    \item \textbf{Standard Deviation of Message Length:} The average per-round standard deviation of character lengths of non-empty messages.
    \item \textbf{Information Homogeneity:} The average per-round pairwise cosine similarity of embeddings of unique non-empty messages. Embeddings are generated using a Sentence-BERT model (e.g., \texttt{all-mpnet-base-v2}). This measures semantic coherence. 
\end{itemize}

\paragraph{Action-based Metrics}
Let $\mathcal{A}_{\text{move}} = \{\texttt{UP}, \texttt{DOWN}, \texttt{LEFT}, \texttt{RIGHT}\}$ be movement actions and $\mathcal{A}_{\text{coord}} = \mathcal{A}_{\text{move}} \cup \{\texttt{STAY}\}$ be coordination-relevant actions.
\begin{itemize}
    \item \textbf{Directional Entropy:} The average per-round Shannon entropy of actions in $\mathcal{A}_{\text{move}}$ taken by agents. Measures the unpredictability or variability of movement directions.
    \begin{equation}
        H_t(\mathcal{A}_{\text{move}}) = -\sum_{a \in \mathcal{A}_{\text{move}}} p_t(a) \log_2 p_t(a)
    \end{equation}
    where $p_t(a)$ is the proportion of agents performing action $a$ in round $t$ from the set $\mathcal{A}_{\text{move}}$.
    \item \textbf{Stillness Proportion:} The average per-round proportion of agents executing the \texttt{STAY} action.
    \item \textbf{Dominant Action Proportion:} The average per-round proportion of agents performing the single most frequent action within the set $\mathcal{A}_{\text{coord}}$. A high value indicates strong action consensus.
    \item \textbf{Polarization Index:} The average per-round magnitude of the mean movement vector. Action vectors $\mathbf{v}(a)$ are assigned (e.g., $\mathbf{v}(\texttt{UP})=(0,-1)$, $\mathbf{v}(\texttt{STAY})=(0,0)$).
    \begin{equation}
        P_t = \left\| \frac{1}{N_t^{\text{coord}}} \sum_{i \text{ s.t. } A_{i,t} \in \mathcal{A}_{\text{coord}}} \mathbf{v}(A_{i,t}) \right\|_2
    \end{equation}
    where $N_t^{\text{coord}}$ is the number of agents performing an action from $\mathcal{A}_{\text{coord}}$ in round $t$. Indicates overall movement alignment.
\end{itemize}

\paragraph{Position and Interaction-based Metrics}
\begin{itemize}
    \item \textbf{Average Moving Distance:} The average per-round cumulative Manhattan distance moved by each agent from its previous position.
    \item \textbf{Exploration Rate:} The average per-round number of unique grid cells occupied by any agent up to that round.
    \item \textbf{Local Structure Preservation Count:} The average per-round count of pairs of agents that were adjacent (Manhattan distance 1) in round $t-1$ and remain adjacent in round $t$.
    \item \textbf{Agent Push Events:} The average per-round count of events where agent A, intending to move into agent B's adjacent cell, successfully does so, and agent B is displaced in the same direction as A's intended movement. This indicates a successful cooperative push.
\end{itemize}






