In other words, the possible neighborhoods for a new vertex added with a buffer are precisely the subsets $S$ of the vertex set $V$ of $G$ such that $S$ is contained in a $(b,1)$-annulus and all points in $V - S$ lie outside of the radius-$1$ circle.
We use a modified radial sweep algorithm to determine all such subsets $S$ of $V$.
This subsection is devoted to proving the following.


\begin{theorem}\label{thm:buffer}
    Let $G$ be a unit disk graph with vertex set $V$, and let $0 < b < 1$.
    The list of possible neighborhoods for a vertex $v$ added to $G$ such that $\|v - w\|_2 > b$ for all $w \in V$ can be obtained in $\mathcal{O}(n \Delta)$ time, where $\Delta$ is the maximum cardinality of a subset of $V$ contained in a radius-$2$ circle.
\end{theorem}


Theorem~\ref{thm:buffer} follows from an analysis of Algorithm~\ref{alg:enumerate_buffer_regions}, 
% as well as Proposition~\ref{prop:vxs_on_boundary} which implies that it suffices to enumerate the subsets $S$ contained in a $(b,1)$-annulus with two vertices on its boundary and none inside the inner circle.
% We describe Algorithm~\ref{alg:enumerate_buffer_regions} 
which we describe in parts throughout this section.
We first find all subsets contained in a $(b,1)$-annulus with two vertices on its boundary and no vertices contained within its inner circle.
To do so, we conduct radial sweeps of annuli around a fixed points on their outer and inner boundaries.


\begin{algorithm}
\caption{Enumerate neighborhoods for a new vertex added to a unit disk graph with no other vertices within distance $b$ ($0 < b < 1$).}
\label{alg:enumerate_buffer_regions}
\begin{algorithmic}[1]
    \Require {Nonempty finite set of points $V \subset \mathbb{R}^2$ and $b \in (0,1)$}
    \Ensure {Subsets of $V$ contained in a $(b,1)$-annulus with no points in inner circle}
    % {sets of points contained in a unit-circle which has no points within distance $b$ of its center}
    \Statex

    \Function{BufferNeighborhoods}{$V,b$}
    \Let{$\mathrm{Nbrhds}$}{$\{\}$}
    \For{$v \in V$}
        \Let{$L_1$}{$\textsc{OuterSweep}(V, v, b)$}
        % \Comment{Determine points in $V$ which are contained in a $(b,1)$-annulus with $v$ on its outer boundary.}
        \For{$S \in \textsc{SetsFromIntervals}(L_1)$}
            \State{add $S$ and $S \cup v$ to $\mathrm{Nbrhds}$}
        \EndFor
        \Let{$L_2$}{$\textsc{InnerSweep}(V,v,b)$}
        \For{$S \in \textsc{SetsFromIntervals}(L_2)$}
            \State{add $S \cup v$ to $\mathrm{Nbrhds}$}
        \EndFor
    \EndFor
    \State \Return{$\mathrm{Nbrhds}$}
    % \Let{$L_1$}{$\cup_{p \in V} \textsc{OuterSweepRegions}(V,p,b)$}
    % \Let{$L_2$}{$\cup_{p \in V} \textsc{InnerSweepRegions}(V,p,b)$}
    % \State \Return {$L_1 \cup L_2$}
    \EndFunction
\end{algorithmic}
\end{algorithm}



% We begin by describing algorithms for sweeping an annulus around a fixed point $v$ on either its inner or outer circle and determine the sets $S$ contained in an annulus with two points from $V$ on its boundary and all other points in $V - S$ outside of the outer circle.


\begin{algorithm}
\caption{List of points and angles at which points enter and exit a $(b,1)$-annulus swept around a fixed point $v$ on its outer boundary}
%{Enumerate subsets of a finite set of points in the plane which are contained in a $(b,1)$-annulus with a fixed point on the boundary of its radius-$1$ circle and no points inside the radius-$b$ circle}
%{Sweep $(b,1)$-annulus around a point on the perimeter of outer circle, record other points as they enter or exit either the inner or outer circle}
\label{alg:outer_sweep}
\begin{algorithmic}[1]
    \Require{Nonempty finite set of points $V \subset \mathbb{R}^2$, $v \in V$, and $b \in (0,1)$}
    \Ensure{Points $w \in V$ and angles $\theta \in (-\pi/2, \pi/2)$ of rotation at which $w$ enters and exits a $(b,1)$-annulus swept counterclockwise around fixed point $v$ on outer boundary
    }
    \Statex

    \Function{OuterSweep}{$V,v,b$}
    \Let{$L$}{$\{ \}$}
    \For{$w \in V - v$ with $\|v - w\|_2 < 2$}
    %\State
    \Comment{$w$ will enter \& exit the sweep}
        \If{$1 - b < \|v - w\|_2 < 1 + b$}
        % \State 
        \Comment{$w$ will enter \& exit both circles}
            \Let{$\theta_{\mathrm{min}}$}{angle $w$ enters outer circle}
            \Let{$\tdis$}{angle $w$ enters inner circle}
            \Let{$\tre$}{angle $w$ exits inner circle}
            \Let{$\tmax$}{angle $w$ exits outer circle}
        \Else
        %\State
        \Comment{$w$ will only enter \& exit the outer circle}
            \Let{$\tmin$}{angle $w$ enters outer circle}
            \Let{$\tdis$, $\tre$}{None}
            \Let{$\tmax$}{angle $w$ exits outer circle}
        \EndIf
      \State{add $(w, \tmin, \tdis, \tre, \tmax)$ to $L$}
    \EndFor

    \State \Return{ $L$ }
    \EndFunction
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\caption{List of points and angles at which they enter and exit a $(b,1)$-annulus swept around a fixed point on its inner boundary}
%{Enumerate subsets of a finite set of points in the plane which are contained in a $(b,1)$-annulus with a fixed point on the boundary of its inner circle}
\label{alg:inner_sweep}
\begin{algorithmic}[1]
    \Require{Nonempty finite set of points $V \subset \mathbb{R}^2$, $v \in V$, and $b \in (0,1)$}
    \Ensure{Points $w \in V$ and angles $\theta \in (-\pi/2, \pi/2)$ of rotation at which $w$ enters and exits a $(b,1)$-annulus swept counterclockwise around fixed point $v$ on inner boundary}
    \Statex

    \Function{InnerSweep}{$V,v,b$}
    \Let{$L$}{$\{ \}$}
    \For{$w \in V - p$ with $\|v - w\|_2 < 1+b$}
    % \State
    \Comment{$w$ will enter \& exit the sweep}
    %$(b,1)$-annulus swept counterclockwise around fixed point $p$ on its inner circle
        \If{$1-b < \|v - w\|_2 < 2b$}
        % \State 
        \Comment{$w$ will enter \& exit both circles}
            \Let{$\tmin$}{angle $w$ enters outer circle}
            \Let{$\tdis$}{angle $w$ enters inner circle}
            \Let{$\tre$}{angle $w$ exits inner circle}
            \Let{$\tmax$}{angle $w$ exits outer circle}
        \ElsIf{$\|v - w\|_2 > 2b$}
        % \State 
        \Comment{$w$ will only enter \& exit outer circle}
            \Let{$\tmin$}{angle $w$ enters outer circle}
            \Let{$\tdis$, $\tre$}{None}
            \Let{$\tmax$}{angle $w$ exits outer circle}
        \ElsIf{$\|v - w\|_2 < 1-b$}
        % \State 
        \Comment{$w$ will only enter \& exit inner circle}
            \Let{$\tmin$, $\tmax$}{None}
            \Let{$\tdis$}{angle $w$ enters inner circle}
            \Let{$\tre$}{angle $w$ exits inner circle}
        \EndIf
    \State{add $(w, \tmin, \tdis, \tre, \tmax)$ to $L$}
    \EndFor

    \State \Return{ $L$ }
    \EndFunction
\end{algorithmic}
\end{algorithm}


First, we sweep a $(b,1)$-annulus around a fixed point $v \in V$ on its outer boundary (see Algorithm~\ref{alg:outer_sweep}).
Consider the $(b,1)$-annulus whose center is at $v + \left[ \begin{matrix} 1 & 0 \end{matrix} \right]^\T$.
We imagine a full counterclockwise rotation of the annulus around the fixed point $v$.
Points $w \in V$ with $1 - b < \|v - w\|_2 < 1 + b$ will enter and exit both the inner and outer circles of the annulus as it rotates.
Using trigonometric equations similar to those described in Section~\ref{sec:radial}, we record the angles of rotation for each of these four moments: let $\tmin$ denote the angle at which $w$ enters the outer circle, $\tdis$ the angle at which $w$ enters the inner circle (and disappears from the annulus), $\tre$ the angle at which $w$ exits the inner circle (and reappears in the annulus), and $\tmax$ the angle at which $w$ exits the outer circle.
We add the $5$-tuple $(w, \tmin, \tdis, \tre, \tmax)$ to a list $L$.
Points $w \in V$ with $\|v - w\|_2 < 1-b$ or $\|v - w\|_2 > 1 + b$ will enter and exit only the outer circle of the annulus as it rotates about $v$.
In this case, we set $\tdis = \mathrm{None}$ and $\tre = \mathrm{None}$.

Second, we sweep a $(b,1)$-annulus around a fixed point $v \in V$ on its inner boundary (see Algorithm~\ref{alg:inner_sweep}).
Consider the $(b,1)$-annulus centered at $v + \left[ \begin{matrix} b & 0 \end{matrix} \right]^\T$.
As it rotates counterclockwise about $v$, points $w \in V$ within distance $1 + b$ of $v$ will enter and exit the annulus.
If $1 - b < \|v - w\|_2 < 2b$, then $w$ will enter and exit the annulus twice in one full rotation, passing through both the inner and outer boundaries.
We again record the angles $\tmin$, $\tdis$, $\tre$, and $\tmax$ defined above, using basic trigonometry, and add the tuple $(w, \tmin, \tdis, \tre, \tmax)$ to a list $L$.
If $2b < \|v - w\|_2 < 1+b$, then $w$ only enters and exits the annulus once during the sweep, via the outer boundary.
We record the angles $\tmin$ and $\tmax$ and set $\tdis = \mathrm{None}$ and $\tre = \mathrm{None}$.
Finally, if $\|v - w\|_2 < 1-b$, then $w$ only enters and exits the annulus via the inner boundary, and we set $\tmin = \mathrm{None}$ and $\tre = \mathrm{None}$.

\begin{algorithm}
    \caption{Obtain sets of points contained in a $(b,1)$-annulus from a sweep around a given point $v$}
    \label{alg:sets_from_intervals}
    \begin{algorithmic}[1]
        %\Require{Nonempty finite set of points $V \subset \mathbb{R}^2$, $v \in V$, and $b \in (0,1)$}
        \Require{Nonempty finite subset $V$ of $\mathbb{R}^2$; $L$, the output of Algorithm~\ref{alg:outer_sweep} or Algorithm~\ref{alg:inner_sweep}}
        %\Ensure{Subsets of $V$ contained in a $(b,1)$-annulus with $v$ on the boundary and no points in the interior of its inner circle}
        \Ensure{Collection of subsets of $V$ contained in a $(b,1)$-annulus with no points in its inner circle}
        \Statex

        \Function{SetsFromIntervals}{$L$}
        %\Let{$L$}{$\textsc{OuterSweep}(V,v,b)$}
        \Let{$M$}{$[\ ]$}
        \Let{$R$}{$\textsc{InitialSet}(L)$} \Comment{See Algorithm~\ref{alg:initial_set} in Appendix~\ref{appendix:InitialSet}}
        \Let{$B$}{$\{\}$} \Comment{Bad vertices: contained in the inner circle}
        \For{$(w, \tmin, \tdis, \tre, \tmax) \in L$ and }
            \For{$\theta \in \{\tmin, \tdis, \tre, \tmax\}$}
                \If{$\theta$ is not None}
                    \State{add $(w, \theta, \mathrm{type})$ to $M$, where $\mathrm{type} \in \{\min, \mathrm{dis}, \mathrm{re}, \max\}$}
                \EndIf
            \EndFor
            \If{$\tre < \tdis$} \Comment{$w$ is bad when sweep begins}
                \State{add $(w, \tdis, \mathrm{type}=\mathrm{dis})$ to $B$}
            \EndIf
        \EndFor
        \State{Sort $M$ by angles $\theta$ in increasing order}
        \Let{$\mathrm{Sets}$}{$\{\}$}
        %\Let{$C$}{$\{\}$}
        \For{$(w, \theta, \mathrm{type}) \in M$}
            \If{$\mathrm{type}=\max$}
                remove $w$ from $R$
                \If{$B = \emptyset$}
                    %\Let{$C$}{$R$}
                    %\State{add $C \cup w$ to $\mathrm{Sets}$}
                    add $R$ and $R \cup w$ to $\mathrm{Sets}$
                \EndIf
            \ElsIf{$\mathrm{type}=\min$}
                add $w$ to $R$
                \If{$B = \emptyset$}
                    %\Let{$C$}{$R$}
                    %\State{add $C$ to $\mathrm{Sets}$}
                    add $R$ and $R - w$ to $\mathrm{Sets}$
                \EndIf
            \ElsIf{$\mathrm{type}=\mathrm{dis}$}
                remove $w$ from $R$
                \If{$B = \emptyset$}
                    %\Let{$C$}{$R$}
                    %\State{add $C \cup w$ to $\mathrm{Sets}$}
                    add $R \cup w$ to $\mathrm{Sets}$
                \EndIf
                \State{add $w$ to $B$}
            \ElsIf{$\mathrm{type}=\mathrm{re}$}
                add $w$ to $R$
                \State{remove $w$ from $B$}
                \If{$B = \emptyset$}
                    %\Let{$C$}{$R$}
                    %\State{add $C$ to $\mathrm{Sets}$}
                    add $R$ to $\mathrm{Sets}$
                \EndIf
            \EndIf
        \EndFor
        \State \Return{$\mathrm{Sets}$}
        \EndFunction
    \end{algorithmic}
\end{algorithm}


We now describe how to obtain the sets $S$ of vertices contained in a $(b,1)$-annulus with $V - S$ outside of its outer boundary (see Algorithm~\ref{alg:sets_from_intervals}).
By Proposition~\ref{prop:vxs_on_boundary}, it suffices to find the sets $S$ contained in a $(b,1)$-annulus with two points on its boundary (keeping track of whether they are on the outer or inner boundary) and all other points in $V - S$ outside of the outer boundary.
One of the points on the boundary will be the point $v$ we are sweeping around, and the other will be a point that is entering or exiting the sweep.

Let $L_v$ be a list of tuples $(w, \tmin, \tdis, \tre, \tmax)$ obtained from a sweep around $v \in V$ using either Algorithm~\ref{alg:outer_sweep} or~\ref{alg:inner_sweep}.
We first determine the points contained in the annulus when the sweep begins (Algorithm~\ref{alg:initial_set}).
These are those points $w$ which are close enough to $v$ to enter and exit the sweep and are such that 
\begin{itemize}
    \item $\tmax < \tmin$ and $\tdis < \tre$, or 
    \item $\tmax < \tmin$ and $\tdis, \tre = \mathrm{None}$, or 
    \item $\tmin, \tmax = \mathrm{None}$ and $\tdis < \tre$.
\end{itemize}
We add these points to a ``running set" $R$.
Any points $w$ which are not contained in the annulus when the sweep begins but which are contained in its inner circle (those with $\tre < \tdis$) we add to a ``bad set" $B$.

From $L_v$, we make a new list $M_v$ of tuples $(w, \theta, \mathrm{type})$ to record the angles $\theta$, in increasing order, at which points $w$ enter and exit the annulus during the sweep, along with whether it is entering or exiting and which boundary it is passing through.
Specifically, $\mathrm{type}$ is one of `$\min$', `$\mathrm{dis}$', `$\mathrm{re}$', or `$\max$' depending on whether $\theta$ is the angle at which $w$ enters the outer circle, enters the inner circle, exits the inner circle, or exits the outer circle of the annulus, respectively.
% Specifically, $M_v$ is a list of tuples $(w, \theta, \mathrm{type})$ obtained from $L_v$ by taking each angle $\theta$ from a tuple $(w, \tmin, \tdis, \tre, \tmax)$ and its $\mathrm{type}$, being either .
% We sort $M_v$ so that the angles are increasing.

Now, we go through the tuples in $M_v$ in increasing order of $\theta$.
If a vertex $w$ exits the outer circle (that is, if the tuple $(w, \theta, \mathrm{type})$ has type `$\max$'), we remove $w$ from $R$. We then check if the set of bad vertices $B$ is empty and, if it is, add both $R$ and $R \cup w$ to a list $\mathrm{Sets}$ which will be the output of Algorithm~\ref{alg:sets_from_intervals}.
If a vertex $w$ enters the outer circle (if the tuple has type `$\min$'), we add it to $R$, and if $B = \emptyset$, we add $R$ and $R - w$ to $\mathrm{Sets}$.
If a vertex $w$ enters the inner circle (if the tuple has type `$\mathrm{dis}$'), we remove $w$ from $R$, check if $B = \emptyset$, and, if it is, add $R \cup w$ to $\mathrm{Sets}$.
Then, we add $w$ to $B$.
Finally, if a vertex $w$ exits the inner circle (if the tuple has type `$\mathrm{re}$'), we add it to $R$ and remove it from $B$.
If now $B = \emptyset$, we add $R$ to $\mathrm{Sets}$.

Once the list $M_v$ is exhausted, $\mathrm{Sets}$ contains all sets of vertices which are contained in a $(b,1)$-annulus with $v$ fixed on a boundary.
If $v$ is fixed on the outer boundary, then for each set $S$ in $\mathrm{Sets}$, both $S$ and $S \cup v$ are possible subsets of $V$ contained in a $(b,1)$-annulus with no points in its inner circle.
On the other hand, if $v$ was fixed on the inner boundary, then only $S \cup v$ is a possible subset of $V$ contained in a $(b,1)$-annulus with no points in its inner circle (see Proposition~\ref{prop:vxs_on_boundary}).

Performing Algorithms~\ref{alg:outer_sweep} and~\ref{alg:inner_sweep} each $n = |V|$ times, by Proposition~\ref{prop:vxs_on_boundary} we obtain all subsets $S$ of $V$ for which there exists a $(b,1)$-annulus containing $S$ and with every point in $V - S$ outside of the radius-$1$ circle in $\mathcal{O}(n^2)$ time.
This is summarized in Algorithm~\ref{alg:enumerate_buffer_regions}.

As with our previous algorithm in~\citep{buchanan2023node}, the run time of Algorithm~\ref{alg:enumerate_buffer_regions} can be improved using parameterized complexity.
Letting $\Delta$ denote the maximum number of points contained in a radius-$2$ circle (the maximum number of neighbors that a vertex added to $G$ can have), our algorithm runs in time $\mathcal{O}(n \Delta)$.

We also note that our algorithms can be generalized to unit ball graphs in $\mathbb{R}^3$ by sweeping two concentric spheres, one of radius $b$ and one of radius $1$, around the axis formed by the line segment between two vertices $u, v \in V$ with $\|u - v\|_2 < 2$.
We do not describe such an algorithm here, as it would be a lengthy description, and as unit disk graphs are reasonable models for many of the relevant applications mentioned here (including our running example of an autonomous satellite swarm imaging a region on the surface of an object).

By adjusting the value of $b$, we can use this algorithm to fill in a region with a reliable graph whose vertices are evenly spaced apart.
In Section~\ref{sec:formation_planning}, we will compare this algorithm to another method for spreading out vertices without decreasing reliability which we presently describe.


\subsection{Fruchterman-Reingold for ball graphs}\label{sec:spring}

We now describe an alternative approach for modifying a unit ball graph for reliability and area coverage purposes.
In particular, we investigate a method for providing more even area coverage without decreasing the reliability of the graph obtained using Algorithm~\ref{alg:enumerate_buffer_regions} or the simpler version from~\citep{buchanan2023node} described in Section~\ref{sec:radial}.

The Fruchterman-Reingold, or spring layout, algorithm introduced in~\citep{fruchterman1991graph} is a standard graph drawing method.
It is based on a simple idea: vertices should be reasonably spaced apart, and adjacent vertices should be closer together than pairs of nonadjacent vertices.
To achieve this, vertices are treated like similarly charged particles, repelling one another, while edges are treated like springs, resisting this force.
The algorithm iterates some number of times, at each iteration linearly scaling down this combination of attractive and repulsive forces (reducing the ``temperature") until vertices settle into place.

Spring layout algorithms have also been used in a variety of applications.
Variations of the Fruchterman-Reingold algorithm have been proposed for the deployment of large-scale wireless sensor networks~\citep{deng2019optimized,li2022fruchterman}.
A related concept of virtual force algorithms has also been studied in the context of wireless sensor network coverage (see, for example,~\citep{howard2002mobile,qi2022wireless}).

While the spring layout algorithm can provide a more even spread of vertices over a region, it can also drastically change the underlying ball graph.
Of concern to us is the scenario in which edges are deleted (when vertices which were within communication distance are moved further apart), decreasing the reliability of the resulting ball graph.
Extra edges, on the other hand, only increase the reliability.
Luckily, this simple algorithm is not hard to modify so that it respects adjacencies in a unit disk or ball graph.
We chose to modify the existing Fruchterman-Reingold algorithm from the NetworkX Python library~\citep{SciPyProceedings_11}.\footnote{\url{https://networkx.org/documentation/stable/_modules/networkx/drawing/layout.html}}
There are a number of ways that one might stop edges in a unit ball graph from being broken by the Fruchterman-Reingold algorithm.
Here, we do so by leveraging the temperature: at each iteration, we check whether any pair vertices which were previously within distance $1$ are now of distance greater than $1$ apart.
If such a pair exists, we simply go back to the positions at the last iteration, reduce the temperature, and move on to the next iteration.
We now describe our modified Fruchterman-Reingold algorithm for ball graphs in more detail.

Let $G$ be a unit ball graph of order $n$ with vertex set $V$ and edge set $E$.
We consider $G$ to lie within a {\em frame}, a minimum rectangle or rectangular prism containing all points in $V$.
Let $k$ denote the optimal distance between an average pair of vertices at the end of the algorithm.
In two dimensions, it is common to set $k = \sqrt{A/n}$, where $A$ denotes the area of the frame.
Finally, let $t$ denote the initial {\em temperature}, which determines how far we allow vertices to move at the first iteration.
For the algorithm we chose to modify, $t$ is $1/10$ of the maximum length of a side of the frame.
For each pair of distinct vertices $u,v \in V$, we calculate the force $f_r(u,v) = k^2 / d_{u,v}^{2}$ of repulsion.
When $uv \in E$, we calculate the force $f_a(u,v) = d_{u,v} / k$ of attraction, and we let $f_a(u,v) = 0$ when $uv \notin E$.
Let $F$ denote the matrix of forces between vertices: $F_{u,v} = f_r(u,v) - f_a(u,v)$.
We use these forces to calculate the initial displacement vector $\Vec{\mathrm{disp}}_v$ for each vertex $v$.
In two dimensions, letting $v = \left[ \begin{matrix} x_v & y_v \end{matrix} \right]^\T$, the first coordinate of $\Vec{\mathrm{disp}}_v$ is $\sum_{w \neq v} (x_v - x_w) F_{v,w}$ and the second is $\sum_{w \neq v} (y_v - y_w) F_{v,w}$.
We scale each displacement vector according to the temperature, obtaining a vector $\delta_v = \Vec{\mathrm{disp}}_v \cdot t / l_v$, where $l_v$ is the length of $\Vec{\mathrm{disp}}_v$.

Classical Fruchterman-Reingold algorithms come in two types: at each iteration, either all vertices move at once according to their displacement vectors, or the vertices move one at a time, requiring a recalculation of forces at each iteration.
In the former case, the new position for each vertex $v$ is $\left[ \begin{matrix} x_v & y_v \end{matrix} \right]^\T + \delta_v$.
In the latter case, we cycle through the vertices of $G$, moving a single vertex $v$ according to $\delta_v$ at each iteration.
Our solution to the problem of breaking edges is essentially the same in either case: if any pair of vertices previously within distance $1$ would be at distance $> 1$ after any iteration, we avoid moving any vertices at all, lower the temperature by $t / (\mathrm{it} + 1)$, where `$\mathrm{it}$' denotes the total number of iterations, and move on to the next iteration (essentially weakening the forces $F_{u,v}$).
If all pairs of vertices previously within distance $1$ remain within distance $1$, we keep the new positions and again lower the temperature by $t / (\mathrm{it} + 1)$ for the next iteration.
As the temperature decreases to $t / (\mathrm{it} + 1)$ at the last iteration, the positions of the vertices stabilize.

% In the next section, we will add vertices to maximize reliability and then use this algorithm to provide more even spacing.
% Perhaps surprisingly, we will show that iterating Algorithm~\ref{alg:enumerate_buffer_regions} provides a better spread over a region and a comparable (though slightly lower) reliability than using the two algorithms in conjunction.


\section{Formation planning for autonomous swarms}\label{sec:formation_planning}

In this section, we apply Algorithm~\ref{alg:enumerate_buffer_regions} and the modified Fruchterman-Reingold algorithm from Section~\ref{sec:spring} to obtain swarm formations with even area coverage and high reliability.
Returning to our running example, we consider an autonomous swarm of satellites assigned to image a region on the surface of an object.
We begin by assigning satellites to image the outer boundary of the region.
Our goal is to assign the remaining satellites to cover the interior of the region so that the entire region is evenly covered and so that the communication network is not only connected but highly reliable.
We note that search and rescue missions by robots, imaging of an ocean bed by autonomous underwater vehicles, or use of unmanned aerial vehicles for precision agriculture may be modeled similarly.
Our findings indicate that using Algorithm~\ref{alg:enumerate_buffer_regions} alone (as opposed to using it in conjunction with our modified Fruchterman-Reingold algorithm) is particularly effective in accomplishing this goal.

\begin{figure}
    \centering
    \includegraphics[scale=.45]{bs_after_spring_0.pdf}
    \caption{Fifteen agents cover the outer boundary of a circular region, modeled by a unit disk graph forming a regular $15$-gon whose edges are of length $0.9$}
    \label{fig:15-gon}
\end{figure}

As a basis for our simulations, we imagine a circular disk to be covered by a swarm of $30$ agents.\footnote{This is simply for illustration; regions of other shapes, and swarms of other sizes, may be considered as well.}
We begin with a unit disk graph on $15$ vertices forming a regular $15$-gon whose edges have length $0.9$ (see Figure~\ref{fig:15-gon}).
These vertices outline a circular region with area about $14.717$ (radius $\approx 2.16$).
We add $15$ additional vertices one at a time to this unit disk graph using four different methods:

\begin{enumerate}[(M1)]

    \item\label{item:rand}
    {\em Random:}
    Add vertices randomly to the interior of the region, conditioned on them being within unit distance of at least one existing vertex ({\em i.e.}, conditioned on connectedness).

    \item\label{item:rand_spring} 
    {\em Random \& Spring:}
    Add vertices as in item~(M\ref{item:rand}), 
    but apply the Fruchterman-Reingold algorithm from Section~\ref{sec:spring} each time a vertex is added, leaving the positions of the initial $15$ vertices fixed.

    \item\label{item:buffer} 
    {\em Buffer:}
    Use Algorithm~\ref{alg:enumerate_buffer_regions} and Monte Carlo simulations to add vertices which maximize the resulting reliability while being at distance at least $0.65$ from any other vertex.

    \item\label{item:buffer_spring} 
    {\em Buffer \& Spring:}
    Add vertices as in item~(M\ref{item:buffer}), but apply the Fruchterman-Reingold algorithm from Section~\ref{sec:spring} each time a vertex is added.
\end{enumerate}

The specifics of each of these methods are discussed below, and examples of the resulting graphs are depicted in Figure~\ref{fig:sim_pics}.
For a reliability measure, we use the all-terminal reliability with edge-operation probabilities all $90\%$.
These edge-operation probabilities may be adjusted, and unreliable vertices introduced, with additional information regarding the agents in the application and their communication devices.
Using the Zero-One Estimator theorem of Karp and Luby~\citep{karp_monte-carlo_1985}, or one of its improved forms (see, {\em e.g.},~\citep{dagum2000optimal}), one can easily compute upper bounds on the number of Monte Carlo simulations necessary to obtain, with probability $1 - \delta$, an estimate of $\Rel_A$ with relative error $\epsilon$ (known as an $(\epsilon, \delta)$-approximation).
For a graph $G$ with high reliability, however, these upper bounds can be quite large.
Such Monte Carlo techniques proved inefficient for the more reliable graphs produced by the methods in items~(M\ref{item:buffer}) and~(M\ref{item:buffer_spring}) above.
Instead, we use an open-source program called $\mathcal{K}$-RelNet, introduced in~\citep{paredes2019principled}, to obtain $(\epsilon, \delta)$-estimates of $\Rel_A(G)$.
Essentially, the program reduces the problem of finding all-terminal reliability (or the more general $K$-terminal reliability, see~\citep{colbourn_combinatorics_1987}) to counting the number of assignments satisfying a Boolean formula in conjunctive normal form.
It then obtains an $(\epsilon, \delta)$-approximation of this count using a state-of-the-art approximate model counter ApproxMC, introduced in~\citep{chakraborty2013scalable} and now in its sixth version, ApproxMC6~\citep{yang2023rounding}.
We set $\epsilon = 0.8$ and $\delta = 0.2$ for our relative estimates; these are the default values for the $\mathcal{K}$-RelNet program, and a relative error of $0.8$ provides quite a small absolute error bound for the more reliable graphs in question.


