%\end{align}
%\end{assumption}
%Throughout this paper, unless otherwise stated, we will always assume that Assumption \ref {Assum:1} holds.

Since all weights $w_j=1/N$ for QMC rules, the corresponding ``discrete inner product'' is given as in \eqref{eq:discrete_inner_product}, where the quadrature rule is a QMC rule \eqref{QMC_rule} that satisfies Assumption \ref{Assum:1}. Then  QMC hyperinterpolation $\mathcal{Q}_I f$ is defined as follows.
\begin{definition}[QMC hyperinterpolation]
Let $f\in L_2(\Omega),$ and $\mathcal{P}=(\bsx_n)_{n=0}^{N-1}$ be quadrature points satisfy Assumption \ref{Assum:1}. The quasi-Monte Carlo (QMC) hyperinterpolation of range $I$ is defined by
\begin{align}\label{QMChyper}
\mathcal{Q}_I f:=\sum_{\bsh \in I} \left<f,q_{\bsh}  \right>_{N} q_{\bsh}.
\end{align}
\end{definition}\label{QMC_hyper_def}
\begin{remark}
For the QMC rules that satisfy the exactness condition \eqref{hyper_exact_assump} for every $p\in \mathbb{P}_I(\Omega),$ Assumption \ref{Assum:1} is also satisfied. Therefore, some hyperinterpolations constructed using QMC rules can also be classified as QMC hyperinterpolation.
\end{remark}

Obviously, it holds that $\mathcal{Q}_I f\in\mathbb{P}_I(\Omega)$.
Moreover, $\mathcal{Q}_I f$ belongs to a reproducing kernel Hilbert space with the reproducing kernel
\begin{align*}
G_I(\bsx,\bsy):=\sum_{\bsh\in I} q_{\bsh}(\bsx)\overline{q_{\bsh}(\bsy)}
\end{align*}
in the sense that \cite{reimer2012multivariate}
\begin{align}\label{reproducing_property}
\left<g,   G_I(\cdot,\bsx)\right>=g(\bsx), \qquad \forall g\in \mathbb{P}_I(\Omega).
\end{align}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{$L_2$ error bound for $\mathcal{Q}_I f$}
With the aid of reproducing property \eqref{reproducing_property}, the construction of QMC hyperinterpolation implies the following theorem:
\begin{theorem}\label{thm_L_2_error}
Given $f\in L_2(\Omega),$ let $\mathcal{Q}_I f $ be  defined by \eqref{QMChyper}. Then
\begin{align}\label{QMC_L_2_oprator}
\|\mathcal{Q}_If\|_{L_2}\leq\sqrt{1+\eta}\|f\|_{\infty},
\end{align}
and
\begin{equation}\label{equ:L_2error}
\|\mathcal{Q}_I f-f\|_{L_2}\leq \left(\sqrt{1+\eta}+1 \right)E_I(f)+ \Vert \mathcal{Q}_I p^*-p^* \Vert_{L_2},
\end{equation}
where  $E_I(f)=\Vert f-p^*\Vert_\infty$ and  $p^*\in\mathbb{P}_I(\Omega)$ denotes the best approximation polynomial of $f$ in terms of the uniform norm.
\end{theorem}
\begin{proof}
For any $f\in L_2(\Omega)$, we have $\mathcal{Q}_I f\in\mathbb{P}_I(\Omega)$ and hence $\left\langle G_I(\cdot,\bsx_n),\mathcal{Q}_I f\right\rangle=\mathcal{Q}_I f(\bsx_n)$. Thus,

\begin{align*}
\left\langle \mathcal{Q}_I f,\mathcal{Q}_I f \right\rangle
& = \left\langle \frac{1}{N}\sum_{n=0}^{N-1} f(\bsx_n)G_I(\cdot,\bsx_n),\mathcal{Q}_I f\right\rangle = \frac{1}{N}\sum_{n=0}^{N-1} f(\bsx_n)\mathcal{Q}_I f(\bsx_n)\\
& \leq \left(\frac{1}{N}\sum_{n=0}^{N-1}f^2(\bsx_n)\right)^{1/2}\left(\frac{1}{N}\sum_{n=0}^{N-1}\left(\mathcal{Q}_If(\bsx_n)\right)^2\right)^{1/2}\\
&\leq \sqrt{1+\eta}\|f\|_{\infty}\|\mathcal{Q}_If\|_{L_2},
\end{align*}
where the first inequality is due to the Cauchy--Schwarz inequality and the second one holds by using \eqref{QMC_assump}. This estimate immediately implies the result \eqref{QMC_L_2_oprator}.

For the error bound \eqref{equ:L_2error}, we have 
\begin{align*}
\|\mathcal{Q}_I f-f\|_{L_2}
& = \|\mathcal{Q}_I(f-p)+(p-f)+(\mathcal{Q}_I p-p)\|_{L_2} \\
&\leq \|\mathcal{Q}_I(f-p)\|_{L_2} + \|f-p\|_{L_2}+\|\mathcal{Q}_I p-p\|_{L_2}\\
& \leq \sqrt{1+\eta}\|f-p\|_{\infty}+\|f-p\|_{\infty} + \|\mathcal{Q}_I p-p\|_{L_2}
\end{align*}
for any $p\in\mathbb{P}_I(\Omega).$ It follows, since this estimate holds for all polynomials $p$ in $\mathbb{P}_I(\Omega),$ that
\begin{align*}
\|\mathcal{Q}_I f-f\|_{L_2} \leq\left(\sqrt{1+\eta}+1\right)E_I(f) + \|\mathcal{Q}_I p^*-p^*\|_{L_2}.
\end{align*}
Thus, we have done.
\end{proof}


\begin{remark}
The $L_2$ upper bound of the QMC hyperinterpolation operator $\mathcal{Q}_I$ is larger than that of the hyperinterpolation operator $\mathcal{L}_I$ by a factor of $\eta \in (0,1)$, which accounts for the primary difference in $L_2$ approximation error between the QMC hyperinterpolation and the classical hyperinterpolation, given by $\Vert \mathcal{Q}_I p^*-p^*\Vert_{L_2}$. From the above error analysis, the approximation quality of QMC hyperinterpolation is slightly weaker than that of hyperinterpolation with the same range.
\end{remark}

In the following subsections, we give two classes of concrete quadrature points of $\mathcal{Q}_I f$ according to different polynomial spaces $ \mathbb{P}_I(\Omega).$  For short, we write
\begin{align}\label{int_error_criterion}
\text{err}_N(p,\mathbb{P}_{I}(\Omega)):&=\left|\int_{\Omega} p^2(\bsx) \rd \bsx-\frac{1}{N}\sum_{n=0}^{N-1} p^2(\bsx_n)\right|,\;\;p\in  \mathbb{P}_{I}(\Omega).
\end{align}

