\subsection{Polynomial lattice rules in weighted Walsh space}
For non-periodic functions $f\in L_{2}(\Omega)$, one can use the system of multivariate Walsh functions for approximation. Given a fixed index set $I,$ define
\[  \mathbb{P}_I^{\wal}(\Omega):=\mathrm{span}\left\{ \wal_{\bsh},\;\bsh\in I\right\}. \]
Then we can construct $\mathcal{Q}_I f$  by polynomial lattice rules. The polynomial lattice rule is a QMC rule based on a polynomial lattice point set, and in particular, the rank-1 polynomial lattice point set is analogous to the rank-1 lattice point set, but is based on linear algebra over finite fields.  

Let $b$ be a prime number and $\FF_b$ denote the finite field with $b$ elements. We identify $\FF_b$ with the set $\{0,1,\ldots,b-1\}$, equipped with addition and multiplication modulo $b$. We denote by $\FF_b[x]$ the ring of polynomials over $\FF_b$, and by $\FF_b((x^{-1}))$ the field of formal Laurent series over $\FF_b$.
Then the rank-1 polynomial lattice point set is defined as follows.

\begin{definition}
    Let $m\in \NN$, and let $p\in \FF_b[x]$ and $\bsq =(q_1,\ldots,q_d)\in (\FF_b[x])^d$ be such that $\deg(p)=m$ and $\deg(q_j)< m$ for all $j$. We identify an integer $h\in \NN_0$, whose $b$-adic expansion is given by $h=\eta_0+\eta_1b+\ldots$, with the polynomial $h(x)=\eta_0+\eta_1 x+\cdots\in \FF_b[x]$. The rank-1 polynomial lattice point set with modulus $p$ and generating vector $\bsq$, denoted by $P(p,\bsq)$, is the set of $b^m$ points defined by
    \[ \bsx_h=\left( \nu_m\left(\frac{h(x)q_1(x)}{p(x)} \right),\ldots, \nu_m\left(\frac{h(x)q_d(x)}{p(x)} \right)\right)\in \Omega,\]
    where the map $\nu_m: \FF_b((x^{-1}))\to [0,1)$ is defined by
    \[ \nu_m\left( \sum_{i=w}^{\infty}a_ix^{-i}\right) = \sum_{i=\max\{1,w\}}^{m}a_ib^{-i}.\]
\end{definition}

Polynomial lattice point sets are an important class of so-called \emph{digital nets}, a family of QMC point sets, see \cite{Dick_Pillichshammer_2010}. 
With this fact in mind, we have a different way to represent rank-1 polynomial lattice point sets using the generating matrices over $\FF_b$.
Similar to the rank-1 lattice rules in weighted Korobov space, we have the following existence theorem for Assumption \ref{Assum:1}.

\begin{theorem}\label{Example_C_existence}
Let an index set $I\subset \NN_0^d$ with finite cardinality \(|I|\), $\alpha>1/2$, and product weights $\boldsymbol{\gamma} = (\gamma_1, \gamma_2, \ldots) \in [0, 1]^{\mathbb{N}}$ be given. There exists a positive integer $m^*$, which depends on $d$, $\alpha$ and $\bsgamma$, such that, for any integer $m\ge m^*$, the $b^m$-points rank-1 polynomial lattice rule with a suitable choice of modulus $p\in \FF_b[x]$ and generating vector $\bsq\in (\FF_b[x])^d$ satisfies Assumption \ref{Assum:1} for all $p\in \mathbb{P}^{\wal}_{I}(\Omega).$ 
\end{theorem}

\begin{proof}
    A similar argument made in \cite{DP2005} shows that there exists a polynomial lattice rule with modulus $p\in \FF_b[x]$ and generating vector $\bsq \in (\FF_b[x])^d$ such that $p$ is irreducible with $\deg(p)=m$ and $\deg(q_j)<m$, for which the worst-case error in the weighted Walsh space, $H_{d,\alpha,\bsgamma}^{\wal}$ is bounded by
    \begin{align*}
        e^{\wor}(P(p,\bsq), H_{d,\alpha,\bsgamma}^{\wal}) & := \sup_{\substack{f\in H_{d,\alpha,\bsgamma}^{\wal}\\ \|f\|_{d,\alpha,\bsgamma}^{\wal}\le 1}}\left| \int_{[0,1)^d}f(\bsx)\rd \bsx - \frac{1}{b^m}\sum_{h=0}^{b^m-1}f(\bsx_h) \right|\\
%        & \: =\left( \sum_{\substack{\bsk\in \NN_0^d\setminus \{\bszero\}\\ \mathrm{tr}_m(\bsk)(x) \cdot \bsq(x) \equiv 0 \pmod{p(x)}}}\frac{1}{(\breve{r}_{\alpha, \bsgamma}(\bsk))^2} \right)^{1/2} \\
        & \: \leq \left( \frac{2}{b^m-1}\sum_{\bsk\in \NN_0^d\setminus \{\bszero\}}\frac{1}{(\breve{r}_{\alpha, \bsgamma}(\bsk))^{2\lambda}} \right)^{1/\lambda}\\
        & \: = \left( \frac{2}{b^m-1}\left(-1+\prod_{j=1}^{d}\left(1+\gamma_{j}^2\frac{b-1}{b^{2\alpha\lambda}-b}\right)\right)\right)^{1/\lambda},
    \end{align*}
    for any $\lambda\in (1/(2\alpha),1]$.

    As shown in Appendix~\ref{app:Walsh_algebra}, the weighted Walsh space with $\alpha>1/2$ is an algebra, i.e., we have
    \[ \| p^2\|_{d,\alpha,\bsgamma}^{\wal}\leq \breve{C}(d) \left(\|p\|_{d,\alpha,\bsgamma}^{\wal}\right)^2 \quad \text{with $\breve{C}(d)=2^d \prod_{j=1}^{d}\left(1+\gamma_{j}^2\frac{b-1}{b^{2\alpha}-b}\right)^{1/2}$,} \]
    for any $p\in H_{d,\alpha,\bsgamma}^{\wal}$. Thus, it holds for any $p\in \mathbb{P}_I^{\wal}(\Omega)$ that
    \begin{align*}
        \text{err}_{b^m}(p,\mathbb{P}^{\wal}_{I}(\Omega)) & \leq \| p^2\|_{d,\alpha,\bsgamma}^{\wal}e^{\wor}(P(p,\bsq), H_{d,\alpha,\bsgamma}^{\wal})\\
        & \leq \breve{C}(d) \left(\|p\|_{d,\alpha,\bsgamma}^{\wal}\right)^2\left( \frac{2}{b^m-1}\left(-1+\prod_{j=1}^{d}\left(1+\gamma_{j}^2\frac{b-1}{b^{2\alpha\lambda}-b}\right)\right)\right)^{1/\lambda}\\
        & \leq \breve{C}(d) \left(\max_{\bsh\in I} \breve{r}_{\alpha,\bsgamma}^2(\bsh)\right)\| p\|_{L_2}^2\\
       &\qquad\qquad\times \left( \frac{2}{b^m-1}\left(-1+\prod_{j=1}^{d}\left(1+\gamma_{j}^2\frac{b-1}{b^{2\alpha\lambda}-b}\right)\right)\right)^{1/\lambda}.
    \end{align*}
    This proves the existence of $m^*\in \NN$ such that Assumption~\ref{Assum:1} holds for any $m\ge m^*$.
\end{proof}

In this case, our approximation scheme \eqref{QMChyper} becomes 
\begin{align*}
\mathcal{Q}_I f(\bsy) 
:=\sum_{\bsh\in I} 
& \left( \frac{1}{b^m} \sum_{m=0}^{b^m-1} 
f\left( \nu_m\left( \frac{n(x)\bsq(x)}{p(x)} \right) \right) 
\overline{\wal_{\bsh}\left( \nu_m\left( \frac{n(x)\bsq(x)}{p(x)} \right) \right)} 
\right) \wal_{\bsh}(\bsy).
\end{align*}


