\subsection{CBC Constructions for Rank-1 Lattice Rules}
Now we give concrete computer search algorithms for a good rank-1 lattice point set $P_{N,\bsz}$ for $\mathcal{Q}_If$, so that it satisfies Assumption \ref{Assum:1}. Recall that the $P_{N,\bsz}$ is fully characterized by the generating vector $\bsz\in \mathbb{Z}^d.$  Therefore, it suffices to search for the generating vector $\bsz$ from
\begin{align}\label{CBC_serach_range}
G_{d}(N):=\left\{z\in\left\{1,2,\ldots,N-1  \right\}\;:\;\gcd(\bsz,N)=1  \right\}^d,
\end{align}
where the restriction that the components of the generating vector $\bsz$ are all coprime with $N$ would let every projection of a lattice point set have $N$ distinct values. When $N$ is prime, the number of all possible candidates in $G_d(N)$ is $(N-1)^d.$  Hence, the exhaustive search strategy for generating vector $\bsz$ is infeasible as the great computation costs of $(N-1)^d$ for large $N$ and $d.$

Nowadays, the most widely used computer search algorithm for the generating vector $\bsz$ of a rank-1 lattice point set is the component-by-component construction, or for short, CBC construction, which was first proposed by Korobov \cite{Korobov1963} and reinvented by Sloan and Reztsov \cite{sloan2002component}. We outline the general principle of CBC construction in Algorithm~\ref{cbc_principle}.
Here we remark that the selection criterion can be designed by minimizing an error criterion, or by satisfying congruence equations, and so on. Moreover, if there exist several distinct elements $z_s\in G_1(N)$ that satisfy the selection criterion $R$, it is allowed either to choose any of them arbitrarily or to make some rule so that the choice is unique.

\begin{algorithm}[t]
\caption{CBC construction principle}
\label{cbc_principle}
Let $N$ be a prime number, let $d\in\mathbb{N}.$
Construct a generating vector $\bsz=(z_1,\ldots,z_d)\in G_d(N)$, where $G_d(N)$ is defined in \eqref{CBC_serach_range}, as follows.
\begin{enumerate}
\item Choose a sufficiently good one-dimensional generator $g_1\in G_1(N),$ in most cases, $g_1$ is set to 1.
\item \textbf{For} $s$ from $2$ to $d$ do the following:\\
Assume that $\{z_1,\ldots,z_{s-1}\}\in G_{s-1}(N)$ have already been found. Choose $z_{s}\in G_1(N)$ by some selection boolean criterion $R,$ i.e., pick up $z_s$ such that
\begin{align*}
R(z_1,\ldots,z_{s-1},z_s)=\text{true}.
\end{align*}
\textbf{end for}
\item Set $\bsz=(z_1,\ldots,z_{d}).$
\end{enumerate}
\end{algorithm}

Note that the size of the search space of the generating vector $\bsz$ in Algorithm \ref{cbc_principle} is $d (N-1),$ which has a significant reduction as compared to the exhaustive search with a full space of size $(N-1)^d.$ Furthermore, the CBC construction is extensible; that is, additional components $z_{d+1}$ can be added to the already-obtained vector $\bsz\in \mathbb{Z}^d$ by running one loop in the CBC algorithm. However, note that we also need to consider the extra computation costs of the selection boolean criterion $R.$


Since the key of constructing the generating vector $\bsz$ for QMC hyperinterpolation is Assumption \ref{Assum:1}, we can design the selection boolean criterion $R$ by minimizing the integration error criterion \eqref{int_error_criterion}. The following character property for the dual lattice is necessary to derive the analytic form of \eqref{int_error_criterion}.
\begin{definition}[Dual lattice]
    For $N\in \NN$ with $N\geq 2$ and a generating vector $\bsz\in \{1,\ldots,N-1\}^d$, the set
    \[ P_{N, \bsz}^{\perp}:=\left\{\bsh \in \ZZ^{d} \mid \bsh \cdot \bsz \equiv 0 \pmod N\right\} \]
    is called the dual lattice of the rank-1 lattice point set $P_{N, z}$.
\end{definition}
Then the following property of rank-1 lattice rules holds.
\begin{lemma}[Character property]\label{lem:character}
    For $N\in \NN$ with $N\geq 2$ and a generating vector $\bsz\in \{1,\ldots,N-1\}^d$,
    \[ \frac{1}{N}\sum_{n=0}^{N-1} \exp \left(2 \pi i \bsh \cdot \bsx_n\right)= \begin{cases}1 & \text{if $\bsh \in P_{N, \bsz}^{\perp}$,} \\ 0 & \text{otherwise,}\end{cases} \]
    holds for any vector $\bsh \in \ZZ^{d}$.
\end{lemma}
 With the help of character property, we can deduce the analytic form of integration error \eqref{int_error_criterion}. Denote $p\in  \mathbb{P}_I (\Omega)\setminus\{\boldsymbol{0}\}$ by $p(\bsx)=\sum_{\bsh\in I} a_{\bsh} \exp(2\pi i\bsh \cdot \bsx)$. Then we have 
\[ \int_{\Omega}p^2(\bsx)\rd \bsx  = \sum_{\bsh\in I}|a_{\bsh}|^2\]
and
\begin{align*}
\frac{1}{N}\sum_{n=0}^{N-1} p^2(\bsx_n)&=\frac{1}{N}\sum_{n=0}^{N-1}\left(\sum_{\bsh \in I} a_{\bsh}\exp(2\pi i \bsh\cdot \bsx_n )\right)^2\\
&=\sum_{\bsh'\in I}\sum_{\bsh''\in I} a_{\bsh'}\overline{a_{\bsh''}}\left(\frac{1}{N} \sum_{n=0}^{N-1} \exp(2\pi i (\bsh'-\bsh'')\cdot\bsx_n)\right)\\
&=\sum_{\bsh'\in I} a_{\bsh'}\sum_{\substack{\bsh''\in I\\ \bsh'-\bsh''\in P_{N,\bsz}^{\perp}}} \overline{a_{\bsh''}},
\end{align*}
so that the signed integration error is equal to
\begin{align}
\frac{1}{N}\sum_{n=0}^{N-1} p^2(\bsx_n)-\int_{\Omega}p^2(\bsx)\rd \bsx =\sum_{\bsh'\in I} a_{\bsh'}\sum_{\substack{\bsh''\in I\\ \bsh'-\bsh''\in P_{N,\bsz}^{\perp}\backslash\{ \boldsymbol{0}  \}}} \overline{a_{\bsh''}}. \label{integration_error}
\end{align}



To extract the constant $\eta$ in Assumption \ref{Assum:1}, considering the size of hyperbolic cross set \eqref{dimension_A_d}, we have the first integration error estimates.

\begin{lemma}\label{lem:assumption_error_bounds}
For the rank-1 lattice rule, we have the following error estimation.
\begin{align}\label{lattice_integration_error}
\emph{err}_N(p,\mathbb{P}_I(\Omega))\leq \sqrt{|I|}\Vert p \Vert_{d,\alpha,\bsgamma}^2  R_{N,\alpha,d,\bsgamma}(\bsz) \prod_{j=1}^d \max(1,2^{\alpha}\gamma_j),
\end{align}
and
\begin{align}\label{lattice_integration_error_R}
\emph{err}_N(p,\mathbb{P}_I(\Omega))\leq \Vert p\Vert_{d,\alpha,\bsgamma}^2 S_{N,\alpha,d,\bsgamma}(\bsz),
\end{align}
where we write
\begin{align}
R^2_{N,\alpha,d,\bsgamma}(\bsz) & =\sum_{\bsh \in P_{N,\bsz}^{\perp} \backslash \{\boldsymbol{0} \}}\frac{1}{r_{\alpha,\bsgamma}^2(\bsh)},\qquad \text{and} \label{quantity} \\
S^2_{N,\alpha,d,\bsgamma}(\bsz)
& =\sum_{\bsh^* \in P_{N,\bsz}^{\perp}\backslash \{ \boldsymbol{0}  \}}\sum_{\bsh'\in\mathbb{Z}^d} \frac{1}{r_{\alpha,\bsgamma}^2(\bsh')r_{\alpha,\bsgamma}^2(\bsh^*+\bsh')}.\notag
\end{align}
\end{lemma}


\begin{proof}
 Note that the polynomial $p$ is infinitely smooth, thus $p\in H_{d,\alpha,\bsgamma}$ for any $\alpha>1/2$, and it follows from \eqref{integration_error} that
\begin{align*}
\left| \int_{\Omega} p^2(\bsx) \rd \bsx-\frac{1}{N}\sum_{n=0}^{N-1} p^2(\bsx_n)  \right|\leq \sum_{\bsh' \in I} |a_{\bsh'}|\sum_{\substack{\bsh''\in I \\ \bsh'-\bsh'' \in P_{N,\bsz}^{\perp}\backslash \{ \boldsymbol{0} \}}}| a_{\bsh''}|.
\end{align*}
Then, by using the Cauchy–-Schwarz inequality twice, we obtain
\begin{align*}
\text{err}_N(p,\mathbb{P}_I(\Omega))&\leq  R_{N,\alpha,d,\bsgamma}(\bsz)\sum_{\bsh' \in I} |a_{\bsh'}|\left(\sum_{\substack{\bsh''\in I \\ \bsh'-\bsh'' \in P_{N,\bsz}^{\perp}\backslash\{\boldsymbol{0}\}}}| a_{\bsh''}|^2r^2_{\alpha,\bsgamma}(\bsh'-\bsh'')\right)^{1/2} \\
&\leq  R_{N,\alpha,d,\bsgamma}(\bsz)\\
&\qquad\times\sum_{\bsh' \in I} |a_{\bsh'}|\left(\sum_{\substack{\bsh''\in I \\ \bsh'-\bsh'' \in P_{N,\bsz}^{\perp}\backslash\{\boldsymbol{0}\}}}\left( a_{\bsh''} r_{\alpha,\bsgamma}(\bsh'')\right)^2\frac{r^2_{\alpha,\bsgamma}(\bsh'-\bsh'')}{r_{\alpha,\bsgamma}^2(\bsh'')}\right)^{1/2} \\
&\leq \Vert p\Vert_{d,\alpha,\bsgamma} R_{N,\alpha,d,\bsgamma}(\bsz)\sum_{\bsh'\in I}|a_{\bsh'}|\left( \sup_{\substack{\bsh''\in I\\ \bsh''-\bsh' \in P_{N,\bsz}^{\perp}\backslash\{\boldsymbol{0}\}}} \frac{r_{\alpha,\bsgamma}^2(\bsh'-\bsh'')} {r_{\alpha,\bsgamma}^2(\bsh'')}\right)^{1/2} \\
&\leq \Vert p\Vert_{d,\alpha,\bsgamma}^2 R_{N,\alpha,d,\bsgamma}(\bsz)\\
&\qquad\times\left( \sum_{\bsh'\in I}\frac{1}{r^2_{\alpha,\bsgamma}(\bsh')}\sup_{\substack{\bsh''\in \mathbb{Z}^d \\ \bsh''-\bsh' \in P_{N,\bsz}^{\perp}\backslash\{\boldsymbol{0}\}}} \frac{r_{\alpha,\bsgamma}^2(\bsh'-\bsh'')} {r_{\alpha,\bsgamma}^2(\bsh'')}\right)^{1/2}.
\end{align*}
Let $\bsh^*=\bsh''-\bsh'\in P_{N,\bsz}^{\perp}\backslash\{\boldsymbol{0}\}.$ For any choice of $\bsh'\in I,$  from \cite[Chapter 13]{dick2022lattice}, it is true that
\begin{align*}
\frac{r_{\alpha,\bsgamma}^2(\bsh'-\bsh'')} {r_{\alpha,\bsgamma}^2(\bsh'')}=\frac{r_{\alpha,\bsgamma}^2(\bsh^*)}{r^2_{\alpha,\bsgamma}(\bsh^*+\bsh')}\leq r_{\alpha,\bsgamma}^2(\bsh')\prod_{j=1}^d \max(1,2^{2\alpha}\gamma_j^2),
\end{align*}
which leads to \eqref{lattice_integration_error}. On the other hand, we can get rid of the size of index set $I$ by introducing a new quantity. By rewriting the integration error \eqref{int_error_criterion}, we have
\begin{align*}
\text{err}_N(p,\mathbb{P}_I(\Omega))&\leq \sum_{\bsh' \in I} |a_{\bsh'}|\sum_{\substack{\bsh''\in I \\ \bsh'-\bsh'' \in P_{N,\bsz}^{\perp}\backslash \{ \boldsymbol{0}  \}}}\left(| a_{\bsh''}|r_{\alpha,\bsgamma}(\bsh'')\right) \frac{1}{r_{\alpha,\bsgamma}(\bsh'')}.
\end{align*}
Again, by using the Cauchy–-Schwarz inequality twice, we have
\begin{align*}
\text{err}_N(p,\mathbb{P}_I(\Omega)) &\leq \Vert p\Vert_{d,\alpha,\bsgamma}\sum_{\bsh'\in I} |a_{\bsh'}|\left(\sum_{\substack{\bsh''\in \mathbb{Z}^d \\ \bsh'-\bsh'' \in P_{N,\bsz}^{\perp}\backslash \{ \boldsymbol{0}  \}}} \frac{1} {r_{\alpha,\bsgamma}^2(\bsh'')} \right)^{1/2}\\
&\leq \Vert p\Vert_{d,\alpha,\bsgamma}^2\left(  \sum_{\bsh'\in\mathbb{Z}^d}\frac{1}{r_{\alpha,\bsgamma}^2(\bsh')}\sum_{\bsh^* \in P_{N,\bsz}^{\perp}\backslash \{ \boldsymbol{0}  \}} \frac{1}{r_{\alpha,\bsgamma}^2(\bsh^*+\bsh')} \right)^{1/2}
\end{align*}
and therefore obtain \eqref{lattice_integration_error_R}.
\end{proof}

Using the definition of the hyperbolic cross set, we can distinguish $\Vert p\Vert_{L_2}^2$ for $p\in \mathbb{P}_{I}(\Omega),$ from $\Vert p\Vert_{d,\alpha,\bsgamma}^2,$ that is
\begin{align*}
\Vert p\Vert_{d,\alpha,\bsgamma}^2=\sum_{\bsh\in I} |a_{\bsh}|^2 r^2_{\alpha,\bsgamma}(\bsh)\leq M \Vert p\Vert_{L_2}^2.
\end{align*}
Hence, the integration error $\text{err}_N(p,\mathbb{P}_I(\Omega))$ is characterized by special quantities $R_{N,\alpha,d,\bsgamma}(\bsz)$ and $S_{N,\alpha,d,\bsgamma}(\bsz).$ In fact, under suitable choices of $\bsz$ (depending on $N$), both $R_{N,\alpha,d,\bsgamma}(\bsz)$ and $S_{N,\alpha,d,\bsgamma}(\bsz)$ tend to zero as $N\rightarrow \infty$, thereby ensuring that Assumption \ref{Assum:1} is eventually satisfied with a suitable number of function evaluations  $N.$ However, a good generating vector would also lead to a faster convergence rate of them, and then it is natural to construct such a good generating vector $\bsz$ by 
CBC construction with selection criterion that minimizes either $R_{N,\alpha,s,\bsgamma}(\bsz)$ or $S_{N,\alpha,s,\bsgamma}(\bsz)$ from the range $G_1(N)$ in Algorithm \ref{cbc_principle}. 

Note that
there is a concise computable form of the criterion \eqref{quantity}  when \(\alpha\) is a natural number:
\[
R^2_{N,\alpha,s,\bsgamma}(\bsz) = \frac{1}{N} \sum_{\bsx \in P_{N,\bsz}} \left[ -1+\prod_{j=1}^{s}\left(1+\gamma_j^2   (2\pi)^{2\alpha} \frac{(-1)^{\alpha+1}}{(2\alpha)!} B_{2\alpha}(x_j) \right) \right],
\]
where \(B_{2\alpha}\) is the Bernoulli polynomial of degree \(2\alpha\).
Now, the CBC construction for a good generating vector $\bsz$ of a rank-1 lattice rule proceeds as in Algorithm~\ref{Algorithm_1}.

\begin{algorithm}[t]
\caption{CBC for $R_{N,\alpha,s,\bsgamma}$}
\label{Algorithm_1}
    Let \(d, N \in \mathbb{N}\), \(\alpha > \frac{1}{2}\) and \(\bsgamma\) be given.
\begin{enumerate}
    \item Let \(z_1^* = 1\) and \(\ell = 1\).
    \item Compute \(R_{N,\alpha,\ell+1,\bsgamma}(z_1^*, \dots, z_\ell^*, z_{\ell+1})\) for all \(z_{\ell+1} \in \{1, \dots, N - 1\}\) and let
    \[
    z_{\ell+1}^* = \arg \min_{z_{\ell+1}} R_{N,\alpha,\ell+1,\bsgamma}(z_1^*, \dots, z_\ell^*, z_{\ell+1}).
    \]
    \item If \(\ell + 1 < d\), let \(\ell = \ell + 1\) and go to Step 2.
\end{enumerate}
\end{algorithm}
The necessary computational cost for the CBC algorithm can be made small by using the fast Fourier transform \cite{nuyens2006fast}, that we only need $O(d N\log N) $ arithmetic operations with $O(N)$ memory.



Similarly to Algorithm \ref{Algorithm_1}, we can search for generating vector $\bsz$ by another CBC construction that just replaces the quantity $R_{N,\alpha,s,\bsgamma}$ by the quantity $S_{N,\alpha,s,\bsgamma}$.  As mentioned in \cite{cai2025l2approximationusingrandomizedlattice}, for a given generating vector $\bsz=(z_1,\ldots,z_s),$  when $\alpha>1/2$ is an integer,
$S_{N,\alpha,s,\bsgamma}$ has a computable formula as

\begin{align*}
 \left[S_{N,\alpha,s, \bsgamma}\left(\bsz_{s-1}, z_{s}\right)\right]^2 & =\frac{1}{N} \sum_{k=0}^{N-1} \theta_{\bsz_{s-1}, \alpha,\bsgamma}(k) \left(1+\gamma_s ^2 \frac{(-1)^{\alpha+1}(2\pi)^{2\alpha}}{(2\alpha)!} B_{2\alpha}\left(\left\{\frac{kz_s}{N}\right\}\right) \right)^2 \\
 & \quad -\prod_{j=1}^{s} (1+2\zeta(4\alpha)\gamma_j^4),
\end{align*}
where we write
\[ \theta_{\bsz_{s-1}, \alpha,\bsgamma}(k) = \prod_{j=1}^{s-1} \left(1+\gamma_j ^2 \frac{(-1)^{\alpha+1}(2\pi)^{2\alpha}}{(2\alpha)!} B_{2\alpha}\left(\left\{\frac{kz_j}{N}\right\}\right) \right)^2 . \]
To be precise, the corresponding CBC algorithm is described as in Algorithm~\ref{Algorithm_2}.

\begin{algorithm}[t]
\caption{CBC for $S_{N,\alpha,s,\bsgamma}$}
\label{Algorithm_2}
   Let \(d, N \in \mathbb{N}\), \(\alpha > \frac{1}{2}\) and \(\bsgamma\) be given.
\begin{enumerate}
    \item Let \(z_1^* = 1\) and \(\ell = 1\).
    \item Compute \(S_{N,\alpha,\ell+1,\bsgamma}(z_1^*, \dots, z_\ell^*, z_{\ell+1})\) for all \(z_{\ell+1} \in \{1, \dots, N - 1\}\) and let
    \[
    z_{\ell+1}^* = \arg \min_{z_{\ell+1}} S_{N,\alpha,\ell+1,\bsgamma}(z_1^*, \dots, z_\ell^*, z_{\ell+1}).
    \]
    \item If \(\ell + 1 < d\), let \(\ell = \ell + 1\) and go to Step 2.
\end{enumerate}
\end{algorithm}
The following bounds for  $R_{N,\alpha,s,\bsgamma} $ and $S_{N,\alpha,s,\bsgamma} $ hold.
\begin{proposition}\label{quantity_proposition}
Let $N$ be a prime number, let $d\in\mathbb{N},$ and let $ \bsgamma=(\gamma_j)_{j\geq 1}$ be product weights. Assume that $\bsz=(z_1,\ldots,z_d  )$ is a generate vector found by CBC construction for the weighted Korobov space. Then for arbitrary $\tau \in[1/2,\alpha)$ and for any $s\in \{ 1,2,\ldots,d\}$  we have
\begin{align}\label{CBCerror}
R_{N,\alpha,s,\bsgamma}(\bsz_{s-1},z_s)\leq \frac{2^\tau}{N^{\tau}}\prod_{j=1}^s \left(1+2\gamma_j^{1/(2\tau)}\zeta(\alpha/\tau) \right)^{\tau},
\end{align}
and
\begin{align}\label{CBCSerror}
S_{N,\alpha,s,\bsgamma}(\bsz_{s-1},z_s)\leq \frac{1}{N^\tau}\prod_{j=1}^s \left(1+2^{4\alpha+1} \zeta(\alpha/\tau)\gamma_j^{1/(2\tau)} \right)^{2\tau}.
\end{align}
\end{proposition}
\begin{proof}
The inequality \eqref{CBCerror} is shown in \cite{kuo2003component} and \eqref{CBCSerror} is in \cite{dick2007lattice}.
\end{proof}
















