\subsection{CBC Constructions for Polynomial Lattice Rules}
We now turn to the construction of good polynomial lattice rules in the weighted Walsh space $H_{d,\alpha,\bsgamma}^{\wal}$.
In this setting, we need to replace the definition of the hyperbolic cross $\mathcal{A}_{d}(M)$ with
\begin{align*}
\breve{\Acal}_{d}(M)=\{\bsh\in \NN_0^d:\left(\breve{r}_{\alpha,\bsgamma}(\bsh)  \right)^2 \leq M \}.
\end{align*}
The size of this new set $\breve{\Acal}_{d}(M)$ can be estimated as follows:

\begin{lemma}\label{lem:size_index_set_Walsh}
    For any $M\ge 1$ and $\lambda\in (1/(2\alpha),1]$, it holds that
    \[ \left| \breve{\Acal}_{d}(M)\right|\leq M^{\lambda}\prod_{j=1}^{d}\left(1+\gamma_{j}^2\frac{b-1}{b^{2\alpha\lambda}-b}\right).\]
\end{lemma}
\begin{proof}
We have
\begin{align*}
    \left| \breve{\Acal}_{d}(M)\right| & = \sum_{\bsh\in \NN_0^d}\II_{\left(\breve{r}_{\alpha,\bsgamma}(\bsh)  \right)^2 \leq M}\leq \sum_{\bsh\in \NN_0^d}\left( \frac{M}{\left(\breve{r}_{\alpha,\bsgamma}(\bsh)  \right)^2}\right)^{\lambda} \\
    & = M^{\lambda}\sum_{\bsh\in \NN_0^d}\frac{1}{\left(\breve{r}_{\alpha,\bsgamma}(\bsh)  \right)^{\lambda}}= M^{\lambda}\prod_{j=1}^{d}\left(1+\gamma_{j}^2\frac{b-1}{b^{2\alpha\lambda}-b}\right).
\end{align*}
This completes the proof.
\end{proof}
We also have a concept of dual polynomial lattice analogous to the dual lattice.
\begin{definition}[Dual polynomial lattice]
    Let $m\in \NN$, and let $p\in \FF_b[x]$ and $\bsq\in (\FF_b[x])^d$ be such that $\deg(p)=m$ and $\deg(q_j)<m$ for all $j$. Then, the set
    \[ P^{\perp}(p,\bsq):=\left\{\bsh \in \NN_0^{d} \mid \tr_m(\bsh(x)) \cdot \bsq(x) \equiv 0 \pmod {p(x)}\right\} \]
    is called the dual polynomial lattice of the polynomial lattice point set $P(p,\bsq)$, where $\tr_m(h(x)):=\eta_0+\eta_1x+\cdots+\eta_{m-1}x^{m-1}$ for $h=\eta_0+\eta_1b+\cdots$ and is applied component-wise to a vector.
\end{definition}
Then the following property of polynomial lattice rules holds.
\begin{lemma}[Character property]\label{lem:character_polynomial}
    Let $m\in \NN$, and let $p\in \FF_b[x]$ and $\bsq\in (\FF_b[x])^d$ be such that $\deg(p)=m$ and $\deg(q_j)<m$ for all $j$. Then,
    \[ \frac{1}{b^m}\sum_{\bsx\in P(p,\bsq)} \wal_{\bsh}(\bsx)= \begin{cases}1 & \text{if $\bsh \in P^{\perp}(p,\bsq)$,} \\ 0 & \text{otherwise,}\end{cases} \]
    holds for any vector $\bsh \in \NN_0^{d}$.
\end{lemma}
 With the help of character property, we can deduce the analytic form of integration error \eqref{int_error_criterion}, in a similar way to that done in the previous subsection. Denote $f\in  \mathbb{P}^{\wal}_I (\Omega)\setminus\{\boldsymbol{0}\}$ by $f(\bsx)=\sum_{\bsh\in I} a_{\bsh} \wal_{\bsh}(\bsx)$. Then we have 

\begin{align*}
\frac{1}{b^m}\sum_{\bsx\in P(p,\bsq)} f^2(\bsx)&=\frac{1}{b^m}\sum_{\bsx\in P(p,\bsq)}\left|\sum_{\bsh \in I} a_{\bsh}\wal_{\bsh}(\bsx)\right|^2\\
&=\sum_{\bsh'\in I}\sum_{\bsh''\in I} a_{\bsh'}\overline{a_{\bsh''}}\left(\frac{1}{b^m}\wal_{\bsh'\ominus \bsh''}(\bsx)\right)\\
&=\sum_{\bsh'\in I} a_{\bsh'}\sum_{\substack{\bsh''\in I\\ \bsh'\ominus \bsh''\in P^{\perp}(p,\bsq)}} \overline{a_{\bsh''}}
\end{align*}
and 
\begin{align}\label{walsh_integration_error}
\frac{1}{b^m}\sum_{\bsx\in P(p,\bsq)} f^2(\bsx)-\int_{\Omega}f^2(\bsx)\rd \bsx=\sum_{\bsh'\in I} a_{\bsh'}\sum_{\substack{\bsh''\in I\\ \bsh'\ominus \bsh''\in P^{\perp}(p,\bsq)\setminus \{\bszero\}}} \overline{a_{\bsh''}}. \end{align}

Analogously to Lemma~\ref{lem:assumption_error_bounds}, we obtain the following error bounds for weighted Walsh spaces.
\begin{lemma}\label{lem:polynomial_error_bounds}
Let $m\in \NN$, and let $p\in \FF_b[x]$ and $\bsq\in (\FF_b[x])^d$ be such that $\deg(p)=m$ and $\deg(q_j)<m$ for all $j$. The following error bounds hold
\begin{align}\label{polynomial lattice_integration_error}
\emph{err}_{b^m}(f,\mathbb{P}^{\wal}_I(\Omega))\leq \sqrt{|I|}(\| f\|^{\wal}_{d,\alpha,\bsgamma})^2 \breve{R}_{b^m,\alpha,d,\bsgamma}(p,\bsq),
\end{align}
where we write
\begin{align*}
\breve{R}^2_{b^m,\alpha,d,\bsgamma}(p,\bsq)=\sum_{\bsh \in P^{\perp}(p,\bsq)\setminus \{\bszero\}}\frac{1}{(\breve{r}_{\alpha,\bsgamma}(\bsh))^2}.
\end{align*}
\end{lemma}

\begin{proof}
 Since any polynomial $f\in \PP^{\wal}_{I}(\Omega)$ is of finite degree, $f\in H^{\wal}_{d,\alpha,\bsgamma}$ for any $\alpha>1/2$ and it follows from \eqref{walsh_integration_error} that
\begin{align*}
\left| \int_{\Omega} f^2(\bsx) \rd \bsx-\frac{1}{b^m}\sum_{\bsx\in P(p,\bsq)} f^2(\bsx)  \right|\leq \sum_{\bsh'\in I} |a_{\bsh'}|\sum_{\substack{\bsh''\in I\\ \bsh'\ominus \bsh''\in P^{\perp}(p,\bsq)\setminus \{\bszero\}}} |a_{\bsh''}|.
\end{align*}
Then, by using the Cauchy–-Schwarz inequality twice, we obtain
\begin{align*}
\text{err}_{b^m}(f,\mathbb{P}^{\wal}_I(\Omega))&\leq  \breve{R}_{b^m,\alpha,d,\bsgamma}(p,\bsq)\\
&\qquad\times\sum_{\bsh' \in I} |a_{\bsh'}|\left(\sum_{\substack{\bsh''\in I\\ \bsh'\ominus \bsh''\in P^{\perp}(p,\bsq)\setminus \{\bszero\}}} |a_{\bsh''}|^2 (\breve{r}_{\alpha,\bsgamma}(\bsh'\ominus \bsh''))^2\right)^{1/2} \\
&\leq \| p\|^{\wal}_{d,\alpha,\bsgamma} \breve{R}_{b^m,\alpha,d,\bsgamma}(p,\bsq)\\
&\qquad\times\sum_{\bsh'\in I}|a_{\bsh'}|\left( \sup_{\substack{\bsh''\in I\\ \bsh'\ominus \bsh''\in P^{\perp}(p,\bsq)\setminus \{\bszero\}}} \frac{(\breve{r}_{\alpha,\bsgamma}(\bsh'\ominus \bsh''))^2}{(\breve{r}_{\alpha,\bsgamma}(\bsh''))^2}\right)^{1/2} \\
&\leq (\| p\|^{\wal}_{d,\alpha,\bsgamma})^2 \breve{R}_{b^m,\alpha,d,\bsgamma}(p,\bsq)\\
&\qquad\times\left( \sum_{\bsh'\in I}\frac{1}{(\breve{r}_{\alpha,\bsgamma}(\bsh'))^2}\sup_{\substack{\bsh''\in \NN_0^d\\ \bsh'\ominus \bsh''\in P^{\perp}(p,\bsq)\setminus \{\bszero\}}} \frac{(\breve{r}_{\alpha,\bsgamma}(\bsh'\ominus \bsh''))^2}{(\breve{r}_{\alpha,\bsgamma}(\bsh''))^2}\right)^{1/2}.
\end{align*}

By using Lemma~\ref{lem:mu1_property}, for any $h,k\in \NN_0$, it holds that
\begin{align*}
    \breve{r}_{\alpha,\gamma}(h)  =\max\left\{ 1,\frac{b^{\alpha\mu_1(h)}}{\gamma}\right\} &\leq \max\left\{ 1,\frac{b^{\alpha\mu_1(k)}}{\gamma}, \frac{b^{\alpha\mu_1(h\ominus k)}}{\gamma}\right\}\\ &\leq \max\left\{ \breve{r}_{\alpha,\gamma}(k), \breve{r}_{\alpha,\gamma}(h\ominus k)\right\}\\
    & \leq \breve{r}_{\alpha,\gamma}(k) \breve{r}_{\alpha,\gamma}(h\ominus k).
\end{align*} 
It implies that, for any $\bsh',\bsh''\in \NN_0^d$, we have
\begin{align*}\frac{(\breve{r}_{\alpha,\bsgamma}(\bsh'\ominus \bsh''))^2}{(\breve{r}_{\alpha,\bsgamma}(\bsh''))^2}&=\frac{(\breve{r}_{\alpha,\bsgamma}(\bsh''\ominus \bsh'))^2}{(\breve{r}_{\alpha,\bsgamma}(\bsh''))^2}\\
&\leq \frac{(\breve{r}_{\alpha,\bsgamma}(\bsh'')\breve{r}_{\alpha,\bsgamma}((\bsh''\ominus \bsh')\ominus \bsh''))^2}{(\breve{r}_{\alpha,\bsgamma}(\bsh''))^2}=(\breve{r}_{\alpha,\bsgamma}(\bsh'))^2.
\end{align*}
Applying this inequality, we obtain the bound shown in \eqref{polynomial lattice_integration_error}. 
\end{proof}

If $I=\breve{\Acal}_d(M)$ for some $M\geq 1$, it follows from the definition of the weighted Walsh space that
\[ (\| p\|^{\wal}_{d,\alpha,\bsgamma})^2 = \sum_{\bsh\in I}|a_{\bsh}|^2(\breve{r}_{\alpha,\bsgamma}(\bsh))^2\leq M\sum_{\bsh\in I}|a_{\bsh}|^2\leq M\|p\|_{L_2}^2.\]
Moreover, for the error bound \eqref{polynomial lattice_integration_error}, the size of the index set is bounded above as shown in Lemma~\ref{lem:size_index_set_Walsh}. Thus, the remaining task is to find good $p$ and $\bsq$ such that $\breve{R}_{b^m,\alpha,d,\bsgamma}(p,\bsq)$ becomes small. Here, CBC construction can be used for the criteria as in Algorithm~\ref{Algorithm_4}.
Although we omit the detailed derivations, we have a computable formula for $\breve{R}_{b^m,\alpha,d,\bsgamma}(p,\bsq)$ as
\[  \breve{R}^2_{b^m,\alpha,d,\bsgamma}(p,\bsq)=-1+\frac{1}{b^m}\sum_{\bsx\in P(p,\bsq)}\prod_{j=1}^{d}\left( 1+\gamma_j^2 \phi_{\alpha}(x_j)\right),\]
where
\begin{align*}
    \phi_{\alpha}(x)
    &= \sum_{h=1}^{\infty} \frac{\wal_h(x)}{b^{2\alpha \mu_1(h)}}
     = \sum_{\ell=1}^{\infty} \frac{1}{b^{2\alpha \ell}} \sum_{h=b^{\ell-1}}^{b^{\ell}-1} \wal_h(x) \\
    &= 
    \begin{cases}
        \dfrac{b-1}{b^{2\alpha} - b}, & \text{if } x = 0, \\[2ex]
        \dfrac{b-1}{b^{2\alpha} - b}
        - \dfrac{1}{b^{2\alpha c_0}} \cdot \dfrac{b^{2\alpha} - 1}{b^{2\alpha} - b},
        & \begin{aligned}
            &\text{if } x = \dfrac{x_1}{b} + \dfrac{x_2}{b^2} + \cdots, \\
            & \text{ with } x_1 = \cdots = x_{c_0-1} = 0\text{ and } x_{c_0} \neq 0.
        \end{aligned}
    \end{cases}
\end{align*}

\begin{algorithm}[t]
\caption{CBC for polynomial lattice rules}
\label{Algorithm_4}
    Let \(d, m \in \mathbb{N}\), \(\alpha > \frac{1}{2}\) and \(\bsgamma\) be given. Let $p\in \FF_b[x]$ be irreducible with $\deg(p)=m$.
\begin{enumerate}
    \item Let \(q_1^* = 1\in \FF_b[x]\) and \(\ell = 1\).
    \item Compute \(\breve{R}_{b^m,\alpha,\ell+1,\bsgamma}(p,(q_1^*, \dots, q_\ell^*, q_{\ell+1}))\) for all $q_{\ell+1}\in\FF_b[x]$ such that $\deg(q_{\ell+1})<m$ and let
    \[
    q_{\ell+1}^* = \arg \min_{z_{\ell+1}} \breve{R}_{b^m,\alpha,\ell+1,\bsgamma}(p,(q_1^*, \dots, q_\ell^*, q_{\ell+1})).
    \]
    \item If \(\ell + 1 < d\), let \(\ell = \ell + 1\) and go to Step 2.
\end{enumerate}
\end{algorithm}



The following bound for $\breve{R}_{b^m,\alpha,d,\bsgamma}(p,\bsq)$ holds.
\begin{proposition}\label{polynomial_quantity_proposition}
For $m\in \NN$, let $p\in \FF_b[x]$ be irreducible with $\deg(p)=m$, let $d\in\mathbb{N},$ and let $ \bsgamma=(\gamma_j)_{j\geq 1}$ be product weights. Assume that $\bsq=(q_1,\ldots,q_d)\in (\FF_b[x])^d$ is a generating vector constructed by the CBC algorithm for the weighted Walsh space. Then, for arbitrary $\tau \in[1/(2\alpha),1)$ and for any $s\in \{ 1,2,\ldots,d\}$, we have
\begin{align*}
\breve{R}_{b^m,\alpha,s,\bsgamma}(p,(q_1,\ldots,q_s))\leq \left( \frac{2}{b^m-1}\left(-1+\prod_{j=1}^{s}\left(1+\gamma_{j}^2\frac{b-1}{b^{2\alpha\lambda}-b}\right)\right)\right)^{1/(2\lambda)}.
\end{align*}
\end{proposition}

 Similarly to Lemma~\ref{lem:assumption_error_bounds}, we can derive another bound on $\text{err}_{b^m}(f,\mathbb{P}^{\wal}_I(\Omega))$ with a different computable quality criterion in this setting. However, showing an upper bound on that criterion is not straightforward, so that we do not discuss that bound in this work. Investigating another bound remains a topic for future research.



