\section{Lasso QMC hyperinterpolation}\label{sec:lasso}
 The QMC hyperinterpolation is good at dealing with high-dimensional approximation problems about smooth functions. However, when we construct $\mathcal{Q}_I f$ using discrete function values, it is often the case that we cannot avoid noise in the sampling process, such as the observing error and the rounding error. To extend QMC hyperinterpolation to more realistic problems, we combine Lasso (``Least Absolute Shrinkage and Selection Operator'') with $\mathcal{Q}_I f$ to reduce noise. We first decompose the function approximation problem $\Vert \mathcal{Q}_If^{\boldsymbol{\epsilon}}-f\Vert_{L_2}$ into an undetermined polynomial approximation problem $\Vert p-\mathcal{Q}_I f\Vert_{L_2}.$ Then discretize the \(L_2\) norm using quadrature points that satisfy the exactness condition~\eqref{hyper_exact_assump} for all \(p \in \mathbb{P}_I(\Omega)\), and introduce an additional \(\ell_1\)-regularization term. Note that the quadrature points used to discretize the \(L_2\) norm are different from those used in the construction of \(\mathcal{Q}_I f\). This leads to a new approximation scheme, which is analyzed using statistical tools. Specifically, let $\boldsymbol{\epsilon} \in \mathbb{R}^{N}$ have independent components $\epsilon_j \sim \mathcal{N}(0, \sigma^2).$ Consider the $L_2$ approximation of $f\in L_2(\Omega)$ by $\mathcal{Q}_If$ with $N$ noisy data $f^\epsilon(\bsx_n)=f(\bsx_n)+\epsilon_n$ over $N$ quadrature points $\bsx_n,\;n=0,\ldots,N-1.$  Then 
 \begin{align*}
\Vert \mathcal{Q}_I f^\epsilon-f\Vert_{L_2}\leq \Vert \mathcal{Q}_I f^\epsilon-\mathcal{Q}_I f\Vert_{L_2}+\Vert \mathcal{Q}_I f-f\Vert_{L_2}.
 \end{align*}
 Since 
 \begin{align*}
\mathcal{Q}_I f^{\epsilon}=\sum_{\bsh\in I}\left( \frac{1}{N}\sum_{n=0} ^{N-1} f(\bsx_n)\overline{q_{\bsh}(\bsx_n) }+\frac{1}{N}\sum_{n=0} ^{N-1} \epsilon_n\overline{q_{\bsh}(\bsx_n) }\right)q_{\bsh}(\bsx)
 \end{align*}
 and
 \begin{align*}
\Vert \mathcal{Q}_I f^\epsilon-\mathcal{Q}_I f\Vert_{L_2}^2=\int_{\Omega}\left(\frac{1}{N} \sum_{n=0}^{N-1}\epsilon_n \left(\sum_{\bsh\in I}q_{\bsh}(\bsx)\overline{q_{\bsh}}(\bsx_n) \right) \right)^2 \rd \bsx,
 \end{align*}
with $\mathbb{E}(\epsilon_n)=0,\;n=0,\ldots,N-1,$  by considering the expectation of  $\Vert \mathcal{Q}_I f^\epsilon-\mathcal{Q}_I f\Vert_{L_2}^2$ for $\epsilon,$ we have
\begin{align*}
\mathbb{E} \left(\Vert \mathcal{Q}_I f^\epsilon-\mathcal{Q}_If\Vert_{L_2}^2\right)&=\frac{\sigma^2}{N^2}\sum_{n=0}^{N-1}\int_{\Omega} \left(\sum_{\bsh\in I}q_{\bsh}(\bsx)\overline{q_{\bsh}}(\bsx_n) \right)^2 \rd \bsx \\
&=\frac{\sigma^2}{N^2}\sum_{n=0}^{N-1}\sum_{\bsh\in I} q_{\bsh}(\bsx_n)\overline{q_{\bsh}(\bsx_n)} =\frac{\sigma^2|I|}{N},
\end{align*}
where the second equality follows from the orthogonality of $q_{\bsh}$. Then, by the Cauchy–-Schwarz inequality, we have 
\begin{align}\label{expection_noiseerror}
\mathbb{E} \left(\Vert \mathcal{Q}_I f^\epsilon-\mathcal{Q}_If\Vert_{L_2}\right)\leq \sqrt{\mathbb{E} \left(\Vert \mathcal{Q}_I f^\epsilon-\mathcal{Q}_If\Vert_{L_2}^2\right)}= \sigma\sqrt{\frac{|I|}{N}}  .
 \end{align}
The upper bound \eqref{expection_noiseerror} will increase with $|I|,$, making it difficult to get a reasonable $L_2$ approximation error bound by QMC hyperinterpolation with noisy data.  To obtain a more stable approximation scheme for $f\in L_2(\Omega)$ with noisy data, we wish to design a new approximation scheme related to QMC hyperinterpolation based on regularization techniques.

For short, let us write $\mathcal{Q}_I f:=\sum_{\bsh\in I} \tilde{\beta}_{\bsh} q_{\bsh}(\bsx),$ and assume that a new approximation scheme is given by $p=\sum_{\bsh\in I}\beta_{\bsh}q_{\bsh}(\bsx)$ with undetermined coefficients $\beta_{\bsh}.$ 
Denoting $\boldsymbol{\beta}=(\beta_{\bsh})_{\bsh\in I} $ and $\tilde{\boldsymbol{\beta}}=(\tilde{\beta}_{\bsh})_{\bsh\in I}, $ given an $\ell_1$ regularization penalty to $p$, we have the following $\ell_1$-regularization least squares problem. 
\begin{align}\label{l1_model}
\min_{p\in \mathbb{P}_I(\Omega)}\left\{\Vert p-\mathcal{Q}_I f\Vert_{L_2}^2+\lambda\Vert \boldsymbol{\beta} \Vert_1\right\},\;\;\;\;\lambda>0.
\end{align}
It should be noted that the integration for $L_2$ error in \eqref{l1_model} can be accurately evaluated using the QMC rules that satisfy the exactness assumption \eqref{hyper_exact_assump}, and then we make a new data sampling (with noise $\epsilon$) for both $p$ and $\mathcal{Q}_I f$ over quadrature points of QMC rules for \eqref{hyper_exact_assump} and the model \eqref{l1_model} can be rewritten into the matrix form
\begin{align}\label{matrix_ell_1}
\hat{\boldsymbol{\beta}}: =\arg\min_{\boldsymbol{\beta}}\left\{\frac{1}{N}\Vert \mathbf{y}-\mathbf{X}\boldsymbol{\beta} \Vert_2^2+\lambda\Vert \boldsymbol{\beta} \Vert_1\right\},\;\;\;\;\lambda>0,
\end{align}
where $\mathbf{X} = \left( q_{\bsh}(\bsx_n') \right)_{\bsh \in I,\; n = 0,\ldots,N-1}$ is the Fourier matrix evaluated at quadrature points of QMC rules satisfy \eqref{hyper_exact_assump}, and $ \mathbf{y}$ is the newly function values (with noisy $\epsilon$) of $\mathcal{Q}_I f$ over $\bsx_n',$ that is
\begin{align*}
\mathbf{y} = \mathbf{X}\tilde{\boldsymbol{\beta}} + \boldsymbol{\epsilon} \in \mathbb{R}^{N}.
\end{align*}
Then we have the following theorem about the solution to \eqref{matrix_ell_1}.




\begin{theorem}\label{matrix_X*X=I}
For a given finite index set $I$ with finite cardinality $|I|,$ and QMC rules that  satisfy the exactness assumption \eqref{hyper_exact_assump}, the unique solution of Lasso \eqref{matrix_ell_1} is 
\begin{align}\label{lasso_analytic_solution}
\hat{\boldsymbol{\beta}}=\eta_S\left(\frac{1}{N}  \mathbf{X}^* \mathbf{y},\lambda\right),
\end{align}
where $\eta_S(a,k)$ is a \emph{soft thresholding operator} \cite{Donoho_1994}
\begin{equation*}
 \eta_{S}(a,k):=\max(0,a-k)+\min(0,a+k).
\end{equation*}
\end{theorem}
\begin{proof}
Note that any two distinct columns of the Fourier matrix $\mathbf{X}$ are either orthogonal or equal to each other. This follows because
\begin{align*}
\left(  \mathbf{X^* X}\right)_{\bsh',\;\bsh}=\sum_{n=0}^{N-1} q_{\bsh}(\bsx_n')\overline{q_{\bsh'}(\bsx_n')}=\begin{cases}
N\;\; if \;\bsh=\bsh'\\
0\;\; else.
\end{cases}
\end{align*}
Then by \cite[Theorem 3.4]{Lasso_hyper_2021}, we have \eqref{lasso_analytic_solution}.
\end{proof}
By denoting  
\[
\boldsymbol{\epsilon}' = \frac{1}{N} \mathbf{X}^* \boldsymbol{\epsilon} \quad \text{and} \quad \boldsymbol{\epsilon}'' = \left(\frac{1}{N} \sum_{n=0}^{N-1} \epsilon_n \overline{q_{\bsh}(\bsx_n)}\right)_{\bsh\in I},\;
\]  
it is clear that both \(\boldsymbol{\epsilon}'\) and \(\boldsymbol{\epsilon}''\) follow the distribution \(\mathcal{N}(0, \sigma^2/N)\). Therefore, the analytical solution \(\hat{\boldsymbol{\beta}}\) coincides with the coefficients obtained by applying a soft-thresholding operator to \(\mathcal{Q}_I f^{\epsilon}\), since  
\[
\frac{1}{N} \mathbf{X}^* \mathbf{y} = \frac{1}{N} \mathbf{X}^*\mathbf{X}\tilde{\boldsymbol{\beta}}+\frac{1}{N}\mathbf{X}^*\boldsymbol{\epsilon}=\tilde{\boldsymbol{\beta}} + \boldsymbol{\epsilon}'
\]  
and the coefficients of \(\mathcal{Q}_I f^{\boldsymbol{\epsilon}}\) correspond to \(\tilde{\boldsymbol{\beta}} + \boldsymbol{\epsilon}''\).



We directly define this new approximation scheme by Lasso QMC hyperinterpolation, which is similar to Lasso hyperinterpolation proposed in \cite{Lasso_hyper_2021}. 
 \begin{definition}[Lasso QMC hyperinterpolation]
     Given a real-valued function $f\in L_2(\Omega),$ and an index set $I$ with finite cardinality $|I|$, assume that a QMC rule with $N$ quadrature points satisfies Assumption \ref{Assum:1}. Then the Lasso QMC hyperinterpolation is defined by
     \begin{align*}
\mathcal{Q}^{\lambda}_I f:=\sum_{\bsh\in I}\eta_{S}\left(\left< f,q_{\bsh}\right>_N,\lambda\right) q_{\bsh}.
\end{align*}
 \end{definition}
The quadrature points for Lasso QMC hyperinterpolation are not required to satisfy the exactness assumption, which is the main difference from Lasso hyperinterpolation. The following compatibility condition and the consistency theorem can be found in \cite[Chapter 6]{Peter_Lasso_book_2011}.
\begin{definition}[Compatibility condition]
Assume that \( S_0 \subset \{1, \ldots, |I| \} \), and define
\[
\boldsymbol{\beta}_{S_0} := \boldsymbol{\beta} \cdot \mathbf{1}_{S_0},
\]
where \( \mathbf{1}_{S_0} \in \mathbb{R}^{|I|} \) is the indicator (or characteristic) function of the set \( S_0 \). For the regularization model \eqref{matrix_ell_1}, we say that the compatibility condition is met for the set $S_0$, if for some $\phi_0> 0,$  and for all $\boldsymbol{\beta}$ satisfying $\Vert \boldsymbol{\beta}_{S_0^c} \Vert_1\leq 3\Vert\boldsymbol{\beta}_{S_0} \Vert_1,$ it holds that
\begin{align*}
\Vert \boldsymbol{\beta}_{S_0} \Vert_1^2\leq \left(\boldsymbol{\beta}^* \hat{\Sigma} \boldsymbol{\beta}\right) s_0/\phi_0^2,
\end{align*}
where $ \hat{\Sigma}=\frac{1}{N}\mathbf{X}^*\mathbf{X}$ and $s_0=|S_0|.$
\end{definition}
\begin{theorem}[Consistency of the Lasso]
For the regularization model \eqref{matrix_ell_1}, assume that the compatibility condition
holds for $S_0$. For some $t>0,$ let the regularization parameter be
\begin{align*}
\lambda=4\hat{\sigma}\sqrt{ \frac{t^2+2\log |I| }{N}},
\end{align*}
where $ \hat{\sigma}$ is some estimator of $\sigma.$  Then with probability at least $1-\mu,$ where 
\begin{align*}
\mu:=2\exp(-t^2/2)+\mathbf{P}(\hat{\sigma}\leq \sigma),
\end{align*}
we have 
\begin{align*}
\Vert \mathbf{X}(\hat{\boldsymbol{\beta}}-\tilde{\boldsymbol{\beta}})\Vert_2^2/N+\lambda\Vert \hat{\boldsymbol{\beta}}-\tilde{\boldsymbol{\beta}}\Vert_1\leq 4\lambda^2 s_0 /\phi_0^2,
\end{align*}
with $\hat{\boldsymbol{\beta}},\;\tilde{\boldsymbol{\beta}} $ corresponding to the coefficients of $\mathcal{Q}_I f$ and $\mathcal{Q}_I^\lambda f^{\epsilon}$ respectively.
\end{theorem}
With the consistency of the Lasso and the exactness assumption of quadrature rules, we can deduce the following result.
\begin{corollary}
\begin{align}\label{lasso_denoise_error}
\Vert \mathbf{X}(\hat{\boldsymbol{\beta}}-\tilde{\boldsymbol{\beta}})\Vert_2^2/N=\Vert \mathcal{Q}_I ^{\lambda} f^{\epsilon}-\mathcal{Q}_I f\Vert_{L_2} \leq \frac{2\lambda\sqrt{s_0}  }{\phi_0},
\end{align}
with a larger probability for the proper choice of $\lambda.$
The upper bound \eqref{lasso_denoise_error} shows the great denoising ability of Lasso, since it reduces the term $|I|$ in \eqref{expection_noiseerror} by $\log |I|.$ 
\end{corollary}













