\section{Walsh spaces are algebra}\label{app:Walsh_algebra}
Following \cite[Appendix~2]{Novak2004}, here we prove that the Walsh space $H_{d,\alpha,\bsgamma}^{\wal}$ is an algebra for any $\alpha>1/2$.
That is, for any $f,g\in H_{d,\alpha,\bsgamma}^{\wal}$, we have $fg\in H_{d,\alpha,\bsgamma}^{\wal}$ and
\[ \| fg\|_{d,\alpha,\bsgamma}^{\wal}\leq \breve{C}(d) \|f\|_{d,\alpha,\bsgamma}^{\wal} \|g\|_{d,\alpha,\bsgamma}^{\wal} \quad \text{with $\breve{C}(d)=2^d \prod_{j=1}^{d}\left(1+\gamma_{j}^2\frac{b-1}{b^{2\alpha}-b}\right)^{1/2}$.} \]

In what follows, we denote the digit-wise addition and subtraction modulo $b$ by $\oplus$ and $\ominus$, respectively. As preparation, we prove the following lemma.
\begin{lemma}\label{lem:mu1_property}
For any $h,k\in \NN_0$, it holds that
\[ \mu_1(h)\leq \max\left( \mu_1(k), \mu_1(h\ominus k)\right).\] 
\end{lemma}
\begin{proof}
    The case with $\mu_1(h)\leq \mu_1(k)$ is trivial. For the case with $\mu_1(h)> \mu_1(k)$, we have $\mu_1(h\ominus k)=\mu_1(h)$. Thus, the result holds with equality.
\end{proof}

It follows from \cite[Corollary~A.5]{Dick_Pillichshammer_2010} that
\begin{align*}
    f(\bsx)g(\bsx) = \sum_{\bsh,\bsk\in \NN_0^d}\breve{f}(\bsh)\breve{g}(\bsk)\wal_{\bsh\oplus \bsk}(\bsx) = \sum_{\bsk\in \NN_0^d}\left(\sum_{\bsh\in \NN_0^d}\breve{f}(\bsh)\breve{g}(\bsk\ominus \bsh)\right)\wal_{\bsk}(\bsx)
\end{align*}
Thus, we have
\[ \left(\| fg\|_{d,\alpha,\bsgamma}^{\wal}\right)^2 = \sum_{\bsk\in \NN_0^d}\breve{r}_{\alpha,\bsgamma}^2(\bsk)\left|\sum_{\bsh\in \NN_0^d}\breve{f}(\bsh)\breve{g}(\bsk\ominus \bsh)\right|^2. \]

By using Lemma~\ref{lem:mu1_property}, for any fixed $\bsk\in \NN_0^d$, we obtain
\begin{align*}
    \breve{r}_{\alpha,\bsgamma}(\bsk) & = \prod_{j=1}^{d} \max\left(1,\frac{b^{\alpha \mu_1(k_j)}}{\gamma_{j}}\right)\leq \prod_{j=1}^{d} \max\left(1,\frac{b^{\alpha \mu_1(h_j)}+b^{\alpha \mu_1(k_j\ominus h_j)}}{\gamma_{j}}\right)\\
%    & \leq \prod_{j=1}^{d} \left(\max\left(1,\frac{b^{\alpha \mu_1(h_j)}}{\gamma_{j}}\right)+\max\left(1,\frac{b^{\alpha \mu_1(k_j\ominus h_j)}}{\gamma_{j}}\right)\right)\\
    & = \sum_{u\subseteq \{1,\ldots,d\}} \prod_{j\in u}\max\left(1,\frac{b^{\alpha \mu_1(h_j)}}{\gamma_{j}}\right)\prod_{j'\in -u}\max\left(1,\frac{b^{\alpha \mu_1(k_j\ominus h_j)}}{\gamma_{j}}\right)\\
    & = \sum_{u\subseteq \{1,\ldots,d\}} \breve{r}_{\alpha,\bsgamma}(\bsh_u,\bszero)\breve{r}_{\alpha,\bsgamma}((\bsk\ominus \bsh)_{-u},\bszero),
\end{align*}
for all $\bsh\in \NN_0^d$. For $u\subseteq \{1,\ldots,d\}$, let us define
\begin{align*}
    F_u(\bsx) & = \sum_{\bsh\in \NN_0^d}\left|\breve{f}(\bsh)\right| \breve{r}_{\alpha,\bsgamma}(\bsh_u,\bszero)\wal_{\bsh}(\bsx), \\
    G_u(\bsx) & = \sum_{\bsh\in \NN_0^d}\left|\breve{g}(\bsh)\right| \breve{r}_{\alpha,\bsgamma}(\bsh_u,\bszero)\wal_{\bsh}(\bsx),
\end{align*}
both of which are well-defined functions in $L_2([0,1)^d)$, since $\breve{r}_{\alpha,\bsgamma}(\bsh_u,\bszero)\leq \breve{r}_{\alpha,\bsgamma}(\bsh)$ for all $\bsh$ and $u$, and moreover, $f$ and $g$ belong to $H_{d,\alpha,\bsgamma}^{\wal}$. Using these functions and the triangle inequality, for any $\bsk\in \NN_0^d$, we have
\begin{align*}
    \breve{r}_{\alpha,\bsgamma}(\bsk)\left|\sum_{\bsh\in \NN_0^d}\breve{f}(\bsh)\breve{g}(\bsk\ominus \bsh)\right| & \leq \breve{r}_{\alpha,\bsgamma}(\bsk)\sum_{\bsh\in \NN_0^d}|\breve{f}(\bsh)|\, |\breve{g}(\bsk\ominus \bsh)|\\
    & \leq \sum_{u\subseteq \{1,\ldots,d\}} \sum_{\bsh\in \NN_0^d}\breve{r}_{\alpha,\bsgamma}(\bsh_u,\bszero)\breve{r}_{\alpha,\bsgamma}((\bsk\ominus \bsh)_{-u},\bszero) \\
    &\qquad\times|\breve{f}(\bsh)|\, |\breve{g}(\bsk\ominus \bsh)|\\
    & = \sum_{u\subseteq \{1,\ldots,d\}} \sum_{\bsh\in \NN_0^d}\breve{F}_u(\bsh)\breve{G}_{-u}(\bsk\ominus \bsh).
\end{align*}
This leads to a bound
\begin{align*}
    \left(\| fg\|_{d,\alpha,\bsgamma}^{\wal}\right)^2 & \leq \sum_{\bsk\in \NN_0^d}\left( \sum_{u\subseteq \{1,\ldots,d\}} \sum_{\bsh\in \NN_0^d}\breve{F}_u(\bsh)\breve{G}_{-u}(\bsk\ominus \bsh)\right)^2 \\
    & \leq 2^d\sum_{u\subseteq \{1,\ldots,d\}}\sum_{\bsk\in \NN_0^d} \left( \sum_{\bsh\in \NN_0^d}\breve{F}_u(\bsh)\breve{G}_{-u}(\bsk\ominus \bsh)\right)^2,
\end{align*} 
where the last inequality follows from the Cauchy--Schwarz inequality.

For fixed $u$, we give a bound on 
\[ a_u = \sum_{\bsk\in \NN_0^d}\left( \sum_{\bsh\in \NN_0^d}\breve{F}_u(\bsh)\breve{G}_{-u}(\bsk\ominus \bsh)\right)^2. \]
We have
\begin{align*}
    a_u & = \sum_{\substack{\bsk_u\in \NN_0^{|u|}\\ \bsk_{-u}\in \NN_0^{d-|u|}}}\left( \sum_{\substack{\bsh_u\in \NN_0^{|u|}\\ \bsh_{-u}\in \NN_0^{d-|u|}}}\breve{F}_u(\bsh_u,\bsh_{-u})\breve{G}_{-u}(\bsk_u\ominus \bsh_u, \bsk_{-u}\ominus \bsh_{-u})\right)^2\\
%    & = \sum_{\substack{\bsk_u\in \NN_0^{|u|}\\ \bsk_{-u}\in \NN_0^{d-|u|}}}\left( \sum_{\substack{\bsh_u\in \NN_0^{|u|}\\ \bsh_{-u}\in \NN_0^{d-|u|}}}\breve{F}_u(\bsk_u\ominus \bsh_u,\bsh_{-u})\breve{G}_{-u}(\bsh_u, \bsk_{-u}\ominus \bsh_{-u})\right)^2\\
    & = \sum_{\substack{\bsk_u\in \NN_0^{|u|}\\ \bsk_{-u}\in \NN_0^{d-|u|}}}\sum_{\substack{\bsh_u\in \NN_0^{|u|}\\ \bsh_{-u}\in \NN_0^{d-|u|}}}\sum_{\substack{\bsl_u\in \NN_0^{|u|}\\ \bsl_{-u}\in \NN_0^{d-|u|}}}\breve{F}_u(\bsk_u\ominus \bsh_u,\bsh_{-u})\breve{F}_u(\bsk_u\ominus \bsl_u,\bsl_{-u})\\
    & \qquad \qquad \qquad \times \breve{G}_{-u}(\bsh_u, \bsk_{-u}\ominus \bsh_{-u}) \breve{G}_{-u}(\bsl_u, \bsk_{-u}\ominus \bsl_{-u}).
\end{align*}
Here, applying the Cauchy--Schwarz inequality leads to
\begin{align*}
    & \sum_{\bsk_u\in \NN_0^{|u|}}\breve{F}_u(\bsk_u\ominus \bsh_u,\bsh_{-u})\breve{F}_u(\bsk_u\ominus \bsl_u,\bsl_{-u})\\
    & \leq \left(\sum_{\bsk_u\in \NN_0^{|u|}}(\breve{F}_u(\bsk_u\ominus \bsh_u,\bsh_{-u}))^2\right)^{1/2}\left(\sum_{\bsk_u\in \NN_0^{|u|}}(\breve{F}_u(\bsk_u\ominus \bsl_u,\bsl_{-u}))^2\right)^{1/2}\\
    & = \left(\sum_{\bsk_u\in \NN_0^{|u|}}(\breve{F}_u(\bsk_u,\bsh_{-u}))^2\right)^{1/2}\left(\sum_{\bsk_u\in \NN_0^{|u|}}(\breve{F}_u(\bsk_u,\bsl_{-u}))^2\right)^{1/2}.
\end{align*}
Similarly, we have
\begin{align*}
    & \sum_{\bsk_{-u}\in \NN_0^{d-|u|}}\breve{G}_{-u}(\bsh_u, \bsk_{-u}\ominus \bsh_{-u}) \breve{G}_{-u}(\bsl_u, \bsk_{-u}\ominus \bsl_{-u}) \\
    & \leq \left(\sum_{\bsk_{-u}\in \NN_0^{d-|u|}}(\breve{G}_{-u}(\bsh_u, \bsk_{-u}))^2\right)^{1/2}\left(\sum_{\bsk_{-u}\in \NN_0^{d-|u|}}(\breve{G}_{-u}(\bsl_u, \bsk_{-u}))^2\right)^{1/2}.
\end{align*}
With these bounds, we further have
\begin{align*}
    a_u & \le \left(\sum_{\bsh_{-u}\in \NN_0^{d-|u|}}\left(\sum_{\bsk_u\in \NN_0^{|u|}}(\breve{F}_u(\bsk_u,\bsh_{-u}))^2\right)^{1/2}\right)^{2}\\
    & \qquad\qquad\qquad\times \left(\sum_{\bsh_u\in \NN_0^{|u|}}\left(\sum_{\bsk_{-u}\in \NN_0^{d-|u|}}(\breve{G}_{-u}(\bsh_u, \bsk_{-u}))^2\right)^{1/2}\right)^2.
\end{align*}
%\begin{align*}
%    a_u &\leq\sum_{\bsh_{-u}\in \NN_0^{d-|u|}}\sum_{\bsl_{-u}\in \NN_0^{d-|u|}}\left(\sum_{\bsk_u\in \NN_0^{|u|}}(\breve{F}_u(\bsk_u,\bsh_{-u}))^2\right)^{1/2}\left(\sum_{\bsk_u\in \NN_0^{|u|}}(\breve{F}_u(\bsk_u,\bsl_{-u}))^2\right)^{1/2}\\
%    &\quad\times\sum_{\bsh_u\in \NN_0^{|u|}}\sum_{\bsl_u\in \NN_0^{|u|}}\left(\sum_{\bsk_{-u}\in \NN_0^{d-|u|}}(\breve{G}_{-u}(\bsh_u, \bsk_{-u}))^2\right)^{1/2}\left(\sum_{\bsk_{-u}\in \NN_0^{d-|u|}}(\breve{G}_{-u}(\bsl_u, \bsk_{-u}))^2\right)^{1/2}\\
%    & = \left(\sum_{\bsh_{-u}\in \NN_0^{d-|u|}}\left(\sum_{\bsk_u\in \NN_0^{|u|}}(\breve{F}_u(\bsk_u,\bsh_{-u}))^2\right)^{1/2}\right)^{2}\\
%    &\qquad\qquad\qquad\times \left(\sum_{\bsh_u\in \NN_0^{|u|}}\left(\sum_{\bsk_{-u}\in \NN_0^{d-|u|}}(\breve{G}_{-u}(\bsh_u, \bsk_{-u}))^2\right)^{1/2}\right)^2.
%\end{align*}
Regarding the last two factors, it holds that
\begin{align*}
    & \left(\sum_{\bsh_{-u}\in \NN_0^{d-|u|}}\left(\sum_{\bsk_u\in \NN_0^{|u|}}(\breve{F}_u(\bsk_u,\bsh_{-u}))^2\right)^{1/2}\right)^{2} \\
%    & = \left(\sum_{\bsh_{-u}\in \NN_0^{d-|u|}}\left(\sum_{\bsk_u\in \NN_0^{|u|}}\left|\breve{f}(\bsk_u,\bsh_{-u})\right|^2 (\breve{r}_{\alpha,\bsgamma}(\bsk_u,\bszero))^2\right)^{1/2}\frac{\breve{r}_{\alpha,\bsgamma}(\bsh_{-u},\bszero)}{\breve{r}_{\alpha,\bsgamma}(\bsh_{-u},\bszero)}\right)^{2}\\
    & = \left(\sum_{\bsh_{-u}\in \NN_0^{d-|u|}}\left(\sum_{\bsk_u\in \NN_0^{|u|}}\left|\breve{f}(\bsk_u,\bsh_{-u})\right|^2 (\breve{r}_{\alpha,\bsgamma}(\bsk_u,\bsh_{-u}))^2\right)^{1/2}\frac{1}{\breve{r}_{\alpha,\bsgamma}(\bsh_{-u},\bszero)}\right)^{2}\\
    & \leq \sum_{\bsh_{-u}\in \NN_0^{d-|u|}}\sum_{\bsk_u\in \NN_0^{|u|}}\left|\breve{f}(\bsk_u,\bsh_{-u})\right|^2 (\breve{r}_{\alpha,\bsgamma}(\bsk_u,\bsh_{-u}))^2\times   \sum_{\bsh_{-u}\in \NN_0^{d-|u|}}\frac{1}{(\breve{r}_{\alpha,\bsgamma}(\bsh_{-u},\bszero))^2}\\
    & = \left(\| f\|_{d,\alpha,\bsgamma}^{\wal}\right)^2 \sum_{\bsh_{-u}\in \NN_0^{d-|u|}}\frac{1}{(\breve{r}_{\alpha,\bsgamma}(\bsh_{-u},\bszero))^2},
\end{align*}
as well as
\begin{align*}
    \left(\sum_{\bsh_u\in \NN_0^{|u|}}\left(\sum_{\bsk_{-u}\in \NN_0^{d-|u|}}(\breve{G}_{-u}(\bsh_u, \bsk_{-u}))^2\right)^{1/2}\right)^2\leq \left(\| g\|_{d,\alpha,\bsgamma}^{\wal}\right)^2  \sum_{\bsh_u\in \NN_0^{|u|}}\frac{1}{(\breve{r}_{\alpha,\bsgamma}(\bsh_u,\bszero))^2}.
\end{align*}

Altogether we obtain
\begin{align*}
    \left(\| fg\|_{d,\alpha,\bsgamma}^{\wal}\right)^2 
    & \leq 2^d\sum_{u\subseteq \{1,\ldots,d\}}a_u\\
    & \leq 2^d\left(\| f\|_{d,\alpha,\bsgamma}^{\wal}\right)^2\left(\| g\|_{d,\alpha,\bsgamma}^{\wal}\right)^2\\
    &\qquad\qquad\times\sum_{u\subseteq \{1,\ldots,d\}}\sum_{\bsh_{-u}\in \NN_0^{d-|u|}}\frac{1}{(\breve{r}_{\alpha,\bsgamma}(\bsh_{-u},\bszero))^2}\sum_{\bsh_u\in \NN_0^{|u|}}\frac{1}{(\breve{r}_{\alpha,\bsgamma}(\bsh_u,\bszero))^2}\\
%    & = 2^d\left(\| f\|_{d,\alpha,\bsgamma}^{\wal}\right)^2\left(\| g\|_{d,\alpha,\bsgamma}^{\wal}\right)^2\sum_{u\subseteq \{1,\ldots,d\}}\sum_{\bsh\in \NN_0^{d}}\frac{1}{(\breve{r}_{\alpha,\bsgamma}(\bsh))^2}\\
    & = 4^d\left(\| f\|_{d,\alpha,\bsgamma}^{\wal}\right)^2\left(\| g\|_{d,\alpha,\bsgamma}^{\wal}\right)^2\sum_{\bsh\in \NN_0^{d}}\frac{1}{(\breve{r}_{\alpha,\bsgamma}(\bsh))^2}.
\end{align*}
Finally, the last sum over $\bsh$ is given by
\begin{align*}
    \sum_{\bsh\in \NN_0^{d}}\frac{1}{(\breve{r}_{\alpha,\bsgamma}(\bsh))^2} & = \prod_{j=1}^{d}\sum_{h_j=0}^{\infty}\min\left(1,\frac{\gamma^2_{j}}{b^{2\alpha \mu_1(h_j)}}\right) = \prod_{j=1}^{d}\left(1+\gamma_{j}^2\sum_{\ell_j=1}^{\infty}\sum_{h_j=b^{\ell_j-1}}^{b^{\ell_j}-1}\frac{1}{b^{2\alpha \mu_1(h_j)}}\right)\\
%    & = \prod_{j=1}^{d}\left(1+\gamma_{j}^2\sum_{\ell_j=1}^{\infty}\frac{(b-1)b^{\ell_j-1}}{b^{2\alpha \ell_j}}\right)\\
    & = \prod_{j=1}^{d}\left(1+\gamma_{j}^2\frac{b-1}{b^{2\alpha}-b}\right).
\end{align*}
This concludes the result.


