\begin{restatable}{proposition}{propbluedisjoint}
   Given a bichromatic planar $n$-point set, there are $\frac{2}{7}n+1$ disjoint triangles containing all blue points such that no triangle contains a red point.
   \label{prop:blue_disjoint}
\end{restatable}

%\propbluedisjoint*

\begin{proof}
    Let $b$ be the number of blue points and $r$ the number of red points. If $b\le\frac{4}{7}n+1$, then we can cover all blue points in pairs from left to right, such that the resulting triangles are disjoint. This way we need at most $\frac{b+1}{2}\le\frac{2}{7}n+1$ triangles. If $r\le\frac{3}{7}n-1$, we can apply Lemma \ref{lem:gen triangles} to cover all blue points using at most $\frac{2}{3}r\le\frac{2}{7}n+1$ triangles. Since $b+r=n$ one of these two has to be the case, finishing the proof.
\end{proof}

\begin{restatable}{lemma}{lemgreedy}
   Given a bichromatic point set in the plane consisting of $b$ blue and $b-3t$ red points in general position, there is a set of $t$ triangles with vertices at different blue points that do not contain a red point.
	\label{lem:b-3t}
\end{restatable}

%\lemgreedy*

\begin{proof}
	We apply induction on $t$. If $t=0$, we do not have anything to show. For the induction step let $t\geq 1$ and $p$ be an arbitrary blue point. 

	The other blue points have a fixed cyclic order around $p$ such that at most one angle between two consecutive ones of them is larger than $\pi$. Thus out of the $b-1$ angles, at least $b-2$ can be used to define blue triangles of $p$ and two consecutive points. The $b-2$ triangles constructed this way are interior disjoint. Since $t\geq1,$ the number of red points is at most $b-3$. Hence at least one of the $b-2$ triangles does not contain red points. We now apply induction on the $b-3$ blue vertices that are not incident to this triangle and all of the $b-3t=(b-3)-3(t-1)$ red points to obtain $t-1$ triangles with vertices at different blue points that do not contain a red point. Since the original triangle does not share a vertex with any of these by construction and does not contain red points either, the lemma follows.
\end{proof}

\begin{restatable}{corollary}{corgreedy}
\label{cor:greedily covering triangles}
   Given a bichromatic point set in the plane consisting of $b$ blue and $b-3t$ red points in general position, where $t\in\mathbb{N}_0, t\le \frac{b}{3}$, there is a set of $\lceil\frac{b-t}{2}\rceil$ triangles such that every blue point is contained in a triangle and no triangle contains a red point.
\end{restatable}

%\corgreedy*

\begin{proof}
     By Lemma \ref{lem:b-3t}, there are $t$ vertex-disjoint blue triangles covering at least 3 blue points each and not containing any red point. The remaining $b-3t$ blue points can be covered in pairs as we did in \Cref{prop:match+comp}. Using Iverson brackets $[\cdot]$ the number of triangles used is
	\begin{equation*}
	t+\left\lceil\frac{b-3t}{2}\right\rceil = \frac{2t+b-3t}{2}+\frac{[2\nmid b-3t]}{2} = \frac{b-t}{2}+\frac{[{2\nmid b-t}]}{2} = \left\lceil\frac{b-t}{2}\right\rceil.
	\end{equation*}
\end{proof}

\begin{restatable}{proposition}{propcombinedupperbounds}
   \label{prop:combined upper bounds}
   Given a bichromatic planar $n$-point set, there is a set of $\frac{4}{15}n + \Oh(1)$ vertices, segments and triangles containing no red points and using all blue points as vertices exactly once.
\end{restatable}

%\propcombinedupperbounds*

\begin{proof}
	Let $r$ and $b$ be the number of red and blue points, respectively, and set $x:=\frac{b-r}{3}\leq \frac{b}{3}$. If there are more red points than blue points, then we can cover the blue points in pairs for an even better upper bound of $\frac{1}{2}b+\Oh(1)\leq\frac{1}{4}(r+b)+\Oh(1)$, so in the remaining case $x\geq 0$.
 Note that $n:=r+b=2b-3x$ is the total number of points. Taking the bounds from Lemma \ref{lem:gen triangles} with $t:=\lfloor x\rfloor$ and Corollary~\ref{cor:greedily covering triangles} with $r=b-3x$, we get that the number of triangles required per point is upper bounded by
	\begin{equation*}
	\max_{x\in[0,\frac{b}{3}]}\min\left(\frac{\frac{2}{3}(b-3x)+\frac{5}{3}}{n},\frac{1}{n}\left\lceil\frac{b-\lfloor x\rfloor}{2}\right\rceil\right).
	\end{equation*}
 This expression can be upper bounded by
 \begin{equation*}
    \max_{x\in[0,\frac{b}{3}]}\min\left(\frac{2x-\frac{2}{3}b-\frac{5}{3}}{3x-2b}, \frac{x-b-2}{6x-4b}\right)
 \end{equation*}
 via rearranging the terms and observing that
 \begin{equation*}
    \left\lceil\frac{b-\lfloor x\rfloor}{2}\right\rceil\le\frac{b-\lfloor x\rfloor+1}{2}\le\frac{b- x+2}{2}.
 \end{equation*}
 Regarding $b$ as a constant, we can see that both expressions in the minimum are monotone in $x$ for $x\in[0,\frac{b}{3}]$. The first is monotonically decreasing while the second is monotonically increasing. This implies that the worst case is attained for the unique value of $x$ making both expressions equal. Setting them equal yields $x=\frac{1}{9}(b-16)$. Therefore the number of triangles required per point is upper bounded by
 \begin{equation*}
    \frac{\frac{1}{9}(b-16)-b-2}{\frac{6}{9}(b-16)-4b+4} = \frac{4b+17}{15b+30}.
 \end{equation*}
 This completes the proof.
\end{proof}

